-- ============================================================================
-- EC45 RECUT: Decision Analysis (decision, EC4), Capital Portfolio (portfolio,
-- EC5) and Joint Ventures (joa, EC9) question banks brought onto the current
-- engines (petrolord-engines fb5a363 for decisionTree.js, voi.js, portfolio.js
-- and afe.js; engines #274 jointVenture.js on its canonical path).
--
-- GENERATED by tools/course-waves/ec45-recut/gen_ec45_migration.py from
-- docs/ec45-recut/decision_edits.json, portfolio_edits.json and joa_edits.json
-- (with the joa bank sources under tools/course-banks/joa). Never hand-edit.
--
-- WHAT MOVES.
--   decision questions: 141 rows (beginner 41, intermediate 35, advanced 65)
--   portfolio questions: 178 rows (beginner 63, intermediate 53, advanced 62)
--   joa questions: 2 rows (beginner 1, intermediate 0, advanced 1)
--   321 question rows in all. 9 of them (decision only) carry a re-derived
--   answer_index: the key the current engine gives, checked by engine call
--   (tools/course-waves/decision/recut/keytruth.mjs); portfolio and joa move no key.
--   decision Expert capstone: the dataset line only ("repaired" goes):
--     'the ABALAMA tree, lottery and surveys, read through Decision Studio and the repaired VOI Analyzer'
--     -> 'the ABALAMA tree, lottery and surveys, read through Decision Studio and the VOI Analyzer'
--   portfolio Expert capstone: the dataset line only ("repaired" goes):
--     'the IDOHO inventory and the IDOHO-2 AFE, read through the repaired risk summary and the partner split'
--     -> 'the IDOHO inventory and the IDOHO-2 AFE, read through the risk summary and the partner split'
-- WHAT DOES NOT MOVE. No ord, module key, scope or row count, and no key outside
-- those decision rows; each course keeps 396 active questions (132 a tier) and
-- 3 capstones of 6 fields.
-- No capstone prompt, title, cert tier or graded field (key, label, unit,
-- expected, tolerance, order) moves. No other table is touched: capstone
-- attempts and certifications stand as issued and are asserted byte-identical
-- after the file. Lessons, labs and panels ship in the NextGen site build.
--
-- W3. 20261026_w3_decision and 20261026_w3_portfolio appended one sentence to
-- capstone prompts and wrote no question row. This file applies whether or not
-- W3 is applied: every question row has one served text either way, and each
-- capstone guard accepts the prompt in its pre-W3 or its post-W3 form (by md5).
-- W3 guards on prompt and fields only, so it still applies after this file.
--
-- GUARDS. Each question row is addressed by (app_slug, tier, scope, module_key,
-- ord) among active rows and must carry EITHER its served prompt, options,
-- answer_index and explanation exactly (it is updated, then read back) OR the
-- recut ones exactly (already applied, left alone). Anything else raises naming
-- the row and, run in a transaction, the whole file rolls back. Every update
-- touches exactly 1 row.
--
-- TRANSACTION. Like every migration in this repository the file carries no
-- transaction lines of its own: the owner's apply script
-- (tools/course-waves/ec45-recut/apply_ec45_recut.sh) wraps it in one.
-- SAFE TO RE-RUN: a second run finds every row recut and writes nothing.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0. The attempts and certifications that stand as issued (snapshot).
-- ----------------------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select app_slug, tier, count(*) as n from public.academy_capstone_attempts
     where app_slug in ('decision', 'portfolio', 'joa') group by 1, 2 order by 1, 2
  loop
    raise notice 'ec45 recut: % attempt(s) on %/% stand as graded (no graded field moves)', r.n, r.app_slug, r.tier;
  end loop;
  perform set_config('ec45.snapshot', md5(coalesce((select string_agg(md5(a::text), ',' order by a.id) from public.academy_capstone_attempts a where a.app_slug in ('decision', 'portfolio', 'joa')), '') || '#' || coalesce((select string_agg(md5(c::text), ',' order by md5(c::text)) from public.academy_certifications c where c.app_slug in ('decision', 'portfolio', 'joa')), '')), false);
end $$;

-- ----------------------------------------------------------------------------
-- 1. decision: 141 question rows (beginner 41, intermediate 35, advanced 65).
-- ----------------------------------------------------------------------------
do $$
declare
  r         record;
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_done    integer := 0;
begin
  for r in
    select * from (values
      ('beginner', 'final', null::text, 1, 'A board says it cannot survive a loss of 80.0000 million USD on one well, and the EKPAN tree still recommends the drill at 105.0000. Why does the board''s position change nothing in the rollback?', '["The loss is already priced in, because the EKPAN tree''s dry hole of -25.0000 was discounted at a risk premium before it was typed into its terminal.", "The limit bears on the farm-out as well, so it lowers both branch values together and leaves their order at the root unchanged.", "The engine is risk neutral: it maximises expected money and has no utility function or risk aversion setting where that limit could be entered.", "The EKPAN tree''s drill cost of 55.0000 is charged before weighting, which caps the loss the rollback can see at the cost rather than at the whole dry hole outcome."]'::jsonb, 2, 'On the EKPAN tree the drill loses money with probability 0.500000 and still wins, 105.0000 against 37.7500, because the rollback ranks branches by their averages alone.'::text, 'A board says it cannot survive a loss of 80.0000 million USD on one well, and the EKPAN tree still recommends the drill at 105.0000. Why does the board''s position change nothing in the rollback?', '["The loss is already priced in, because the EKPAN tree''s dry hole of -25.0000 was discounted at a risk premium before it was typed into its terminal.", "The limit bears on the farm-out as well, so it lowers both branch values together and leaves their order at the root unchanged.", "The engine is risk neutral: it maximises expected money and has no utility function or risk aversion setting where that limit could be entered.", "The EKPAN tree''s drill cost of 55.0000 is charged before weighting, which caps the loss the rollback can see at the cost and leaves the whole dry hole outcome out."]'::jsonb, 2, 'On the EKPAN tree the drill loses money with probability 0.500000 and still wins, 105.0000 against 37.7500, because the rollback ranks branches by their averages alone.'::text),
      ('beginner', 'final', null::text, 4, 'A tree passes every check the engine makes: known node types, at least one branch per node, and probabilities summing to 1 within 1e-6. What has that established?', '["That the recommended branch is robust, since a choice that turned inside the tolerance of 1e-6 would have been refused as ambiguous.", "Only that the tree is well formed; nothing about whether its payoffs are discounted, its probabilities true, or its branches complete.", "That no better branch was left off, since a decision node refuses to roll back when a walk-away at 0.0000 would beat every branch it was given.", "That the chance nodes agree across stages, because the engine checks every later chance node against the ones above it."]'::jsonb, 1, 'The published allNegative case passes every check and recommends a branch worth -52.0000, because no walk-away was drawn and the engine never adds one.'::text, 'A tree passes every check the engine makes: known node types, at least one branch per node, probabilities summing to 1 within 1e-6, and every cost and payoff a finite number. What has that established?', '["That the recommended branch is robust, since a choice that turned inside the tolerance of 1e-6 would have been refused as ambiguous.", "Only that the tree is well formed; nothing about whether its payoffs are discounted, its probabilities true, or its branches complete.", "That no better branch was left off, since a decision node refuses to roll back when a walk-away at 0.0000 would beat every branch it was given.", "That the chance nodes agree across stages, because the engine checks every later chance node against the ones above it."]'::jsonb, 1, 'The published allNegative case passes every check and recommends a branch worth -52.0000, because no walk-away was drawn and the engine never adds one.'::text),
      ('beginner', 'final', null::text, 7, 'A four level tree in the shape of deepAlternation has its deepest chance node rebuilt with three branches typed at 0.333333 each. What does the engine return for the root?', '["Nothing: that node is refused with its sum printed as 0.999999, and a refusal at any depth leaves no EMV anywhere in the tree.", "The root EMV, because 0.999999 sits exactly 1e-6 from 1 and the tolerance accepts a sum lying on its own edge.", "The root EMV with the deepest node rescaled so its three branches sum to 1, which restores the intended equal thirds before weighting.", "An EMV for the levels above the refused node, which enters its parent''s weighting at 0.0000 until the probabilities are retyped."]'::jsonb, 0, 'In binary the gap evaluates to 0.0000010000000000287557, just above 1e-6, so the node is refused, and depth hides nothing: the published sum of 0.200000 two levels down refuses a whole tree too.'::text, 'A four level tree in the shape of deepAlternation has its deepest chance node rebuilt with three branches typed at 0.333333 each. What does the engine return for the root?', '["Nothing: that node is refused with its sum printed as 0.999999, and a refusal at any depth leaves no EMV anywhere in the tree.", "The root EMV, because 0.999999 sits exactly 1e-6 from 1 and the tolerance accepts a sum lying on its own edge.", "The root EMV with the deepest node rescaled so its three branches sum to 1, which restores the intended equal thirds before weighting.", "An EMV for the levels above the refused node, which enters its parent''s weighting at 0.0000 until the probabilities are retyped."]'::jsonb, 1, 'The gap from 1 is a hair above 1e-6 in binary and passes because the test adds a 1e-12 allowance for binary representation, and the thirds are weighted as typed. Depth changes nothing: the published sum of 0.200000 two levels down still refuses a whole tree.'::text),
      ('beginner', 'final', null::text, 9, 'The published chanceRootWithBranchCosts tree has a chance node at its root, with a cost of 2.0000 on calm and 8.0000 on storm. What do the Decision Tree Builder''s cards show?', '["Optimal EMV -3.0000, Chance root on the first move card, and N/A for the next best alternative and the decision advantage.", "Optimal EMV -8.6000, because the Builder totals a chance root''s costs and subtracts them once from the weighted children.", "Optimal EMV -3.0000 with calm as the recommended first move, since calm carries the larger probability of 0.600000 and the higher branch value.", "Optimal EMV 17.0000 for calm, with a decision advantage of 50.0000 over storm, read as if the chance root were a decision between them."]'::jsonb, 0, 'Each branch pays its own cost before weighting, 0.600000 x 17.0000 + 0.400000 x -33.0000 = -3.0000, and a chance root offers no move to recommend.'::text, 'The published chanceRootWithBranchCosts tree has a chance node at its root, with a cost of 2.0000 on calm and 8.0000 on storm. What do the Decision Tree Builder''s cards show?', '["Optimal EMV -3.0000, Chance root: no first decision to make on the first-move card, and N/A for the next best alternative and the decision advantage.", "Optimal EMV -8.6000, because the Builder totals a chance root''s costs and subtracts them once from the weighted children.", "Optimal EMV -3.0000 with calm as the recommended first move, since calm carries the larger probability of 0.600000 and the higher branch value.", "Optimal EMV 17.0000 for calm, with a decision advantage of 50.0000 over storm, read as if the chance root were a decision between them."]'::jsonb, 0, 'Each branch pays its own cost before weighting, 0.600000 x 17.0000 + 0.400000 x -33.0000 = -3.0000, and a chance root offers no move to recommend.'::text),
      ('beginner', 'final', null::text, 10, 'Subtracting every cost on chanceRootWithBranchCosts once, after weighting, gives -8.6000 against the engine''s -3.0000. Where does the difference come from?', '["It weights each cost by the other branch''s probability, so the storm cost of 8.0000 is counted at 0.600000 instead of 0.400000.", "The hand figure charges the storm''s cost in the calm and the calm''s cost in the storm.", "It is the engine rounding each cost to four decimals before weighting, a step that a hand calculation carried at full precision avoids.", "It counts the chance root''s own cost twice, because the engine charges a root cost once and the hand calculation applies it on both branches."]'::jsonb, 1, 'A cost is paid only when its branch occurs: 2.0000 only in the calm and 8.0000 only in the storm, and -8.6000 is never refused because no engine ever sees a hand calculation.'::text, 'Subtracting every cost on chanceRootWithBranchCosts once, after weighting, gives -8.6000 against the engine''s -3.0000. Where does the difference come from?', '["It weights each cost by the other branch''s probability, so the storm cost of 8.0000 is counted at 0.600000 where 0.400000 belongs.", "The hand figure charges the storm''s cost in the calm and the calm''s cost in the storm.", "It is the engine rounding each cost to four decimals before weighting, a step that a hand calculation carried at full precision avoids.", "It counts the chance root''s own cost twice, because the engine charges a root cost once and the hand calculation applies it on both branches."]'::jsonb, 1, 'A cost is paid only when its branch occurs: 2.0000 only in the calm and 8.0000 only in the storm, and -8.6000 is never refused because no engine ever sees a hand calculation.'::text),
      ('beginner', 'final', null::text, 11, 'A reviewer rolls back deepAlternation with its two costs, 4.0000 on go and 6.0000 on push, gathered and taken off together at the root, and gets 3.0000. What went wrong?', '["Nothing went wrong, since costs are additive and the order in which a hand rollback subtracts them cannot change the value at the root.", "The push cost should have been left out, because once push carries its cost of 6.0000 the decision beneath up switches to hold instead.", "The costs should have come off after weighting at every level rather than at the root, which is what the engine does to reach 6.0000.", "The push cost was charged on the down branch too; paid only on up, weighted 0.500000, it costs the root half as much and the root is 6.0000."]'::jsonb, 3, 'Push is paid only under up: 0.500000 x 23.0000 + 0.500000 x -3.0000 = 10.0000, less 4.0000 on go is 6.0000; chanceRootWithBranchCosts shows the same error at -8.6000 against -3.0000.'::text, 'A reviewer rolls back deepAlternation with its two costs, 4.0000 on go and 6.0000 on push, gathered and taken off together at the root, and gets 3.0000. What went wrong?', '["Nothing went wrong, since costs are additive and the order in which a hand rollback subtracts them cannot change the value at the root.", "The push cost should have been left out, because once push carries its cost of 6.0000 the decision beneath up switches to hold instead.", "The costs should have come off after weighting at every level below the root, which is what the engine does to reach 6.0000.", "The push cost was charged on the down branch too; paid only on up, weighted 0.500000, it costs the root half as much and the root is 6.0000."]'::jsonb, 3, 'Push is paid only under up: 0.500000 x 23.0000 + 0.500000 x -3.0000 = 10.0000, less 4.0000 on go is 6.0000; chanceRootWithBranchCosts shows the same error at -8.6000 against -3.0000.'::text),
      ('beginner', 'final', null::text, 17, 'On the published allNegative case the Builder names B with a decision advantage of 3.0000 over A. What does that advantage tell a reader?', '["Only that B loses 3.0000 less than A on average, and nothing about whether either should be taken.", "That B earns 3.0000 on average, since the card reports the winner''s margin above a zero floor.", "That B is the safer branch, because the advantage is worked out on the worst outcome of each branch rather than on their averages.", "That the engine found both branches negative, added a walk-away at 0.0000, and reported B''s margin over A as a fallback."]'::jsonb, 0, 'The engine returns EMV -52.0000 against -55.0000; it has no zero floor and never adds a walk-away, so the recommendation is an instruction to lose 52.0000 on average.'::text, 'On the published allNegative case the Builder names B with a decision advantage of 3.0000 over A. What does that advantage tell a reader?', '["Only that B loses 3.0000 less than A on average, and nothing about whether either should be taken.", "That B earns 3.0000 on average, since the card reports the winner''s margin above a zero floor.", "That B is the safer branch, because the advantage is worked out on the worst outcome of each branch and ignores their averages.", "That the engine found both branches negative, added a walk-away at 0.0000, and reported B''s margin over A as a fallback."]'::jsonb, 0, 'The engine returns EMV -52.0000 against -55.0000; it has no zero floor and never adds a walk-away, so the recommendation is an instruction to lose 52.0000 on average.'::text),
      ('beginner', 'final', null::text, 19, 'On equalEmvTie the branches read A 30.0000, B 30.0000 and C 29.9990. A reviewer relists them as C, A, B. Which branch does the engine name?', '["C, because the branch listed first keeps the decision whenever the values agree to the four decimals they are printed to.", "B, because once C takes the first place in the listing, the tie between A and B passes to the later of the two equal branches.", "A, because A is strictly greater than C and B only equals A.", "C, since 29.9990 differs from 30.0000 by less than the probability tolerance of 1e-6 and the engine counts the two as a tie."]'::jsonb, 2, 'A later branch displaces the best only when strictly greater: A beats C''s 29.9990 and B at 30.0000 does not beat A, so the EMV stays 30.0000 and the name records the listing.'::text, 'On equalEmvTie the branches read A 30.0000, B 30.0000 and C 29.9990. A reviewer relists them as C, A, B. Which branch does the engine name?', '["C, because the branch listed first keeps the decision whenever the values agree to the four decimals they are printed to.", "B, because once C takes the first place in the listing, the tie between A and B passes to the later of the two equal branches.", "A, because C sits outside the tie band, A and B tie, and the engine marks the first listed of that pair.", "C, since 29.9990 differs from 30.0000 by less than the probability tolerance of 1e-6 and the engine counts the two as a tie."]'::jsonb, 2, 'In the order C, A, B the engine reports A and B tied and marks A, the first of them; C''s 29.9990 is 0.0010 short, far outside the tie band, although all three round to the same 30.00 card. The EMV stays 30.0000.'::text),
      ('beginner', 'final', null::text, 20, 'On the EKPAN lottery at 0.228571, with its actions listed Drill, Farm out, Walk away, the engine names Farm out. What would it name with the list reordered as Farm out, Drill, Walk away?', '["Drill, because a choice at a crossing follows listing order, as on the published drillFarmOut tree at 0.200000.", "Farm out again, because there Farm out is larger by rounding residue and listing order decides only an exact tie.", "Drill, since with Farm out first the strictly greater comparison lets the next branch displace it by the EKPAN lottery''s residue of -7.11e-15.", "Neither, because the engine refuses a decision whose two leading branches print the same value, as the EKPAN lottery''s two do at 21.7143."]'::jsonb, 1, 'On the EKPAN lottery Drill less Farm out is -7.11e-15 in either order, so Drill is never strictly greater; on drillFarmOut the two are exactly 12.0000 and the first listed wins.'::text, 'On the EKPAN lottery at 0.228571, with its actions listed Drill, Farm out, Walk away, the engine prints Drill 21.7143 and Farm out 21.7143. What does it report with the list reordered as Farm out, Drill, Walk away?', '["Drill as the single best action, because Drill comes out larger by the residue of -7.11e-15 in either order.", "The same two actions tied, with Farm out now carrying the action index because it is listed first.", "Farm out alone with indifferent false, since once it leads the listing the residue decides in its favour.", "A refusal, because the engine refuses a lottery whose two leading actions print the same value, as these two do at 21.7143."]'::jsonb, 1, '80 / 350 has no exact binary image, so Drill less Farm out is -7.11e-15, far inside the tie band of 1e-9 x max(1, |best|). The engine reports the tie in either order, and only the marked action follows the listing, as on drillFarmOut at 0.200000.'::text),
      ('beginner', 'final', null::text, 34, 'About the published drillFarmOut sweep, Ada writes "drill from 0.200000" and Bola writes "farm out up to 0.200000". Whose reading is honest?', '["Ada''s, because the engine names Drill at 0.200000 and the recommendation there is the tree''s own answer to the question.", "Bola''s, because Farm out leads on every row below 0.200000 and a tie is resolved toward the action that held before it.", "Ada''s, since the tie at 0.200000 is float residue of the kind the EKPAN lottery shows at its crossing, and Drill is larger by it.", "Neither alone: at 0.200000 both branches are worth 12.0000 and the owner is indifferent, and the engine''s Drill there is listing order."]'::jsonb, 3, 'The engine keeps the first branch listed on an exact tie and has no tie flag; the advantage at 0.200000 is 0.0000, and above it Drill leads, 27.5000 to 15.0000 at 0.250000.'::text, 'About the published drillFarmOut sweep, Ada writes "drill from 0.200000" and Bola writes "farm out up to 0.200000". Whose reading is honest?', '["Ada''s, because the engine marks Drill at 0.200000 and the mark there is the tree''s own answer to the question.", "Bola''s, because Farm out leads on every row below 0.200000 and a tie is resolved toward the action that held before it.", "Ada''s, since the tie at 0.200000 is float residue of the kind the EKPAN lottery shows at its crossing, and Drill is larger by it.", "Neither alone: at 0.200000 both branches are worth 12.0000 and the owner is indifferent, and the engine''s Drill there is listing order."]'::jsonb, 3, 'At 0.200000 the engine reports the two branches tied (indifferent true) and marks Drill because it is listed first; above it Drill leads, 27.5000 to 15.0000 at 0.250000.'::text),
      ('beginner', 'final', null::text, 37, 'The VOI Analyzer''s second action is Do Not, with every payoff 0. Set beside the EKPAN lottery''s three actions, which one is it, and what does offering it instead of the farm-out do?', '["It is Walk away, which the farm-out dominates, so the Analyzer keeps the alternative that is never best and drops the one that can be.", "It is the farm-out with its payoffs cleared, so the Analyzer still values the same three actions, with one of them simply set to 0.0000.", "It is Drill at no cost, the Analyzer''s way of pricing the decision without the EKPAN lottery''s drill cost of 55.0000.", "It is a placeholder the Analyzer ignores, so the survey is valued on Drill alone as if the owner had no alternative."]'::jsonb, 0, 'On the EKPAN lottery Farm out pays 95 p, positive whenever success is possible, so walking away never wins; the Analyzer''s gross value of 19.84 is the two action number, against 24.8250 with the farm-out.'::text, 'The VOI Analyzer''s second action is Do Not, with every payoff 0. Set beside the EKPAN lottery''s three actions, which one is it, and what does offering it in place of the farm-out do?', '["It is Walk away, which the farm-out dominates, so the Analyzer keeps the alternative that is never best and drops the one that can be.", "It is the farm-out with its payoffs cleared, so the Analyzer still values the same three actions, with one of them simply set to 0.0000.", "It is Drill at no cost, the Analyzer''s way of pricing the decision without the EKPAN lottery''s drill cost of 55.0000.", "It is a placeholder the Analyzer ignores, so the survey is valued on Drill alone as if the owner had no alternative."]'::jsonb, 0, 'On the EKPAN lottery Farm out pays 95 p, positive whenever success is possible, so walking away never wins; the Analyzer''s gross value of 19.84 is the two action number, against 24.8250 with the farm-out.'::text),
      ('beginner', 'final', null::text, 38, 'At a survey cost of exactly 24.8250, the two root branches of the information tree built on the EKPAN lottery tie, and the engine recommends acquiring the survey. What decides that?', '["The survey''s positive gross value, since the EKPAN lottery''s survey, worth 24.8250 before its cost, is always worth acquiring at that same price.", "Float residue at the crossing, as at the EKPAN lottery''s switch of 0.228571, where the survey branch comes out larger in its last binary digits.", "A rule breaking ties toward the branch that carries more information, which the information tree applies before it compares values.", "The tie rule: acquiring is listed first, and a later branch replaces it only when strictly greater."]'::jsonb, 3, 'The price that makes information neutral is its gross value, 24.8250 on the EKPAN lottery; at that cost the branches are equal and the name is listing order, as on drillFarmOut at 0.200000.'::text, 'At a survey cost of exactly 24.8250, the two root branches of the information tree built on the EKPAN lottery tie, and the optimal path marks acquiring the survey. What decides that mark?', '["The survey''s positive gross value, since the EKPAN lottery''s survey, worth 24.8250 before its cost, is always worth acquiring at that same price.", "Float residue at the crossing, as at the EKPAN lottery''s switch of 0.228571, where the survey branch comes out larger in its last binary digits.", "A rule breaking ties toward the branch that carries more information, which the information tree applies before it compares values.", "The tie rule: both branches come to 75.7500, and acquiring carries the mark as the branch typed first."]'::jsonb, 3, 'The price that makes information neutral is its gross value, 24.8250 on the EKPAN lottery. At that cost the branches tie, the engine reports the tie, and the mark is listing order, as on drillFarmOut at 0.200000.'::text),
      ('beginner', 'final', null::text, 39, 'Before its repair the VOI Analyzer printed a gross value of information of -15.00 for IRRI, whose indicators were both typed 20 / 80. What does the repaired Analyzer do there, and why?', '["Prints 0.00 in place of -15.00, clamping the value at the floor information derived by Bayes never falls below.", "Withholds the value of information, because the typed numbers imply a success chance that contradicts the stated one.", "Prints -15.00 as before beside a warning, since a negative value correctly tells the user that the survey is not worth buying.", "Refuses the form with a message naming the sum in percent, because an indicator typed 20 / 80 is not a distribution."]'::jsonb, 1, 'Both indicators at 20 / 80 imply a success chance of 0.200000 against 0.3 stated; the repaired Analyzer keeps EMV without information at 15.00 and EVPI at 63.00 and withholds the rest.'::text, 'IRRI''s indicators are both typed 20 / 80. Weighted by those typed chances with nothing checking them against the stated prior, the numbers give a gross value of information of -15.00. What does the VOI Analyzer do there, and why?', '["Prints 0.00 in place of -15.00, clamping the value at the floor information derived by Bayes never falls below on any survey.", "Withholds the value of information, because the typed numbers imply a success chance that contradicts the stated one.", "Prints -15.00 beside a warning, since a negative value correctly tells the user that the survey is not worth buying.", "Refuses the form with a message naming the sum in percent, because an indicator typed 20 / 80 is not a distribution."]'::jsonb, 1, 'Both indicators at 20 / 80 imply a success chance of 0.200000 against 0.3 stated. The Analyzer keeps EMV without information at 15.00 and EVPI at 63.00 and withholds the rest.'::text),
      ('beginner', 'final', null::text, 41, 'OKRIKA''s appraisal cost of 18.0000 is paid today and its development cost of 150.0000 only after a result is known. What must hold for the root''s 87.0000 to mean anything?', '["Every cost and payoff must already be discounted to the date of the root decision, because the rollback takes them at face value.", "The development cost must be typed undiscounted, since the engine discounts each deeper level of the tree by one stage before weighting it.", "Nothing about timing, because costs paid in different years cancel out of any comparison between branches that contain them.", "The appraisal cost must be charged at the root instead of on its branch, so that money paid today stays apart from later money."]'::jsonb, 0, 'The engine has no rate and no date in any node, so a tree is only as well discounted as its typed numbers; the EKPAN tree''s develop cost of 90.0000 after a marginal find needs the same care.'::text, 'OKRIKA''s appraisal cost of 18.0000 is paid today and its development cost of 150.0000 only after a result is known. What must hold for the root''s 87.0000 to mean anything?', '["Every cost and payoff must already be discounted to the date of the root decision, because the rollback takes them at face value.", "The development cost must be typed undiscounted, since the engine discounts each deeper level of the tree by one stage before weighting it.", "Nothing about timing, because costs paid in different years cancel out of any comparison between branches that contain them.", "The appraisal cost must be charged at the root and kept off its branch, so that money paid today stays apart from later money."]'::jsonb, 0, 'The engine has no rate and no date in any node, so a tree is only as well discounted as its typed numbers; the EKPAN tree''s develop cost of 90.0000 after a marginal find needs the same care.'::text),
      ('beginner', 'module', 'm01-what-a-decision-tree-is'::text, 8, 'An analyst applies a discount rate by hand to an NPV that is already discounted, then types the result as a terminal payoff. What happens to the tree?', '["The engine detects the second discount and refuses the terminal with the message Distribution payoff has no finite mean.", "Nothing changes, because the rollback strips any rate applied to a payoff before it weights the payoff at its chance node.", "Every payoff shrinks while costs stay put, pulling the choice toward the cheaper branch, and nothing in the output shows it.", "Payoffs and costs shrink alike, so the EMV falls in proportion and the recommended branch can never change as a result."]'::jsonb, 2, 'The engine adds numbers at face value, so a smaller 420.0000 meets an unchanged cost of 55.0000. Neither discounting twice nor not at all leaves any trace in the output.'::text, 'An analyst applies a discount rate by hand to an NPV that is already discounted, then types the result as a terminal payoff. What happens to the tree?', '["The engine detects the second discount and refuses the terminal as a distribution payoff with no finite mean.", "Nothing changes, because the rollback strips any rate applied to a payoff before it weights the payoff at its chance node.", "Every payoff shrinks while costs stay put, pulling the choice toward the cheaper branch, and nothing in the output shows it.", "Payoffs and costs shrink alike, so the EMV falls in proportion and the recommended branch can never change as a result."]'::jsonb, 2, 'The engine adds numbers at face value, so a smaller 420.0000 meets an unchanged cost of 55.0000. Neither discounting twice nor not at all leaves any trace in the output.'::text),
      ('beginner', 'module', 'm01-what-a-decision-tree-is'::text, 9, 'A Builder terminal on a tree is linked to a saved Monte Carlo run, and the run is later revalued. What does the tree use for that terminal?', '["The revalued run, because the Builder re-reads every linked run each time the tree is rolled back and replaces the stored numbers.", "The copy of the run''s NPV mean, P90 and P10 stored when it was linked, until the terminal is linked again.", "A refusal, Distribution payoff has no finite mean, until the changed run is linked again.", "The revalued P10 and P90 beside the old mean, since only the mean is copied at linking and the percentiles are read live from the run."]'::jsonb, 1, 'Linking stores a copy in million USD at that moment and nothing re-reads the run, so a tree rolled back to 105.0000 on a stale copy gives no warning. Unlinking keeps the mean as a fixed payoff.'::text, 'A Builder terminal on a tree is linked to a saved Monte Carlo run, and the run is later revalued. What does the tree use for that terminal?', '["The revalued run, because the Builder re-reads every linked run each time the tree is rolled back and replaces the stored numbers.", "The copy of the run''s NPV mean, P90 and P10 stored when it was linked, until the terminal is linked again.", "A refusal saying the distribution payoff has no finite mean, until the changed run is linked again.", "The revalued P10 and P90 beside the old mean, since only the mean is copied at linking and the percentiles are read live from the run."]'::jsonb, 1, 'Linking stores a copy in million USD at that moment and nothing re-reads the run, so a tree rolled back to 105.0000 on a stale copy gives no warning. Unlinking keeps the mean as a fixed payoff.'::text),
      ('beginner', 'module', 'm01-what-a-decision-tree-is'::text, 10, 'On the published equalEmvTie case, branches A and B are both worth 30.0000 and C is worth 29.9990, and the engine returns A. Listed with B first, what does it return?', '["B, at the same EMV of 30.0000, because a later branch replaces the current best only when strictly greater.", "A, because the engine sorts a decision node''s branches by name before it compares their values.", "No recommendation, because an exact tie is refused as ambiguous with a message naming the node.", "C, because 29.9990 lies within the engine''s tolerance of 30.0000 and the last near tie listed is kept."]'::jsonb, 0, 'Equal never displaces earlier, so the first of the tied branches keeps the root at 30.0000. In a tie the recommendation records the order of typing and nothing about the branches.'::text, 'On the published equalEmvTie case, branches A and B are both worth 30.0000 and C is worth 29.9990, and the engine marks A. Listed with B first, what does it mark?', '["B, at the same EMV of 30.0000, because the engine reports A and B tied and marks the first listed of them.", "A, because the engine sorts a decision node''s branches by name before it compares their values.", "No branch at all, because an exact tie is refused as ambiguous with a message naming the node.", "C, because 29.9990 lies within the engine''s tolerance of 30.0000 and the last near tie listed is kept."]'::jsonb, 0, 'A and B tie, so the engine reports both with indifferent true and marks whichever is listed first, and the root stays 30.0000. The mark records the order of typing and nothing about the branches.'::text),
      ('beginner', 'module', 'm01-what-a-decision-tree-is'::text, 11, 'A tree with undiscounted payoffs, a success probability chosen to flatter the drill and conveniently ordered branches rolls back with no error. What does the absence of an error establish?', '["That its payoffs are present values, since the engine refuses a terminal typed without a rate.", "That no branch left off the tree would have beaten the best, since each decision node is checked for a walk-away before it is accepted.", "That its probabilities describe the prospect, since a probability chosen to favour one branch would push its chance node out of tolerance.", "Only that the tree is well formed: known node types, at least one branch per node and probability sums within 1e-6 of 1."]'::jsonb, 3, 'The engine checks shape, never truth. Any set of probabilities that sums to 1 within 1e-6 passes, and the EKPAN tree''s 105.0000 is only as good as its inputs.'::text, 'A tree with undiscounted payoffs, a success probability chosen to flatter the drill and conveniently ordered branches rolls back with no error. What does the absence of an error establish?', '["That its payoffs are present values, since the engine refuses a terminal typed without a rate.", "That no branch left off the tree would have beaten the best, since each decision node is checked for a walk-away before it is accepted.", "That its probabilities describe the prospect, since a probability chosen to favour one branch would push its chance node out of tolerance.", "Only that the tree is well formed: known node types, at least one branch per node and probability sums within 1e-6 of 1."]'::jsonb, 3, 'The engine checks shape only. Any set of probabilities that sums to 1 within 1e-6 passes, and the EKPAN tree''s 105.0000 is only as good as its inputs.'::text),
      ('beginner', 'module', 'm01-what-a-decision-tree-is'::text, 14, 'At the EKPAN tree''s root decision node, which three numbers does the engine compare?', '["105.0000, 37.7500 and 0.0000, each the child''s value less the cost on its branch.", "160.0000, 37.7500 and 0.0000, the nodes'' own values, with the drill cost of 55.0000 charged once the maximum has been taken.", "420.0000, 95.0000 and 0.0000, the best payoff reachable on each branch.", "-25.0000, 0.0000 and 0.0000, the worst outcome each branch can deliver, since the root guards against a loss."]'::jsonb, 0, 'Nodes combine branch values, never raw child values: the drill''s chance node is 160.0000 and its branch 105.0000. The root takes the largest, EMV 105.0000, best branch index 0.'::text, 'At the EKPAN tree''s root decision node, which three numbers does the engine compare?', '["105.0000, 37.7500 and 0.0000, each the child''s value less the cost on its branch.", "160.0000, 37.7500 and 0.0000, the nodes'' own values, with the drill cost of 55.0000 charged once the maximum has been taken.", "420.0000, 95.0000 and 0.0000, the best payoff reachable on each branch.", "-25.0000, 0.0000 and 0.0000, the worst outcome each branch can deliver, since the root guards against a loss."]'::jsonb, 0, 'Nodes combine branch values, each a child value less its branch cost: the drill''s chance node is 160.0000 and its branch 105.0000. The root takes the largest, EMV 105.0000, best branch index 0.'::text),
      ('beginner', 'module', 'm02-chance-nodes'::text, 2, 'A chance node with three equal outcomes paying 30, 60 and 90 has each probability typed as 0.333333. What does the engine return?', '["A refusal printing the sum 0.999999, because a sum sitting at the edge of the 1e-6 tolerance is not accepted.", "EMV 60.0000, since 0.999999 is within 1e-6 of 1 and the check is inclusive at its edge.", "EMV 60.0000 from the weights rescaled to sum to 1, with the typed sum printed as a warning.", "EMV 35.0000, the published thirdsProbabilities result, since that case types its thirds to six decimals."]'::jsonb, 0, 'Seven decimals, 0.3333333 each, are accepted at EMV 60.0000; six decimals print 0.999999 and are refused. The thirdsProbabilities case is a different tree whose 35.0000 matches its own golden.'::text, 'A chance node with three equal outcomes paying 30, 60 and 90 has each probability typed as 0.333333. What does the engine return?', '["A refusal printing the sum 0.999999, because a sum sitting at the edge of the 1e-6 tolerance is not accepted.", "EMV 59.9999: the check includes its edge, so 0.999999 passes and the thirds are weighted as typed.", "EMV 60.0000 from the weights rescaled to sum to 1, with the typed sum printed as a warning.", "EMV 35.0000, the published thirdsProbabilities result, since that case types its thirds to six decimals."]'::jsonb, 1, 'The test is |sum - 1| at most 1e-6 plus a 1e-12 allowance for binary representation, so six decimals pass and the node is worth 0.333333 x (30 + 60 + 90) = 59.9999. Five decimals, 0.33333 each, are refused. The thirdsProbabilities case is a different tree whose 35.0000 matches its own golden.'::text),
      ('beginner', 'module', 'm02-chance-nodes'::text, 7, 'What do the Decision Tree Builder''s cards show for the chanceRootWithBranchCosts tree, whose root is a chance node?', '["Optimal EMV -3.0000, Chance root on the first-move card, and N/A on the next best alternative and decision advantage cards.", "Calm as the recommended first move, being the likelier branch at 0.600000, with storm as the next best alternative and a decision advantage beside it.", "No cards, since the Builder needs a decision at the root and refuses to roll back a tree whose root is a chance node.", "Optimal EMV -8.6000, since the Builder subtracts the tree''s costs once after the rollback to fill the card."]'::jsonb, 0, 'The cards assume a decision at the root. Facing that chance is worth -3.0000, and there is no move to recommend or compare.'::text, 'What do the Decision Tree Builder''s cards show for the chanceRootWithBranchCosts tree, whose root is a chance node?', '["-3.0000 for the tree, the chance-root label on the first-move card, and N/A on the two cards that would compare one move with another.", "Calm as the recommended first move, being the likelier branch at 0.600000, with storm as the next best alternative and a decision advantage of 50.0000 beside it.", "No cards, since the Builder needs a decision at the root and refuses to roll back a tree whose root is a chance node.", "Optimal EMV -8.6000, since the Builder subtracts the tree''s costs once after the rollback to fill the card."]'::jsonb, 0, 'The cards assume a decision at the root. Facing that chance is worth -3.0000, and there is no move to recommend or compare.'::text),
      ('beginner', 'module', 'm02-chance-nodes'::text, 9, 'To be conservative, an analyst types the summary''s P90 of 185 as the EKPAN tree''s success payoff instead of its mean. What does the tree then report?', '["The drill branch rises to 206.5000, because under the exceedance meaning a P90 is the high case of the summary.", "The EMV stays at 105.0000, since the engine reads a linked payoff at its mean whatever statistic is typed in.", "The drill branch falls to 94.5000 and still wins, because a P90 moves a payoff less than a P50 would.", "The drill branch falls to 22.7500, below the farm-out''s 37.7500, so the tree recommends the farm-out at an EMV that is not the drill''s value."]'::jsonb, 3, 'P90 is the low case. Read there, the drill weighting gives 22.7500 and the root takes Farm out at 37.7500, which turns a risk preference into what looks like an expected value.'::text, 'To be conservative, an analyst types the summary''s P90 of 185 as the EKPAN tree''s success payoff in place of its mean. What does the tree then report?', '["The drill branch rises to 206.5000, because under the exceedance meaning a P90 is the high case of the summary.", "The EMV stays at 105.0000, since the engine reads a linked payoff at its mean whatever statistic is typed in.", "The drill branch falls to 94.5000 and still wins, because a P90 moves a payoff less than a P50 would.", "The drill branch falls to 22.7500, below the farm-out''s 37.7500, so the tree recommends the farm-out at an EMV that is not the drill''s value."]'::jsonb, 3, 'P90 is the low case. Read there, the drill weighting gives 22.7500 and the root takes Farm out at 37.7500, which turns a risk preference into what looks like an expected value.'::text),
      ('beginner', 'module', 'm02-chance-nodes'::text, 10, 'A summary typed as a terminal payoff carries a P90 of 185, a P50 of 390 and a P10 of 710, and no mean. What does the engine return?', '["A refusal, Distribution payoff has no finite mean, since the engine does not estimate a mean from the percentiles.", "An EMV using the P50 of 390 as the payoff, since the middle of the distribution stands in for a mean the summary does not carry.", "An EMV using the midpoint of the P90 and the P10 as its estimate of the mean, printed with a warning.", "An EMV of 105.0000, from the mean last stored for that terminal when a run was linked to it."]'::jsonb, 0, 'Only the mean enters the rollback, so a summary without one gives the engine nothing to weight. It refuses rather than guessing from 185, 390 and 710.'::text, 'A summary typed as a terminal payoff carries a P90 of 185, a P50 of 390 and a P10 of 710, and no mean. What does the engine return?', '["A refusal that names the terminal and says the distribution payoff has no finite mean, since the engine does not estimate a mean from the percentiles.", "An EMV using the P50 of 390 as the payoff, since the middle of the distribution stands in for a mean the summary does not carry.", "An EMV using the midpoint of the P90 and the P10 as its estimate of the mean, printed with a warning.", "An EMV of 105.0000, from the mean last stored for that terminal when a run was linked to it."]'::jsonb, 0, 'Only the mean enters the rollback, so a summary without one gives the engine nothing to weight. It refuses and does not guess a mean from 185, 390 and 710.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 1, 'On the EKPAN tree the Builder shows Optimal EMV 105.0000, Recommended first move Drill, Next best alternative 37.7500 and Decision advantage 67.2500. What does the advantage measure?', '["The money the drill makes over the farm-out on the one well drilled, since both moves face the same outcome.", "The drill node''s value less the farm-out''s, read off the drawing''s node labels before the drill cost is charged.", "The drill''s lead over the farm-out in only the outcomes where it does better, weighted across the 0.500000 of the probability that is not a dry hole.", "The EMV given up by taking the farm-out instead of the drill, a difference of averages that says nothing about how often the drill does worse."]'::jsonb, 3, 'The advantage is 105.0000 less 37.7500. The drill still leaves -80.0000 half the time while the farm-out never loses, and no card shows that.'::text, 'On the EKPAN tree the Builder shows Optimal EMV 105.0000, Recommended first move Drill, Next best alternative 37.7500 and Decision advantage 67.2500. What does the advantage measure?', '["The money the drill makes over the farm-out on the one well drilled, since both moves face the same outcome.", "The drill node''s value less the farm-out''s, read off the drawing''s node labels before the drill cost is charged.", "The drill''s lead over the farm-out in only the outcomes where it does better, weighted across the 0.500000 of the probability that is not a dry hole.", "The EMV given up by taking the farm-out over the drill, a difference of averages that says nothing about how often the drill does worse."]'::jsonb, 3, 'The advantage is 105.0000 less 37.7500. The drill still leaves -80.0000 half the time while the farm-out never loses, and no card shows that.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 2, 'Inside the EKPAN tree''s drill, a reader compares Develop at 260.0000 with Sell at 140.0000 and picks Develop. What has the comparison got wrong?', '["It finds the wrong branch, since Sell at 140.0000 beats Develop once the develop cost of 90.0000 has been paid.", "It finds the right branch at a value 90.0000 too high, and that inflated value would then be weighted into the drill node.", "Nothing, since a decision node compares payoffs, and only a chance node needs branch values net of their costs.", "Nothing, since a cost on a branch below a chance node is charged at the drill branch above it, alongside the 55.0000, rather than where it sits."]'::jsonb, 1, 'A decision node only ever compares branch values: Develop is 260.0000 less 90.0000, which is 170.0000, against Sell''s 140.0000. The drill chance node weights 170.0000.'::text, 'Inside the EKPAN tree''s drill, a reader compares Develop at 260.0000 with Sell at 140.0000 and picks Develop. What has the comparison got wrong?', '["It finds the wrong branch, since Sell at 140.0000 beats Develop once the develop cost of 90.0000 has been paid.", "It finds the right branch at a value 90.0000 too high, and that inflated value would then be weighted into the drill node.", "Nothing, since a decision node compares payoffs, and only a chance node needs branch values net of their costs.", "Nothing, since a cost on a branch below a chance node moves up to the drill branch above it and is charged there with the 55.0000."]'::jsonb, 1, 'A decision node only ever compares branch values: Develop is 260.0000 less 90.0000, which is 170.0000, against Sell''s 140.0000. The drill chance node weights 170.0000.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 4, 'On the EKPAN tree, Sell under the marginal find reads onOptimalPath false. Which reading of that flag is right?', '["Sell is a poor outcome, since a false flag marks a branch whose value falls below the root EMV of 105.0000.", "Sell can never be reached, because the marginal find itself sits off the optimal path beneath the drill''s chance node and so is never faced.", "Develop is better there, 170.0000 against 140.0000, and Sell would be off the path anyway had the owner not drilled.", "Sell loses money once the drill cost of 55.0000 is charged against its 140.0000 as well, and a false flag is how the engine records that loss."]'::jsonb, 2, 'A false flag says a branch is not reached under the best strategy, not that it is poor: Sell''s 140.0000 is above 105.0000 and still off the path because Develop wins at 170.0000.'::text, 'On the EKPAN tree, Sell under the marginal find reads onOptimalPath false. Which reading of that flag is right?', '["Sell is a poor outcome, since a false flag marks a branch whose value falls below the root EMV of 105.0000.", "Sell can never be reached, because the marginal find itself sits off the optimal path beneath the drill''s chance node and so is never faced.", "Develop is better there, 170.0000 against 140.0000, and Sell would be off the path anyway had the owner not drilled.", "Sell loses money once the drill cost of 55.0000 is charged against its 140.0000 as well, and a false flag is how the engine records that loss."]'::jsonb, 2, 'A false flag says a branch is not reached under the best strategy and says nothing about its quality: Sell''s 140.0000 is above 105.0000 and still off the path because Develop wins at 170.0000.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 5, 'Drill pays 40.0000 at a cost of 10.0000 and Farm out pays 30.0000. The same two branches are typed once with Drill first and once with Farm out first. What does the engine return?', '["Drill in both orders, since the engine compares children before their costs and Drill''s 40.0000 is the larger.", "Drill when Drill is listed first and Farm out when Farm out is listed first, both at EMV 30.0000.", "Farm out in both orders, since a branch with no cost wins an exact tie against a branch that carries one.", "A refusal in both orders, since two branches of exactly equal value leave the decision node without a best branch."]'::jsonb, 1, 'Drill''s branch value is 40.0000 less 10.0000, which is 30.0000, exactly Farm out''s. A later branch displaces an earlier one only by being strictly greater, so the order of typing names the move.'::text, 'Drill pays 40.0000 at a cost of 10.0000 and Farm out pays 30.0000. The same two branches are typed once with Drill first and once with Farm out first. What does the engine report?', '["Drill in both orders, since the engine compares children before their costs and Drill''s 40.0000 is the larger.", "A tie both ways at EMV 30.0000, with Drill marked when Drill is listed first and Farm out marked when Farm out is.", "Farm out in both orders, since a branch with no cost wins an exact tie against a branch that carries one.", "A refusal in both orders, since two branches of exactly equal value leave the decision node without a best branch."]'::jsonb, 1, 'Drill''s branch value is 40.0000 less 10.0000, which is 30.0000, exactly Farm out''s. The engine reports the two tied in either order, and the optimal path marks whichever is listed first.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 6, 'At a success probability of 0.228571, the EKPAN lottery (the two-outcome model, not the EKPAN tree) prints Drill 21.7143 and Farm out 21.7143 and names Farm out, the second branch. Why?', '["The tie rule, which on an exact tie keeps the branch carrying no cost rather than the branch that is listed first.", "The tie rule, which keeps the last branch listed when two values print as equal to four decimals.", "The engine rounds branch values to four decimals before comparing, and breaks the printed tie toward the safer branch.", "The crossing has no exact binary image, so the values differ in their last binary digits and Farm out is larger by that residue; the tie rule plays no part."]'::jsonb, 3, 'Only an exact tie goes to the first branch. Two values printed as 21.7143 can be unequal, and the engine chooses between them without any tie involved.'::text, 'At a success probability of 0.228571 the EKPAN lottery, the two-outcome model, prints Drill 21.7143 and Farm out 21.7143, and Drill less Farm out is -7.11e-15. What does the engine report?', '["Farm out as the best action, because it is larger by the residue and the engine compares values to the last binary digit.", "Drill as the single best action, because a branch that carries a cost wins an exact tie against one that carries none.", "Neither action, because the engine rounds values to four decimals before comparing and refuses two actions that print alike.", "A tie: the residue is far inside the band of 1e-9 x max(1, |best|), and Drill, listed first, carries the action index."]'::jsonb, 3, 'Two values tie when they differ by at most 1e-9 x max(1, |best|). A residue of -7.11e-15 is far inside that, so the engine lists both actions as tied and only the mark goes to the first listed.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 7, 'The published drillFarmOut tree, with its success probability swept, reads Drill 12.0000 and Farm out 12.0000 at 0.200000, and the engine reports Drill. Which reading is right?', '["Drill is named at 0.200000 only because it is listed first; Farm out leads at 0.150000, 9.0000 to -3.5000, and Drill leads at 0.250000, 27.5000 to 15.0000.", "Drill is named because its value is larger in the last binary digits, the same residue that names Farm out on the EKPAN lottery.", "Drill is named because a branch that carries a cost wins an exact tie against one that pays out without any cost.", "Farm out should have been named, since the engine keeps the branch that led at the lower probability of 0.150000."]'::jsonb, 0, 'This is an exact tie, 12.0000 against 12.0000, so the strictly greater rule keeps the first branch. The EKPAN lottery''s crossing is a different case, a rounding residue, and borrowing that explanation here is the mistake examined.'::text, 'The published drillFarmOut tree, with its success probability swept, reads Drill 12.0000 and Farm out 12.0000 at 0.200000, and the optimal path marks Drill. Which reading is right?', '["Drill is marked at 0.200000 only because it is listed first; Farm out leads at 0.150000, 9.0000 to -3.5000, and Drill leads at 0.250000, 27.5000 to 15.0000.", "Drill is marked because its value is larger in the last binary digits, a residue the engine reads as a lead.", "Drill is marked because a branch that carries a cost wins an exact tie against one that pays out without any cost.", "Farm out should have been named, since the engine keeps the branch that led at the lower probability of 0.150000."]'::jsonb, 0, 'This is an exact tie, 12.0000 against 12.0000: the engine reports both branches tied with indifferent true and marks Drill, the first listed. The EKPAN lottery''s crossing at 0.228571 is a reported tie as well, its residue of -7.11e-15 inside the band.'::text),
      ('beginner', 'module', 'm03-decision-nodes'::text, 8, 'Which plan states the EKPAN tree''s optimal strategy?', '["Drill; on a success take 420.0000; on a marginal find sell for 140.0000, the safer later choice; on a dry hole accept -25.0000.", "Drill and take 420.0000, since the optimal path is the single line from the root down to the best payoff.", "Drill; on a success take 420.0000; on a marginal find develop; on a dry hole accept -25.0000.", "Drill; on a marginal find develop; on a dry hole farm out instead for 0.0000 rather than accept the -25.0000."]'::jsonb, 2, 'The path runs through one branch at each decision reached and every branch of each chance node on it, so it covers the dry hole at 0.500000. The farm-out is a root alternative, not a move available after drilling.'::text, 'Which plan states the EKPAN tree''s optimal strategy?', '["Drill; on a success take 420.0000; on a marginal find sell for 140.0000, the safer later choice; on a dry hole accept -25.0000.", "Drill and take 420.0000, since the optimal path is the single line from the root down to the best payoff.", "Drill; on a success take 420.0000; on a marginal find develop; on a dry hole accept -25.0000.", "Drill; on a marginal find develop; on a dry hole farm out for 0.0000 and avoid the -25.0000."]'::jsonb, 2, 'The path runs through one branch at each decision reached and every branch of each chance node on it, so it covers the dry hole at 0.500000. The farm-out is a root alternative and no move available after drilling.'::text),
      ('beginner', 'module', 'm04-rolling-back-a-sequence'::text, 13, 'deepAlternation rolls back to 6.0000 along a path that runs go, then up and down, then push, then win and lose. What is 6.0000?', '["An average over paths that pay quite different amounts, none of which needs to be 6.0000.", "The payoff of the most likely route through the tree, since the path follows the branches the rollback kept.", "What the company receives if it follows the optimal path at every decision, whichever outcomes arrive along the way.", "The worst the company can reach along the optimal path, once the costs of go and push have both been paid."]'::jsonb, 0, 'Win after push pays 50.0000 before the costs of 6.0000 and 4.0000, and down pays -3.0000 before the 4.0000; the root weights these, so 6.0000 is a mean and the path is a plan, never a forecast.'::text, 'deepAlternation rolls back to 6.0000 along a path that runs go, then up and down, then push, then win and lose. What is 6.0000?', '["An average over paths that pay quite different amounts, none of which needs to be 6.0000.", "The payoff of the most likely route through the tree, since the path follows the branches the rollback kept.", "What the company receives if it follows the optimal path at every decision, whichever outcomes arrive along the way.", "The worst the company can reach along the optimal path, once the costs of go and push have both been paid."]'::jsonb, 0, 'Win after push pays 50.0000 before the costs of 6.0000 and 4.0000, and down pays -3.0000 before the 4.0000; the root weights these, so 6.0000 is a mean, and the path is a plan to follow with no forecast in it.'::text),
      ('beginner', 'module', 'm04-rolling-back-a-sequence'::text, 14, 'The Decision Tree Builder''s drawing labels OKRIKA''s development chance node after a good appraisal with its own value, 375.0000. What happens if that figure is weighted into the appraisal node?', '["Nothing changes, because the drawing''s label and the branch value are the same number whenever the branch lies on the optimal path.", "The good branch is overstated by OKRIKA''s sale price of 95.0000, which the drawing adds to the development as its fallback.", "The appraisal branch comes out slightly low, because the label is rounded for display while the rollback weights the unrounded value.", "The good branch is overstated by the whole 150.0000 development cost."]'::jsonb, 3, 'A node label is the value before the cost on the branch into it; the appraisal node takes 225.0000 after a good result and 25.0000 after a poor one, never 375.0000 or 56.0000.'::text, 'The Decision Tree Builder''s drawing labels OKRIKA''s development chance node after a good appraisal with its own value, 375.0000. What happens if that figure is weighted into the appraisal node?', '["Nothing changes, because the drawing''s label and the branch value are the same number whenever the branch lies on the optimal path.", "The good branch is overstated by OKRIKA''s sale price of 95.0000, which the drawing adds to the development as its fallback.", "The appraisal branch comes out slightly low, because the label is rounded for display while the rollback weights the unrounded value.", "The good branch is overstated by the whole 150.0000 development cost."]'::jsonb, 3, 'A node label is the value before the cost on the branch into it; the appraisal node takes 225.0000 after a good result and 25.0000 after a poor one, and it never takes 375.0000 or 56.0000.'::text),
      ('beginner', 'module', 'm05-when-the-decision-changes'::text, 2, 'At success 0.228571 on the EKPAN lottery the engine prints Drill 21.7143 and Farm out 21.7143 and names Farm out, although Drill is listed first. Why Farm out?', '["Ties go to the branch that cannot lose money, and the lottery''s farm-out never loses.", "The tie rule keeps the branch listed first, and the engine re-lists the lottery''s actions by value, which puts Farm out first below the switch.", "The engine treats a probability typed to six decimals as rounded, and on the lottery it falls back to the farm-out when two values look level.", "Drill less Farm out comes out at -7.11e-15 on the lottery, because 80 / 350 has no exact binary image."]'::jsonb, 3, 'A true tie would go to Drill, the first branch listed; the EKPAN lottery''s choice at 0.228571 is rounding residue under a strictly greater test, so report the switch and no winner at it.'::text, 'A sensitivity sweep of the EKPAN lottery lands exactly on its switch, 0.228571. How should a report describe the engine''s first move there?', '["As Farm out, since at a switch the engine hands the tie to the action that cannot lose money on the lottery.", "As Drill with indifferent false, since the engine re-lists actions by value and Drill heads the list above the switch.", "As Farm out alone, since a gap of -7.11e-15 below Drill is still a gap and the engine compares values to the last binary digit.", "As indifference: both actions sit in the tied set, and Drill holds the index only as the first action typed."]'::jsonb, 3, 'Values within 1e-9 x max(1, |best|) of the best share the tied set, and 80 / 350 leaves a gap far smaller than that, so the sweep''s honest entry at 0.228571 is a switch point with no winner.'::text),
      ('beginner', 'module', 'm05-when-the-decision-changes'::text, 3, 'Swept, the published drillFarmOut tree reads Drill 12.0000 and Farm out 12.0000 at success 0.200000 and names Drill. How should that row be reported?', '["The two are indifferent at 0.200000; Drill is named only because it is listed first, and the advantage is 0.0000.", "Drilling is better from 0.200000 upward, since the engine names Drill at the first row where it is no longer behind.", "Farm out is best up to and including 0.200000, since a tie on a published tree is resolved toward the branch that cannot lose.", "Drill wins by a residue too small to print, the same way the EKPAN lottery''s crossing at 0.228571 is decided."]'::jsonb, 0, 'The drillFarmOut tie is exact to the last digit, so the tie rule decides it; the EKPAN lottery''s crossing is decided by -7.11e-15 of residue instead, and neither result is a recommendation.'::text, 'Swept, the published drillFarmOut tree reads Drill 12.0000 and Farm out 12.0000 at success 0.200000 and names Drill. How should that row be reported?', '["Indifferent at 0.200000: Drill heads the tied pair only through the order of typing, so the row names no winner.", "Drilling is better from 0.200000 upward, since the engine names Drill at the first row where it is no longer behind.", "Farm out is best up to and including 0.200000, since a tie on a published tree is resolved toward the branch that cannot lose.", "Drill wins by a residue too small to print, the same way the EKPAN lottery''s crossing at 0.228571 is decided."]'::jsonb, 0, 'drillFarmOut''s two branches meet exactly at 12.0000 there, and the EKPAN lottery''s crossing at 0.228571 is a reported tie too, with a residue of -7.11e-15 inside the band; neither row is a recommendation.'::text),
      ('beginner', 'module', 'm05-when-the-decision-changes'::text, 5, 'What does the engine report to tell a reader that its recommended branch is tied with the runner-up?', '["A tie flag on the decision node, set when two branch values agree to four decimals.", "The runner-up''s index beside the best, so a tie shows as two branches on the optimal path.", "Nothing: it returns one best branch index whether the runner-up is behind by 25.0000 or by nothing.", "A warning in place of a recommendation whenever two branch values agree within the same 1e-6 tolerance its chance nodes use."]'::jsonb, 2, 'The rollback cannot tell an exact tie, like drillFarmOut''s 12.0000 at 0.200000, from a residue of -7.11e-15 like the EKPAN lottery''s at 0.228571; both come back as one best branch.'::text, 'What does the engine return to tell a reader that its best branch is tied with the runner-up?', '["A tie flag set only when two branch values agree to four decimals, with nothing reported for a residue too small to print.", "The runner-up''s index beside the best, so that a tie shows as two branches marked on the optimal path.", "The tied branches and an indifferent flag beside the best branch index, plus the set tied at card precision; the optimal path marks only the first listed.", "A warning in place of a best branch whenever two branch values agree within the same 1e-6 tolerance its chance nodes use."]'::jsonb, 2, 'Exact equality and last-digit residue look the same on a card, so the engine reports both: drillFarmOut''s 12.0000 at 0.200000 and the EKPAN lottery''s 21.7143 at 0.228571 each come back with indifferent true.'::text),
      ('beginner', 'module', 'm05-when-the-decision-changes'::text, 10, 'At success 0.100000 on the EKPAN lottery a reader sees Drill at -35.5000 and concludes: walk away. What does that answer give up?', '["Nothing, because a negative drill on the lottery means no action on that prospect is worth more than walking away.", "The lottery''s drill at 9.0000, since the drill turns positive at that probability once the farm-out is taken off the table.", "The lottery''s farm-out at 19.0000, since a farm-out is valued at the switch probability rather than at the probability stated.", "The lottery''s farm-out at 9.5000, the best of its three actions there."]'::jsonb, 3, 'A negative drill says only that drilling is worse than nothing; the best action needs every branch compared at once, and at 0.100000 the EKPAN lottery''s Farm out is 9.5000 against Walk away at 0.0000.'::text, 'At success 0.100000 on the EKPAN lottery a reader sees Drill at -35.5000 and concludes: walk away. What does that answer give up?', '["Nothing, because a negative drill on the lottery means no action on that prospect is worth more than walking away.", "The lottery''s drill at 9.0000, since the drill turns positive at that probability once the farm-out is taken off the table.", "The lottery''s farm-out at 19.0000, since a farm-out is valued at the switch probability in place of the probability stated.", "The lottery''s farm-out at 9.5000, the best of its three actions there."]'::jsonb, 3, 'A negative drill says only that drilling is worse than nothing; the best action needs every branch compared at once, and at 0.100000 the EKPAN lottery''s Farm out is 9.5000 against Walk away at 0.0000.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 3, 'On OKRIKA, the development chance node after a poor appraisal sits under a Develop branch reading onOptimalPath false. Its Large and Small probabilities are retyped so they sum to 0.9. What comes back for OKRIKA?', '["A refusal of the whole tree naming that node and printing 0.900000, with no EMV for Appraise, Develop now or Sell now.", "The root at 87.0000 unchanged, since that development reads onOptimalPath false and the sale at 25.0000 is what the appraisal node weights.", "Sell now at 48.0000, the only root branch that passes through no chance node, with the other two root branches reported as refused.", "The root with that node''s probabilities rescaled to sum to 1, since a node below a branch the rollback does not take is repaired quietly rather than refused."]'::jsonb, 0, 'The sum is checked at every chance node however deep, taken or not: the rollback still values that development at -94.0000 before the decision sets it against the sale at 25.0000. A refusal returns no EMV for any part of the tree, and the engine never rescales.'::text, 'On OKRIKA, the development chance node after a poor appraisal sits under a Develop branch reading onOptimalPath false. Its Large and Small probabilities are retyped so they sum to 0.9. What comes back for OKRIKA?', '["A refusal of the whole tree naming that node and printing 0.900000, with no EMV for Appraise, Develop now or Sell now.", "The root at 87.0000 unchanged, since that development reads onOptimalPath false and the sale at 25.0000 is what the appraisal node weights.", "Sell now at 48.0000, the only root branch that passes through no chance node, with the other two root branches reported as refused.", "The root with that node''s probabilities rescaled to sum to 1, since a node below a branch the rollback does not take is fixed quietly and escapes refusal."]'::jsonb, 0, 'The sum is checked at every chance node however deep, taken or not: the rollback still values that development at -94.0000 before the decision sets it against the sale at 25.0000. A refusal returns no EMV for any part of the tree, and the engine never rescales.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 4, 'A reader types the EKPAN tree''s success payoff as 185, the P90 (the low case) of its Monte Carlo NPV summary, instead of linking the summary whose mean is 420. What does the tree read?', '["105.0000 with Drill, since the P90 is the cautious figure and a drill on the tree that survives it survives the mean as well.", "94.5000 with Drill, since 185 sits near the P50 and the tree moves only part way.", "37.7500 with Farm out first, where the linked summary would have given the tree 105.0000 with Drill.", "22.7500 with Drill, the tree''s drill branch at that payoff, since Drill is the only branch that can reach the success payoff."]'::jsonb, 2, 'At 185.0000 the EKPAN tree''s drill branch is 22.7500, below Farm out at 37.7500, so the choice flips; linked, only the mean enters and the tree reads 105.0000.'::text, 'A reader types the EKPAN tree''s success payoff as 185, the P90 (the low case) of its Monte Carlo NPV summary, in place of linking the summary whose mean is 420. What does the tree read?', '["105.0000 with Drill, since the P90 is the cautious figure and a drill on the tree that survives it survives the mean as well.", "94.5000 with Drill, since 185 sits near the P50 and the tree moves only part way.", "37.7500 with Farm out first, where the linked summary would have given the tree 105.0000 with Drill.", "22.7500 with Drill, the tree''s drill branch at that payoff, since Drill is the only branch that can reach the success payoff."]'::jsonb, 2, 'At 185.0000 the EKPAN tree''s drill branch is 22.7500, below Farm out at 37.7500, so the choice flips; linked, only the mean enters and the tree reads 105.0000.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 6, 'Which of these first moves is the tie rule speaking, and nothing else?', '["Farm out on the EKPAN lottery at 0.228571, where both branches print 21.7143 and the lottery keeps the branch the engine met first.", "Develop in the EKPAN tree''s marginal find, where 260.0000 less its cost of 90.0000 beats selling at 140.0000 within the rule''s margin.", "Appraise on OKRIKA at 87.0000, because the appraisal is listed first of the three root branches and the rule favours that position.", "Drill on the published drillFarmOut tree at success 0.200000, where both branches are 12.0000."]'::jsonb, 3, 'An exact tie at drillFarmOut''s 0.200000 goes to Drill because it is listed first, with an advantage of 0.0000; the EKPAN lottery''s Farm out at 0.228571 is residue of -7.11e-15, and Develop at 170.0000 and Appraise by 39.0000 are real margins.'::text, 'Which of these first moves is the tie rule speaking, and nothing else?', '["Farm out on the EKPAN lottery at 0.228571, where both actions print 21.7143 and the lottery keeps the action it meets last.", "Develop in the EKPAN tree''s marginal find, where 260.0000 less its cost of 90.0000 beats selling at 140.0000 within the rule''s margin.", "Appraise on OKRIKA at 87.0000, because the appraisal is listed first of the three root branches and the rule favours that position.", "Drill on the published drillFarmOut tree at success 0.200000, where both branches are 12.0000."]'::jsonb, 3, 'An exact tie at drillFarmOut''s 0.200000 is reported as a tie and Drill is marked because it is listed first, with nothing between the two. The EKPAN lottery at 0.228571 is a reported tie with Drill marked, and Develop at 170.0000 and Appraise by 39.0000 are real margins.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 10, 'The EKPAN lottery''s information tree ties its two root branches at a survey cost of 24.8250. What does the engine recommend there?', '["No further information, because at a net value of 0.0000 on the lottery the engine declines to spend money that buys nothing.", "A refusal, since a lottery survey priced at its gross value leaves no best branch.", "No further information, because 24.8250 is judged against the lottery''s EVPI of 52.0000 and falls short of perfect information.", "Acquire CSEM survey, the first branch listed on the lottery''s information tree, by the tie rule."]'::jsonb, 3, 'At a survey cost of 24.8250 both root branches of the EKPAN lottery''s information tree are 75.7500 and the acquisition is listed first; the advantage is 0.0000, so the recommendation is only the tie rule.'::text, 'The EKPAN lottery''s information tree ties its two root branches at a survey cost of 24.8250. What does the engine report there?', '["No further information, because at a net value of 0.0000 on the lottery the engine declines to spend money that buys nothing.", "A refusal, since a lottery survey priced at its gross value leaves no best branch.", "No further information, because 24.8250 is judged against the lottery''s EVPI of 52.0000 and falls short of perfect information.", "A tie, with Acquire CSEM survey marked because it is the first branch listed on the lottery''s information tree."]'::jsonb, 3, 'At a survey cost of 24.8250 both root branches of the EKPAN lottery''s information tree are 75.7500. The engine reports them tied and marks the acquisition, listed first.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 12, 'On IRRI both indicators are typed 20 / 80 percent. What does the repaired VOI Analyzer report for the value of information?', '["A gross value of -15.00, the figure printed on those inputs before the repair, which it now shows beside a warning.", "A value of 0.00, since two readings with the same outcome chances cannot change the decision.", "It withholds it, with consistent false, and still reports EMV without information 15.00 and EVPI 63.00.", "A refusal before anything is computed, since chances that disagree are not chances at all."]'::jsonb, 2, 'The typed numbers are chances that cannot all be true, implying 0.200000 success against a stated 0.300000; before the repair the Analyzer printed -15.00, which Bayes can never produce because information is never worth less than 0.'::text, 'On IRRI both indicators are typed 20 / 80 percent. What does the VOI Analyzer report for the value of information?', '["A gross value of -15.00, the figure the typed chances give with nothing checking them, shown beside a warning.", "A value of 0.00, since two readings with the same outcome chances cannot change the decision.", "It withholds it, with consistent false, and still reports EMV without information 15.00 and EVPI 63.00.", "A refusal before anything is computed, since chances that disagree are not chances at all."]'::jsonb, 2, 'The typed numbers are chances that cannot all be true, implying 0.200000 success against a stated 0.300000. Weighted with nothing checking them they would give -15.00, which Bayes can never produce because information is never worth less than 0.'::text),
      ('intermediate', 'final', null::text, 1, 'An analyst values perfect information on the EKPAN lottery at its 0.350000 prior by repricing the prospect as a certain success, 365.0000 million USD after the drill cost. What is the EVPI, and where did the analyst go wrong?', '["52.0000: the priors stay put, the best value per outcome weights to 127.7500, and EVPI is that less the 75.7500 already available.", "365.0000, since perfect information turns the prospect into a known success and every well it recommends is drilled into a success.", "127.7500, since the value of deciding with the outcome known is itself the worth of the information that makes the deciding possible.", "61.7143, since the EVPI of a two outcome lottery is always read at the switch where Drill and Farm out are worth the same."]'::jsonb, 0, 'Perfect information changes the action, never how often each outcome arrives: the EKPAN lottery is still dry 0.650000 of the time. Read as regret, 0.650000 x 80.0000 = 52.0000.'::text, 'An analyst values perfect information on the EKPAN lottery at its 0.350000 prior by repricing the prospect as a certain success, 365.0000 million USD after the drill cost. What is the EVPI, and where did the analyst go wrong?', '["52.0000: the priors stay put, the best value per outcome weights to 127.7500, and EVPI is that less the 75.7500 already available.", "365.0000, since perfect information turns the prospect into a known success and every well it recommends is drilled into a success.", "127.7500, since the value of deciding with the outcome known is itself the worth of the information that makes the deciding possible.", "61.7143, since the EVPI of a two outcome lottery is always read at the switch where Drill and Farm out are worth the same."]'::jsonb, 0, 'Perfect information changes the action while each outcome arrives as often as before: the EKPAN lottery is still dry 0.650000 of the time. Read as regret, 0.650000 x 80.0000 = 52.0000.'::text),
      ('intermediate', 'final', null::text, 9, 'Before the EC4-0 repair the Analyzer printed a gross value of information of -15.00 on IRRI. Why is a negative value, on its own, evidence of broken inputs?', '["Because the survey cost of 10.0000 had been subtracted from it, and a gross value by definition carries no cost inside it at all.", "Because IRRI''s EVPI is 63.00, and a value below zero is admissible only on a survey that never misreads the outcome it reports.", "Whoever holds a survey can ignore it and take the prior action, so information derived by Bayes is never worth less than 0.", "It is not, since a survey that misleads more often than it informs has a negative value, which the repair now hides from view."]'::jsonb, 2, 'uselessSignal sits on that floor at 0.0000. IRRI''s typed indicators imply success of 0.200000 against 0.300000 stated, and the repaired Analyzer withholds instead.'::text, 'Weighted by IRRI''s typed chances with nothing checking them against the stated prior, the numbers give a gross value of information of -15.00. Why is a negative value, on its own, evidence of broken inputs?', '["Because the survey cost of 10.0000 had been subtracted from it, and a gross value by definition carries no cost inside it at all.", "Because IRRI''s EVPI is 63.00, and a value below zero is admissible only on a survey that never misreads the outcome it reports.", "Whoever holds a survey can ignore it and take the prior action, so information derived by Bayes is never worth less than 0.", "It is not, since a survey that misleads more often than it informs has a negative value, which the Analyzer hides from view."]'::jsonb, 2, 'uselessSignal sits on that floor at 0.0000. IRRI''s typed indicators imply success of 0.200000 against 0.300000 stated, and the Analyzer withholds the value.'::text),
      ('intermediate', 'final', null::text, 11, 'Two engine choices on the EKPAN lottery sit at points of indifference: Farm out named at the success probability 0.228571, and Acquire CSEM survey named at a price of 24.8250. What decides each name?', '["The tie rule decides both, since in each case the engine keeps whichever branch was listed first when two values are equal.", "Binary residue decides both, since 24.8250 printed to four decimals hides a last-digit gap between the two root branches as well.", "Neither is a tie: Farm out is worth more at 0.228571 by the printed precision, and at 24.8250 acquiring keeps a positive net value.", "Binary residue decides the first, since Drill less Farm out is -7.11e-15; the tie rule decides the second, where both branches are exactly 75.7500."]'::jsonb, 3, '80 / 350 has no exact binary image, so the choice at the switch is rounding. 100.5750 less 24.8250 is exactly 75.7500, and at an exact tie the first branch listed, the acquisition, is kept.'::text, 'Two engine results on the EKPAN lottery sit at points of indifference: Drill marked at 80 / 350 (0.228571), and Acquire CSEM survey marked at a price of 24.8250. What decides each mark?', '["The tie rule decides both: in each case the engine reports the two values tied and marks whichever was listed first.", "Binary residue decides both, since 24.8250 printed to four decimals hides a last-digit gap between the two root branches as well.", "Neither is a tie: Farm out is worth more at 0.228571 by the printed precision, and at 24.8250 acquiring keeps a positive net value.", "Binary residue decides the first, since Drill less Farm out is -7.11e-15; the tie rule decides the second, where both branches are exactly 75.7500."]'::jsonb, 0, '80 / 350 has no exact binary image, so Drill less Farm out is -7.11e-15, far inside the tie band of 1e-9 x max(1, |best|), and at 24.8250 the survey is priced at its gross value, so both root branches come to 75.7500. The engine reports each as a tie and marks the first listed.'::text),
      ('intermediate', 'final', null::text, 23, 'Typed into the repaired Analyzer, the EKPAN lottery with Bright spot at 56 percent and No bright spot at 44 percent passes the sum check with its posteriors unchanged. What does it report?', '["75.75 and 52.00 only, withholding EMV with Information, both values of information and the diagram.", "Every card, since the indicator chances sum to 100 and the posteriors are the Bayes results carried at full precision.", "Every card, after rescaling the posteriors until implied success returns to 0.350000.", "A gross value of 40.62 marked inconsistent, since the Analyzer prints what it computed beside its consistency warning."]'::jsonb, 0, '56 percent of 64.673913 plus 44 percent of 9.722222 implies success 0.404952, beyond 0.005 of 0.350000. The 40.62 is what the Analyzer printed before the repair.'::text, 'With its posteriors unchanged, the lottery''s survey is re-entered at 56 percent for one reading and 44 for the other, a pair that passes the sum check. Which results survive?', '["75.75 and 52.00 only, withholding EMV with Information, both values of information and the diagram.", "Every card, since the indicator chances sum to 100 and the posteriors are the Bayes results carried at full precision.", "Every card, after rescaling the posteriors until implied success returns to 0.350000.", "A gross value of 40.62 marked inconsistent, since the Analyzer prints what it computed beside its consistency warning."]'::jsonb, 0, '56 percent of 64.673913 plus 44 percent of 9.722222 implies success 0.404952, beyond 0.005 of 0.350000. The 40.62 is what these typed numbers give with nothing checking them against the stated prior.'::text),
      ('intermediate', 'final', null::text, 24, 'Inverting the EKPAN lottery''s Analyzer entries, Bright spot given Success is 0.646739 x 0.460000 / 0.350000. What does it return, and what does the same arithmetic say with Bright spot typed at 56 percent?', '["0.297500, the joint chance; at 56 percent, a larger joint valued as a stronger survey.", "0.850000, the survey''s hit rate; at 56 percent it exceeds 1, so the typing describes no survey.", "0.646739 unchanged, since inverting only relabels the posterior, and at 56 percent that same posterior with a heavier weight.", "0.850000, and at 56 percent a figure just under 1 marking a very strong survey that the Analyzer still values in full."]'::jsonb, 1, 'The Success column sums to the implied success chance over the stated one, so it sums to 1 only when the typing is consistent. The repaired Analyzer withholds on those 56 percent inputs.'::text, 'Inverting the EKPAN lottery''s Analyzer entries, Bright spot given Success is 0.646739 x 0.460000 / 0.350000. What does it return, and what does the same arithmetic say with Bright spot typed at 56 percent?', '["0.297500, the joint chance; at 56 percent, a larger joint valued as a stronger survey.", "0.850000, the survey''s hit rate; at 56 percent it exceeds 1, so the typing describes no survey.", "0.646739 unchanged, since inverting only relabels the posterior, and at 56 percent that same posterior with a heavier weight.", "0.850000, and at 56 percent a figure just under 1 marking a very strong survey that the Analyzer still values in full."]'::jsonb, 1, 'The Success column sums to the implied success chance over the stated one, so it sums to 1 only when the typing is consistent. The Analyzer withholds on those 56 percent inputs.'::text),
      ('intermediate', 'final', null::text, 25, 'On the Analyzer''s default study, what survey price leaves the survey value-neutral, and which number plays the same role on the tree engine''s EKPAN lottery?', '["23.00, the Net VOI card at the default cost, and on the EKPAN lottery its netEvii of 16.8250 at a price of 8.0000.", "63.00, the EVPI card, and on the EKPAN lottery its EVPI of 52.0000, since information turns neutral when priced at its ceiling.", "38.00, the EMV with Information card, and on the EKPAN lottery its acquire branch of 92.5750 at a price of 8.0000.", "33.0000, the gross value found only in the guidance sentence; on the EKPAN lottery, its evii of 24.8250."]'::jsonb, 3, 'At 33.0000 the net card reads 0.00 and the verdict says the information exactly pays for itself; at 24.8250 the EKPAN lottery''s root branches tie at 75.7500. Both prices are gross values, which no card shows.'::text, 'On the Analyzer''s default study, what survey price leaves the survey value-neutral, and which number plays the same role on the tree engine''s EKPAN lottery?', '["23.00, the Net VOI card at the default cost, and on the EKPAN lottery its netEvii of 16.8250 at a price of 8.0000.", "63.00, the EVPI card, and on the EKPAN lottery its EVPI of 52.0000, since information turns neutral when priced at its ceiling.", "38.00, the EMV with Information card, and on the EKPAN lottery its acquire branch of 92.5750 at a price of 8.0000.", "33.0000, the gross value found only in the guidance sentence; on the EKPAN lottery, its evii of 24.8250."]'::jsonb, 3, 'At 33.0000 the net card reads 0.00 and the verdict says the information costs what it is worth; at 24.8250 the EKPAN lottery''s root branches tie at 75.7500. Both prices are gross values, which no card shows.'::text),
      ('intermediate', 'final', null::text, 28, 'The CSEM survey''s hit rate, 0.850000, is typed into the Analyzer as P(Success | Bright spot) for the EKPAN lottery. How does the repaired Analyzer''s response differ from a hand rollback that makes the same misreading?', '["Both overvalue the survey by the same amount, since the Analyzer and the rollback run the same Bayes arithmetic on the number typed.", "The rollback values Drill after a bright spot at 298.2500 against 207.7989; the Analyzer finds the implied success chance far from 0.350000 and withholds.", "The Analyzer refuses with a message naming the sum, since a success chance of 0.850000 cannot sit in a row that also holds a dry hole.", "The Analyzer converts 0.850000 into the posterior 0.646739 first, because it inverts every typed entry back to likelihoods before valuing."]'::jsonb, 1, 'The Analyzer never inverts and never rescales; the row still sums to 100, so it is withheld and not refused. The hand overstatement lands on the reading that argues for drilling.'::text, 'The CSEM survey''s hit rate, 0.850000, is typed into the Analyzer as P(Success | Bright spot) for the EKPAN lottery. How does the Analyzer''s response differ from a hand rollback that makes the same misreading?', '["Both overvalue the survey by the same amount, since the Analyzer and the rollback run the same Bayes arithmetic on the number typed.", "The rollback values Drill after a bright spot at 298.2500 against 207.7989; the Analyzer finds the implied success chance far from 0.350000 and withholds.", "The Analyzer refuses with a message naming the sum, since a success chance of 0.850000 cannot sit in a row that also holds a dry hole.", "The Analyzer converts 0.850000 into the posterior 0.646739 first, because it inverts every typed entry back to likelihoods before valuing."]'::jsonb, 1, 'The Analyzer never inverts and never rescales; the row still sums to 100, so it is withheld and not refused. The hand overstatement lands on the reading that argues for drilling.'::text),
      ('intermediate', 'final', null::text, 29, 'On IRRI both indicators are typed 20 / 80 percent against a stated Success Case of 30 percent. Which two values does the repaired Analyzer still print, and why can it?', '["15.00 and -15.00, the value at the prior and a gross value of information now shown beside a consistency warning.", "63.00 alone, since EMV without information uses the implied 0.200000.", "None, since typed percents that contradict each other are refused with a message naming the sum in percent.", "15.00 and 63.00, since EMV without information and EVPI use only the stated outcome chances."]'::jsonb, 3, 'The indicators imply success of 0.200000 against 0.300000, far beyond the 0.005 tolerance, so every value that needs the posteriors is withheld. The -15.00 is pre-repair history.'::text, 'On IRRI both indicators are typed 20 / 80 percent against a stated Success Case of 30 percent. Which two values does the Analyzer still print, and why can it?', '["15.00 and -15.00, the value at the prior and a gross value of information shown beside a consistency warning.", "63.00 alone, since EMV without information uses the implied 0.200000.", "None, since typed percents that contradict each other are refused with a message naming the sum in percent.", "15.00 and 63.00, since EMV without information and EVPI use only the stated outcome chances."]'::jsonb, 3, 'The indicators imply success of 0.200000 against 0.300000, far beyond the 0.005 tolerance, so every value that needs the posteriors is withheld. The -15.00 is only what the typed chances give with nothing checking them against the stated prior.'::text),
      ('intermediate', 'final', null::text, 30, 'Before the EC4-0 repair, a posterior row summing to 130 percent printed a gross value of information of 69.00 beside an EVPI card of 63.00. Which bound did that break, and what does the repaired Analyzer do with the input?', '["The upper bound, since no information is worth more than knowing the outcome; the row is now refused with a message naming 130 percent.", "The lower bound, since a gross value above EVPI turns negative once the survey cost is charged, and the input is now withheld.", "No bound, since EVPI is a card after cost and the gross value before it, and the repaired Analyzer prints both unchanged.", "The upper bound, and the repaired Analyzer now rescales the row to 100 percent and prints a value under 63.00."]'::jsonb, 0, '0 <= value <= EVPI for any information derived by Bayes. A row that is not a distribution is refused before any card; withholding is for distributions that contradict the stated chances.'::text, 'A posterior row summing to 130 percent, weighted as typed with nothing checking it, gives a gross value of information of 69.00 beside an EVPI of 63.00. Which bound does that break, and what does the Analyzer do with the input?', '["The upper bound, since no information is worth more than knowing the outcome; the row is refused with a message naming 130 percent.", "The lower bound, since a gross value above EVPI turns negative once the survey cost is charged, and the input is withheld.", "No bound, since EVPI is a card after cost and the gross value before it, and the Analyzer prints both unchanged.", "The upper bound, and the Analyzer rescales the row to 100 percent and prints a value under 63.00."]'::jsonb, 0, '0 <= value <= EVPI for any information derived by Bayes. A row that is not a distribution is refused before any card; withholding is for distributions that contradict the stated chances.'::text),
      ('intermediate', 'final', null::text, 31, 'A capstone answer subtracts the EKPAN tree''s drill branch value, 105.0000, from the EKPAN lottery''s evWithPerfect, 127.7500, to get EVPI. What is wrong?', '["Nothing, since the EKPAN tree and lottery share one prospect at a 0.350000 success chance, and EVPI needs only the best prior value.", "The baseline should be the lottery''s farm-out at 33.2500, since perfect information recommends the farm-out on a dry hole.", "It mixes two models: the lottery''s baseline is its own emvPrior of 75.7500, giving 52.0000, while 105.0000 belongs to the three-outcome tree.", "The subtraction runs backwards, since EVPI is the value at the prior less the value with perfect information."]'::jsonb, 2, 'The EKPAN tree''s drill branch of 105.0000 loses money with probability 0.500000; the EKPAN lottery''s drill action of 75.7500 loses with probability 0.650000. Section 16 carries them as separate fields.'::text, 'A capstone answer subtracts the EKPAN tree''s drill branch value, 105.0000, from the EKPAN lottery''s evWithPerfect, 127.7500, to get EVPI. What is wrong?', '["Nothing, since the EKPAN tree and lottery share one prospect at a 0.350000 success chance, and EVPI needs only the best prior value.", "The baseline should be the lottery''s farm-out at 33.2500, since perfect information recommends the farm-out on a dry hole.", "It mixes two models: the lottery''s baseline is its own emvPrior of 75.7500, giving 52.0000, while 105.0000 belongs to the three-outcome tree.", "The subtraction runs backwards, since EVPI is the value at the prior less the value with perfect information."]'::jsonb, 2, 'The EKPAN tree''s drill branch of 105.0000 loses money with probability 0.500000; the EKPAN lottery''s drill action of 75.7500 loses with probability 0.650000. The course carries them as separate fields.'::text),
      ('intermediate', 'final', null::text, 32, 'On a known dry hole in the EKPAN lottery, Farm out and Walk away both pay 0.0000 and the table names Farm out. If Walk away were listed first, what would happen to EVPI?', '["EVPI would fall, because naming Walk away gives up the farm-out''s 95.0000 on a success that perfect information could still reveal.", "Only the name changes: EVPI stays 52.0000, since it takes the best value per outcome.", "It rises to 61.7143, as the farm-out line no longer sets the switch.", "The engine refuses: a tie on one outcome leaves the best action undefined."]'::jsonb, 1, 'The best value on a dry hole is 0.0000 whichever action is named. A tie on an outcome row is the first-branch rule at work, and it moves labels, never values.'::text, 'On a known dry hole in the EKPAN lottery, Farm out and Walk away both pay 0.0000 and the table names Farm out. If Walk away were listed first, what would happen to EVPI?', '["EVPI would fall, because naming Walk away gives up the farm-out''s 95.0000 on a success that perfect information could still reveal.", "Only the name changes: EVPI stays 52.0000, since it takes the best value per outcome.", "It rises to 61.7143, as the farm-out line no longer sets the switch.", "The engine refuses: a tie on one outcome leaves the best action undefined."]'::jsonb, 1, 'Perfect information takes the largest net value in each outcome, and on a dry hole that is 0.0000 whoever pays it, so relabelling the row leaves 52.0000 intact.'::text),
      ('intermediate', 'module', 'm01-perfect-information'::text, 4, 'On the EKPAN lottery''s Dry hole row the engine reports Farm out as the best action if known, beside a best value of 0.0000. What would listing Walk away before Farm out change?', '["Nothing at all, because the engine breaks a tie by the larger payoff in the other outcome, where the lottery''s Farm out pays 95.0000 against 0.0000.", "Only the name reported for Dry hole, which becomes Walk away; the best value 0.0000 and evWithPerfect 127.7500 on the lottery stay the same.", "evWithPerfect on the lottery, because Walk away is valued as a terminal and Farm out as a chance node, so the rollback reaches a different expectation.", "The prior decision, because listing order is also the order in which the engine weights the lottery''s actions at 0.350000."]'::jsonb, 1, 'Farm out and Walk away both pay 0.0000 on the EKPAN lottery''s dry hole and the engine keeps the first branch listed; EVPI takes the best VALUE per outcome, so 52.0000 does not depend on the label.'::text, 'On the EKPAN lottery''s Dry hole row, the course''s perfect-information table names Farm out as the best action if known, beside a best value of 0.0000. What would listing Walk away before Farm out change?', '["Nothing at all, because a tie is broken by the larger payoff in the other outcome, where the lottery''s Farm out pays 95.0000 against 0.0000.", "Only the name reported for Dry hole, which becomes Walk away; the best value 0.0000 and evWithPerfect 127.7500 on the lottery stay the same.", "evWithPerfect on the lottery, because Walk away is valued as a terminal and Farm out as a chance node, so the rollback reaches a different expectation.", "The prior decision, because listing order is also the order in which the engine weights the lottery''s actions at 0.350000."]'::jsonb, 1, 'The two tied actions pay the same 0.0000 when the well is dry, and the table simply names whichever comes first; since EVPI is built from the best value in each outcome, 52.0000 ignores the label.'::text),
      ('intermediate', 'module', 'm01-perfect-information'::text, 9, 'At 0.228571 the engine names Farm out as the prior best action on the EKPAN lottery, with both actions printed at 21.7143. What decides that name?', '["The tie rule, which keeps the first action listed when a later one is only equal, and so names the farm-out whenever the two lottery values print alike.", "A built-in preference for the action that never loses money when two lottery EMVs agree to four decimals.", "Floating point residue: 80 / 350 has no exact binary image, and Drill comes out below Farm out in the last binary digits.", "EVPI, which is 61.7143 under Farm out and lower under Drill, so the engine names the lottery action that leaves the most to learn."]'::jsonb, 2, 'Drill is listed before Farm out on the EKPAN lottery, so the tie rule would name Drill; Drill less Farm out is -7.11e-15 there, and EVPI of 61.7143 is the same whichever is named.'::text, 'At 0.228571 on the EKPAN lottery both actions print 21.7143. What does the engine return as the prior best action there?', '["Farm out alone, because Drill comes out below it in the last binary digits and the engine compares values to that digit.", "Farm out, by a built-in preference for the action that never loses money when two lottery EMVs agree to four decimals.", "A tie with indifferent true, and Drill, listed first, carries the action index; EVPI is 61.7143 either way.", "Farm out, because EVPI is 61.7143 under Farm out and lower under Drill, so the engine names the action that leaves the most to learn."]'::jsonb, 2, 'The residue at the switch, -7.11e-15, sits far inside the band the engine allows a tie, so both actions are reported as tied; EVPI is 61.7143 whichever of them is marked.'::text),
      ('intermediate', 'module', 'm01-perfect-information'::text, 10, 'On the EKPAN lottery at a success probability of 0.050000, EVPI is 13.5000. In which outcome does perfect information change the prior action?', '["Dry hole, where the lottery''s Drill at -80.0000 gives way to 0.0000, exactly as it does at the stated prior of 0.350000.", "Success, where the prior best Farm out gives way to Drill''s 365.0000 against 95.0000 on the lottery.", "Both outcomes, since at a low success chance Walk away is the lottery''s prior best action and each outcome favours something else.", "Neither, since 13.5000 is the value of confirming the lottery''s prior action rather than of changing it in some outcome."]'::jsonb, 1, 'Left of the switch the EKPAN lottery''s prior best is Farm out, so the only gain is on Success: 0.050000 x (365.0000 less 95.0000) = 13.5000. Walk away is never best on the lottery above 0.'::text, 'On the EKPAN lottery at a success probability of 0.050000, EVPI is 13.5000. In which outcome does perfect information change the prior action?', '["Dry hole, where the lottery''s Drill at -80.0000 gives way to 0.0000, exactly as it does at the stated prior of 0.350000.", "Success, where the prior best Farm out gives way to Drill''s 365.0000 against 95.0000 on the lottery.", "Both outcomes, since at a low success chance Walk away is the lottery''s prior best action and each outcome favours something else.", "Neither, since 13.5000 is the value of confirming the lottery''s prior action with no change to it in any outcome."]'::jsonb, 1, 'Left of the switch the EKPAN lottery''s prior best is Farm out, so the only gain is on Success: 0.050000 x (365.0000 less 95.0000) = 13.5000. Walk away is never best on the lottery above 0.'::text),
      ('intermediate', 'module', 'm01-perfect-information'::text, 11, 'A reader builds the EKPAN lottery''s perfect-information table from the gross Drill payoffs, 420.0000 and -25.0000, instead of the net ones. What survives the error?', '["The best action in each outcome survives and the value does not, because 420.0000 enters the weighting where 365.0000 belongs.", "Both survive, because the lottery''s drill cost of 55.0000 is paid in every outcome and so cancels out of evWithPerfect.", "Neither survives, because -25.0000 now beats 0.0000 on Dry hole and Drill becomes best in both outcomes.", "The value survives and the action does not, since a cost matters only when two actions are compared within an outcome."]'::jsonb, 0, 'On the EKPAN lottery Drill still wins Success and still loses Dry hole (-25.0000 is below 0.0000), but Drill enters evWithPerfect only on Success, so its 55.0000 cost does not cancel.'::text, 'A reader builds the EKPAN lottery''s perfect-information table from the gross Drill payoffs, 420.0000 and -25.0000, in place of the net ones. What survives the error?', '["The best action in each outcome survives and the value does not, because 420.0000 enters the weighting where 365.0000 belongs.", "Both survive, because the lottery''s drill cost of 55.0000 is paid in every outcome and so cancels out of evWithPerfect.", "Neither survives, because -25.0000 now beats 0.0000 on Dry hole and Drill becomes best in both outcomes.", "The value survives and the action does not, since a cost matters only when two actions are compared within an outcome."]'::jsonb, 0, 'On the EKPAN lottery Drill still wins Success and still loses Dry hole (-25.0000 is below 0.0000), but Drill enters evWithPerfect only on Success, so its 55.0000 cost does not cancel.'::text),
      ('intermediate', 'module', 'm02-imperfect-information-by-bayes'::text, 5, 'A reader divides the EKPAN lottery joint chance 0.297500 by the prior 0.350000 and gets 0.850000. What went wrong?', '["The posterior divides the joint by the chance of the reading, 0.460000, giving 0.646739; dividing by the prior returns the likelihood the calculation started from.", "Nothing went wrong: the hit rate and the lottery''s posterior coincide whenever the joint chance is taken with the success outcome rather than the dry one.", "The joint should first be multiplied by the lottery''s pSignal of 0.460000 and only then divided by the prior 0.350000.", "The divisor should be the lottery''s dry hole prior of 0.650000, since a posterior compares the reading with the alternative outcome."]'::jsonb, 0, 'Bayes on the EKPAN lottery is joint over pSignal: 0.297500 / 0.460000 = 0.646739. A reader who finishes holding the hit rate has divided by the wrong number.'::text, 'A reader divides the EKPAN lottery joint chance 0.297500 by the prior 0.350000 and gets 0.850000. What went wrong?', '["The posterior divides the joint by the chance of the reading, 0.460000, giving 0.646739; dividing by the prior returns the likelihood the calculation started from.", "Nothing went wrong: the hit rate and the lottery''s posterior coincide whenever the joint chance is taken with the success outcome, leaving the dry one aside.", "The joint should first be multiplied by the lottery''s pSignal of 0.460000 and only then divided by the prior 0.350000.", "The divisor should be the lottery''s dry hole prior of 0.650000, since a posterior compares the reading with the alternative outcome."]'::jsonb, 0, 'Bayes on the EKPAN lottery is joint over pSignal: 0.297500 / 0.460000 = 0.646739. A reader who finishes holding the hit rate has divided by the wrong number.'::text),
      ('intermediate', 'module', 'm02-imperfect-information-by-bayes'::text, 7, 'Reading the EKPAN lottery likelihood 0.850000 as the chance of success after a bright spot, what is Drill worth after a bright spot, and which way does the error push?', '["207.7989 either way, because Drill is still the lottery''s best action after a bright spot and its value is read from the tree rather than from the probability.", "262.7989, the lottery''s drill chance node, because 0.850000 enters the weighting before the drill cost of 55.0000 and never meets it.", "An understatement on the lottery, because 0.850000 leaves out the prior of 0.350000, which the posterior adds on top of the hit rate.", "298.2500 against the posterior''s 207.7989, an overstatement on the reading that argues for drilling."]'::jsonb, 3, 'The engine at probability 0.85 gives the EKPAN lottery''s Drill 298.2500; at the posterior 0.646739 it is 207.7989. The error pushes the decision the way a hopeful team already leans.'::text, 'Reading the EKPAN lottery likelihood 0.850000 as the chance of success after a bright spot, what is Drill worth after a bright spot, and which way does the error push?', '["207.7989 either way, because Drill is still the lottery''s best action after a bright spot and its value is read from the tree alone, whatever the probability.", "262.7989, the lottery''s drill chance node, because 0.850000 enters the weighting before the drill cost of 55.0000 and never meets it.", "An understatement on the lottery, because 0.850000 leaves out the prior of 0.350000, which the posterior adds on top of the hit rate.", "298.2500 against the posterior''s 207.7989, an overstatement on the reading that argues for drilling."]'::jsonb, 3, 'The engine at probability 0.85 gives the EKPAN lottery''s Drill 298.2500; at the posterior 0.646739 it is 207.7989. The error pushes the decision the way a hopeful team already leans.'::text),
      ('intermediate', 'module', 'm02-imperfect-information-by-bayes'::text, 12, 'Before the repair, the VOI Analyzer printed a gross value of information of -15.00 for typed indicator numbers. What does the lower bound on EVII say about that card, and what does the repaired Analyzer do?', '["The survey was harmful: acting on its readings lost 15.00 against the prior decision, and the repaired Analyzer reports the loss as a negative card.", "The repaired Analyzer clamps the value to 0.00, which is the lower bound applied as a floor on whatever the typed numbers produce.", "Information derived by Bayes can never be worth less than 0, so the typed numbers contradicted each other; the repaired Analyzer withholds that value.", "The negative figure was net of the survey cost, and the repaired Analyzer now splits it into a gross card and a net card."]'::jsonb, 2, 'A company holding a survey can always ignore it, so EVII cannot be negative. The -15.00 card is history from before the repair; the Analyzer now keeps EMV without information and EVPI and withholds the rest.'::text, 'Weighted by typed indicator numbers with nothing checking them against the stated prior, a VOI Analyzer entry gives a gross value of information of -15.00. What does the lower bound on EVII say about that figure, and what does the Analyzer do?', '["The survey was harmful: acting on its readings lost 15.00 against the prior decision, and the Analyzer reports the loss as a negative card.", "The Analyzer clamps the value to 0.00, which is the lower bound applied as a floor on whatever the typed numbers produce.", "Information derived by Bayes can never be worth less than 0, so the typed numbers contradict each other; the Analyzer withholds that value.", "The negative figure was net of the survey cost, and the Analyzer splits it into a gross card and a net card."]'::jsonb, 2, 'A company holding a survey can always ignore it, so EVII cannot be negative. The -15.00 is only the unguarded arithmetic; the Analyzer keeps EMV without information and EVPI and withholds the rest.'::text),
      ('intermediate', 'module', 'm03-buying-the-information'::text, 1, 'A budget memo quotes 24.8250 as the worth of the EKPAN lottery survey, which is priced at 8.0000. What is wrong with the memo?', '["Nothing is wrong, since the price is sunk once the contract is signed, and a value of information is always quoted before sunk costs are taken off.", "It should quote 92.5750, the lottery''s acquisition branch, since that is what the company holds after paying for the survey.", "It understates the worth, since the survey also protects the 75.7500 the lottery is worth at the prior and that belongs in the figure.", "It quotes gross as net, overstating the survey''s contribution by exactly its price; the net value is 16.8250."]'::jsonb, 3, 'On the EKPAN lottery netEvii is evii less the cost: 24.8250 less 8.0000 is 16.8250. The 92.5750 is the whole decision with the survey bought, not the survey''s own contribution.'::text, 'A budget memo quotes 24.8250 as the worth of the EKPAN lottery survey, which is priced at 8.0000. What is wrong with the memo?', '["Nothing is wrong, since the price is sunk once the contract is signed, and a value of information is always quoted before sunk costs are taken off.", "It should quote 92.5750, the lottery''s acquisition branch, since that is what the company holds after paying for the survey.", "It understates the worth, since the survey also protects the 75.7500 the lottery is worth at the prior and that belongs in the figure.", "It quotes gross as net, overstating the survey''s contribution by exactly its price; the net value is 16.8250."]'::jsonb, 3, 'On the EKPAN lottery netEvii is evii less the cost: 24.8250 less 8.0000 is 16.8250. The 92.5750 is the whole decision with the survey bought, which is more than the survey adds on its own.'::text),
      ('intermediate', 'module', 'm03-buying-the-information'::text, 2, 'Why can the EKPAN lottery survey''s price of 8.0000 be taken off before or after the readings are weighted with the same result, when a cost on one branch of a chance node cannot?', '["Because the survey price is already discounted and a chance-branch cost is not, so the engine applies the two at different points in the rollback.", "The survey price sits on the branch that buys the survey and is paid whichever reading arrives, while a chance-branch cost is paid on that branch alone.", "Because readings are signals rather than outcomes, and the engine skips any cost placed on a signal branch while weighting it.", "It cannot: taking 8.0000 off after weighting charges it 0.460000 plus 0.540000 times over, which overstates the price paid."]'::jsonb, 1, 'On the EKPAN lottery the price is paid once on every path through the survey, and 0.460000 plus 0.540000 is 1, so 100.5750 less 8.0000 is 92.5750 either way. A chance-branch cost must come off inside its branch.'::text, 'Why can the EKPAN lottery survey''s price of 8.0000 be taken off before or after the readings are weighted with the same result, when a cost on one branch of a chance node cannot?', '["Because the survey price is already discounted and a chance-branch cost is not, so the engine applies the two at different points in the rollback.", "The survey price sits on the branch that buys the survey and is paid whichever reading arrives, while a chance-branch cost is paid on that branch alone.", "Because readings are signals that are not outcomes themselves, and the engine skips any cost placed on a signal branch while weighting it.", "It cannot: taking 8.0000 off after weighting charges it 0.460000 plus 0.540000 times over, which overstates the price paid."]'::jsonb, 1, 'On the EKPAN lottery the price is paid once on every path through the survey, and 0.460000 plus 0.540000 is 1, so 100.5750 less 8.0000 is 92.5750 either way. A chance-branch cost must come off inside its branch.'::text),
      ('intermediate', 'module', 'm03-buying-the-information'::text, 7, 'At what survey price do the two root branches of the EKPAN lottery information tree tie, and why that price?', '["52.0000 on the lottery, the EVPI, since a price above the value of perfect information is the first price at which any survey loses money.", "24.8250, the gross EVII, since the acquisition branch is 100.5750 less the price and the other branch holds at 75.7500.", "100.5750 on the lottery, the price at which the acquisition branch reaches zero and stops adding anything to the root.", "16.8250 on the lottery, the net value, since the tie comes when the price has used up everything the survey adds."]'::jsonb, 1, 'On the EKPAN lottery the branches are equal when the price is 100.5750 less 75.7500 = 24.8250. EVPI is the neutral price of a survey that never misreads, and the neutral price compares two branches, never a branch with zero.'::text, 'At what survey price do the two root branches of the EKPAN lottery information tree tie, and why that price?', '["52.0000 on the lottery, the EVPI, since a price above the value of perfect information is the first price at which any survey loses money.", "24.8250, the gross EVII, since the acquisition branch is 100.5750 less the price and the other branch holds at 75.7500.", "100.5750 on the lottery, the price at which the acquisition branch reaches zero and stops adding anything to the root.", "16.8250 on the lottery, the net value, since the tie comes when the price has used up everything the survey adds."]'::jsonb, 1, 'On the EKPAN lottery the branches are equal when the price is 100.5750 less 75.7500 = 24.8250. EVPI is the neutral price of a survey that never misreads, and the neutral price is where the two branches meet, one branch against the other.'::text),
      ('intermediate', 'module', 'm03-buying-the-information'::text, 8, 'At a survey cost of exactly 24.8250 the EKPAN lottery information tree''s root still names the acquisition. What does that name carry?', '["Only the listing order: the branches tie at 75.7500 and the engine keeps the first branch listed, so a net value of 0.0000 says nothing favours buying.", "A small positive net value hidden by printing to four decimals, since the engine compares the unrounded lottery branch values.", "A preference for information whenever the two lottery branches fall within the engine''s tolerance of 1e-6 of each other.", "A real recommendation, since at the neutral price the survey still lowers the chance of drilling a dry hole on the lottery."]'::jsonb, 0, 'At a cost equal to the EKPAN lottery''s EVII the two root branches tie and the strictly-greater comparison keeps the acquisition, listed first. Nothing in the engine flags the tie, so read netEvii beside every root choice.'::text, 'At a survey cost of exactly 24.8250 the EKPAN lottery information tree''s root still marks the acquisition. What does that mark carry?', '["Only the listing order: the branches tie at 75.7500, the engine reports the tie and marks the first listed, and a net value of 0.0000 says nothing favours buying.", "A small positive net value hidden by printing to four decimals, since the engine compares the unrounded lottery branch values.", "A preference for information whenever the two lottery branches fall within the engine''s tolerance of 1e-6 of each other.", "A real recommendation, since at the neutral price the survey still lowers the chance of drilling a dry hole on the lottery."]'::jsonb, 0, 'At a cost equal to the EKPAN lottery''s EVII the two root branches tie; the engine reports the tie and marks the acquisition, listed first. Read netEvii beside every root choice.'::text),
      ('intermediate', 'module', 'm03-buying-the-information'::text, 9, 'costExactlyNetZero returns root branch values 43.0000 and 43.0000 and bestBranchIndex 0. What would listing the no-information branch first change?', '["The recommendation, which becomes doing without the survey, while the root value stays 43.0000.", "Nothing, since the engine breaks exact ties toward the branch with fewer nodes below it, which is the no-information branch in either order.", "The root value, since the rollback weights a decision node''s branches in listing order before it takes the maximum.", "The tie price, which moves away from the survey''s gross value of 12.5000 toward the prior."]'::jsonb, 0, 'A decision node replaces the incumbent only on a strictly greater value, so the first listed wins a tie. The survey there costs 12.5000, its gross value, and the root is 43.0000 whichever branch is named.'::text, 'costExactlyNetZero returns root branch values 43.0000 and 43.0000 and bestBranchIndex 0. What would listing the no-information branch first change?', '["The marked branch, which becomes doing without the survey, while the root value stays 43.0000 and the tie is reported either way.", "Nothing, since the engine breaks exact ties toward the branch with fewer nodes below it, which is the no-information branch in either order.", "The root value, since the rollback weights a decision node''s branches in listing order before it takes the maximum.", "The tie price, which moves away from the survey''s gross value of 12.5000 toward the prior."]'::jsonb, 0, 'The two root branches tie, so the engine reports the tie in either order and marks whichever is listed first. The survey there costs 12.5000, its gross value, and the root is 43.0000 whichever branch is marked.'::text),
      ('intermediate', 'module', 'm04-accuracy-and-value'::text, 8, 'From accuracy 0.650000 upward the symmetric survey on the EKPAN lottery is worth 0.7250, 8.0500, 15.3750 and so on, rising by the same step each 0.050000. Why equal steps?', '["The posteriors rise in equal steps with accuracy, so the Drill value after a success reading grows by the same amount each row.", "The evii is a fixed fraction of the EVPI of 52.0000, and that fraction grows in proportion to accuracy.", "The actions are fixed across those rows, Drill after a success reading and Farm out after a dry one, so the value is four joint terms each a straight line in accuracy.", "The engine interpolates between the switch accuracy and a perfect reading instead of running Bayes on each row."]'::jsonb, 2, 'The terms are 0.350000 x a x 365.0000, 0.650000 x (1 less a) x -80.0000 and 0.350000 x (1 less a) x 95.0000. The posteriors are not linear: 0.556818, 0.617647, 0.682927.'::text, 'From accuracy 0.650000 upward the symmetric survey on the EKPAN lottery is worth 0.7250, 8.0500, 15.3750 and so on, rising by the same step each 0.050000. Why equal steps?', '["The posteriors rise in equal steps with accuracy, so the Drill value after a success reading grows by the same amount each row.", "The evii is a fixed fraction of the EVPI of 52.0000, and that fraction grows in proportion to accuracy.", "The actions are fixed across those rows, Drill after a success reading and Farm out after a dry one, so the value is four joint terms each a straight line in accuracy.", "The engine interpolates between the switch accuracy and a perfect reading and skips Bayes on each row."]'::jsonb, 2, 'The terms are 0.350000 x a x 365.0000, 0.650000 x (1 less a) x -80.0000 and 0.350000 x (1 less a) x 95.0000. The posteriors are not linear: 0.556818, 0.617647, 0.682927.'::text),
      ('intermediate', 'module', 'm05-the-voi-analyzer'::text, 3, 'An analyst enters No bright spot at 64 percent beside Bright spot at 46.000000 percent for the EKPAN lottery''s survey. What comes back from the repaired VOI Analyzer?', '["A refusal before any card: \"Indicator chances sum to 110 percent, expected 100\".", "The two cards that use only the stated chances, 75.75 and 52.00, with the other values and the diagram withheld.", "Full cards computed after rescaling the two indicator chances so that they sum to 100 percent.", "A refusal that names the Bright spot box as the one to correct."]'::jsonb, 0, 'Percents that are not a distribution are refused outright, and the message names the sum in percent. Withholding is the answer to chances that sum correctly but contradict the stated outcome chances.'::text, 'An analyst enters No bright spot at 64 percent beside Bright spot at 46.000000 percent for the EKPAN lottery''s survey. What comes back from the VOI Analyzer?', '["A refusal before any card: \"Indicator chances sum to 110 percent, expected 100\".", "The two cards that use only the stated chances, 75.75 and 52.00, with the other values and the diagram withheld.", "Full cards computed after rescaling the two indicator chances so that they sum to 100 percent.", "A refusal that names the Bright spot box as the one to correct."]'::jsonb, 0, 'Percents that are not a distribution are refused outright, and the message names the sum in percent. Withholding is the answer to chances that sum correctly but contradict the stated outcome chances.'::text),
      ('intermediate', 'module', 'm05-the-voi-analyzer'::text, 4, 'Suppose the CSEM survey''s indicator chances for the EKPAN lottery are entered as 56 and 44 percent while both posteriors keep their Bayes values. Which results does the repaired check let through?', '["A refusal, because the indicator chances no longer agree with the stated outcome chances and the Analyzer declines to compute any card.", "A gross value of information of 40.62 beside an EVPI of 52.00, which is what these inputs produce on the four cards and in the sentence.", "EMV without information 75.75 and EVPI 52.00, withholding EMV with information, the gross and net value and the diagram.", "The gross value of 19.84, after rescaling the posteriors so that they fit the stated success chance of 0.350000 again."]'::jsonb, 2, 'The chances sum to 100, so nothing is refused, but they imply success 0.404952 against the stated 0.350000, more than 0.005 away. 40.62 is what the Analyzer printed before the repair; the check never repairs.'::text, 'Suppose the CSEM survey''s indicator chances for the EKPAN lottery are entered as 56 and 44 percent while both posteriors keep their Bayes values. Which results does the Analyzer''s check let through?', '["A refusal, because the indicator chances no longer agree with the stated outcome chances and the Analyzer declines to compute any card.", "A gross value of information of 40.62 beside an EVPI of 52.00, which is what these inputs produce on the four cards and in the sentence.", "EMV without information 75.75 and EVPI 52.00, withholding EMV with information, the gross and net value and the diagram.", "The gross value of 19.84, after rescaling the posteriors so that they fit the stated success chance of 0.350000 again."]'::jsonb, 2, 'The chances sum to 100, so nothing is refused, but they imply success 0.404952 against the stated 0.350000, more than 0.005 away. 40.62 is what these typed numbers give with nothing checking them against the stated prior; the check never repairs.'::text),
      ('intermediate', 'module', 'm05-the-voi-analyzer'::text, 5, 'Before the repair, the VOI Analyzer printed a gross value of information of 69.00 beside an EVPI of 63.00 for a Positive Seismic posterior row summing to 130 percent. What happens now, and what was wrong with 69.00?', '["The inputs are refused with \"Outcome chances given \"Positive Seismic\" sum to 130 percent, expected 100\"; 69.00 was a survey worth more than knowing the answer.", "The value is withheld while 15.00 and 63.00 stay on their cards, since a row that sums past 100 contradicts the stated chances.", "The value is capped at 63.00, because EVPI is the ceiling and a survey can reach it but never pass it.", "The row is rescaled to 100 percent and valued, and 69.00 was wrong only because the old build skipped that step."]'::jsonb, 0, 'A row summing to 130 percent is not a set of chances at all, so it is refused; a withholding is for chances that cannot all be true together. No survey beats perfect information at 63.00.'::text, 'One indicator''s outcome chances add up to 130 percent. Left unchecked, that row would value the survey at 69.00 with EVPI at 63.00. What does the Analyzer return, and why is 69.00 impossible?', '["The inputs are refused with \"Outcome chances given \"Positive Seismic\" sum to 130 percent, expected 100\"; 69.00 is a survey worth more than knowing the answer.", "The value is withheld while 15.00 and 63.00 stay on their cards, since a row that sums past 100 contradicts the stated chances.", "The value is capped at 63.00, because EVPI is the ceiling and a survey can reach it but never pass it.", "The row is rescaled to 100 percent and valued, and 69.00 is wrong only because that rescaling step was skipped."]'::jsonb, 0, 'A row summing to 130 percent is not a set of chances at all, so it is refused; a withholding is for chances that cannot all be true together. No survey beats perfect information at 63.00.'::text),
      ('intermediate', 'module', 'm05-the-voi-analyzer'::text, 6, 'In the Analyzer''s default study, Positive Seismic comes up 40 percent of the time with Success Case at 60 percent, and Negative Seismic 60 percent with Success Case at 10 percent. What check do these typed numbers have to pass?', '["The Success Case entries down the column must add to 100 percent, the way a distribution over indicators would.", "Weighted by the indicator chances they must return the stated Success Case: 40 percent x 60 percent + 60 percent x 10 percent = 30 percent.", "Each posterior must be at least the stated 30 percent, because a survey can only raise the chance it reports on.", "The indicator chances must match the outcome chances, 40 percent against 30 percent and 60 percent against 70 percent, within 0.005 in decimals."]'::jsonb, 1, 'Posteriors carry the prior inside them, so their weighted average must give back the stated chance; the repaired Analyzer withholds when an implied chance sits more than 0.005 from it.'::text, 'In the Analyzer''s default study, Positive Seismic comes up 40 percent of the time with Success Case at 60 percent, and Negative Seismic 60 percent with Success Case at 10 percent. What check do these typed numbers have to pass?', '["The Success Case entries down the column must add to 100 percent, the way a distribution over indicators would.", "Weighted by the indicator chances they must return the stated Success Case: 40 percent x 60 percent + 60 percent x 10 percent = 30 percent.", "Each posterior must be at least the stated 30 percent, because a survey can only raise the chance it reports on.", "The indicator chances must match the outcome chances, 40 percent against 30 percent and 60 percent against 70 percent, within 0.005 in decimals."]'::jsonb, 1, 'Posteriors carry the prior inside them, so their weighted average must give back the stated chance; the Analyzer withholds when an implied chance sits more than 0.005 from it.'::text),
      ('intermediate', 'module', 'm05-the-voi-analyzer'::text, 13, 'At a survey cost of 33.0000 on the Analyzer''s default study the Net VOI card reads 0.00. What do the verdict and the drawn tree''s root say?', '["The verdict calls acquiring positive and the root acquires, since a net value of zero counts as no loss and so as a gain.", "The verdict says the information is not justified and the root reads \"No further information\", because acquiring is chosen only when it strictly gains over not acquiring.", "The verdict says the information exactly pays for itself, and the root still reads \"Acquire 3D Seismic Survey\" because the tied branches keep the first listed.", "The verdict says it exactly pays for itself and the root reads \"No further information\", the branch kept when two values are equal."]'::jsonb, 2, 'The two root branches tie and the engine replaces a branch only on a strictly greater value. At 40.0000 the card reads -7.00 and the root turns to "No further information".'::text, 'At a survey cost of 33.0000 on the Analyzer''s default study the Net VOI card reads 0.00. What do the verdict and the drawn tree''s root say?', '["The verdict calls acquiring positive and the root acquires, since a net value of zero counts as no loss and so as a gain.", "The verdict says the information is not justified and the root reads \"No further information\", because acquiring is chosen only when it strictly gains over not acquiring.", "The verdict says it rounds to zero and acquiring or not is indifferent, and the root marks \"Acquire 3D Seismic Survey\", the first listed of two tied branches.", "The verdict says it rounds to zero, and the root reads \"No further information\", the branch kept when two values are equal."]'::jsonb, 2, 'The two root branches tie; the engine reports the tie and marks the first listed. At 40.0000 the card reads -7.00 and the root turns to "No further information".'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 2, 'Which line is the EKPAN lottery''s value with the CSEM survey, before its cost?', '["0.350000 x 207.7989 + 0.650000 x 9.2361, weighting each signal''s value by the prior of the outcome it points to", "0.460000 x 207.7989 + 0.540000 x 9.2361 = 100.5750", "0.460000 x 207.7989 + 0.540000 x -36.7361, keeping Drill after No bright spot because Drill is best at the prior", "0.460000 x 207.7989 + 0.540000 x 9.2361 less 8.0000, taking the survey cost out before the value is called gross"]'::jsonb, 1, 'Weight by pSignal, never by the prior, and take the best action after each signal: Farm out at 9.2361 after No bright spot. EVII is 100.5750 less 75.7500 = 24.8250.'::text, 'Which line is the EKPAN lottery''s value with the CSEM survey, before its cost?', '["0.350000 x 207.7989 + 0.650000 x 9.2361, weighting each signal''s value by the prior of the outcome it points to", "0.460000 x 207.7989 + 0.540000 x 9.2361 = 100.5750", "0.460000 x 207.7989 + 0.540000 x -36.7361, keeping Drill after No bright spot because Drill is best at the prior", "0.460000 x 207.7989 + 0.540000 x 9.2361 less 8.0000, taking the survey cost out before the value is called gross"]'::jsonb, 1, 'Weight each signal by its pSignal, and take the best action after each signal: Farm out at 9.2361 after No bright spot. EVII is 100.5750 less 75.7500 = 24.8250.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 4, 'The CSEM survey on the EKPAN lottery is quoted at exactly 24.8250. What does the information tree recommend, and what does that mean?', '["\"Acquire CSEM survey\", only because the two root branches tie at 75.7500 and the engine keeps the branch listed first; the money is the same either way.", "\"No further information\", because a net value of zero buys nothing and the engine prefers not to spend on information.", "\"Acquire CSEM survey\", but by floating-point residue, since the two branch values differ in their last binary digits.", "\"Acquire CSEM survey\" on merit, because 24.8250 is below the gross value and the net value at that price is 16.8250."]'::jsonb, 0, 'The neutral price is the gross evii, 24.8250, where acquire is 100.5750 less 24.8250 = 75.7500. An exact tie goes to the first branch; float residue is what decides the drill against farm-out choice at 0.228571.'::text, 'The CSEM survey on the EKPAN lottery is quoted at exactly 24.8250. What does the information tree mark, and what does that mean?', '["\"Acquire CSEM survey\", only because the two root branches tie at 75.7500 and the engine marks the branch listed first; it reports the tie, and the money is the same either way.", "\"No further information\", because a net value of zero buys nothing and the engine prefers not to spend on information.", "\"Acquire CSEM survey\", but by floating-point residue, since the two branch values differ in their last binary digits.", "\"Acquire CSEM survey\" on merit, because 24.8250 is below the gross value and the net value at that price is 16.8250."]'::jsonb, 0, 'The neutral price is the gross evii, 24.8250, where acquire is 100.5750 less 24.8250 = 75.7500. The engine reports the tie and marks the first branch; the drill against farm-out crossing at 0.228571 is a reported tie as well.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 9, 'On IRRI, both indicators are typed 20 / 80 percent into the Analyzer defaults. What does the repaired Analyzer report?', '["EMV without information 15.00 and EVPI 63.00, withholding the rest, because the typing implies success 0.200000 against the 0.300000 stated.", "A gross value of information of -15.00 and a net value of -25.00 on its cards, showing that a survey read this way is worse than useless to the decision.", "A refusal, because two identical rows of chances are not a distribution and cannot be valued.", "A gross value of 0.00, since two identical indicators move nothing and so leave the value at zero."]'::jsonb, 0, 'The rows sum to 100 so nothing is refused, but the implied chance sits far more than 0.005 from the stated one. The -15.00 was printed before the repair, and information derived by Bayes is never worth less than 0.'::text, 'On IRRI, both indicators are typed 20 / 80 percent into the Analyzer defaults. What does the Analyzer report?', '["EMV without information 15.00 and EVPI 63.00, withholding the rest, because the typing implies success 0.200000 against the 0.300000 stated.", "A gross value of information of -15.00 and a net value of -25.00 on its cards, showing that a survey read this way is worse than useless to the decision.", "A refusal, because two identical rows of chances are not a distribution and cannot be valued.", "A gross value of 0.00, since two identical indicators move nothing and so leave the value at zero."]'::jsonb, 0, 'Each row is a valid set of chances, which is why there is no refusal; together they point to a 0.200000 prospect where 0.300000 was stated. Bayes never makes information worth less than 0, so the unguarded -15.00 is a symptom and no value.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 11, 'Working the EKPAN lottery by hand, an analyst''s posteriors weighted by their signal chances do not return the prior of 0.350000. What does that show?', '["A survey informative enough to move the average belief away from the prior, which is what gives it a value above zero.", "A posterior divided by the wrong thing, so every value built on it is wrong before any action is chosen.", "Inputs that contradict each other, which the tree engine would withhold in the way the Analyzer does.", "Rounding to six decimals, which the engine allows for within its 1e-6 tolerance on each probability column it checks."]'::jsonb, 1, 'The check is 0.460000 x 0.646739 + 0.540000 x 0.097222 = 0.350000; a survey moves belief up on one reading and down on the other, never on average.'::text, 'Working the EKPAN lottery by hand, an analyst''s posteriors weighted by their signal chances do not return the prior of 0.350000. What does that show?', '["A survey informative enough to move the average belief away from the prior, which is what gives it a value above zero.", "A posterior divided by the wrong thing, so every value built on it is wrong before any action is chosen.", "Inputs that contradict each other, which the tree engine would withhold in the way the Analyzer does.", "Rounding to six decimals, which the engine allows for within its 1e-6 tolerance on each probability column it checks."]'::jsonb, 1, 'The check is 0.460000 x 0.646739 + 0.540000 x 0.097222 = 0.350000; a survey moves belief up on one reading and down on the other, and it never moves on average.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 12, 'An analyst takes the EKPAN lottery''s survey cost of 8.0000 off inside each signal branch and again at the information tree''s root. What net value do they report?', '["16.8250, since a constant taken off every signal branch cannot change which action wins after either signal, and so cannot change the money either.", "12.8250, since the inner charge is weighted by the signal chances and only about half of it survives to reach the root.", "0.8250, because charging the survey on every branch of the tree is the same as quoting it at 24.0000.", "8.8250, where the net value is 16.8250, because the weights sum to 1 and the inner charges add one more 8.0000."]'::jsonb, 3, 'The acquire branch becomes 84.5750 instead of 92.5750 against 75.7500. The actions do not change, but the money does: subtract the cost once, after the Bayes value.'::text, 'An analyst takes the EKPAN lottery''s survey cost of 8.0000 off inside each signal branch and again at the information tree''s root. What net value do they report?', '["16.8250, since a constant taken off every signal branch cannot change which action wins after either signal, and so cannot change the money either.", "12.8250, since the inner charge is weighted by the signal chances and only about half of it survives to reach the root.", "0.8250, because charging the survey on every branch of the tree is the same as quoting it at 24.0000.", "8.8250, where the net value is 16.8250, because the weights sum to 1 and the inner charges add one more 8.0000."]'::jsonb, 3, 'The acquire branch becomes 84.5750, down from 92.5750, against 75.7500. The actions do not change, but the money does: subtract the cost once, after the Bayes value.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 13, 'Why can the tree engine never withhold a value of information the way the VOI Analyzer does?', '["It quietly rescales any posteriors that fail the check so that they return the stated prior before it values the survey on its own.", "It has a wider consistency tolerance than the Analyzer, so inputs that fail 0.005 there pass here.", "It takes likelihoods and derives the posteriors itself, so its inputs cannot contradict the stated outcome chances.", "It does withhold, but its withheld values print as 0.0000 in the table rather than as a missing card."]'::jsonb, 2, 'Contradictory inputs are only reachable when posteriors are typed by hand, which the Analyzer allows and the tree engine does not.'::text, 'Why can the tree engine never withhold a value of information the way the VOI Analyzer does?', '["It quietly rescales any posteriors that fail the check so that they return the stated prior before it values the survey on its own.", "It has a wider consistency tolerance than the Analyzer, so inputs that fail 0.005 there pass here.", "It takes likelihoods and derives the posteriors itself, so its inputs cannot contradict the stated outcome chances.", "It does withhold, but its withheld values print as 0.0000 in the table, so no card looks missing."]'::jsonb, 2, 'Contradictory inputs are only reachable when posteriors are typed by hand, which the Analyzer allows and the tree engine does not.'::text),
      ('advanced', 'final', null::text, 2, 'A report on IRRI copies the repaired Analyzer and writes the net value of information as 0.00 million USD, on the grounds that nothing was computed. Why is that line wrong?', '["A withheld value is not zero: the entries imply 0.200000 against a stated 0.300000, so there is no net value to quote, and the report should say it is withheld and why.", "It should read -25.00, the net value the same inputs give once the survey cost of 10.0000 is taken off the gross value of -15.00 that Bayes produces for them.", "It should read 23.00, the default study''s net value, because IRRI is the default study and a consistency warning changes the wording of the guidance and not the price.", "The zero is right but incomplete, since a net card of 0.00 means the survey is priced exactly at its gross value and the report must set the survey cost of 10.0000 beside it."]'::jsonb, 0, 'The repaired Analyzer shows only EMV without information 15.00 and EVPI 63.00 on IRRI. The -15.00 gross and -25.00 net are history from before the repair, and writing 0.00 reads a withholding as a card priced at its value.'::text, 'A report on IRRI copies the Analyzer and writes the net value of information as 0.00 million USD, on the grounds that nothing was computed. Why is that line wrong?', '["A withheld value is not zero: the entries imply 0.200000 against a stated 0.300000, so there is no net value to quote, and the report should say it is withheld and why.", "It should read -25.00, the net value the same inputs give once the survey cost of 10.0000 is taken off the gross value of -15.00 that Bayes produces for them.", "It should read 23.00, the default study''s net value, because IRRI is the default study and a consistency warning changes the wording of the guidance and not the price.", "The zero is right but incomplete, since a net card of 0.00 means the survey is priced exactly at its gross value and the report must set the survey cost of 10.0000 beside it."]'::jsonb, 0, 'The Analyzer shows only EMV without information 15.00 and EVPI 63.00 on IRRI. The -15.00 gross and -25.00 net are what the typed chances give with nothing checking them against the stated prior, and writing 0.00 reads a withholding as a card priced at its value.'::text),
      ('advanced', 'final', null::text, 3, 'Two entries each sit exactly on the edge of their check in decimal: typed posteriors implying 0.305000 against a stated 0.300000, and three branches typed 0.333333 on the node "Three equal outcomes". What does the engine do with each today?', '["It accepts both, since the EC4-0 repair that resolved finding D1 gave every probability comparison in the engine the same 1e-12 representation allowance.", "It refuses both, because each lands a hair outside its tolerance in binary arithmetic, 0.0050000000000000044 for the first and a sum printed as 0.999999 for the second.", "It accepts the second, rounding a sum of 0.999999 to 1 before comparing, and refuses the first, because the half percent check is exclusive at its boundary.", "It accepts the first, because the half percent check adds a 1e-12 allowance, and refuses the second, because the 1e-6 sum test has no allowance for binary rounding."]'::jsonb, 3, '0.305 - 0.3 is 0.0050000000000000044 in binary and passes only by the 1e-12 allowance; three copies of 0.333333 miss 1 by a binary gap just above 1e-6, and that comparison was left strict (EC4-8, still open).'::text, 'Two entries each sit exactly on the edge of their check in decimal: typed posteriors implying 0.305000 against a stated 0.300000, and three branches typed 0.333333 on the node "Three equal outcomes". What does the engine do with each?', '["It accepts both, since the half percent check and the 1e-6 sum test each add a 1e-12 allowance for binary representation; the node rolls back at 59.9999.", "It refuses both, because each lands a hair outside its tolerance in binary arithmetic, 0.0050000000000000044 for the first and a sum printed as 0.999999 for the second.", "It accepts the second, rounding a sum of 0.999999 to 1 before comparing, and refuses the first, because the half percent check is exclusive at its boundary.", "It accepts the first, because the half percent check adds a 1e-12 allowance, and refuses the second, because the 1e-6 sum test compares against 1e-6 alone."]'::jsonb, 0, '0.305 - 0.3 is 0.0050000000000000044 in binary and passes by the 1e-12 allowance; three copies of 0.333333 miss 1 by a binary hair above 1e-6 and pass by the same allowance, so the node pays 30, 60 and 90 at 0.333333 each and is worth 59.9999.'::text),
      ('advanced', 'final', null::text, 4, 'A Decision Studio brief on a saved two-branch tree reads Optimal EMV 20.0000 with first move "A". Branch A pays 20 and was meant to carry a cost of 5; branch B pays 12. The provenance line names the saved tree. What does the brief tell a reader about that cost?', '["That it was charged, since the rollback refuses a cost that is not a number, and Decision Studio cannot brief a tree that the engine has refused to roll back at all, whatever its provenance line says.", "That it was never charged: A is worth exactly its payoff, which is what a cost typed as \"abc\", left empty or cleared in the Builder gives, and no line of the brief flags it.", "That it was typed as the text \"5\", which the engine reads as a number and which leaves branch A at its full payoff of 20.", "Nothing either way, because the brief prints each root value before the cost on its branch, so 20.0000 would appear whether or not the 5 was charged."]'::jsonb, 1, 'With the cost charged A is worth 15.0000; a non-numeric, empty or absent cost is charged as 0 and A reads 20.0000, and the brief re-rolls the saved tree with every silent default it carries.'::text, 'A Decision Studio brief on a saved two-branch tree reads Optimal EMV 20.0000 with first move "A". Branch A pays 20 and was meant to carry a cost of 5; branch B pays 12. The provenance line names the saved tree. What does the brief tell a reader about that cost?', '["That it was charged, since the rollback refuses a cost that is not a number, and Decision Studio cannot brief a tree that the engine has refused to roll back at all, whatever its provenance line says.", "That it was never charged: A is worth exactly its payoff, which is what a cost left out of the saved tree gives, and no line of the brief flags it.", "That it was typed as the text \"5\", which the engine reads as a number and which leaves branch A at its full payoff of 20.", "Nothing either way, because the brief prints each root value before the cost on its branch, so 20.0000 would appear whether or not the 5 was charged."]'::jsonb, 1, 'With the cost charged A is worth 15.0000. A cost typed as "abc" or left as an empty entry is refused by node label, so a brief that prints 20.0000 re-rolled a tree whose cost was left out, which the engine reads as 0 without a message; clearing a cost box in the Builder removes the entry in just that way.'::text),
      ('advanced', 'final', null::text, 6, 'The published equalEmvTie tree in a brief and the Analyzer tie case (Success 25 percent paying 200, Dry hole 75 percent paying -50, decision cost 12.5) each name a winner at an exact tie. Where can a reader see that it is a tie?', '["On both screens: the brief marks the first move as indifferent, and the Analyzer adds a consistency warning whenever its two actions are equal at 0.00.", "On neither, since both round the values to two decimals, so the tied branch and the one worth 29.9990 cannot be told apart from 30.0000 on either screen.", "In the Analyzer, as a net value of 20.00 equal to EMV with information, and in the brief, by naming A and B together as the first move.", "In the brief, a Decision advantage row of 0.0000; the Analyzer prints no margin, and its insight names ''Drill Exploration Well'' beside an EMV of 0.00."]'::jsonb, 3, 'Both apps keep whichever branch or action is listed first, because the comparison is strictly greater. Only the brief''s derived advantage row prints the zero margin; the Analyzer''s cards (0.00, 20.00, 20.00, 46.88) never compare its two actions.'::text, 'The published equalEmvTie tree in a brief and the Analyzer tie case (Success 25 percent paying 200, Dry hole 75 percent paying -50, decision cost 12.5) both sit on an exact tie. Where can a reader see that it is a tie?', '["Only in the brief, through a Decision advantage row of 0.0000 beside the first move, while the Analyzer names ''Drill Exploration Well'' as the optimal decision and prints no margin at all.", "On neither, since both round the values to two decimals, so the tied branch and the one worth 29.9990 cannot be told apart from 30.0000 on either screen.", "In the Analyzer, as a net value of 20.00 equal to EMV with information, and in the brief, by naming A and B together on the first-move row and leaving C off at 29.9990.", "On both: the brief names A, B and C together and writes Indifferent at the precision shown, and the Analyzer''s insight says both actions come to the same figure."]'::jsonb, 3, 'The brief reads the card-precision tie set, where C''s 29.9990 rounds to the same 30.00, and the Analyzer''s insight opens by saying ''Drill Exploration Well'' and ''Do Not Drill Exploration Well'' both come to $0.00M, so the decision without new information is indifferent between them.'::text),
      ('advanced', 'final', null::text, 7, 'On the Analyzer''s default study one survey is tendered at 32.996 and another at 33.004. A reviewer reads both netVoi cards and both verdict sentences. What should the report say?', '["That both are priced at the gross voi of 33.00: the cards read 0.00 and -0.00 while the verdicts, which test the unrounded net value, split positive and negative.", "That the first is worth buying and the second is not, exactly as the verdict sentences state, since the unrounded net value is the more precise of the two readings.", "That both are value-neutral, as the cards say, because the verdict sentence is written from the rounded card and simply lags it by one step of rounding.", "That neither can be judged, because the Analyzer withholds the net value once the survey cost comes within 0.005 of the gross value."]'::jsonb, 0, 'The cards are two-decimal strings and the verdict reads the sign of a difference far smaller than any cost estimate resolves. The neutral price is the gross value, 33.00 here, so the survey is priced at its value.'::text, 'On the Analyzer''s default study one survey is tendered at 32.996 and another at 33.004. A reviewer reads both netVoi cards and both verdict sentences. What should the report say?', '["That both are priced at the gross voi of 33.00: both cards read 0.00 and both verdicts say the value rounds to zero, from one rounded net value.", "That the first is worth buying and the second is not, exactly as the verdict sentences state, since the unrounded net value is the more precise of the two readings.", "That the second is priced a hair above its value, since its card prints -0.00 and a negative zero keeps the sign of the unrounded net value.", "That neither can be judged, because the Analyzer withholds the net value once the survey cost comes within 0.005 of the gross value."]'::jsonb, 0, 'One rounding feeds both the card and the sentence, so they cannot split; information turns neutral at a price equal to its gross value, 33.00 here, and both tenders sit within half a cent of it.'::text),
      ('advanced', 'final', null::text, 8, 'Three negative numbers came out of these tools: a gross voi of -15.00 for IRRI before the repair, an EVII of -1.42e-14 for the symmetric EKPAN lottery survey at accuracy 0.550000, and a netVoi card of -17.00 on the pricey case. Which signals inputs that cannot all be true?', '["All three, because a value of information below zero, gross or net, is impossible for a signal that the decision maker is always free to ignore and never has to act on.", "The -15.00 and the -1.42e-14, since both are gross values of information below the floor of zero, while the -17.00 is a net value and therefore a legitimate answer.", "Only the -15.00: a gross value derived by Bayes cannot fall below 0, while -1.42e-14 is float residue printed as 0.0000 and -17.00 is a price above the value.", "Only the -17.00, because the pricey case charges 50.0000 for a survey worth 33.00, and a value of information below its own cost means the typed chances disagree."]'::jsonb, 2, 'A negative net value says the price is too high; a negative gross value says the entries contradict the stated prior. The engine reports EVII residue below 1e-9 as 0.0000.'::text, 'Three negative numbers come out of these tools: a gross voi of -15.00 from IRRI''s typed chances weighted with nothing checking them against the stated prior, an EVII of -1.42e-14 for the symmetric EKPAN lottery survey at accuracy 0.550000, and a netVoi card of -17.00 on the pricey case. Which signals inputs that cannot all be true?', '["All three, because a value of information below zero, gross or net, is impossible for a signal that the decision maker is always free to ignore and never has to act on.", "The -15.00 and the -1.42e-14, since both are gross values of information below the floor of zero, while the -17.00 is a net value and therefore a legitimate answer.", "Only the -15.00: a gross value derived by Bayes cannot fall below 0, while -1.42e-14 is float residue printed as 0.0000 and -17.00 is a price above the value.", "Only the -17.00, because the pricey case charges 50.0000 for a survey worth 33.00, and a value of information below its own cost means the typed chances disagree."]'::jsonb, 2, 'A negative net value says the price is too high; a negative gross value says the entries contradict the stated prior. The engine returns an EVII of -1.42e-14, float residue that prints as 0.0000.'::text),
      ('advanced', 'final', null::text, 10, 'In the engine, the published impossibleSignal case lists a reading "Never" with likelihoods 0.000000 / 0.000000. In the Analyzer, missingOutcomeChanceCountsAsZero leaves one outcome chance given Positive Seismic blank. How does each tool answer?', '["The engine accepts the survey, gives Never the priors as its posterior and returns evii 12.5000 with no warning; the Analyzer refuses, naming a sum of 60 percent.", "Both refuse, the engine because a reading with pSignal 0.000000 cannot be divided by, and the Analyzer because a blank entry lies outside the range of 0 to 100 percent.", "Both accept and count the blank as zero, the engine returning evii 12.5000 and the Analyzer printing a gross voi of 41.00 in its guidance sentence beside its EVPI card of 63.00.", "The engine refuses Never because its likelihoods sum to 0, and the Analyzer withholds the value while it keeps EMV without information 15.00."]'::jsonb, 0, 'Never adds 0 to each outcome''s column, so both columns still sum to 1 and pSignal 0.000000 is the only sign. The Analyzer checks every distribution in percent first; 41.00 is what it printed before the repair.'::text, 'In the engine, the published impossibleSignal case lists a reading "Never" with likelihoods 0.000000 / 0.000000. In the Analyzer, missingOutcomeChanceCountsAsZero leaves one outcome chance given Positive Seismic blank. How does each tool answer?', '["The engine accepts the survey, gives Never the priors as its posterior and returns evii 12.5000 with no warning; the Analyzer refuses, naming a sum of 60 percent.", "Both refuse, the engine because a reading with pSignal 0.000000 cannot be divided by, and the Analyzer because a blank entry lies outside the range of 0 to 100 percent.", "Both accept and count the blank as zero, the engine returning evii 12.5000 and the Analyzer printing a gross voi of 41.00 in its guidance sentence beside its EVPI card of 63.00.", "The engine refuses Never because its likelihoods sum to 0, and the Analyzer withholds the value while it keeps EMV without information 15.00."]'::jsonb, 0, 'Never adds 0 to each outcome''s column, so both columns still sum to 1 and pSignal 0.000000 is the only sign. The Analyzer checks every distribution in percent first; 41.00 is what the typed numbers give with nothing checking them.'::text),
      ('advanced', 'final', null::text, 15, 'The published chanceRootWithBranchCosts tree is shown in a Decision Studio brief and on the Decision Tree Builder''s cards. What do the two surfaces show?', '["Both give -8.6000 and recommend the calm branch, whose value of 17.0000 beats the storm branch at -33.0000 by a Decision advantage of 50 shown on both of the surfaces.", "The brief gives -3.0000 with \"Single path\" as the route the engine picked, while the Builder refuses the tree outright because a chance node cannot sit at the root of a tree.", "Both give -3.0000 and write \"Single path\", with the next best row printed as 0.0000 because there is no alternative worth anything.", "Both give -3.0000; the brief writes \"Single path\" and prints no next best or advantage row, and the Builder writes \"Chance root\" with N/A on the other two cards."]'::jsonb, 3, 'A chance root offers no choice, so there is nothing to recommend or compare against. The -3.0000 charges each cost on its own branch before weighting; subtracting the costs after weighting gives -8.6000.'::text, 'The published chanceRootWithBranchCosts tree is shown in a Decision Studio brief and on the Decision Tree Builder''s cards. What do the two surfaces show?', '["Both give -8.6000 and recommend the calm branch, whose value of 17.0000 beats the storm branch at -33.0000 by a Decision advantage of 50 shown on both of the surfaces.", "The brief gives -3.0000 with calm as the route the engine picked, while the Builder refuses the tree outright because a chance node cannot sit at the root of a tree.", "Both give -3.0000 and read Chance root: no first decision to make, with the next best row printed as 0.0000 because there is no alternative worth anything.", "Both give -3.0000 and read Chance root: no first decision to make; the brief prints no next best or advantage row, and the Builder shows N/A on those two cards."]'::jsonb, 3, 'A chance root offers no choice, so both screens share one first-move label and there is nothing to compare. The -3.0000 charges each cost on its own branch before weighting; subtracting the costs after weighting gives -8.6000.'::text),
      ('advanced', 'final', null::text, 17, 'The same slip is made in two tools: outcome chances that add to 90 percent are typed into the repaired Analyzer, and priors that add to 0.900000 are passed to the Bayes engine. What does each return?', '["Both refuse with the fraction message, since the Analyzer hands its percent entries straight to the same Bayes check as the engine and simply prints whatever message it gets back on screen.", "The engine refuses, while the Analyzer rescales the outcome chances so that they add to 100 percent, values the survey on the rescaled chances and marks each of its cards as approximate.", "The Analyzer withholds the value of information and keeps EMV without information and EVPI on screen, while the engine, which has no withholding state of its own, refuses the priors outright.", "Each refuses before computing anything, the Analyzer with \"Outcome chances sum to 90 percent, expected 100\" and the engine with \"Outcome probabilities sum to 0.900000, expected 1\"."]'::jsonb, 3, 'Chances that are not a distribution are refused in both, and the repaired Analyzer names the sum in percent on a form that takes percent. Withholding is kept for distributions that contradict each other, as IRRI''s do.'::text, 'The same slip is made in two tools: outcome chances that add to 90 percent are typed into the Analyzer, and priors that add to 0.900000 are passed to the Bayes engine. What does each return?', '["Both refuse with the fraction message, since the Analyzer hands its percent entries straight to the same Bayes check as the engine and simply prints whatever message it gets back on screen.", "The engine refuses, while the Analyzer rescales the outcome chances so that they add to 100 percent, values the survey on the rescaled chances and marks each of its cards as approximate.", "The Analyzer withholds the value of information and keeps EMV without information and EVPI on screen, while the engine, which has no withholding state of its own, refuses the priors outright.", "Each refuses before computing anything, the Analyzer with \"Outcome chances sum to 90 percent, expected 100\" and the engine with \"Outcome probabilities sum to 0.900000, expected 1\"."]'::jsonb, 3, 'Chances that are not a distribution are refused in both, and the Analyzer names the sum in percent on a form that takes percent. Withholding is kept for distributions that contradict each other, as IRRI''s do.'::text),
      ('advanced', 'final', null::text, 18, 'Two repairs are proposed: nudging one of three 0.333333 branches up until the sum reaches 1, and nudging typed posteriors until the implied prior lands at 0.305000. What do the two repairs share?', '["Each makes a check pass by bending the inputs it protects: the thirds stop being equal and the EMV leaves 60.0000, and the posteriors keep the contradiction behind 34.75, only less of it.", "Each is the documented repair, since the rollback expects one branch to absorb the rounding error and the Analyzer''s allowance exists for posteriors tuned onto its boundary on purpose by the person typing them.", "Neither changes a value, because the nudge in each case is smaller than the tolerance it clears, 1e-6 on the sum and 0.005 on the implied prior.", "Each is harmless for the thirds and harmful for the posteriors, because a sum nudged to 1 still weights the payoffs of 30, 60 and 90 equally."]'::jsonb, 0, 'Thirds typed to seven places, 0.3333333, roll back to 60.0000 without favouring a branch. A value accepted at 0.305000 is not certified: moving the default study there raised the gross voi from 33.00 to 34.75.'::text, 'Two fixes are proposed: nudging one of three branches typed 0.333 up until the sum reaches 1, and nudging typed posteriors until the implied prior lands at 0.305000. What do the two fixes share?', '["Each makes a check pass by bending the inputs it protects: the thirds stop being equal and the EMV leaves 60.0000, and the posteriors keep the contradiction behind 34.75, only less of it.", "Each is the documented fix, since the rollback expects one branch to absorb the rounding error and the Analyzer''s allowance exists for posteriors tuned onto its boundary on purpose by the person typing them.", "Neither changes a value, because the nudge in each case is smaller than the tolerance it clears, 1e-6 on the sum and 0.005 on the implied prior.", "Each is harmless for the thirds and harmful for the posteriors, because a sum nudged to 1 still weights the payoffs of 30, 60 and 90 equally."]'::jsonb, 0, 'Thirds typed to six places or more, 0.333333 or 0.3333333, pass without favouring a branch, at 59.9999 and 60.0000. A value accepted at 0.305000 is not certified: moving the default study there raised the gross voi from 33.00 to 34.75.'::text),
      ('advanced', 'final', null::text, 19, 'A reviewer tests a typed survey only by averaging its posteriors back to the priors, and on posteriorsOffsetButPriorsAgree the implied chances match the stated ones. What does the repaired Analyzer do with that entry?', '["It values it normally, since the only test standing between typed posteriors and a value is the implied-prior check, and this case passes that check.", "It withholds the value of information and keeps EMV without information 15.00 and EVPI 63.00, the answer every failed check produces.", "It refuses it before any consistency test, because the outcome chances given Positive Seismic sum to 110 percent and are not a distribution.", "It prints a gross voi of 42.50 beside EVPI 63.00, because the allowance of 1e-4 percentage points covers a sum that misses by ten."]'::jsonb, 2, 'Each distribution is checked in percent first, so this case never reaches the implied-prior test. Before the repair the same entry printed 42.50, plausible and under the ceiling.'::text, 'A reviewer tests a typed survey only by averaging its posteriors back to the priors, and on posteriorsOffsetButPriorsAgree the implied chances match the stated ones. What does the Analyzer do with that entry?', '["It values it normally, since the only test standing between typed posteriors and a value is the implied-prior check, and this case passes that check.", "It withholds the value of information and keeps EMV without information 15.00 and EVPI 63.00, the answer every failed check produces.", "It refuses it before any consistency test, because the outcome chances given Positive Seismic sum to 110 percent and are not a distribution.", "It prints a gross voi of 42.50 beside EVPI 63.00, because the allowance of 1e-4 percentage points covers a sum that misses by ten."]'::jsonb, 2, 'Each distribution is checked in percent first, so this case never reaches the implied-prior test. Weighted as typed with nothing checking them, the same entries give 42.50, plausible and under the ceiling.'::text),
      ('advanced', 'final', null::text, 20, 'Before the EC4-0 repair the Analyzer printed gross values of 245.00 for certainPosteriorsWithheld, 40.62 for the EKPAN lottery typed with indicators at 56 and 44 percent, and 33.00 for indicatorChancesAboveHundred. Which could a check on the output, between 0 and EVPI, have caught?', '["All three, because each differs from the value the same survey has when it is typed correctly, and an output check compares every printed figure against that value.", "Only the 245.00, above its EVPI of 63.00; 40.62 sits under 52.00 and 33.00 is the default study''s genuine value, which is why the repair tests the inputs.", "The 245.00 and the 40.62, since both exceed the honest EKPAN lottery value of 19.84, and an output check bounds each figure by the full-precision value of the survey.", "None of them, because a gross voi appears only in the guidance sentence and the CSV export, where no check of any kind is applied."]'::jsonb, 1, 'A bound on the output sees only values outside 0 to EVPI. 40.62 against 52.00 and 33.00 against 63.00 look ordinary, so the repaired Analyzer refuses or withholds on the inputs instead.'::text, 'Weighted as typed with nothing checking them, published certainPosteriorsWithheld gives a gross voi of 245.00, the EKPAN lottery typed with indicators at 56 and 44 percent gives 40.62, and indicatorChancesAboveHundred gives 33.00. Which could a check on the output, between 0 and EVPI, have caught?', '["All three, because each differs from the value the same survey has when it is typed correctly, and an output check compares every printed figure against that value.", "Only the 245.00, above its EVPI of 63.00; 40.62 sits under 52.00 and 33.00 is the default study''s genuine value, which is why the Analyzer tests the inputs.", "The 245.00 and the 40.62, since both exceed the honest EKPAN lottery value of 19.84, and an output check bounds each figure by the full-precision value of the survey.", "None of them, because a gross voi appears only in the guidance sentence and the CSV export, where no check of any kind is applied."]'::jsonb, 1, 'A bound on the output sees only values outside 0 to EVPI. 40.62 against 52.00 and 33.00 against 63.00 look ordinary, so the Analyzer refuses or withholds on the inputs.'::text),
      ('advanced', 'final', null::text, 25, 'The likelihood 0.850000 is used as a posterior twice: by hand in the EKPAN lottery''s Bayes step, and in the Analyzer as the Success chance given Bright spot, with the Dry hole chance given Bright spot typed so the pair still sums to 100. What goes wrong in each?', '["Both value the drill after a bright spot at 298.2500, because the Analyzer and the Bayes step put the same success chance against the same payoffs.", "Nothing goes wrong in either, because a likelihood equals its posterior whenever every column of the survey sums to 1.", "By hand the drill after a bright spot is valued at 298.2500 instead of 207.7989; in the Analyzer the implied Success misses 0.350000 by far more than 0.005, so the value is withheld.", "By hand nothing moves, because Bayes renormalises, and the Analyzer refuses the box as a likelihood typed where a posterior belongs."]'::jsonb, 2, '0.850000 is the chance of a bright spot given success, and the posterior is 0.646739. Typed at 46.000000 percent, a Success chance that high after Bright spot averages back far above the stated chance, and the Analyzer never repairs it.'::text, 'The likelihood 0.850000 is used as a posterior twice: by hand in the EKPAN lottery''s Bayes step, and in the Analyzer as the Success chance given Bright spot, with the Dry hole chance given Bright spot typed so the pair still sums to 100. What goes wrong in each?', '["Both value the drill after a bright spot at 298.2500, because the Analyzer and the Bayes step put the same success chance against the same payoffs.", "Nothing goes wrong in either, because a likelihood equals its posterior whenever every column of the survey sums to 1.", "By hand the drill after a bright spot is valued at 298.2500 where 207.7989 is right; in the Analyzer the implied Success misses 0.350000 by far more than 0.005, so the value is withheld.", "By hand nothing moves, because Bayes renormalises, and the Analyzer refuses the box as a likelihood typed where a posterior belongs."]'::jsonb, 2, '0.850000 is the chance of a bright spot given success, and the posterior is 0.646739. Typed at 46.000000 percent, a Success chance that high after Bright spot averages back far above the stated chance, and the Analyzer never repairs it.'::text),
      ('advanced', 'final', null::text, 27, 'The EKPAN lottery typed with posteriors of 64.7 and 9.7 percent gives an implied Success of exactly 0.350000, a delta of 0.000000e+0, and a gross voi of 19.89. At full precision the delta is 5.551115e-17 and the gross voi 19.84. Which entry describes the survey?', '["The rounded one, because a delta of exactly zero is a stronger consistency result than the binary residue of 5.551115e-17 that the full-precision entry leaves behind.", "The full-precision one: a zero delta says only that the entries agree with the stated chance, and the rounded posteriors describe a slightly different survey.", "Both equally, because the Analyzer treats every entry whose delta is inside 0.005 as the same survey, and the gap between 19.89 and 19.84 is only rounding noise on the card.", "Neither, because a delta below 1e-12 falls inside the representation allowance and the Analyzer withholds what it cannot tell from zero."]'::jsonb, 1, 'Six rounded EKPAN lottery rows pass the check with gross values from 18.41 to 20.51. The survey is the same in every row; a pass certifies agreement, not precision.'::text, 'The EKPAN lottery typed with posteriors of 64.7 and 9.7 percent gives an implied Success of exactly 0.350000, a delta of 0.000000e+0, and a gross voi of 19.89. At full precision the delta is 5.551115e-17 and the gross voi 19.84. Which entry describes the survey?', '["The rounded one, because a delta of exactly zero is a stronger consistency result than the binary residue of 5.551115e-17 that the full-precision entry leaves behind.", "The full-precision one: a zero delta says only that the entries agree with the stated chance, and the rounded posteriors describe a slightly different survey.", "Both equally, because the Analyzer treats every entry whose delta is inside 0.005 as the same survey, and the gap between 19.89 and 19.84 is only rounding noise on the card.", "Neither, because a delta below 1e-12 falls inside the representation allowance and the Analyzer withholds what it cannot tell from zero."]'::jsonb, 1, 'Five rounded EKPAN lottery rows pass the check with gross values from 18.41 to 20.51, and the sixth passing row is the full-precision 19.84 entry. The survey is the same in every row; a pass certifies agreement and says nothing of precision.'::text),
      ('advanced', 'final', null::text, 28, 'Before the repair contradictingPosterior printed a gross voi of 75.00 beside an EVPI of 63.00. A colleague proposes restoring such values but capping each one at its EVPI. What is wrong with that?', '["Nothing, since the excess of 12 over EVPI is exactly the part the contradiction added, and removing it leaves the honest value of the survey.", "A cap sets the value too low, because EVPI binds only information derived by Bayes, and typed posteriors can legitimately be worth more than knowing the outcome in advance when the survey is a good one.", "The cap should be EMV without information, 15.00, since no survey can be worth more than the prospect it studies.", "A capped 63.00 still rests on posteriors implying 0.420000 against a stated 0.300000, and a cap never touches contradictions that print under the ceiling, such as 40.62 for the EKPAN lottery."]'::jsonb, 3, 'The with side weights a prospect succeeding 0.420000 of the time against one stated at 0.300000, so the uplift is belief, not information. The repaired Analyzer never clips and never repairs.'::text, 'A colleague wants the Analyzer to print contradictingPosterior''s unguarded 75.00 again, only capped at the 63.00 EVPI. What is wrong with that plan?', '["Nothing, since the excess of 12 over EVPI is exactly the part the contradiction added, and removing it leaves the honest value of the survey.", "A cap sets the value too low, because EVPI binds only information derived by Bayes, and typed posteriors can legitimately be worth more than knowing the outcome in advance when the survey is a good one.", "The cap should be EMV without information, 15.00, since no survey can be worth more than the prospect it studies.", "A capped 63.00 still rests on posteriors implying 0.420000 against a stated 0.300000, and a cap never touches contradictions that print under the ceiling, such as 40.62 for the EKPAN lottery."]'::jsonb, 3, 'The with side weights a prospect succeeding 0.420000 of the time against one stated at 0.300000, so the uplift is belief with no information in it. The Analyzer withholds the value outright and prints no clipped figure.'::text),
      ('advanced', 'final', null::text, 29, 'The published three-outcome, four-action lottery records Farm out as the best action for Dry under perfect information. If Relinquish were listed before Farm out, what would change?', '["Nothing, because the engine prefers the action with positive payoffs in the other outcomes whenever two actions tie in one outcome.", "evWithPerfect would fall, since Relinquish pays nothing in Large or Medium and perfect information averages each action over all three outcomes.", "emvPrior would switch to Relinquish at 0.0000, because listing order decides the prior choice whenever two actions tie in any outcome.", "The action recorded for Dry would read Relinquish, and evWithPerfect 133.0000 and the EVPI of 24.0000 would stay where they are."]'::jsonb, 3, 'Farm out and Relinquish both pay 0.0000 in Dry at no cost; the strictly greater comparison keeps the first listed. EVPI takes the best value per outcome, which is 0.0000 either way.'::text, 'The published three-outcome, four-action lottery records Farm out as the best action for Dry under perfect information. If Relinquish were listed before Farm out, what would change?', '["Nothing, because the engine prefers the action with positive payoffs in the other outcomes whenever two actions tie in one outcome.", "evWithPerfect would fall, since Relinquish pays nothing in Large or Medium and perfect information averages each action over all three outcomes.", "emvPrior would switch to Relinquish at 0.0000, because listing order decides the prior choice whenever two actions tie in any outcome.", "The action recorded for Dry would read Relinquish, and evWithPerfect 133.0000 and the EVPI of 24.0000 would stay where they are."]'::jsonb, 3, 'Farm out and Relinquish both pay 0.0000 in Dry at no cost and tie, and the golden records the first listed of the pair. EVPI takes the best value per outcome, which is 0.0000 either way.'::text),
      ('advanced', 'final', null::text, 31, 'On a two-branch chance node paying 10 and 30, one probability is typed as the text "0.5" beside 0.5; on a second copy the probability on the branch paying 10 is left empty beside 1 on the branch paying 30. What does each node roll back to?', '["20.0000 and a refusal, since an empty probability leaves the sum short of 1 and the engine returns a message that names the node at fault instead of a value.", "A refusal and 30.0000, because a probability typed as text is not a number and is refused in the same way as a payoff typed as \"20abc\", before any weighting.", "20.0000 and 30.0000: text that reads as a number is converted, and an empty probability is read as 0, so the second node weights only the branch paying 30.", "20.0000 both times, because an empty probability is shared out evenly with the other branch before the sum is checked."]'::jsonb, 2, 'A cleared probability usually surfaces as a sum that is not 1; it passes only when the other branches already sum to 1, and then its branch vanishes from the weighting without a message.'::text, 'On a two-branch chance node paying 10 and 30, one probability is typed as the text "0.5" beside 0.5; on a second copy the probability on the branch paying 10 is left empty beside 1 on the branch paying 30. What does each node roll back to?', '["20.0000 and a refusal, since an empty probability leaves the sum short of 1 and the engine returns a message that names the node at fault and gives no value.", "A refusal and 30.0000, because a probability typed as text is not a number and is refused in the same way as a payoff typed as \"20abc\", before any weighting.", "20.0000 and 30.0000: text that reads as a number is converted, and an empty probability is read as 0, so the second node weights only the branch paying 30.", "20.0000 both times, because an empty probability is shared out evenly with the other branch before the sum is checked."]'::jsonb, 2, 'A cleared probability usually surfaces as a sum that is not 1; it passes only when the other branches already sum to 1, and then its branch vanishes from the weighting without a message.'::text),
      ('advanced', 'final', null::text, 32, 'A reviewer checks, on the decision where A pays 20 meant at a cost of 5 and B pays 12, that A''s branch value equals its payoff less the intended cost. What does A reading 20.0000, and on another copy 25.0000, reveal?', '["At 20.0000 the payoff was typed as the text \"20\", and at 25.0000 a probability was typed as text, each converted with a rounding error.", "At 20.0000 the cost was never charged, being text, empty or absent; at 25.0000 a cost of -5 was accepted as money received.", "Both are refusals the reviewer missed, since the engine returns the payoff unchanged whenever it rejects a cost.", "At 20.0000 the cost was charged after the branch was chosen, and at 25.0000 it was charged twice in the wrong direction."]'::jsonb, 1, '"5" as text converts to 5 and gives 15.0000; anything else non-numeric is 0, and a negative cost is a receipt. A stays the first move in both, so only the arithmetic shows it.'::text, 'A reviewer checks, on the decision where A pays 20 meant at a cost of 5 and B pays 12, that A''s branch value equals its payoff less the intended cost. One copy reads A at 20.0000, and another copy returns a refusal naming branch A. What does each reveal?', '["At 20.0000 the payoff was typed as the text \"20\", and the refusal comes from a probability typed as text on one of the branches.", "At 20.0000 the cost was left out of the tree and read as 0; the refusal comes from a cost typed as text that is not a number or below zero, which the engine will not read as money.", "Both are refusals the reviewer missed, since the engine returns the payoff unchanged whenever it rejects a cost.", "At 20.0000 the cost was charged after the branch was chosen, and the refusal comes from a cost of 5 typed as the text \"5\"."]'::jsonb, 1, 'A cost of "5" typed as text converts to 5 and gives 15.0000. A cost left out reads 0 with no message, while a cost of "abc", an empty entry or -5 is refused by node label, so only the arithmetic shows the omitted cost.'::text),
      ('advanced', 'final', null::text, 33, 'At p = 80 / 350 on the EKPAN lottery the engine names Farm out; at success 0.200000 the published drillFarmOut tree names Drill. Which of these results is the tie rule at work?', '["Only drillFarmOut, an exact tie at 12.0000 with Drill listed first; at 80 / 350 the two values differ by -7.11e-15 and the choice is that binary residue.", "Both, since each is an exact tie and the engine names the branch it was given first, which is Drill on the published tree and Farm out on the EKPAN lottery.", "Only the lottery, because at 0.228571 the EVPI peaks at 61.7143, and the engine breaks a tie there toward Farm out, the one action on the lottery that cannot lose money.", "Neither, because the engine has no tie rule at all, and each of the two results comes from floating-point residue in the last binary digits of the two values."]'::jsonb, 0, 'The first listed option wins an exact tie because the comparison is strictly greater. On the lottery Drill is listed before Farm out, so Farm out winning at 21.7143 against 21.7143 can only be residue.'::text, 'At p = 80 / 350 on the EKPAN lottery and at success 0.200000 on the published drillFarmOut tree, Drill and Farm out print the same value. What does the engine report at each?', '["A tie at both, each marking Drill as the first listed: drillFarmOut ties exactly at 12.0000, and the lottery''s -7.11e-15 is residue inside the band.", "A tie only on drillFarmOut; at 80 / 350 Farm out is larger by -7.11e-15 of residue, so the engine names it as the single best action.", "A tie only on the lottery, because at 0.228571 the EVPI peaks at 61.7143 and the engine reads that peak as indifference between the two actions.", "Neither, because the engine has no tie rule at all, and each of the two results comes from floating-point residue in the last binary digits of the two values."]'::jsonb, 0, 'Two values tie when they differ by at most 1e-9 x max(1, |best|): 12.0000 against 12.0000 is exact, and -7.11e-15 is far inside the band. The engine reports indifferent true at both and marks Drill, listed first.'::text),
      ('advanced', 'final', null::text, 34, 'The Analyzer tie case (Success 25 percent paying 200, Dry hole 75 percent paying -50, decision cost 12.5, survey cost 5.0000) names ''Drill Exploration Well'' as optimal and gives a gross voi of 25.00. What do those two outputs tell a reader?', '["Drilling is better by a margin of 25.00, the value the survey adds on top of the drill''s EMV without information of 0.00.", "The survey is worth 25.00 because the Analyzer drops the tied Do Not action and values the information against the drill alone.", "The recommendation is only the listing order, since acting and Do Not are both worth 0, and the survey is valuable because a decision that unsettled can be tipped by any signal.", "The inputs are inconsistent, because a tied prior leaves the implied chances undefined, so 25.00 is a figure from before the repair."]'::jsonb, 2, 'Acting is 0.25 x 200 plus 0.75 x -50, less 12.5, which is 0. EVPI peaks at a switch for the same reason, 61.7143 at 0.228571 on the EKPAN lottery.'::text, 'The Analyzer tie case (Success 25 percent paying 200, Dry hole 75 percent paying -50, decision cost 12.5, survey cost 5.0000) opens its insight by saying ''Drill Exploration Well'' and ''Do Not Drill Exploration Well'' both come to $0.00M, and gives a gross voi of 25.00. What do those two outputs tell a reader?', '["Drilling is better by a margin of 25.00, the value the survey adds on top of the drill''s EMV without information of 0.00.", "The survey is worth 25.00 because the Analyzer drops the tied Do Not action and values the information against the drill alone.", "The prior decision is perfectly unsettled, since acting and Do Not are both worth 0, and a decision that unsettled can be tipped by any informative signal, which is why the survey is worth 25.00.", "The inputs are inconsistent, because a tied prior leaves the implied chances undefined, so the Analyzer should have withheld the 25.00."]'::jsonb, 2, 'Acting is 0.25 x 200 plus 0.75 x -50, less 12.5, which is 0. EVPI peaks at a switch for the same reason, 61.7143 at 0.228571 on the EKPAN lottery.'::text),
      ('advanced', 'final', null::text, 35, 'The EKPAN information tree is saved with a survey cost of 24.8250 and briefed in Decision Studio. What do its decision rows say?', '["Optimal EMV 75.7500 on \"No further information\", because at a cost equal to the gross value the engine declines to spend money on an indifferent survey.", "Optimal EMV 100.5750 on \"Acquire CSEM survey\" and an advantage of 24.8250, since the brief reports the information before its cost.", "Optimal EMV 92.5750 and an advantage of 16.8250, the rows this tree prints whatever survey cost is saved with it.", "Optimal EMV 75.7500 on \"Acquire CSEM survey\", a next best of 75.7500 and an advantage of 0.0000: the survey sits at its gross value and the move named is the branch listed first."]'::jsonb, 3, 'Acquiring is 100.5750 less 24.8250, which is 75.7500, tying no further information. On an information tree the advantage row is netEvii, 0.0000 here, and the tie goes to the first branch.'::text, 'The EKPAN information tree is saved with a survey cost of 24.8250 and briefed in Decision Studio. What do its decision rows say?', '["Optimal EMV 75.7500 on \"No further information\", because at a cost equal to the gross value the engine declines to spend money on an indifferent survey.", "Optimal EMV 100.5750 on \"Acquire CSEM survey\" and an advantage of 24.8250, since the brief reports the information before its cost.", "Optimal EMV 92.5750 and an advantage of 16.8250, the rows this tree prints whatever survey cost is saved with it.", "Optimal EMV 75.7500, a first move naming \"Acquire CSEM survey\" and \"No further information\" as coming to the same figure, a next best of 75.7500 and an advantage of Indifferent at the precision shown."]'::jsonb, 3, 'Acquiring is 100.5750 less 24.8250, which is 75.7500, tying no further information, so the brief names both root branches on the first-move row and writes Indifferent at the precision shown on the advantage row.'::text),
      ('advanced', 'final', null::text, 38, 'Which sentence reports the EKPAN lottery''s CSEM survey value completely?', '["Worth 19.84 gross and 11.84 net at a cost of 8.0000 against an EVPI card of 52.00, the survey''s full value on the lottery.", "Worth 16.8250 at a cost of 8.0000, below a ceiling of 52.0000, which is also the price at which buying it becomes neutral.", "Worth 24.8250 net of its 8.0000 cost against a ceiling of 61.7143, the EVPI at the drill against farm-out switch.", "Worth 24.8250 gross and 16.8250 net at a cost of 8.0000, against a ceiling of 52.0000, with Drill, Farm out and Walk away available; the two-action Analyzer gives 19.84."]'::jsonb, 3, 'A value of information needs its actions, its tree and its consistency: 19.84 is right for two actions, and the neutral price is the gross 24.8250, not the net.'::text, 'Which sentence reports the EKPAN lottery''s CSEM survey value completely?', '["Worth 19.84 gross and 11.84 net at a cost of 8.0000 against an EVPI card of 52.00, the survey''s full value on the lottery.", "Worth 16.8250 at a cost of 8.0000, below a ceiling of 52.0000, which is also the price at which buying it becomes neutral.", "Worth 24.8250 net of its 8.0000 cost against a ceiling of 61.7143, the EVPI at the drill against farm-out switch.", "Worth 24.8250 gross and 16.8250 net at a cost of 8.0000, against a ceiling of 52.0000, with Drill, Farm out and Walk away available; the two-action Analyzer gives 19.84."]'::jsonb, 3, 'A value of information needs its actions, its tree and its consistency: 19.84 is right for two actions, and the neutral price is the gross 24.8250; the net plays no part in it.'::text),
      ('advanced', 'final', null::text, 39, 'Four entries reach the rollback: a payoff summary carrying NPV P90 185, NPV P50 390 and NPV P10 710 but no mean; a payoff typed "20abc"; a payoff left empty; and a cost typed "abc". Which does the engine refuse?', '["All four, since each is an entry the engine cannot read as a number, and it refuses a tree rather than guess a value for it.", "The summary and \"20abc\"; the empty payoff is read as 0 and the \"abc\" cost is charged as 0, both without a message.", "Only \"20abc\", because a summary without a mean is valued at its NPV P50 of 390, and empty or text entries count as 0.", "The summary, the empty payoff and \"20abc\", while the cost typed \"abc\" passes alone, because a cost is optional and a payoff is not."]'::jsonb, 1, 'The two refusals read "Distribution payoff has no finite mean" and "Terminal payoff is not a number". An empty payoff silently turns a branch paying 20 at a cost of 5 into -5.0000, and an unreadable cost lifts it to 20.0000.'::text, 'Four entries reach the rollback: a payoff summary carrying NPV P90 185, NPV P50 390 and NPV P10 710 but no mean; a payoff typed "20abc"; a payoff left empty; and a cost typed "abc". Which does the engine refuse?', '["All four, since each is an entry the engine cannot read as a number, and it refuses the tree and guesses no value for it.", "The summary and \"20abc\"; the empty payoff is read as 0 and the \"abc\" cost is charged as 0, both without a message.", "Only \"20abc\", because a summary without a mean is valued at its NPV P50 of 390, and empty or text entries count as 0.", "The summary, the empty payoff and \"20abc\", while the cost typed \"abc\" passes alone, because a cost is optional and a payoff is not."]'::jsonb, 0, 'Four messages come back, one per entry, each ending with the node it stopped at: the mean-less summary and "20abc" fail as payoffs, the empty box as a blank payoff and "abc" as a cost. An entry missing from the tree altogether is the one case read as 0.'::text),
      ('advanced', 'final', null::text, 41, 'IRRI''s two readings both put success at 20 percent, and the published uselessSignal case''s two readings both leave the posterior at 0.300000. Each signal says the same thing whatever it reads. Why is one worth 0.0000 and the other withheld?', '["uselessSignal''s posteriors average back to the stated 0.300000, so ignoring it earns emvPrior and it is worth 0.0000; IRRI''s average to 0.200000, a prospect nobody stated.", "Both are worth 0.0000 in truth, and IRRI is withheld only because the Analyzer cannot display a zero value of information without raising a consistency warning beside it.", "uselessSignal is derived from likelihoods and so exempt from every check, while IRRI is withheld because the Analyzer will not value two indicators typed with identical percents of outcome chances.", "IRRI is worth -15.00 because its readings point toward a poorer prospect, and the repaired Analyzer withholds values that would discourage buying."]'::jsonb, 0, 'Averaging Bayes posteriors over the readings returns the prior, which sets the floor of 0; uselessSignal''s actions both read 43.0000. IRRI''s readings return 20 percent, so the -15.00 it printed before the repair was never a value.'::text, 'IRRI''s two readings both put success at 20 percent, and the published uselessSignal case''s two readings both leave the posterior at 0.300000. Each signal says the same thing whatever it reads. Why is one worth 0.0000 and the other withheld?', '["uselessSignal''s posteriors average back to the stated 0.300000, so ignoring it earns emvPrior and it is worth 0.0000; IRRI''s average to 0.200000, a prospect nobody stated.", "Both are worth 0.0000 in truth, and IRRI is withheld only because the Analyzer cannot display a zero value of information without raising a consistency warning beside it.", "uselessSignal is derived from likelihoods and so exempt from every check, while IRRI is withheld because the Analyzer will not value two indicators typed with identical percents of outcome chances.", "IRRI is worth -15.00 because its readings point toward a poorer prospect, and the Analyzer withholds values that would discourage buying."]'::jsonb, 0, 'Averaging Bayes posteriors over the readings returns the prior, which sets the floor of 0; after either uselessSignal reading the actions read Drill 43, Farm out 18 and Do nothing 0, so the best value is 43.0000 after each. IRRI''s readings return 20 percent, so the -15.00 its typed chances give with nothing checking them against the stated prior was never a value.'::text),
      ('advanced', 'final', null::text, 42, 'A survey''s likelihoods given Success are typed as 0.333333 for each of three readings, and every other column is sound. What does the Bayes engine return?', '["A value, since the EC4-0 repair gave each likelihood column the same 1e-12 representation allowance that it gave the implied-prior half percent check.", "A value, because likelihoods are checked across each reading''s row rather than down each outcome''s column, and three readings of 0.333333 do not form a row.", "A refusal naming the Success column at 0.999999, because each likelihood column faces the same 1e-6 test as a chance node, with no binary allowance.", "A refusal naming the readings, because three readings with equal likelihoods carry no information and the engine will not value a signal that cannot change anything."]'::jsonb, 2, 'Three copies of 0.333333 sum in binary to a gap of just over 1e-6, and the tolerance has no allowance for that (EC4-8 is open). Typing seven places, 0.3333333, would pass.'::text, 'A survey''s likelihoods given Success are typed as 0.333333 for each of three readings, and every other column is sound. What does the Bayes engine return?', '["A value, since each likelihood column faces the chance-node test, |sum - 1| at most 1e-6 plus a 1e-12 allowance, and 0.333333 typed in six places passes.", "A value, because likelihoods are checked only across each reading''s row, and three readings of 0.333333 do not form a row.", "A refusal naming the Success column at 0.999999, because each likelihood column faces the 1e-6 test with no binary allowance.", "A refusal naming the readings, because three readings with equal likelihoods carry no information and the engine will not value a signal that cannot change anything."]'::jsonb, 0, 'Three copies of 0.333333 miss 1 by a binary hair above 1e-6, inside the 1e-12 allowance the same test carries for chance nodes and priors. The published likelihoodColumnShortByTwoMillionths case, summing to 0.999998, is refused.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 2, 'IRRI is the Analyzer''s default study with both Positive Seismic and Negative Seismic typed as 20 / 80 percent. What does the repaired Analyzer show?', '["A gross voi of -15.00 and a netVoi card of -25.00, because after either reading the best action is Do Not and the with side comes to 0.", "A refusal naming the sum in percent, since two indicators typed with identical outcome chances do not form a distribution at all.", "Every card at 0.00, since a withheld value is printed as zero so that the verdict sentence can still call the survey value neutral.", "EMV without information 15.00 and EVPI 63.00, with every other card and the diagram withheld."]'::jsonb, 3, 'The readings imply a 0.200000 success chance against a stated 0.300000, so consistent is false and withheld is true; the -15.00 and -25.00 are pre-repair cards and history, and the two surviving cards use only the stated outcome chances.'::text, 'IRRI is the Analyzer''s default study with both Positive Seismic and Negative Seismic typed as 20 / 80 percent. What does the Analyzer show?', '["A gross voi of -15.00 and a netVoi card of -25.00, because after either reading the best action is Do Not and the with side comes to 0.", "A refusal naming the sum in percent, since two indicators typed with identical outcome chances do not form a distribution at all.", "Every card at 0.00, since a withheld value is printed as zero so that the verdict sentence can still call the survey value neutral.", "EMV without information 15.00 and EVPI 63.00, with every other card and the diagram withheld."]'::jsonb, 3, 'The readings imply a 0.200000 success chance against a stated 0.300000, so consistent is false and withheld is true; the -15.00 and -25.00 are what the typed chances give with nothing checking them against the stated prior, and the two surviving cards use only the stated outcome chances.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 4, 'The published justInsideTolerance case states 0.300000 / 0.700000 and implies 0.305000 / 0.695000. What does the repaired engine report?', '["Consistent false, because 0.305 - 0.3 is 0.0050000000000000044 in binary, above 0.005, which is the result recorded as finding D1.", "Consistent false, because the allowance is relative, half a percent of the stated 0.300000, and a delta of 5.000000e-3 is far beyond it.", "Consistent true, because the boundary is inclusive and a 1e-12 allowance absorbs the binary residue in 0.305 - 0.3.", "Consistent true with a boundary mark beside the cards, showing the delta sits exactly on the half percent line."]'::jsonb, 2, 'Before the EC4-0 repair the engine had no allowance and called this case inconsistent; D1 is resolved, a delta of exactly 5.000000e-3 now reads consistent true, and nothing grades it as sitting on the line.'::text, 'The published justInsideTolerance case states 0.300000 / 0.700000 and implies 0.305000 / 0.695000. What does the engine report?', '["Consistent false, because 0.305 - 0.3 is 0.0050000000000000044 in binary, above 0.005, and the check compares against 0.005 alone.", "Consistent false, because the allowance is relative, half a percent of the stated 0.300000, and a delta of 5.000000e-3 is far beyond it.", "Consistent true, because the boundary is inclusive and a 1e-12 allowance absorbs the binary residue in 0.305 - 0.3.", "Consistent true with a boundary mark beside the cards, showing the delta sits exactly on the half percent line."]'::jsonb, 2, 'The check compares every delta against 0.005 plus a 1e-12 allowance, so a delta of exactly 5.000000e-3 in the typed decimals reads consistent true, and nothing grades it as sitting on the line.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 5, 'On the Analyzer defaults the gross voi is 33.00 at an implied success chance of 0.300000 and 34.75 at 0.305000 (consistentAtHalfPercent), while the pre-repair 35.10 at 0.306000 is now withheld. What does the climb from 33.00 to 34.75 show?', '["The typed posteriors describe a sharper survey, and posteriors further from the prior always carry more information.", "Part of an accepted value can be extra success the stated chances never granted, so a pass does not certify the value.", "The allowance rescales the posteriors onto the stated chances before valuing, so 34.75 includes a correction the engine adds.", "It is binary residue from the 1e-12 allowance, so 33.00 and 34.75 describe the same survey to two decimals."]'::jsonb, 1, 'The value climbs with the contradiction inside the half point: 34.75 carries the same kind of error as the withheld 35.10, only less of it, and nudging entries under the line does not make them agree.'::text, 'On the Analyzer defaults the gross voi is 33.00 at an implied success chance of 0.300000 and 34.75 at 0.305000 (consistentAtHalfPercent), while 35.10 at 0.306000, what its typed chances give with nothing checking them, is withheld. What does the climb from 33.00 to 34.75 show?', '["The typed posteriors describe a sharper survey, and posteriors further from the prior always carry more information.", "Part of an accepted value can be extra success the stated chances never granted, so a pass does not certify the value.", "The allowance rescales the posteriors onto the stated chances before valuing, so 34.75 includes a correction the engine adds.", "It is binary residue from the 1e-12 allowance, so 33.00 and 34.75 describe the same survey to two decimals."]'::jsonb, 1, 'The value climbs with the contradiction inside the half point: 34.75 carries the same kind of error as the withheld 35.10, only less of it, and nudging entries under the line does not make them agree.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 10, 'Before the EC4-0 repair the published contradictingPosterior case printed a gross voi of 75.00 beside an EVPI card of 63.00. Why was that value impossible?', '["The survey cost of 10.0000 was added to the with side where it should have been subtracted, which lifted the gross value past its ceiling.", "The with side averaged to a 0.420000 success chance against a stated 0.300000, so the subtraction included the uplift of believing in a better prospect.", "The EVPI card came from the two action form and the voi from a lottery with a farm-out, so the two numbers described different lotteries.", "EVPI caps expected value with information and not the value of information, so 75.00 above 63.00 was ordinary arithmetic on consistent inputs."]'::jsonb, 1, 'Information derived by Bayes satisfies 0 <= evii <= evpi; 75.00 set a 0.420000 prospect after the survey against a 0.300000 prospect before it. It is history, and the repaired Analyzer withholds the value.'::text, 'Weighted as typed with nothing checking them, the published contradictingPosterior case gives a gross voi of 75.00 beside an EVPI card of 63.00. Why is that value impossible?', '["The survey cost of 10.0000 is added to the with side where it should be subtracted, which lifts the gross value past its ceiling.", "The with side averages to a 0.420000 success chance against a stated 0.300000, so the subtraction includes the uplift of believing in a better prospect.", "The EVPI card comes from the two action form and the voi from a lottery with a farm-out, so the two numbers describe different lotteries.", "EVPI caps only the expected value with information, leaving the value of information free, so 75.00 above 63.00 is ordinary arithmetic on consistent inputs."]'::jsonb, 1, 'Information derived by Bayes satisfies 0 <= evii <= evpi; 75.00 sets a 0.420000 prospect after the survey against a 0.300000 prospect before it, and the Analyzer withholds the value.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 11, 'A reviewer proposes fixing the pre-repair Analyzer by capping any value of information at EVPI. Why does that not fix it?', '["Clipping would change the verdict sentence, which is computed from the unclipped value, so the card and the sentence would disagree.", "EVPI is itself withheld whenever the inputs contradict each other, so there would be no ceiling left to clip the value against.", "Capping 75.00 at 63.00 is what the repaired Analyzer already does, so the proposal duplicates the repair rather than adding to it.", "Contradictions also land below the ceiling: the EKPAN lottery typed with indicators at 56 and 44 percent printed 40.62 under an EVPI of 52.00."]'::jsonb, 3, 'The honest value on those EKPAN lottery entries is 19.84, and indicatorChancesAboveHundred printed 33.00, the very card the consistent defaults print; a test on the output catches only the loudest cases, so the repair tests the inputs.'::text, 'A reviewer proposes guarding the Analyzer by capping any value of information at EVPI and printing it. Why would that not be enough?', '["Clipping would change the verdict sentence, which is computed from the unclipped value, so the card and the sentence would disagree.", "EVPI is itself withheld whenever the inputs contradict each other, so there would be no ceiling left to clip the value against.", "Capping 75.00 at 63.00 is what the Analyzer already does, so the proposal only duplicates a check it already carries.", "Contradictions also land below the ceiling: the EKPAN lottery typed with indicators at 56 and 44 percent gives 40.62 under an EVPI of 52.00."]'::jsonb, 3, 'The honest value on those EKPAN lottery entries is 19.84, and indicatorChancesAboveHundred gives 33.00, matching the defaults'' own gross voi; a test on the output catches only the loudest cases, so the Analyzer tests the inputs.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 12, 'The published pricey case prints a netVoi card of -17.00 today, and IRRI printed a gross voi of -15.00 before the repair. What separates the two?', '["Nothing of substance: a misleading survey has a negative gross value just as an expensive survey has a negative net value.", "The first is a pre-repair card and history, while the second is what the repaired Analyzer prints for IRRI today.", "The first says a price of 50.0000 exceeds a gross value of 33.00; the second could only come from typed inputs that contradict the stated prior.", "Both say the survey costs more than it adds, and they differ only in whether the survey cost of 10.0000 was deducted."]'::jsonb, 2, 'A decision maker can always ignore a Bayes signal, so evii is at least 0, and uselessSignal sits on that floor at 0.0000; a negative net value says the price is too high, a negative gross value says the inputs disagree.'::text, 'The published pricey case prints a netVoi card of -17.00, and IRRI''s typed chances give a gross voi of -15.00 with nothing checking them against the stated prior. What separates the two?', '["Nothing of substance: a misleading survey has a negative gross value just as an expensive survey has a negative net value.", "The first is a figure the Analyzer withholds, while the second is what the Analyzer prints for IRRI beside its warning.", "The first says a price of 50.0000 exceeds a gross value of 33.00; the second could only come from typed inputs that contradict the stated prior.", "Both say the survey costs more than it adds, and they differ only in whether the survey cost of 10.0000 was deducted."]'::jsonb, 2, 'A decision maker can always ignore a Bayes signal, so evii is at least 0, and uselessSignal sits on that floor at 0.0000; a negative net value says the price is too high, a negative gross value says the inputs disagree.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 13, 'posteriorsAboveHundred types outcome chances given Positive Seismic that sum to 130 percent; IRRI types two readings whose outcome chances each sum to 100. How does the repaired Analyzer treat each?', '["It refuses the first before computing anything, and withholds the value on IRRI while still showing 15.00 and 63.00.", "It withholds both, keeping EMV without information and EVPI, because every contradiction in typed percents is reported the same way.", "It clips the first to 100 percent and values it at the pre-repair 69.00, and it withholds the value of information on IRRI.", "It withholds the first with a warning naming 130 percent, and refuses IRRI because its two readings are typed identically."]'::jsonb, 0, 'A refusal says the typed numbers are not chances at all, with the message "Outcome chances given "Positive Seismic" sum to 130 percent, expected 100"; a withholding says they are chances that cannot all be true together.'::text, 'posteriorsAboveHundred types outcome chances given Positive Seismic that sum to 130 percent; IRRI types two readings whose outcome chances each sum to 100. How does the Analyzer treat each?', '["It refuses the first before computing anything, and withholds the value on IRRI while still showing 15.00 and 63.00.", "It withholds both, keeping EMV without information and EVPI, because every contradiction in typed percents is reported the same way.", "It clips the first to 100 percent and values it at 69.00, and it withholds the value of information on IRRI.", "It withholds the first with a warning naming 130 percent, and refuses IRRI because its two readings are typed identically."]'::jsonb, 0, 'A refusal says the typed numbers are not chances at all, with the message "Outcome chances given "Positive Seismic" sum to 130 percent, expected 100"; a withholding says they are chances that cannot all be true together.'::text),
      ('advanced', 'module', 'm01-inputs-that-contradict-each-other'::text, 15, 'Before the repair, indicatorChancesAboveHundred, with indicator chances summing to 110 percent, printed a gross voi of 33.00. What made that value dangerous, and what happens to the entry today?', '["Nothing, since rescaling indicator chances by their sum leaves the posteriors alone, and the Analyzer still prints 33.00.", "It sat inside the half percent allowance, so the check passed it, and today the allowance is narrowed to catch it.", "It contradicted the stated chances, so today the value is withheld and EMV without information 15.00 and EVPI 63.00 remain on the screen.", "It matched the card the consistent defaults print; today it is refused with \"Indicator chances sum to 110 percent, expected 100\"."]'::jsonb, 3, 'A 110 percent indicator set is not a distribution, so it is refused outright and never reaches the consistency check; an output test would have passed 33.00, which sat under 63.00.'::text, 'With nothing checking its sums, indicatorChancesAboveHundred, with indicator chances summing to 110 percent, gives a gross voi of 33.00. What makes that value dangerous, and what does the Analyzer do with the entry?', '["Nothing, since rescaling indicator chances by their sum leaves the posteriors alone, and the Analyzer prints 33.00.", "It sits inside the half percent allowance, so the check passes it, and the allowance would need narrowing to catch it.", "It contradicts the stated chances, so the value is withheld and EMV without information 15.00 and EVPI 63.00 remain on the screen beside the consistency warning.", "It matches the defaults'' own gross voi of 33.00, and the entry is refused with \"Indicator chances sum to 110 percent, expected 100\"."]'::jsonb, 3, 'A 110 percent indicator set is not a distribution, so it is refused outright before the consistency check; an output test would have passed 33.00, which sits under 63.00.'::text),
      ('advanced', 'module', 'm02-bigger-lotteries'::text, 2, 'With the outcome known first, the published golden records the best actions for Large, Medium and Dry on the three outcome lottery as indices 0, 0 and 2. Why does Dry record Farm out?', '["Farm out and Relinquish both pay 0.0000 in Dry, and the strictly greater comparison keeps the one listed first.", "Farm out breaks the tie by its better payoffs in Large and Medium, which the engine consults when two actions pay the same in one outcome.", "Relinquish is left out of perfect information because it pays nothing in any outcome, so Farm out is the only costless action there.", "Farm out is what the engine recommends at the prior once a well is dry, and perfect information repeats it."]'::jsonb, 0, 'Listed the other way round the golden would name Relinquish and evWithPerfect would stay at 133.0000, since EVPI takes the best value per outcome.'::text, 'With the outcome known first, the published golden records the best actions for Large, Medium and Dry on the three outcome lottery as indices 0, 0 and 2. Why does Dry record Farm out?', '["Farm out and Relinquish both pay 0.0000 in Dry and tie, and the golden records the first listed of the tied pair.", "Farm out breaks the tie by its better payoffs in Large and Medium, which the engine consults when two actions pay the same in one outcome.", "Relinquish is left out of perfect information because it pays nothing in any outcome, so Farm out is the only costless action there.", "Farm out is what the engine recommends at the prior once a well is dry, and perfect information repeats it."]'::jsonb, 0, 'Listed the other way round the golden would name Relinquish and evWithPerfect would stay at 133.0000, since EVPI takes the best value per outcome.'::text),
      ('advanced', 'module', 'm02-bigger-lotteries'::text, 12, 'At a Large chance of 0.300000 on the three outcome lottery, Drill alone is worth 161.0000 and Drill with partner 80.5000. Why can the partner never be the best action on this lottery?', '["It is dominated by Farm out in every outcome, since Farm out pays at least as much as the partner in Large, Medium and Dry alike.", "Its payoffs and cost are exactly half of Drill alone''s, so it is worth half at every probability, and when half is negative Farm out, never below 0, beats it.", "It is never best at the stated prior, but at a Large chance of 0.000000 it halves Drill alone''s loss and so leads the other actions.", "It could lead if the engine''s risk aversion setting were raised, since halving the Dry loss is exactly what a cautious operator pays for."]'::jsonb, 1, 'Half of a positive value is smaller and half of a negative one is still negative; at a Large chance of 0.000000 Drill alone is 5.0000, the partner 2.5000 and Farm out 15.0000, and the engine has no risk aversion parameter.'::text, 'At a Large chance of 0.300000 on the three outcome lottery, Drill alone is worth 161.0000 and Drill with partner 80.5000. Why can the partner never be the best action on this lottery?', '["It is dominated by Farm out in every outcome, since Farm out pays at least as much as the partner in Large, Medium and Dry alike.", "Its payoffs and cost are exactly half of Drill alone''s, so it is worth half at every probability, and when half is negative Farm out, which stays at 0 or above, beats it.", "It is never best at the stated prior, but at a Large chance of 0.000000 it halves Drill alone''s loss and so leads the other actions.", "It could lead if the engine''s risk aversion setting were raised, since halving the Dry loss is exactly what a cautious operator pays for."]'::jsonb, 1, 'Half of a positive value is smaller and half of a negative one is still negative; at a Large chance of 0.000000 Drill alone is 5.0000, the partner 2.5000 and Farm out 15.0000, and the engine has no risk aversion parameter.'::text),
      ('advanced', 'module', 'm03-the-decision-brief'::text, 1, 'Decision Studio briefs the EKPAN tree as Optimal EMV 105.0000, Recommended first move Drill, Next best alternative 37.7500 and Decision advantage 67.2500. Which rows are engine returns?', '["All four, since the brief re-rolls the saved tree at brief time and reads each of the rows directly off the engine''s result.", "Only the Recommended first move, since Optimal EMV is copied from the answer the Decision Tree Builder stored with the tree.", "Every row except the advantage, since the engine returns Next best alternative as the second branch listed at the root.", "Optimal EMV and Recommended first move; the other two are arithmetic on the rollback."]'::jsonb, 3, 'On the EKPAN tree, next best is the largest other root branch value, Farm out at 37.7500, and the advantage is 105.0000 less 37.7500; the brief recomputes the saved tree rather than storing the Builder''s answer, so the two agree on the numbers.'::text, 'Decision Studio briefs the EKPAN tree as Optimal EMV 105.0000, Recommended first move Drill, Next best alternative 37.7500 and Decision advantage 67.2500. Which rows are engine returns?', '["All four, since the brief re-rolls the saved tree at brief time and reads each of the rows directly off the engine''s result.", "Only the Recommended first move, since Optimal EMV is copied from the answer the Decision Tree Builder stored with the tree.", "Every row except the advantage, since the engine returns Next best alternative as the second branch listed at the root.", "Optimal EMV and Recommended first move; the other two are arithmetic on the rollback."]'::jsonb, 3, 'On the EKPAN tree, next best is the largest other root branch value, Farm out at 37.7500, and the advantage is 105.0000 less 37.7500; the brief recomputes the saved tree and stores none of the Builder''s answers, so the two agree on the numbers.'::text),
      ('advanced', 'module', 'm03-the-decision-brief'::text, 5, 'The published equalEmvTie has root branches A 30.0000, B 30.0000 and C 29.9990, and the brief prints Recommended first move A with a Decision advantage of 0.0000. Why A?', '["It is listed first, and the engine replaces the best branch only when a later one is strictly greater.", "A was larger before rounding, and the advantage of 0.0000 is float residue left by subtracting two nearly equal values.", "C at 29.9990 sits closer to B, and the engine breaks a tie against whichever tied branch has the nearer runner up.", "The brief picks the branch with the least exposure among tied values, and A carries the smallest downside of the three."]'::jsonb, 0, 'A and B are exactly equal, so an advantage of 0.0000 beside a named first move is a tie reported as a recommendation; the recommendation comes from listing order and says nothing about which branch is better.'::text, 'The published equalEmvTie has root branches A 30.0000, B 30.0000 and C 29.9990. What does a Decision Studio brief print on its first-move and advantage rows?', '["Indifferent: \"A\", \"B\" and \"C\" come to the same figure, and Indifferent at the precision shown, because C rounds to the same 30.00 card as A and B.", "Recommended first move \"A\" with a Decision advantage of 0.0000, because A is listed first and the next best, B, is also 30.0000.", "Indifferent: \"A\" and \"B\" come to the same figure, with an advantage of 0.0010 over C, which sits outside the tie band.", "Recommended first move \"C\", since the brief prefers the tied branch with the smallest downside and C carries the least exposure."]'::jsonb, 0, 'The brief reads the card-precision tie set, and A, B and C all round to 30.00. The engine still marks A, the first listed, for the optimal path; the brief names no single branch its own figures cannot separate.'::text),
      ('advanced', 'module', 'm03-the-decision-brief'::text, 6, 'The brief prints chanceRootWithBranchCosts as Optimal EMV -3.0000 and Recommended first move Single path, with no Next best alternative or Decision advantage row. What does that mean?', '["The brief failed to find a second branch, and the two missing rows should be worked out by hand from the calm and storm branches.", "The engine picked calm as the single path, since it is listed first and carries the higher branch value of 17.0000.", "The brief hides both rows whenever the Optimal EMV is negative, because a losing tree has no alternative worth quoting.", "The root is a chance node, so there is no choice to recommend or compare, and Single path is not a branch the engine picked."]'::jsonb, 3, 'The Builder writes Chance root and N/A for the same tree, and singleBranchDecision likewise prints just 7.0000 and the move named only; allNegative, at -52.0000, still prints a next best of -55.0000 and an advantage of 3.0000.'::text, 'The brief prints chanceRootWithBranchCosts as Optimal EMV -3.0000 and Recommended first move Chance root: no first decision to make, with no Next best alternative or Decision advantage row. What does that mean?', '["The brief failed to find a second branch, and the two missing rows should be worked out by hand from the calm and storm branches.", "The engine picked calm as the only path, since it is listed first and carries the higher branch value of 17.0000.", "The brief hides both rows whenever the Optimal EMV is negative, because a losing tree has no alternative worth quoting.", "The root is a chance node, so there is no choice to recommend or compare, and the label names no branch the engine picked."]'::jsonb, 3, 'The Builder shows the same label with N/A on its other two cards, and singleBranchDecision likewise prints just 7.0000 and the move named only; allNegative, at -52.0000, still prints a next best of -55.0000 and an advantage of 3.0000.'::text),
      ('advanced', 'module', 'm03-the-decision-brief'::text, 10, 'A summary linked to a terminal arrives with an NPV P90 of 185, an NPV P50 of 390 and an NPV P10 of 710, and no mean. What does the engine do?', '["It rolls back with the NPV P50 of 390, taking the middle case as the best available stand in for the missing mean.", "It averages the three percentiles into a mean and rolls back with that, flagging the payoff as estimated in the brief.", "It rolls back with the NPV P90 of 185, the low case, as a conservative fallback, which flips the EKPAN tree to Farm out.", "It refuses with \"Distribution payoff has no finite mean\" and does not estimate one."]'::jsonb, 3, 'The engine will not guess a mean from percentiles, since the rollback needs the expectation and three percentiles do not fix it; on the EKPAN tree reading 390.0000 would have printed 94.5000.'::text, 'A summary linked to a terminal arrives with an NPV P90 of 185, an NPV P50 of 390 and an NPV P10 of 710, and no mean. What does the engine do?', '["It rolls back with the NPV P50 of 390, taking the middle case as the best available stand in for the missing mean.", "It averages the three percentiles into a mean and rolls back with that, flagging the payoff as estimated in the brief.", "It rolls back with the NPV P90 of 185, the low case, as a conservative fallback, which flips the EKPAN tree to Farm out.", "It refuses with a message naming the terminal, Distribution payoff has no finite mean, and does not estimate one."]'::jsonb, 3, 'The engine will not guess a mean from percentiles, since the rollback needs the expectation and three percentiles do not fix it; on the EKPAN tree reading 390.0000 would have printed 94.5000.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 1, 'A chance node named "Three equal outcomes" pays 30, 60 and 90, and each of its three branches is typed as 0.333333. What does the rollback engine return?', '["An emv of 60.0000, because a sum of 0.999999 sits exactly 1e-6 from 1 and the tolerance on a chance node is inclusive at its edge, so the node passes.", "An emv of 60.0000, because the 1e-12 representation allowance added in the EC4-0 repair absorbs the binary residue on a probability sum as well as on an implied prior.", "A refusal, `Chance branch probabilities sum to 0.999999, expected 1`, because three copies of 0.333333 land a hair more than 1e-6 from 1 in binary and the sum check carries no allowance for that.", "An emv just under 60.0000, because the engine accepts the sum and weights the three payoffs by the thirds exactly as they were typed."]'::jsonb, 2, 'In binary the gap is 0.0000010000000000287557, just above 1e-6, so the node is refused while its message prints 0.999999; typed as 0.3333333 it rolls back to 60.0000. The 1e-12 allowance belongs to the implied-priors check alone, and whether to add one here is an open owner decision (finding EC4-8).'::text, 'A chance node named "Three equal outcomes" pays 30, 60 and 90, and each of its three branches is typed as 0.333333. What does the rollback engine return?', '["An emv of 60.0000, because a sum of 0.999999 sits exactly 1e-6 from 1 and the tolerance on a chance node is inclusive at its edge, so the node passes.", "An emv of 60.0000, because the 1e-12 allowance absorbs the binary residue and the engine then rescales the thirds to sum to 1.", "A refusal, `Chance branch probabilities sum to 0.999999, expected 1`, because three copies of 0.333333 land a hair more than 1e-6 from 1 in binary and the sum check carries no allowance for that.", "An emv just under 60.0000, because the engine accepts the sum and weights the three payoffs by the thirds exactly as they were typed."]'::jsonb, 3, 'The sum test is |sum - 1| at most 1e-6 plus a 1e-12 allowance for binary representation, inclusive, so the node passes and is worth 0.333333 x (30 + 60 + 90) = 59.9999; accepted probabilities are used exactly as typed. Typed as 0.333 each the sum is 0.999000 and the node is refused.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 2, 'The published justInsideTolerance case states a success chance of 0.300000 and implies 0.305000. How does the repaired implied-priors check read it, and why?', '["Consistent true, because the delta, which is 0.0050000000000000044 in binary, is compared against 0.005 plus a 1e-12 representation allowance.", "Consistent false, because in binary floating point the delta is 0.0050000000000000044, which is above the 0.005 threshold by 4.3e-18, so even an inclusive comparison turns it away.", "Consistent true, because the engine rounds every delta to six decimals, 5.000000e-3, before comparing it with the threshold.", "Consistent true, because the repair widened the threshold to 6.000000e-3 so that cases on the old boundary stop flipping."]'::jsonb, 0, 'Compared against 0.005 alone the case would read false, which is what the engine did before EC4-0 (finding D1, now resolved). The allowance absorbs a 4.3e-18 overshoot and nothing of a size worth arguing about.'::text, 'The published justInsideTolerance case states a success chance of 0.300000 and implies 0.305000. How does the implied-priors check read it, and why?', '["Consistent true, because the delta, which is 0.0050000000000000044 in binary, is compared against 0.005 plus a 1e-12 representation allowance.", "Consistent false, because in binary floating point the delta is 0.0050000000000000044, which is above the 0.005 threshold by 4.3e-18, so even an inclusive comparison turns it away.", "Consistent true, because the engine rounds every delta to six decimals, 5.000000e-3, before comparing it with the threshold.", "Consistent true, because the threshold is widened to 6.000000e-3 so that cases on the boundary stop flipping."]'::jsonb, 0, 'Compared against 0.005 alone the case would read false. The allowance absorbs a 4.3e-18 overshoot and nothing of a size worth arguing about.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 3, 'A reviewer argues that since the EC4-0 repair added an allowance to the half percent check, an implied success chance of 0.306000 against a stated 0.3 ought to pass now. What does the Analyzer do with published withheldPastHalfPercent?', '["It prints a gross voi of 35.10, because the allowance moved the inclusive boundary far enough out to take in a delta just past half a percent.", "It refuses the inputs with a message naming the sum in percent, because a delta above half a percent means the typed chances are not a distribution.", "It prints every card with a consistency warning beside them, since the repair only annotates a value built on chances that disagree.", "It withholds the value of information, because the allowance is 1e-12 and a delta of 6.000000e-3 is inconsistent before and after the repair."]'::jsonb, 3, 'The Analyzer still reports EMV without information 15.00 and EVPI 63.00. The gross voi of 35.10 it printed for these inputs before the repair is history, a number built on chances that cannot all be true.'::text, 'A reviewer argues that since the half percent check carries an allowance, an implied success chance of 0.306000 against a stated 0.3 ought to pass. What does the Analyzer do with published withheldPastHalfPercent?', '["It prints a gross voi of 35.10, because the allowance moved the inclusive boundary far enough out to take in a delta just past half a percent.", "It refuses the inputs with a message naming the sum in percent, because a delta above half a percent means the typed chances are not a distribution.", "It prints every card with a consistency warning beside them, since the check only annotates a value built on chances that disagree.", "It withholds the value of information, because the allowance is 1e-12 and a delta of 6.000000e-3 is inconsistent with or without it."]'::jsonb, 3, 'The Analyzer still reports EMV without information 15.00 and EVPI 63.00. The gross voi of 35.10 these inputs give with nothing checking them is a number built on chances that cannot all be true.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 4, 'One engine family holds two boundaries: a chance node''s probabilities must sum to within 1e-6 of 1, and an implied chance must sit within 0.005 of the stated one. What happens exactly at each edge?', '["Both edges hold, because the EC4-0 repair gave each of the two comparisons the same 1e-12 allowance for binary representation error.", "The implied-priors edge holds because of its 1e-12 allowance, while the sum edge has none, so thirds typed as 0.333333 are refused although their decimal gap equals the tolerance.", "Both edges fail, because binary rounding pushes a value sitting exactly on either threshold a hair past it and neither check makes any allowance for that.", "The sum edge holds because its message prints 0.999999, while the implied-priors edge fails at 0.305000 on 4.3e-18 of binary overshoot."]'::jsonb, 1, '0.305 less 0.3 evaluates to 0.0050000000000000044 and passes under the allowance; three copies of 0.333333 leave a gap of 0.0000010000000000287557 and are refused. Two boundaries in the same engine behave differently at their edge.'::text, 'One engine family holds two boundaries: a chance node''s probabilities must sum to within 1e-6 of 1, and an implied chance must sit within 0.005 of the stated one. What happens exactly at each edge?', '["The implied-priors edge holds because of its 1e-12 allowance, while the sum edge has none, so thirds typed as 0.333333 are refused although their decimal gap equals the tolerance.", "Both edges hold, because each of the two comparisons adds the same 1e-12 allowance for binary representation error.", "Both edges fail, because binary rounding pushes a value sitting exactly on either threshold a hair past it and neither check makes any allowance for that.", "The sum edge holds because its message prints 0.999999, while the implied-priors edge fails at 0.305000 on 4.3e-18 of binary overshoot."]'::jsonb, 1, 'The implied-priors delta of 0.305 less 0.3 overshoots 0.005 by 4.3e-18 in binary, and a 0.333333 sum misses 1 by a hair more than 1e-6; one 1e-12 allowance absorbs each, so neither edge flips.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 5, 'Branch A pays 20 with its cost typed as "abc", and branch B pays 12 at no cost. What does the rollback return?', '["A refusal naming branch A, because the engine checks that every cost reads as a number in the same way that it checks every payoff.", "An emv of 20.0000 with A best and no message, because a cost that does not read as a number is charged as zero.", "An emv of 15.0000 with A best, because text typed on a cost is converted to the number the user most likely meant, which here is 5.", "An emv of 12.0000 with B best, because the engine drops a branch whose cost cannot be read and rolls back only what remains."]'::jsonb, 1, 'The intended reading at a cost of 5 is 15.0000, so the root is overstated by the whole cost while the first move still looks sensible. The check is arithmetic: a branch value equal to its child value means the cost was never charged.'::text, 'Branch A pays 20 with its cost typed as "abc", and branch B pays 12 at no cost. What does the rollback return?', '["An emv of 20.0000 with A best and no message, because a cost that does not read as a number is charged as zero.", "A refusal naming branch A, because the engine checks that every cost reads as a number in the same way that it checks every payoff.", "An emv of 15.0000 with A best, because text typed on a cost is converted to the number the user most likely meant, which here is 5.", "An emv of 12.0000 with B best, because the engine drops a branch whose cost cannot be read and rolls back only what remains."]'::jsonb, 1, 'The engine refuses the cost with a message naming branch A and its node: the cost is not a finite number ("abc") and must be a number of 0 or more. Only a cost left out of the tree reads as 0, which gives 20.0000 against the intended 15.0000 with no message.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 6, 'On the decision where A pays 20 at a cost of 5 and B pays 12, three slips are made one at a time: A''s cost typed as "abc", A''s cost typed as -5, and A''s payoff left empty. Which slip changes the recommendation?', '["The cost typed as \"abc\", because a branch carrying a cost the engine cannot read is valued at 0 and loses to B at 12.0000.", "The cost typed as -5, because the engine refuses a negative cost on A and B becomes the only branch it is able to roll back.", "None of the three, since each default leaves A ahead: 20.0000 for the text cost, 25.0000 for the receipt and 15.0000 for the empty payoff.", "The empty payoff, which is read as 0, so branch A becomes -5.0000 and B wins at 12.0000."]'::jsonb, 3, 'A missing payoff is the more dangerous default: "abc" lifts A to 20.0000 and -5 lifts it to 25.0000, both still best, while an empty or null payoff flips the choice. A payoff of "20abc", by contrast, is refused with `Terminal payoff is not a number`.'::text, 'On the decision where A pays 20 at a cost of 5 and B pays 12, three slips are made one at a time: A''s cost typed as "abc", A''s cost typed as -5, and A''s payoff left empty. What does each slip do?', '["The cost typed as \"abc\" is charged as 0 and lifts A to 20.0000, while the other two slips are refused.", "The cost of -5 is read as money received and lifts A to 25.0000, while the other two slips are refused.", "The empty payoff is read as 0, so branch A becomes -5.0000 and B wins at 12.0000, while the two cost slips are refused.", "Each stops the rollback with its own message naming the node, so none of them produces a value or a changed first move."]'::jsonb, 3, 'A cost that is not a finite number, a negative cost and a blank payoff are all refused by node label; the negative cost message says to enter a receipt as a payoff. Only a cost or payoff left out of the tree reads as 0.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 7, 'Why is a cost typed as -5 on branch A, which pays 20, accepted and valued at 25.0000?', '["The engine reads a negative cost as money received, which is right for a farm-in carry and a typing error for everything else, and it cannot tell the two apart.", "The engine flags the negative cost as a receipt in its output, so the 25.0000 arrives with a note that a reviewer is expected to read before using it.", "The engine charges an unreadable cost as zero and then adds the typed magnitude back as a separate receipt on the same branch.", "A branch value is the child value plus its cost, so any cost typed on A adds to it and a cost of 5 would give the same 25.0000."]'::jsonb, 0, 'A branch value is the child value less the cost, so 20 less -5 is 25.0000, and nothing in the output marks it; a cost of 5 gives 15.0000. Only a reader who checks each branch value against the cost they meant will see it.'::text, 'Why is a cost typed as -5 on branch A, which pays 20, refused?', '["A cost cannot be negative: the engine refuses it by branch and node and says to enter a receipt as a payoff, so money received is never read off a cost.", "The engine flags the negative cost as a receipt in its output and values A at 25.0000 beside the note, which is where the refusal is shown.", "The engine charges an unreadable cost as zero and refuses only the magnitude it cannot place on the branch.", "A branch value is the child value plus its cost, so the engine refuses any cost that would lower a branch."]'::jsonb, 0, 'The message names branch A and the negative cost (-5) and says a cost cannot be negative: enter a receipt as a payoff. A branch value is the child value less the cost, so a cost of 5 gives 15.0000.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 10, 'The Bayes calculation behind EVII checks the likelihoods of the EKPAN lottery''s survey before it computes anything. Which numbers must sum to 1?', '["Each signal''s likelihoods across the outcomes, so a bright spot''s 0.850000 given Success and 0.250000 given a dry hole must together sum to 1.", "Each outcome''s likelihoods down its column across the signals, so the Success column reads 0.850000 for a bright spot and 0.150000 for none.", "The chances of the signals themselves, 0.460000 for a bright spot and 0.540000 for none, which the engine checks before any posterior.", "The posteriors after each signal, 0.646739 and 0.353261 after a bright spot, since those are the numbers the action is chosen on."]'::jsonb, 1, 'The survey passes because Success reads 0.850000 / 0.150000 and Dry hole 0.250000 / 0.750000. A Dry hole column summing to 1.200000 is refused with the outcome named; the signal chances and posteriors are derived, never typed.'::text, 'The Bayes calculation behind EVII checks the likelihoods of the EKPAN lottery''s survey before it computes anything. Which numbers must sum to 1?', '["Each signal''s likelihoods across the outcomes, so a bright spot''s 0.850000 given Success and 0.250000 given a dry hole must together sum to 1.", "Each outcome''s likelihoods down its column across the signals, so the Success column reads 0.850000 for a bright spot and 0.150000 for none.", "The chances of the signals themselves, 0.460000 for a bright spot and 0.540000 for none, which the engine checks before any posterior.", "The posteriors after each signal, 0.646739 and 0.353261 after a bright spot, since those are the numbers the action is chosen on."]'::jsonb, 1, 'The survey passes because Success reads 0.850000 / 0.150000 and Dry hole 0.250000 / 0.750000. A Dry hole column summing to 1.200000 is refused with the outcome named; the signal chances and posteriors are derived and are never typed.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 11, 'The EKPAN lottery is typed into the repaired VOI Analyzer with Bright spot at 46.000000 percent and No bright spot at 64 percent. What does the Analyzer show?', '["No cards at all, only the refusal `Indicator chances sum to 110 percent, expected 100`.", "EMV without information 75.75 and EVPI 52.00, with the value of information withheld because the indicators contradict the stated prior.", "A refusal stating the indicator sum as a fraction of 1 rather than in percent, the engine''s internal scale for every chance it checks.", "The cards for renormalised indicator chances, since the Analyzer rescales any indicator set that misses 100 before valuing the survey."]'::jsonb, 0, 'Indicator chances that are not a distribution are refused before anything is computed, with the sum in percent. Withholding with 75.75 and 52.00 is the answer for chances that do sum to 100 but contradict the stated outcome chances.'::text, 'The EKPAN lottery is typed into the VOI Analyzer with Bright spot at 46.000000 percent and No bright spot at 64 percent. What does the Analyzer show?', '["No cards at all, only the refusal `Indicator chances sum to 110 percent, expected 100`.", "EMV without information 75.75 and EVPI 52.00, with the value of information withheld because the indicators contradict the stated prior.", "A refusal stating the indicator sum as a fraction of 1, the engine''s internal scale for every chance it checks, with no percent in it.", "The cards for renormalised indicator chances, since the Analyzer rescales any indicator set that misses 100 before valuing the survey."]'::jsonb, 0, 'Indicator chances that are not a distribution are refused before anything is computed, with the sum in percent. Withholding with 75.75 and 52.00 is the answer for chances that do sum to 100 but contradict the stated outcome chances.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 12, 'IRRI types both indicators as 20 / 80 percent, and published indicatorChancesAboveHundred types indicator chances summing to 110 percent. How do the repaired Analyzer''s answers differ?', '["Both are refused with a message naming the sum in percent, because each set of typed percents fails the check before any card is drawn.", "Both are withheld with 15.00 and 63.00 reported, because each describes chances that the stated outcome chances cannot support.", "IRRI is withheld and still reports EMV without information 15.00 and EVPI 63.00, while the 110 percent case is refused and shows no card.", "IRRI is refused because its implied success chance of 0.200000 is not the stated 0.3, while the 110 percent case is withheld with two cards."]'::jsonb, 2, 'A refusal says the numbers are not chances at all; a withholding says they are chances that cannot all be true together. EMV without information and EVPI depend only on the stated outcome chances, so 15.00 and 63.00 survive a withholding.'::text, 'IRRI types both indicators as 20 / 80 percent, and published indicatorChancesAboveHundred types indicator chances summing to 110 percent. How do the Analyzer''s answers differ?', '["Both are refused with a message naming the sum in percent, because each set of typed percents fails the check before any card is drawn.", "Both are withheld with 15.00 and 63.00 reported, because each describes chances that the stated outcome chances cannot support.", "IRRI is withheld and still reports EMV without information 15.00 and EVPI 63.00, while the 110 percent case is refused and shows no card.", "IRRI is refused because its implied success chance of 0.200000 is not the stated 0.3, while the 110 percent case is withheld with two cards."]'::jsonb, 2, 'A refusal says the numbers are not chances at all; a withholding says they are chances that cannot all be true together. EMV without information and EVPI depend only on the stated outcome chances, so 15.00 and 63.00 survive a withholding.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 13, 'Before the EC4-0 repair, which input the Analyzer now refuses printed a gross voi that looked exactly like a genuine answer on its default study?', '["posteriorsAboveHundred, whose 69.00 sat close enough to the evpi card of 63.00 that nothing on the screen marked it out as a problem.", "chanceOutsideRange, whose -15.00 read as an ordinary survey priced above its worth rather than as a gross value below the floor of zero.", "indicatorChancesAboveHundred, whose 33.00 is the default study''s own voi, printed for indicator chances summing to 110 percent.", "missingOutcomeChanceCountsAsZero, whose 41.00 is the default study''s own EMV with information, so it looked familiar to anyone who ran the defaults."]'::jsonb, 2, 'These cards are history, reconstructed from engine calls. 69.00 is above the 63.00 ceiling and -15.00 is below zero, both impossible on sight; 33.00 is the default study''s genuine voi and could not be caught by eye, while its EMV with information is 38.00.'::text, 'Weighted as typed with nothing checking them, which input the Analyzer refuses gives a gross voi that looks exactly like a genuine answer on its default study?', '["posteriorsAboveHundred, whose 69.00 sits close enough to the evpi card of 63.00 that nothing on the screen would mark it out as a problem.", "chanceOutsideRange, whose -15.00 reads as an ordinary survey priced above its worth and hides a gross value below the floor of zero.", "indicatorChancesAboveHundred, whose 33.00 is the default study''s own voi, given for indicator chances summing to 110 percent.", "missingOutcomeChanceCountsAsZero, whose 41.00 is the default study''s own EMV with information, so it looks familiar to anyone who ran the defaults."]'::jsonb, 2, 'These are unguarded figures from engine calls. 69.00 is above the 63.00 ceiling and -15.00 is below zero, both impossible on sight; 33.00 is the default study''s genuine voi and could not be caught by eye, while its EMV with information is 38.00.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 14, 'Published posteriorsOffsetButPriorsAgree types outcome chances given Positive Seismic that sum to 110 percent, built so that the priors they imply equal the stated ones. Why does a reviewer who checks only the implied priors miss it?', '["The implied-priors test passes, and only the check that each set of outcome chances sums to 100 catches it, which the Analyzer runs first and refuses on.", "The implied-priors test is run on rounded posteriors, so an offset of 10 percent is absorbed inside the half percent tolerance before it can register at all.", "The reviewer''s test is the right one, and the Analyzer passes the case too, since priors that agree prove every typed number is a chance.", "The implied-priors test fails on this case, but the Analyzer reports that failure as a withholding, so the reviewer takes the missing cards for a refusal."]'::jsonb, 0, 'The refusal reads `Outcome chances given "Positive Seismic" sum to 110 percent, expected 100`. Before the repair the same inputs printed a gross voi of 42.50 beside an evpi card of 63.00, a plausible number built on percents that were not chances.'::text, 'Published posteriorsOffsetButPriorsAgree types outcome chances given Positive Seismic that sum to 110 percent, built so that the priors they imply equal the stated ones. Why does a reviewer who checks only the implied priors miss it?', '["The implied-priors test passes, and only the check that each set of outcome chances sums to 100 catches it, which the Analyzer runs first and refuses on.", "The implied-priors test is run on rounded posteriors, so an offset of 10 percent is absorbed inside the half percent tolerance before it can register at all.", "The reviewer''s test is the right one, and the Analyzer passes the case too, since priors that agree prove every typed number is a chance.", "The implied-priors test fails on this case, but the Analyzer reports that failure as a withholding, so the reviewer takes the missing cards for a refusal."]'::jsonb, 0, 'The refusal reads `Outcome chances given "Positive Seismic" sum to 110 percent, expected 100`. Weighted as typed with nothing checking them, the same inputs give a gross voi of 42.50 beside an evpi of 63.00, a plausible number built on percents that are not chances.'::text),
      ('advanced', 'module', 'm04-refusals-and-silent-defaults'::text, 15, 'Thirds typed as 0.333 on "Three equal outcomes", paying 30, 60 and 90, are refused. A user repairs the node by nudging the branch paying 90 until the sum reads 1. What is wrong with that repair?', '["Nothing, because the tolerance of 1e-6 exists precisely so a user can close a rounding gap on whichever branch is most convenient to edit by hand.", "It is refused again, because the engine compares each branch with the others and requires equal chances on a node whose payoffs are evenly spaced.", "It moves the EMV only in the sixth decimal, which the rollback does not print at four places, so the result still reads 60.0000.", "The node passes but no longer says the outcomes are equally likely, so the EMV moves off 60.0000 by whatever the nudge put on that branch."]'::jsonb, 3, 'The repair is to type every third to seven places: 0.3333333 on each branch sums to 1.000000 and rolls back to 60.0000. A nudge changes the chances unequally, which is a different tree that happens to pass the check.'::text, 'Thirds typed as 0.333 on "Three equal outcomes", paying 30, 60 and 90, are refused. A user repairs the node by nudging the branch paying 90 until the sum reads 1. What is wrong with that repair?', '["Nothing, because the tolerance of 1e-6 exists precisely so a user can close a rounding gap on whichever branch is most convenient to edit by hand.", "It is refused again, because the engine compares each branch with the others and requires equal chances on a node whose payoffs are evenly spaced.", "It moves the EMV only in the sixth decimal, which the rollback does not print at four places, so the result still reads 60.0000.", "The node passes but no longer says the outcomes are equally likely, so the EMV moves off 60.0000 by whatever the nudge put on that branch."]'::jsonb, 3, 'The fix is to type every third to six places or more: 0.333333 passes at 59.9999, weighted as typed, and 0.3333333 sums to 1.000000 and rolls back to 60.0000. A nudge changes the chances unequally, which is a different tree that happens to pass the check.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 1, 'On the EKPAN lottery at a success probability of 0.35 the drill is worth 75.7500 and the farm-out 33.2500. What would make either decision module recommend the farm-out at these same payoffs and chances?', '["Setting a risk tolerance below the drill''s loss of 80.0000, which the rollback reads before comparing the two means.", "Nothing in either module, since both maximise expected money and neither holds a utility function or a risk aversion setting.", "The drill''s 0.650000 chance of losing money, since the engine demotes an action that loses more often than it wins.", "A higher discount rate on the drill''s success payoff, because the rollback applies the rate typed on each terminal before weighting."]'::jsonb, 1, 'The engine sees only the two means: 0.350000 x 365.0000 plus 0.650000 x -80.0000 is 75.7500. A preference for the farm-out belongs in words beside the tree, never hidden in a payoff quietly lowered until the farm-out wins.'::text, 'On the EKPAN lottery at a success probability of 0.35 the drill is worth 75.7500 and the farm-out 33.2500. What would make either decision module recommend the farm-out at these same payoffs and chances?', '["Setting a risk tolerance below the drill''s loss of 80.0000, which the rollback reads before comparing the two means.", "Nothing in either module, since both maximise expected money and neither holds a utility function or a risk aversion setting.", "The drill''s 0.650000 chance of losing money, since the engine demotes an action that loses more often than it wins.", "A higher discount rate on the drill''s success payoff, because the rollback applies the rate typed on each terminal before weighting."]'::jsonb, 1, 'The engine sees only the two means: 0.350000 x 365.0000 plus 0.650000 x -80.0000 is 75.7500. A preference for the farm-out belongs in words beside the tree and is never hidden in a payoff quietly lowered until the farm-out wins.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 3, 'A small tree values Drill at 40.0000 less a cost of 10.0000 and Farm out at 30.0000. Listed Drill first it recommends Drill; listed Farm out first it recommends Farm out. What decides the recommendation?', '["The listing order, because a decision node replaces its incumbent only on a strictly greater value, so the first of two equal branches is kept.", "Floating-point residue in the cost subtraction, which leaves one of the branches a few binary digits ahead depending on which is evaluated first.", "The branch with the lower cost, since the engine breaks an equal EMV in favour of the action that commits less money up front.", "The last branch evaluated, because a decision node overwrites its best choice whenever a later value is at least as large."]'::jsonb, 0, 'Both orderings return an emv of 30.0000, and only the label follows the order in which somebody typed the branches. Residue decides at a computed switch point such as 0.228571 on the EKPAN lottery; 40.0000 less 10.0000 is exactly 30.0000.'::text, 'A small tree values Drill at 40.0000 less a cost of 10.0000 and Farm out at 30.0000. Listed Drill first the optimal path marks Drill; listed Farm out first it marks Farm out. What decides the mark?', '["The listing order decides only which tied branch the optimal path marks; the engine reports the two as tied in either order.", "Floating-point residue in the cost subtraction, which leaves one of the branches a few binary digits ahead depending on which is evaluated first.", "The branch with the lower cost, since the engine breaks an equal EMV in favour of the action that commits less money up front.", "The last branch evaluated, because a decision node overwrites its best choice whenever a later value is at least as large."]'::jsonb, 0, 'Both orderings return an emv of 30.0000 with the tie reported, and only the mark follows the order in which somebody typed the branches. At the computed switch point 0.228571 on the EKPAN lottery the engine reports a tie as well; 40.0000 less 10.0000 is exactly 30.0000.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 4, 'In the VOI Analyzer, Success at 25 percent pays 200, Dry hole at 75 percent pays -50, and the decision cost is 12.5. The insight names ''Drill Exploration Well'' as the optimal decision beside an EMV without information of 0.00. Why that action?', '["Acting is worth a small binary residue above 0 once the cost is subtracted, and the Analyzer names whichever action leads by that residue.", "The Analyzer names the risky action whenever the net value is positive, and the netVoi card reads 20.00.", "Acting is worth exactly 0, the same as \"Do Not\", and the named decision is listed first, so it keeps an exact tie.", "The Analyzer compares its actions before charging the decision cost of 12.5, so drilling leads by that amount before any card is filled."]'::jsonb, 2, '0.25 x 200 plus 0.75 x -50 less 12.5 is exactly 0, and nothing on the screen says walking away is worth the same. The gross voi of 25.00 is large precisely because the prior decision is perfectly unsettled.'::text, 'In the VOI Analyzer, Success at 25 percent pays 200, Dry hole at 75 percent pays -50, and the decision cost is 12.5. What does the insight say about the decision without new information, and why?', '["That ''Drill Exploration Well'' is the optimal decision, because acting is worth a small binary residue above 0 once the decision cost of 12.5 is subtracted.", "That drilling is optimal, because the Analyzer names the risky action whenever the net value is positive and the netVoi card reads 20.00.", "That ''Drill Exploration Well'' and ''Do Not Drill Exploration Well'' both come to $0.00M, so it is indifferent between them, because acting is worth exactly 0.", "That drilling leads by 12.5, because the Analyzer compares its two actions on their payoffs alone and charges the decision cost of 12.5 only after it has chosen."]'::jsonb, 2, '0.25 x 200 plus 0.75 x -50 less 12.5 is exactly 0, and the insight names both actions. The gross voi of 25.00 is large because the prior decision is perfectly unsettled.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 5, 'A Decision Studio brief for published equalEmvTie prints Optimal EMV 30.0000 and Recommended first move "A". Which row shows that the recommendation is a tie?', '["Decision advantage, which reads 0.0000 because Next best alternative is also 30.0000.", "Recommended first move, which appends the tied branch \"B\" after \"A\" whenever two root branches share the optimal value.", "Next best alternative, which reads 29.9990 for \"C\" and so shows that the runner-up sits only a hair below the choice.", "Optimal EMV, which is printed without decimals when two branches tie so that a reader can see the value is shared."]'::jsonb, 0, 'Next best alternative is the largest other root branch value, "B" at 30.0000, while "C" is 29.9990. The advantage row is the only place the tie is visible, so read it before the first move.'::text, 'Reading a Decision Studio brief of the published equalEmvTie tree, where would a reviewer see that no single first move is being recommended?', '["Recommended first move, which names A, B and C as coming to the same figure, and Decision advantage, which reads Indifferent at the precision shown.", "Only Decision advantage, which reads 0.0000 because Next best alternative is also 30.0000, beside a first move of \"A\".", "Next best alternative, which reads 29.9990 for \"C\" and so shows that the runner-up sits only a hair below the branch the brief names as its choice.", "Optimal EMV, which is printed without decimals whenever two root branches tie, so that a reader can see at a glance that the value is shared."]'::jsonb, 0, 'All three root values print as 30.00 on a card, C included at 29.9990, so the first-move row lists them together and the advantage row carries the word Indifferent where a margin would be.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 6, 'On the Analyzer''s default study the gross voi is 33.00. At a survey cost of 32.996 the netVoi card reads 0.00. What does the verdict sentence say?', '["The information exactly pays for itself, because the verdict reads the two-decimal card and the card says 0.00.", "Since this is positive, acquiring the information is financially advantageous, because the verdict tests the net value before it is rounded.", "No verdict at all, since the Analyzer drops the sentence whenever a card rounds to zero and leaves the choice to the reader.", "The information exactly pays for itself, because a net value within half a cent of zero falls inside the Analyzer''s neutral band."]'::jsonb, 1, '33 less 32.996 is a small positive amount: the card rounds it to 0.00 and the sentence tests its sign. Only at a cost of exactly 33.000 do the card and the sentence both say neutral; no neutral band exists.'::text, 'On the Analyzer''s default study the gross voi is 33.00. At a survey cost of 32.996 the netVoi card reads 0.00. What does the verdict sentence say?', '["Since this is negative, the information costs more than the value it adds, because the verdict sets the cost against the EVPI card.", "Since this is positive, acquiring the information is financially advantageous, because the verdict tests the net value before it is rounded.", "No verdict at all, since the Analyzer drops the sentence whenever the net card rounds to zero and leaves the whole choice of whether to buy the survey to the reader.", "Since this rounds to zero, the information costs what it is worth, so acquiring it or not is indifferent on EMV grounds, because the verdict reads the card."]'::jsonb, 3, 'The net VOI is rounded once to the two-decimal card, half away from zero with a 1e-12 allowance, and the verdict reads that same value. At 32.990 the card reads 0.01 and the sentence says positive; at 33.010 it reads -0.01 and says negative.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 7, 'Priced at 33.004, the default survey shows -0.00 on its net value card. What is the sign telling a reader?', '["Nothing, since -0.00 and 0.00 are the same number on a two-decimal card and the verdict beside both of them reads value-neutral.", "That the survey cost was entered as a negative receipt, which the Analyzer marks with a sign on an otherwise zero card.", "That the consistency check found a small disagreement, which the Analyzer reports as a signed zero in place of withholding.", "That the net value before rounding is a small negative amount whose sign the rounding kept, which is why the verdict says the survey is not justified."]'::jsonb, 3, 'The cards are toFixed(2) strings: 33 less 33.004 is negative and prints -0.00, and the verdict reads that same value unrounded and writes negative. At 32.996 the card reads 0.00 beside a positive verdict.'::text, 'Priced at 33.004, the default survey''s net value card reads 0.00. What do the card and the verdict tell a reader?', '["That the cost is a hair above the value, since the card prints -0.00 to keep the sign of the unrounded net value.", "That the survey cost was entered as a negative receipt, which the Analyzer marks with a sign on an otherwise zero card.", "That the consistency check found a small disagreement, which the Analyzer reports as a signed zero in place of withholding.", "It sits at its gross value to the cent: 33 less 33.004 rounds to a 0.00 card, and the sentence beside it reads that same card as zero."]'::jsonb, 3, '33 less 33.004 is a small negative amount, and rounded half away from zero to two decimals it is 0.00; -0.00 is never printed, and the verdict reads the same rounded value. At 33.010 the card reads -0.01 beside the negative verdict.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 8, 'A netVoi card reads 0.00 and the verdict beside it says positive. What does a careful reader report?', '["That the survey is a positive investment, because the verdict tests the unrounded number and is therefore the more precise of the two readings.", "That the survey is value-neutral, because the card is what the Analyzer displays and a sentence can never be more precise than its card.", "That the survey is priced at its value, found by comparing the cost with the gross voi, since the cost that makes information neutral is the gross value, 33.00 on the default study.", "That the survey is worth buying at any cost below the evpi card of 63.00, since the ceiling bounds the price and the gross value only bounds the net."]'::jsonb, 2, 'Costs of 32.996 and 33.004 are indistinguishable in any real tender, so a verdict flipping between them reports the sign of a residue. On the EKPAN lottery''s full survey the neutral price is its gross 24.8250.'::text, 'A netVoi card reads 0.00 and the verdict beside it says the value rounds to zero. What does a careful reader report?', '["That the survey is a positive investment, because a card of 0.00 is a rounded positive amount and the verdict only hides its sign.", "That the survey is worth buying, because a 0.00 card means the net value is at least zero before rounding.", "That the survey is priced at its value, found by comparing the cost with the gross voi, since the cost that makes information neutral is the gross value, 33.00 on the default study.", "That the survey is worth buying at any cost below the evpi card of 63.00, since the ceiling bounds the price and the gross value only bounds the net."]'::jsonb, 2, 'Costs of 32.996 and 33.004 both round to a 0.00 card with the rounds-to-zero sentence, and no real tender separates them. The neutral price is the gross value, 33.00 on the default study and 24.8250 on the EKPAN lottery''s full survey.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 1, 'IRRI types both of the Analyzer''s indicators as 20 / 80 percent against stated outcome chances of 30 / 70. What does an expert reading write down?', '["A value of information of -15.00, worked out by hand from the typed chances, since the repaired Analyzer no longer prints one.", "A value of information of 0.00, since a withheld value means the survey cannot change the decision and so is worth nothing.", "No numbers at all, because indicator chances that contradict the stated ones are refused before the Analyzer computes anything.", "EMV without information 15.00 and EVPI 63.00, with the value of information withheld because the inputs imply a success chance of 0.200000."]'::jsonb, 3, 'The two surviving cards depend only on the stated outcome chances. -15.00 is the gross voi printed before the EC4-0 repair, history and below the zero floor that Bayes guarantees, and a withheld value is never written as 0.00.'::text, 'IRRI types both of the Analyzer''s indicators as 20 / 80 percent against stated outcome chances of 30 / 70. What does an expert reading write down?', '["A value of information of -15.00, worked out by hand from the typed chances, since the Analyzer prints none.", "A value of information of 0.00, since a withheld value means the survey cannot change the decision and so is worth nothing.", "No numbers at all, because indicator chances that contradict the stated ones are refused before the Analyzer computes anything.", "EMV without information 15.00 and EVPI 63.00, with the value of information withheld because the inputs imply a success chance of 0.200000."]'::jsonb, 3, '15.00 and 63.00 need nothing but the stated chances, so they survive. The unguarded -15.00 falls under the zero floor Bayes guarantees, and a withheld value is never written as 0.00.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 2, 'Before the EC4-0 repair, published certainPosteriorsWithheld printed a gross voi of 245.00. What made that number impossible on sight?', '["It sat below the default study''s genuine gross voi of 33.00, which any survey on those same payoffs must at least reach.", "It sat above the evpi card of 63.00, and no information can be worth more than perfect information.", "It turned negative once the survey cost of 10.0000 was taken off, and a net value below zero cannot come out of Bayes.", "Its implied success chance of 1.000000 lies outside the range the Analyzer accepts, so the value rested on an out-of-range input."]'::jsonb, 1, 'The inputs imply 1.000000 / 0.000000 against a stated 0.300000 / 0.700000, and the net value then was 235.00. The repaired Analyzer reports 15.00 and 63.00 and withholds the rest.'::text, 'Weighted as typed with nothing checking them, published certainPosteriorsWithheld gives a gross voi of 245.00. What makes that number impossible on sight?', '["It sits below the default study''s genuine gross voi of 33.00, which any survey on those same payoffs must at least reach.", "It sits above the evpi card of 63.00, and no information can be worth more than perfect information.", "It turns negative once the survey cost of 10.0000 is taken off, and a net value below zero cannot come out of Bayes.", "Its implied success chance of 1.000000 lies outside the range the Analyzer accepts, so the value rested on an out-of-range input."]'::jsonb, 1, 'The inputs imply 1.000000 / 0.000000 against a stated 0.300000 / 0.700000, and the net value would be 235.00. The Analyzer reports 15.00 and 63.00 and withholds the rest.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 4, 'The first step of an expert case adds every set of typed percents. The EKPAN lottery typed with No bright spot at 64 percent fails it. What is the answer for that case?', '["The refusal message, `Indicator chances sum to 110 percent, expected 100`, and the box at fault, since a refused case has no value.", "EMV without information 75.75 and EVPI 52.00 with the value of information withheld, as for any typed inputs that fail a check.", "The values from the later steps with No bright spot corrected so that the pair sums to 100, since the message names the box that was mistyped.", "The gross voi the Analyzer printed before the repair, since a refused case is valued the way the Analyzer valued it before EC4-0."]'::jsonb, 0, 'The indicator chances sum to 110.000000 percent, so they are not a distribution. Withholding with 75.75 and 52.00 answers chances that sum correctly but contradict each other, and the message never says whether 64 or 46.000000 is the slip.'::text, 'The first step of an expert case adds every set of typed percents. The EKPAN lottery typed with No bright spot at 64 percent fails it. What is the answer for that case?', '["The refusal message, `Indicator chances sum to 110 percent, expected 100`, and the box at fault, since a refused case has no value.", "EMV without information 75.75 and EVPI 52.00 with the value of information withheld, as for any typed inputs that fail a check.", "The values from the later steps with No bright spot corrected so that the pair sums to 100, since the message names the box that was mistyped.", "The gross voi the typed chances give with nothing checking them, since a refused case is valued by its unguarded arithmetic."]'::jsonb, 0, 'The indicator chances sum to 110.000000 percent, so they are not a distribution. Withholding with 75.75 and 52.00 answers chances that sum correctly but contradict each other, and the message never says whether 64 or 46.000000 is the slip.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 8, 'On the EKPAN lottery an expert values the survey at a cost of 8.0000. Which set of figures belongs in the report?', '["Gross 24.8250, net 16.8250, a neutral price equal to the gross 24.8250, and bounds of 0 and 52.0000 on the gross.", "Gross 24.8250, net 16.8250, and a neutral price of 52.0000, since information stays worth buying until its cost reaches the EVPI ceiling.", "Gross 16.8250 and net 8.8250, since the survey cost is taken off once inside the information tree and again when the net is reported.", "Gross 100.5750 and net 92.5750, since the value of information is the expected value with the survey before the prior is subtracted."]'::jsonb, 0, 'EVII is 100.5750 less 75.7500. The information tree''s two root branches tie at a survey cost of 24.8250, where the engine keeps the acquisition as the branch listed first.'::text, 'On the EKPAN lottery an expert values the survey at a cost of 8.0000. Which set of figures belongs in the report?', '["Gross 24.8250, net 16.8250, a neutral price equal to the gross 24.8250, and bounds of 0 and 52.0000 on the gross.", "Gross 24.8250, net 16.8250, and a neutral price of 52.0000, since information stays worth buying until its cost reaches the EVPI ceiling.", "Gross 16.8250 and net 8.8250, since the survey cost is taken off once inside the information tree and again when the net is reported.", "Gross 100.5750 and net 92.5750, since the value of information is the expected value with the survey before the prior is subtracted."]'::jsonb, 0, 'EVII is 100.5750 less 75.7500. The information tree''s two root branches tie at a survey cost of 24.8250, where the engine reports the tie and marks the acquisition, listed first.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 13, 'The story so far says thirds typed as 0.333 are refused while 0.3333333 rolls back to 60.0000. Where do thirds typed to six places, 0.333333, fall?', '["Accepted at 60.0000, because the message would print 0.999999, which is exactly 1e-6 short and inside a tolerance that includes its edge.", "Accepted at 60.0000, because the EC4-0 repair gave the chance node sum the same 1e-12 allowance that holds the half percent boundary.", "Accepted just below 60.0000, because the engine weights the payoffs by 0.333333 each and reports the slightly smaller mean.", "Refused, because in binary their sum misses 1 by 0.0000010000000000287557 and the chance node check makes no allowance for binary rounding."]'::jsonb, 3, 'Six places and fewer are refused and seven land inside 1e-6. The 1e-12 allowance belongs to the implied-priors check alone; adding one here is an open owner decision (finding EC4-8).'::text, 'The story so far says thirds typed as 0.333 are refused while 0.3333333 rolls back to 60.0000. Where do thirds typed to six places, 0.333333, fall?', '["Accepted at 60.0000, because the message would print 0.999999, which is exactly 1e-6 short and inside a tolerance that includes its edge.", "Accepted at 60.0000, because the engine rescales an accepted sum to 1 before it weights the payoffs of the node.", "Accepted just below 60.0000, because the engine weights the payoffs by 0.333333 each and reports the slightly smaller mean.", "Refused, because in binary their sum misses 1 by a hair above 1e-6 and the chance node check makes no allowance for binary rounding."]'::jsonb, 2, 'The sum test is |sum - 1| at most 1e-6 plus a 1e-12 allowance and includes its edge, so six places pass and are weighted as typed: 0.333333 x (30 + 60 + 90) = 59.9999. Five places and fewer are refused, and seven give 60.0000.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 14, 'The half percent boundary on implied priors holds in the repaired check. What holds it?', '["A 1e-12 allowance on top of 0.005, which absorbs 0.0050000000000000044, the binary value of 0.305 less 0.3.", "An inclusive comparison against 0.005 alone, which suffices because 0.305 less 0.3 is exactly 0.005 in binary floating point.", "A threshold widened to 6.000000e-3, which is why an implied chance of 0.306000 is the first case the Analyzer withholds.", "Rounding each implied chance to six decimals before the delta is taken, so that 0.305000 less 0.300000 comes out exact."]'::jsonb, 0, 'The binary delta overshoots 0.005 by 4.3e-18, and before EC4-0 the engine had no allowance and called justInsideTolerance inconsistent (finding D1). An implied 0.306000 is inconsistent before and after the repair.'::text, 'The half percent boundary on implied priors holds in the Analyzer''s check. What holds it?', '["A 1e-12 allowance on top of 0.005, which absorbs 0.0050000000000000044, the binary value of 0.305 less 0.3.", "An inclusive comparison against 0.005 alone, which suffices because 0.305 less 0.3 is exactly 0.005 in binary floating point.", "A threshold widened to 6.000000e-3, which is why an implied chance of 0.306000 is the first case the Analyzer withholds.", "Rounding each implied chance to six decimals before the delta is taken, so that 0.305000 less 0.300000 comes out exact."]'::jsonb, 0, 'The binary delta overshoots 0.005 by 4.3e-18; compared against 0.005 alone justInsideTolerance would read inconsistent. An implied 0.306000 is inconsistent with or without the allowance.'::text)
    ) as t(tier, scope, module_key, ord, old_prompt, old_options, old_answer, old_expl, new_prompt, new_options, new_answer, new_expl)
  loop
    select case
             when q.prompt = r.old_prompt and q.options = r.old_options and q.answer_index = r.old_answer and q.explanation is not distinct from r.old_expl then 'old'
             when q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer and q.explanation is not distinct from r.new_expl then 'new'
             else 'other' end
      into v_state
      from public.academy_quiz_questions q
     where q.app_slug = 'decision' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec45 recut refused: decision/%/%/%/ord % matched % active rows, expected 1', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
    end if;
    if v_state = 'other' then
      raise exception 'ec45 recut refused: decision/%/%/%/ord % carries neither its served text nor the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
    if v_state = 'old' then
      update public.academy_quiz_questions q
         set prompt = r.new_prompt, options = r.new_options, answer_index = r.new_answer, explanation = r.new_expl
       where q.app_slug = 'decision' and q.active and q.tier = r.tier and q.scope = r.scope
         and q.module_key is not distinct from r.module_key and q.ord = r.ord
         and q.answer_index = r.old_answer;
      get diagnostics v_count = row_count;
      if v_count <> 1 then
        raise exception 'ec45 recut refused: decision/%/%/%/ord % update touched % rows', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
      end if;
      v_updated := v_updated + 1;
    else
      v_done := v_done + 1;
    end if;
    perform 1 from public.academy_quiz_questions q
     where q.app_slug = 'decision' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord
       and q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer
       and q.explanation is not distinct from r.new_expl;
    if not found then
      raise exception 'ec45 recut refused: decision/%/%/%/ord % does not read back as the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
  end loop;
  if v_updated + v_done <> 141 then
    raise exception 'ec45 recut refused: decision accounted for % rows, expected 141', v_updated + v_done;
  end if;
  perform set_config('ec45.rows_decision', (v_updated + v_done)::text, false);
  raise notice 'ec45 recut: decision questions, % updated, % already recut, of 141', v_updated, v_done;
end $$;

-- ----------------------------------------------------------------------------
-- 2. portfolio: 178 question rows (beginner 63, intermediate 53, advanced 62).
-- ----------------------------------------------------------------------------
do $$
declare
  r         record;
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_done    integer := 0;
begin
  for r in
    select * from (values
      ('beginner', 'final', null::text, 1, 'An analyst retypes OKONO''s inventory with every capex and the limit as a count of USD instead of million USD, and changes nothing else. What changes in how the engine solves it, and where would the analyst see the change?', '["Nothing changes in the solve, because risked EMV per million USD is a ratio whose unit cancels, so the ranking and the set come out identical.", "The engine refuses the run with a PortfolioInputError, since a capex that large beside NPVs in million USD fails the engine''s scale check.", "The limit is no longer at most 5000, so the grid turns coarse at the limit divided by 2000 per cell, and only the reported resolution shows the switch.", "The grid stays at 1 million USD per cell but every project now weighs a million times more cells, so none of them fits under the limit and nothing is funded at all."]'::jsonb, 2, 'The exact grid needs whole numbers and a limit of at most 5000; the published rawDollars case runs on a cell of 225000.000000 USD and still reaches the exact 250.0000, with a gap of 0.0000.'::text, 'An analyst retypes OKONO''s inventory with every capex and the limit as a count of USD where they were million USD, and changes nothing else. What changes in how the engine solves it, and where would the analyst see the change?', '["The optimizer switches to its fallback grid, since a limit in the hundreds of millions holds more partial portfolios than the exact solve allows.", "The engine refuses the run with a PortfolioInputError, since a capex that large beside NPVs in million USD fails the engine''s scale check.", "Nothing in the solve or the output: the same funded set comes back, because the knapsack is exact at any scale.", "The grid stays at 1 million USD per cell but every project now weighs a million times more cells, so none of them fits under the limit and nothing is funded at all."]'::jsonb, 2, 'Read at their typed precision, the retyped figures give the same knapsack scaled by a million, so OKONO still funds OK-1 + OK-3 + OK-4 for 291.0000. A unit slip is visible only in the inputs a reviewer reads.'::text),
      ('beginner', 'final', null::text, 2, 'A board minute says the optimizer picked the safe portfolio when it chose OKONO''s 600.0000 set over its 450.0000 one. What role did the simulated loss probabilities play in selecting either set?', '["None: the optimizer and the frontier rank on risked EMV alone, and the seeded risk summary is computed afterwards for the set already chosen.", "They broke a near tie, because the engine penalises each set''s risked EMV by its simulated loss probability before comparing it with the rest of the frontier.", "They screened the inventory, since any project whose failure branch lifts a set''s P(loss) above the default is dropped before the knapsack runs.", "They decided OK-3, which the simulation found worth its risk at 450.0000 and not worth it at 600.0000, where a safer set was available."]'::jsonb, 0, 'The 600.0000 set wins because 402.7500 beats every other set that fits, not because it is safer; a lower-risk set of nearly equal value is never offered.'::text, 'A board minute says the optimizer picked the safe portfolio when it chose OKONO''s 600.0000 set over its 450.0000 one. What role did the simulated loss probabilities play in selecting either set?', '["None: the optimizer and the frontier rank on risked EMV alone, and the seeded risk summary is computed afterwards for the set already chosen.", "They broke a near tie, because the engine penalises each set''s risked EMV by its simulated loss probability before comparing it with the rest of the frontier.", "They screened the inventory, since any project whose failure branch lifts a set''s P(loss) above the default is dropped before the knapsack runs.", "They decided OK-3, which the simulation found worth its risk at 450.0000 and not worth it at 600.0000, where a safer set was available."]'::jsonb, 0, 'The 600.0000 set wins because 402.7500 beats every other set that fits; safety played no part, and a lower-risk set of nearly equal value is not offered.'::text),
      ('beginner', 'final', null::text, 4, 'A risky project''s chance of success is left blank in an inventory. Beyond its risked EMV, what does the blank do to the seeded risk summary of a set that funds it?', '["Nothing, since the simulation draws its own success rate from the entered percentiles whatever pos says, and only the optimizer uses the default.", "The default of 1 travels into the simulation, so the project succeeds in every iteration, never adds a failure to P(loss) and never drags down the P90.", "The simulation refuses to run for that set and reports P(loss) as null until a chance of success is entered for every funded project.", "The simulation treats the blank as a coin toss and draws success half the time, so the set looks riskier than its risked EMV would suggest."]'::jsonb, 1, 'A defaulted value is used everywhere the project is used; at seed 20260829 and 10000 iterations the project is a certain success, so one blank row makes a set look both more valuable and safer.'::text, 'A risky project''s chance of success is left out of its row entirely. Beyond its risked EMV, what does the default do to the seeded risk summary of a set that funds it?', '["Nothing, since the simulation draws its own success rate from the entered percentiles whatever pos says, and only the optimizer uses the default.", "The default of 1 travels into the simulation, so the project succeeds in every iteration, adds no failure to P(loss) and does not drag down the P90.", "The simulation refuses to run for that set and reports P(loss) as null until a chance of success is entered for every funded project.", "The simulation treats the blank as a coin toss and draws success half the time, so the set looks riskier than its risked EMV would suggest."]'::jsonb, 1, 'A pos left out or null is the default 1, used everywhere the project is used; at seed 20260829 and 10000 iterations the project is a certain success. A pos typed as a blank is refused by name before anything runs.'::text),
      ('beginner', 'final', null::text, 5, 'A study already paid for elsewhere is added to OKONO as a project with capex 0.0000 and a positive risked EMV, and the limit stays at 450.0000. Can the engine''s answer hold it together with OK-1 + OK-3 + OK-4?', '["Yes, because a project with capex 0.0000 weighs nothing on any grid and rides along with every set whose risked EMV it raises.", "Yes, but only with overLimit true and overLimitBy of 1 million USD, since the engine lets a free project squeeze in over a limit that is already spent.", "No: the grid charges it one cell, and OK-1 + OK-3 + OK-4 already use all 450.0000 cells, so no spare cell is left for it.", "No, because a capex of 0.0000 is refused by the check that stops a negative capex."]'::jsonb, 2, 'Every project weighs max(1, round(capex / cell)) cells, finding D2; in freeProjectTightLimit the same effect costs 10.0000 of EMV at a limit of 100.0000 while overLimit stays false.'::text, 'A study already paid for elsewhere is added to OKONO as a project with capex 0.0000 and a positive risked EMV, and the limit stays at 450.0000. Can the engine''s answer hold it together with OK-1 + OK-3 + OK-4?', '["No: the optimizer keeps the set it has already found for 450.0000 and adds nothing to a limit that is fully spent.", "Yes, but only with overLimit true and overLimitBy of 1 million USD, since the engine lets a free project squeeze in over a limit that is already spent.", "Yes: a project with capex 0.0000 weighs nothing on the exact solve, so it is funded beside OK-1 + OK-3 + OK-4 whenever its risked EMV is positive.", "No, because a capex of 0.0000 is refused by the check that stops a negative capex."]'::jsonb, 2, 'On the exact solve a free project weighs nothing: freeProjectTightLimit funds free + A at capex 100.0000 for 70.0000 at a limit of 100.0000, and freeProjectZeroLimit funds the free project even at a limit of 0.0000.'::text),
      ('beginner', 'final', null::text, 7, 'Two answers leave money idle: OKONO at 750.0000 spends 690.0000, and the gridUndershoot case spends 4500.0000 of 6000.0000. Why is only the second a reason to distrust the set?', '["The second leaves a quarter of its limit idle and the first under a tenth, and the engine marks an answer unreliable once idle money passes a set share of the limit.", "OKONO solves on an exact grid and its one left-out project, OK-6 at 310.0000, cannot fit, while the undershoot runs on a coarse grid where rounded-up weights squeezed out W, which fits in money.", "The undershoot reports overLimit true, which marks a grid problem, while OKONO at 750.0000 reports false and so needs no further check by the reader.", "Both are equally suspect, since money left unspent always means the knapsack stopped early and a better set of whole projects exists somewhere."]'::jsonb, 1, 'The golden gap of -200.0000 is exactly W''s risked EMV and no flag reports it (finding D4); OKONO''s 60.0000 is genuine because nothing that remains fits.'::text, 'Two answers leave money idle: OKONO at 750.0000 spends 690.0000, and the gridUndershootFallback case, run on the stated fallback grid, spends 4500.0000 of 6000.0000. Why is only the second a reason to look harder at the set?', '["The second leaves a quarter of its limit idle and the first under a tenth, and the engine marks an answer unreliable once idle money passes a set share of the limit.", "OKONO is solved exactly and its one left-out project, OK-6 at 310.0000, cannot fit, while the fallback rounds weights up and states optimalityGap 200.0000, the most its set may leave out.", "The fallback reports overLimit true, which marks a grid problem, while OKONO at 750.0000 reports false and so needs no further check by the reader.", "Both are equally suspect, since money left unspent always means the knapsack stopped early and a better set of whole projects exists somewhere."]'::jsonb, 1, 'On gridUndershootFallback the weights of 500, 500, 500 and 501 cells exceed 2000, so the fallback funds X + Y + Z for 660.0000 with solveMethod grid-feasible, while W at 1499.0000 fits in money and the exact optimum is 860.0000. OKONO''s 60.0000 is genuine because nothing that remains fits.'::text),
      ('beginner', 'final', null::text, 8, 'In tieDifferentComposition the engine returns A for 80.0000 where B + C also reaches 80.0000. What would a reviewer need in order to compare the P(loss) of the two sets?', '["A separate simulation of B + C, because the engine''s risk summary covers only the set it returned and its output names no alternative optimum.", "Nothing extra, since the risk summary averages P(loss) over every set that ties on risked EMV and reports the blended figure beside the funded set.", "Nothing extra, since tied sets share their risked EMV and therefore share their P(loss) and their P90 as well, whatever projects they hold.", "A rerun on a finer grid, since the engine lists alternative optima in its output only when the resolution drops below 1.0000."]'::jsonb, 0, 'The knapsack keeps the first set it builds and replaces it only with a strictly larger EMV; A is one bet and B + C spreads the same 80.0000 over two, so their risk can differ widely.'::text, 'In tieDifferentComposition the engine returns A for 80.0000 where B + C also reaches 80.0000. What would a reviewer need in order to compare the P(loss) of the two sets?', '["A separate simulation of B + C, because the engine''s risk summary covers only the set it returned and its output names no alternative optimum.", "Nothing extra, since the risk summary averages P(loss) over every set that ties on risked EMV and reports the blended figure beside the funded set.", "Nothing extra, since tied sets share their risked EMV and therefore share their P(loss) and their P90 as well, whatever projects they hold.", "A rerun on a finer grid, since the engine lists alternative optima in its output only when the resolution drops below 1.0000."]'::jsonb, 0, 'Among sets tied on risked EMV the optimizer keeps the one with less capex, and at equal capex the set built without the later project in the list; A and B + C both cost 100.0000, so A comes back. A is one bet and B + C spreads the same 80.0000 over two, so their risk can differ widely.'::text),
      ('beginner', 'final', null::text, 9, 'Three inventories each hide a problem: a capex typed as -150, a coarse grid that funds 6002.0000 against 6000.0000, and a coarse grid that leaves out a project worth 200.0000. How does the engine treat each?', '["It refuses all three, because each one breaks a condition the knapsack needs before it can honestly return a set under the limit.", "It flags the first and second through overLimit, and flags the third by printing a negative gap to the exact optimum beside the set.", "It refuses the first and the second, since a set over the limit is rejected like a negative capex, and reports the third as money unspent.", "It refuses the first, flags the second with overLimit true, and says nothing about the third."]'::jsonb, 3, 'The only refusal is a negative capex; the overshoot flag reads overLimitBy 2.0000, and the undershoot''s -200.0000 gap exists only in the golden, never in the engine''s output.'::text, 'Three inventories each hide a problem: a capex typed as -150, a pos typed as 1.4, and a large inventory sent to the stated fallback grid, which leaves out a project worth 200.0000. How does the engine treat each?', '["It refuses all three, because each one breaks a condition the knapsack needs before it can honestly return a set under the limit.", "It refuses the first, reads the second as 1 and funds that project as a certain success, and flags the third through overLimit.", "It refuses the first, reads the second as the default of 1, and reports the third as money unspent with nothing else beside it.", "It refuses the first two by project name, and reports the third with solveMethod \"grid-feasible\" and an optimalityGap of 200.0000."]'::jsonb, 3, 'The messages read Project "B" has a negative capex (-150); capex must be 0 or more, and Project "a" has a pos outside 0 to 1 (1.4); pos must be a number from 0 to 1. On gridUndershootFallback the fallback funds X + Y + Z for 660.0000 and states the bound beside it.'::text),
      ('beginner', 'final', null::text, 10, 'Working a graded inventory, a candidate finds the reported resolution is not 1.0000. Which checks does the Associate method require before the funded set is quoted?', '["Confirm that overLimit reads false, since a coarse grid can only go wrong by overshooting and the repaired flag now reports every overshoot.", "Rerun with a smaller limit until the resolution returns to 1.0000, since the engine offers its exact grid on request once asked.", "Sum the funded capex in money against the limit whatever overLimit says, look for a left-out project that would still fit, and look for an unfunded positive project with capex 0.0000.", "Nothing extra, since both published coarse cases, rawDollars and nonIntegerLimit, reached the exact optimum with a gap of 0.0000."]'::jsonb, 2, 'A coarse grid can overshoot, which is flagged, or undershoot or charge a free project a cell, which are silent (findings D4 and D2); only gridOvershoot''s overLimitBy 2.0000 is reported.'::text, 'Working a graded inventory, a candidate finds the result reports solveMethod "grid-feasible". What does the Associate method require before the funded set is quoted?', '["Nothing extra, since the fallback rounds every weight up and a set that fits its grid can only be the exact optimum.", "Rerun with a smaller limit until solveMethod reads \"exact\", since the engine offers its exact solve on request once asked.", "Read its optimalityGap, 200.0000 on gridUndershootFallback, as the most risked EMV the set may leave out, and look for a left-out project that still fits in money.", "Confirm overLimit reads false, since the fallback can only go wrong by overshooting the limit and the flag reports every overshoot."]'::jsonb, 2, 'The fallback rounds every weight up, so its set always fits the limit; it can fall short of the optimum, and optimalityGap states how far at most: 20.0000 on gridOvershootFallback, where nothing was lost, and 200.0000 on gridUndershootFallback, where W was left out.'::text),
      ('beginner', 'final', null::text, 11, 'A reviewer who counts rows from one opens an inventory without names or ids after a PortfolioInputError that blames Project "1" for a capex of -0.5. Which row holds the bad capex?', '["The first project in the list, since the engine numbers its rows from one in the same way the Suite''s inventory table does.", "The second project in the list, since an unnamed project is named by its position counted from zero.", "Any project with a capex of -0.5, since the number in quotes counts the refused projects rather than naming a position.", "No row at all, since a capex of -0.5 rounds to zero cells and the message is a warning that the run continues past."]'::jsonb, 1, 'The message names a project by name, then id, then position from 0, and the check runs before any set is chosen, so no partial answer comes back.'::text, 'A reviewer who counts rows from one opens an inventory without names or ids after a PortfolioInputError that blames Project "1" for a capex of -0.5. Which row holds the bad capex?', '["The first project in the list, since the engine numbers its rows from one in the same way the Suite''s inventory table does.", "The second project in the list, since an unnamed project is named by its position counted from zero.", "Any project with a capex of -0.5, since the number in quotes counts the refused projects and names no position.", "No row at all, since a capex of -0.5 rounds to zero cells and the message is a warning that the run continues past."]'::jsonb, 1, 'The message names a project by name, then id, then position from 0, and the check runs before any set is chosen, so no partial answer comes back.'::text),
      ('beginner', 'final', null::text, 19, 'An auditor wants to export the 60.0000 that OKONO''s five-project answer at 750.0000 leaves idle. Which part of the engine''s return carries it?', '["As overLimitBy with a negative sign, since that flag measures the distance between the funded capex and the limit on either side.", "Nowhere as a field: the engine returns the limit, the set, its capex and its EMV, and the reader derives the unspent amount by subtraction.", "As the resolution, which rises to 60.0000 whenever a limit cannot be spent exactly in whole projects on the exact grid.", "As a partial slice of OK-6, which the engine funds with the leftover money and reports beside the five whole projects."]'::jsonb, 1, 'Every unspent figure is derived, 750.0000 - 690.0000 = 60.0000, and it is genuine because OK-6 alone costs 310.0000; the frontier''s last point is printed at 690.0000, not at the limit.'::text, 'An auditor wants to export the 60.0000 that OKONO''s five-project answer at 750.0000 leaves idle. Which part of the engine''s return carries it?', '["As overLimitBy with a negative sign, since that flag measures the distance between the funded capex and the limit on either side.", "Nowhere as a field: the engine returns the limit, the set, its capex and its EMV, and the reader derives the unspent amount by subtraction.", "As the resolution, which rises to 60.0000 whenever a limit cannot be spent exactly in whole projects on the exact grid.", "As a partial slice of OK-6, which the engine funds with the leftover money and reports beside the five whole projects."]'::jsonb, 1, 'Every unspent figure is derived, 750.0000 - 690.0000 = 60.0000, and it is genuine because OK-6 alone costs 310.0000; the frontier''s last point is printed at 690.0000, the capex its set costs.'::text),
      ('beginner', 'final', null::text, 26, 'Handed a raised budget of 600.0000, a manager tops up the solved 450.0000 set with whatever else fits rather than re-running the optimizer. Where does topping up stop?', '["At 402.7500, since adding in ratio order to a solved set reaches the next one.", "At 329.0000 for 510.0000, with OK-5 added and nothing else fitting, against 402.7500 from solving again.", "At 444.0000, with OK-2 and OK-5 both added, since the extra 150.0000 of budget covers the pair of them together.", "At 291.0000, since the engine refuses a project added to a solved set by hand."]'::jsonb, 1, 'After OK-5 only 90.0000 is left and OK-2 costs 180.0000; the solved set at 600.0000 gives up OK-3 to fund OK-1 + OK-2 + OK-4 + OK-5.'::text, 'Handed a raised budget of 600.0000, a manager tops up the solved 450.0000 set with whatever else fits and does not re-run the optimizer. Where does topping up stop?', '["At 402.7500, since adding in ratio order to a solved set reaches the next one.", "At 329.0000 for 510.0000, with OK-5 added and nothing else fitting, against 402.7500 from solving again.", "At 444.0000, with OK-2 and OK-5 both added, since the extra 150.0000 of budget covers the pair of them together.", "At 291.0000, since the engine refuses a project added to a solved set by hand."]'::jsonb, 1, 'After OK-5 only 90.0000 is left and OK-2 costs 180.0000; the solved set at 600.0000 gives up OK-3 to fund OK-1 + OK-2 + OK-4 + OK-5.'::text),
      ('beginner', 'final', null::text, 28, 'A report shows OKONO''s frontier ending at 450.0000 and 291.0000 beside a funded set worth 287.7500. What should the reader conclude?', '["The funded set is the greedy set and the frontier is the optimum, which the engine prints side by side so the loss can be seen.", "The grid has undershot, and the 3.2500 between them is a project rounding left out.", "The two were not run on the same inventory and limit, so find which input changed before quoting either.", "The frontier includes projects the funded set excludes for risk, so its last point always sits a little above the set."]'::jsonb, 2, 'The last point is the best risked EMV inside the whole limit and must match the funded set; at 450.0000 both read OK-1 + OK-3 + OK-4 for 291.0000 on a resolution of 1.0000.'::text, 'A report shows OKONO''s frontier ending at 450.0000 and 291.0000 beside a funded set worth 287.7500. What should the reader conclude?', '["The funded set is the greedy set and the frontier is the optimum, which the engine prints side by side so the loss can be seen.", "The grid has undershot, and the 3.2500 between them is a project rounding left out.", "The two were not run on the same inventory and limit, so find which input changed before quoting either.", "The frontier includes projects the funded set excludes for risk, so its last point always sits a little above the set."]'::jsonb, 2, 'The last point is the best risked EMV inside the whole limit and must match the funded set; at 450.0000 both read OK-1 + OK-3 + OK-4 for 291.0000, solved exactly with solveMethod "exact".'::text),
      ('beginner', 'final', null::text, 29, 'rawDollars reports a resolution of 225000.000000 and nonIntegerLimit a resolution of 0.225250. What does a resolution measure?', '["The size of one capex cell in the money units entered, USD in the first case and million USD in the second.", "The precision of the risked EMV, so the second case''s answer is reliable to a far finer margin than the first''s.", "The number of cells the limit is divided into, which grows when the capexes are typed in USD.", "The standard error of the simulated P(loss), which the engine shrinks as the limit grows."]'::jsonb, 0, 'The coarse cell is the limit over 2000: 450000000.0000 over 2000 is 225000.000000 and 450.5000 over 2000 is 0.225250, and both still reach 250.0000 with a gap of 0.0000.'::text, 'gridOvershootFallback, run on the stated fallback grid, reports a resolution of 3.000000 at a limit of 6000.0000. What does a resolution measure?', '["The size of one capex cell in the money units entered, the limit divided into 2000 cells, reported only when the fallback grid runs.", "The precision of the risked EMV, so the answer is reliable only to within 3.000000 million USD of the true optimum.", "The number of cells the limit is divided into, which grows when the capexes are typed in larger units.", "The standard error of the simulated P(loss), which the engine shrinks as the limit grows."]'::jsonb, 0, '6000.0000 over 2000 is 3.000000 million USD per cell, and every capex is rounded up to whole cells, A to 1334, B to 668 and C to 665. On an exact solve the resolution is null, because there is no grid.'::text),
      ('beginner', 'final', null::text, 30, 'In gridOvershoot, A weighs 1333 cells and B 667, together exactly the 2000 cells of a limit of 6000.0000. Why does the pair fit on the grid but not in money?', '["The limit of 6000.0000 is a whole number, so the grid is exact at 1 million USD per cell and the overshoot is only a rounding of the printed totals.", "Both capexes round down on a cell of 3.000000, B''s 2002.0000 included, so the pair weighs less in cells than the 6002.0000 it costs.", "The engine adds a tolerance of one cell to every limit, so that a set landing on the boundary of the grid is not lost to rounding.", "A is charged the minimum of one cell as a large project, so the grid undercounts it by nearly its whole capex of 4000.0000."]'::jsonb, 1, 'A limit over 5000 sends the grid coarse at 6000.0000 over 2000; the engine flags overLimit true and overLimitBy 2.0000 but still returns 800.0000, against 780.0000 for A + C, which truly fits.'::text, 'On gridOvershootFallback the stated fallback grid runs at 3.000000 per cell against a limit of 6000.0000, with A at 4000.0000, B at 2002.0000 and C at 1995.0000. Why are A and B never funded together there?', '["The fallback funds at most two of any three projects, and keeps the pair with the lower total capex.", "Every capex rounds up to whole cells, B to 668, so A''s 1334 and B''s 668 overflow the 2000 cells, and the fallback funds A + C for 780.0000.", "The fallback refuses any project whose capex does not divide evenly by the resolution, and B''s 2002.0000 is refused.", "A is charged the minimum of one cell as a large project, so the grid undercounts it by nearly its whole capex of 4000.0000."]'::jsonb, 1, 'Rounding every weight up keeps any set that fits the grid inside the limit. The fallback funds A + C at 5995.0000, the exact optimum, with overLimit false and optimalityGap 20.0000.'::text),
      ('beginner', 'final', null::text, 31, 'gridOvershoot''s golden gap is 20.0000 and gridUndershoot''s is -200.0000. What does the sign of each gap say about the engine''s set?', '["Both mean the grid was coarse by that many cells, with the sign recording only whether the capexes were rounded up or rounded down.", "A positive gap is a genuine improvement the coarse grid found over exact arithmetic, and a negative one is the grid''s unavoidable rounding cost.", "The engine prints both gaps beside overLimit so that a user running any inventory can see how far the run sits from the exact optimum.", "A positive gap means the set beat the exact optimum by breaking the limit; a negative one means a better fitting set was squeezed out."]'::jsonb, 3, 'The gap is the engine''s EMV less the exact optimum: 800.0000 less 780.0000, and 660.0000 less 860.0000, the second exactly W''s 200.0000.'::text, 'gridOvershootFallback reports optimalityGap 20.0000 and gridUndershootFallback 200.0000. What does each gap say about the fallback''s set?', '["Both mean the grid was coarse by that many cells, the figure recording how many capexes were rounded up.", "Each is exactly the risked EMV the fallback lost, so the first case lost 20.0000 and the second lost 200.0000.", "Each is the amount by which the funded capex sits over the limit, reported beside overLimit for the reader to subtract.", "Each is an upper bound on what was left out: the first set is the exact optimum at 780.0000, while the second falls 200.0000 short."]'::jsonb, 3, 'optimalityGap is the optimum on the same grid with every weight rounded down, less the funded EMV. On gridOvershootFallback that bound admits A + B, yet A + C is the exact optimum; on gridUndershootFallback X + Y + Z at 660.0000 falls short of all four at 860.0000 by exactly the gap.'::text),
      ('beginner', 'final', null::text, 32, 'A capital committee cannot see why gridUndershoot''s four candidates, whose money totals sit inside its coarse limit, are never funded together. What stops the fourth?', '["The engine caps a funded set at three projects on a coarse grid, which keeps the knapsack inside its time budget.", "Z''s 1502.0000 is refused as over a per-project ceiling of 1500.0000, and the grid drops W with it as the least valuable.", "On a cell of 3.000000 every capex rounds up, and the four rounded weights need more than the 2000 cells the limit holds.", "The four together would overshoot in money, so the overshoot flag removes the cheapest project before the answer is reported."]'::jsonb, 2, 'W, X and Y weigh 500 cells each and Z 501, one cell more than 2000; the engine funds X + Y + Z for 660.0000 and overLimit reads false (finding D4).'::text, 'A capital committee cannot see why the four gridUndershoot candidates, whose capex totals 5999.0000 against a limit of 6000.0000, are never funded together on the stated fallback of gridUndershootFallback. What stops the fourth there?', '["The engine caps a funded set at three projects on a coarse grid, which keeps the knapsack inside its time budget.", "Z''s 1502.0000 is refused as over a per-project ceiling of 1500.0000, and the grid drops W with it as the least valuable.", "On a cell of 3.000000 every capex rounds up, and the four rounded weights need more than the 2000 cells the limit holds.", "The four together would overshoot in money, so the overshoot flag removes the cheapest project before the answer is reported."]'::jsonb, 2, 'W, X and Y weigh 500 cells each and Z 501, one cell more than 2000; the fallback funds X + Y + Z for 660.0000 and states optimalityGap 200.0000. Solved exactly, gridUndershoot funds all four for 860.0000.'::text),
      ('beginner', 'final', null::text, 33, 'Between the tight and the slack free-project cases the only change is one extra million of limit, yet funded EMV rises by 10.0000 while funded capex does not move. What did that million pay for?', '["The free project''s capex, which the engine rounds up from 0.0000 to 1 million USD whenever a limit allows it.", "Only the cell the grid charges the free project; the money itself is never spent.", "A change of grid, since a limit of 101.0000 is coarse and every project''s weight in cells is recalculated.", "Nothing real, since both runs share one optimum and the 10.0000 between them is a tie the engine breaks by entry order."]'::jsonb, 1, 'The free project weighs max(1, round(capex / cell)), one cell (finding D2); at 100.0000 A uses every cell and the golden optimum of 70.0000 is missed by 10.0000.'::text, 'Between freeProjectTightLimit and freeProjectSlack the only change is one extra million of limit, and both fund the free project and A. What does the extra million buy?', '["The free project''s capex, which the engine rounds up from 0.0000 to 1 million USD whenever a limit allows it.", "Nothing: both fund capex 100.0000 for 70.0000, and the extra 1.0000 is left unspent.", "A change of method, since a limit of 101.0000 sends the solve to the fallback grid.", "A tie the engine breaks by entry order, which the extra million settles in the free project''s favour."]'::jsonb, 1, 'A free project weighs nothing on the exact solve, so it is funded at a limit of 100.0000 already; freeProjectSlack funds the same set at capex 100.0000 against 101.0000, leaving 1.0000 unspent.'::text),
      ('beginner', 'final', null::text, 34, 'An inventory is typed entirely in USD instead of million USD. Why can a check of risked EMV per million of capex, project by project, never reveal the slip?', '["Both amounts sit in the same unit, so it cancels, and OK-1''s 0.747917 would come out of a USD inventory unchanged.", "The ratio prints to six decimals, which is too coarse to show a factor of a million between two inventories.", "The engine converts USD to million USD before computing risked EMV, so every ratio is taken on corrected numbers.", "The ratio divides by capex in grid cells, and a cell is the same size in either unit."]'::jsonb, 0, 'The engine holds no currency field, no unit field and no scale check; what a USD inventory does change is the grid, which turns coarse once the limit is over 5000.'::text, 'An inventory is typed entirely in USD where million USD was meant. Why can a project-by-project check of risked EMV per million of capex never reveal the slip?', '["Both amounts sit in the same unit, so it cancels, and OK-1''s 0.747917 would come out of a USD inventory unchanged.", "The ratio prints to six decimals, which is too coarse to show a factor of a million between two inventories.", "The engine converts USD to million USD before computing risked EMV, so every ratio is taken on corrected numbers.", "The ratio divides by capex in grid cells, and a cell is the same size in either unit."]'::jsonb, 0, 'The engine holds no currency field, no unit field and no scale check, and the exact solve returns the same set in any unit, as the rawDollars case shows; a mixed inventory is the slip no ratio can catch.'::text),
      ('beginner', 'final', null::text, 41, 'Risking every row by hand before solving, a candidate''s value for one project differs from the explorer''s risked EMV column. What causes does the method name?', '["Grid rounding, since the column shows EMV after capex is rounded to cells.", "The simulation, since the column reports the mean of the seeded Monte Carlo draws, which never lands exactly on the hand line.", "Correlation, which the explorer applies to each project''s EMV before printing.", "A mistyped input, or a clamp that fired: pos over 1 read as 1, pos under 0 as 0, a negative fail_cost as 0."]'::jsonb, 3, 'The engine keeps no record of the value typed before a clamp; OK-3''s hand line, 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500, matching the engine shows the row was read as typed.'::text, 'Risking every row by hand before solving, a candidate''s value for one project differs from the explorer''s risked EMV column. What causes does the method name?', '["Grid rounding, since the column shows EMV after capex is rounded to cells.", "The simulation, since the column reports the mean of the seeded Monte Carlo draws, which never lands exactly on the hand line.", "Correlation, which the explorer applies to each project''s EMV before printing.", "A mistyped input, or a default that fired: a pos left out read as 1, or a negative fail_cost read as 0."]'::jsonb, 3, 'A pos over 1, under 0, blank or non-numeric never reaches the column, because it is refused by project name. OK-3''s hand line, 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500, matching the engine shows the row was read as typed.'::text),
      ('beginner', 'final', null::text, 42, 'freeProjectZeroLimit and limitBelowEveryProject both return an empty set with an EMV of 0.0000. Which of them left value behind that the exact optimum would have taken?', '["freeProjectZeroLimit, where a project costing 0.0000 and worth 10.0000 needed one cell that a limit of 0.0000 does not hold; below every project nothing fits in money either.", "limitBelowEveryProject, since a limit of 30.0000 could have funded part of A, and the knapsack''s refusal to split a project into fractions is where the value was lost in that case.", "Both of them, since an empty set always means the grid has undershot and a better set of whole projects was squeezed out.", "Neither, since an empty set is the engine refusing a limit it cannot use, and no optimum exists for either input."]'::jsonb, 0, 'The golden optimum for freeProjectZeroLimit is 10.0000 on free, a gap of -10.0000 (finding D2), while the golden optimum for limitBelowEveryProject is the empty set.'::text, 'freeProjectZeroLimit and limitBelowEveryProject both run at a limit that no project with a cost can meet. Which of them returns a funded set, and why?', '["freeProjectZeroLimit, whose project costs 0.0000 and weighs nothing, so it is funded for 10.0000; below every project nothing fits.", "limitBelowEveryProject, since a limit of 30.0000 funds part of A, and a fraction of a project is how a tight limit is used.", "Both, since the engine relaxes a limit that no project can meet and funds the cheapest project it has.", "Neither, since an empty set is the engine refusing a limit it cannot use, and no optimum exists for either input."]'::jsonb, 0, 'The engine funds the free project at a limit of 0.0000, which is the golden optimum; limitBelowEveryProject at 30.0000 funds nothing, capex 0.0000 and EMV 0.0000, because A costs 50.0000 and B 80.0000.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 4, 'For the 450.0000 set the engine prints seed 20260829, iterations 10000, P(loss) 0.123600 and P90 -18.3574. Why does it show the seed?', '["Because the seed fixes the average correlation between projects, which is the one simulation input the risk summary has no other field to display.", "So anyone can rerun the same simulation and reproduce its loss probability and percentiles exactly.", "Because the loss probability is still read from a normal approximation, and the seed records which version of that approximation the run applied.", "Because the optimizer breaks ties with it, so another seed can fund another set."]'::jsonb, 1, 'The repaired engine simulates success, failure and the success NPV of each project in every one of 10000 iterations; before EC5-0 these figures came from a normal approximation with nothing to reproduce.'::text, 'For the 450.0000 set the engine prints seed 20260829, iterations 10000, P(loss) 0.123600 and P90 -18.3574. Why does it show the seed?', '["Because the seed fixes the average correlation between projects, which is the one simulation input the risk summary has no other field to display.", "So anyone can rerun the same simulation and reproduce its loss probability and percentiles exactly.", "Because the loss probability is read from a normal approximation, and the seed records which version of that approximation the run applied.", "Because the optimizer breaks ties with it, so another seed can fund another set."]'::jsonb, 1, 'The engine simulates success, failure and the success NPV of each project in every one of 10000 iterations from the seed, so the same seed and iterations reproduce P(loss) 0.123600 and P90 -18.3574 exactly.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 6, 'An analyst types OKONO''s limit of 450.0000 million USD and every capex as counts of USD, keeping the NPVs in million USD. What in the output shows that anything changed?', '["A PortfolioInputError, since a limit above 5000 is outside the range the engine accepts and nothing is chosen.", "A unit warning, since the engine compares the limit with the NPVs and flags an inventory typed at the wrong scale.", "Nothing, since risked EMV per million USD is a ratio whose unit cancels out of every optimizer step.", "The resolution the engine reports, because the limit is now far above 5000 and the grid switches to the limit / 2000 per cell."]'::jsonb, 3, 'The exact grid of 1 million USD per cell needs whole numbers and a limit of at most 5000; the engine holds no currency or unit field, so the reported resolution is the only trace.'::text, 'An analyst types OKONO''s limit of 450.0000 million USD and every capex as counts of USD, keeping the NPVs in million USD. What in the output shows that anything changed?', '["A PortfolioInputError, since a capex in the hundreds of millions is outside the range the engine accepts and nothing is chosen.", "A unit warning, since the engine compares the limit with the NPVs and flags an inventory typed at the wrong scale.", "The solveMethod, which reads \"grid-feasible\" once the capex is typed in USD, since figures that large leave the exact solve.", "Nothing: solved exactly on the capex as typed, it funds OK-1 + OK-3 + OK-4 again with solveMethod \"exact\", and the engine holds no unit field."]'::jsonb, 3, 'The published rawDollars case does the same with the classic inventory: limit 450000000.0000, A + B + D for 250.0000, solveMethod exact. The engine holds no currency or unit field, so a consistently scaled capex column is invisible and harmless.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 9, 'Before EC5-0 a capex of -150 was accepted without a word. Why does the repaired engine refuse it outright instead of clamping it?', '["A negative capex turns the risked EMV negative, and the engine refuses any project whose risked EMV is 0 or less rather than leaving it out.", "The knapsack grid cannot store a negative weight, so the refusal protects the array the optimizer builds and says nothing about what the input means.", "A clamp to 0 would charge the project a grid cell for nothing, and the engine refuses every input that would take capacity the project never asked for.", "A project that pays you to fund it breaks the idea of a limit."]'::jsonb, 3, 'Capex never enters the risked EMV line, and a project with EMV of 0 or less is excluded, not refused; the published message reads Project "B" has a negative capex (-150); capex must be 0 or more.'::text, 'Why does the engine refuse a capex of -150 outright, with no clamp to 0?', '["A negative capex turns the risked EMV negative, and the engine refuses any project whose risked EMV is 0 or less, the same way it refuses a negative capex.", "The knapsack grid cannot store a negative weight, so the refusal protects the array the optimizer builds and says nothing about what the input means.", "A clamp to 0 would charge the project a grid cell for nothing, and the engine refuses every input that would take capacity the project never asked for.", "A project that pays you to fund it breaks the idea of a limit."]'::jsonb, 3, 'Capex never enters the risked EMV line, and a project with EMV of 0 or less is simply left out. The published message reads Project "B" has a negative capex (-150); capex must be 0 or more.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 10, 'A one in four exploration well has its chance of success typed as a percentage and its fail cost typed with a minus sign to show it is a loss. The run returns no error. How is the well valued?', '["As a certain success worth its whole npv_p50, since pos clamps to 1 and a negative fail cost is read as 0.", "As a certain failure, because a pos above 1 is out of range and the engine sets any out of range chance to 0 before it weights the two branches.", "At its intended risked EMV, because the engine divides a pos above 1 by 100 and the typed minus sign cancels the minus sign in the formula.", "It is never valued, since a pos outside 0 to 1 is refused with the same error as a negative capex."]'::jsonb, 0, 'The published posAboveOneClamps case returns 80.0000 for pos 1.4 on an npv_p50 of 80, and negativeFailCostIsZero returns 40.0000 for a fail cost of -30 at pos 0.5; neither sends an error or a note.'::text, 'A one in four exploration well has its chance of success typed correctly and its fail cost typed with a minus sign to show it is a loss. The run returns no error. How is the failure branch valued?', '["At nothing: a negative fail cost is read as 0, so a well like OK-3 would carry 105.0000, its success branch alone.", "At twice the fail cost, since the minus sign typed in the field and the minus sign in the formula compound.", "At its intended cost, because the engine takes the absolute value of a negative fail cost before it weights the branch.", "It is never valued, since a negative fail cost is refused with the same error as a negative capex."]'::jsonb, 0, 'negativeFailCostIsZero returns 40.0000 for a fail cost of -30 at pos 0.5 on an npv_p50 of 80, the success branch alone. A pos typed as a percentage is caught: Project "Appraisal" has a pos outside 0 to 1 (30); pos must be a number from 0 to 1.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 11, 'Four inventories are run through the optimizer. Which one does the engine refuse outright?', '["One with a limit of 30.0000 that sits under every project, since no set can be built and the knapsack has nothing it can return.", "One holding a project whose npv_p10 is entered below its npv_p90, since a success spread cannot be built from an inverted range.", "One holding a project with a capex of -0.5.", "One holding a project with pos 1.4, since a chance of success above 1 lies outside the range the engine documents for pos."]'::jsonb, 2, 'The negative capex is the one refusal; limitBelowEveryProject at 30.0000 funds nothing with capex 0.0000, and a pos of 1.4 is clamped to 1 and returns 80.0000.'::text, 'Four inventories are run through the optimizer. Which one does the engine refuse outright?', '["One with a limit of 30.0000 that sits under every project, since no set can be built and the knapsack has nothing it can return.", "One holding a project whose npv_p10 is entered below its npv_p90, since a success spread cannot be built from an inverted range.", "One holding a project with a capex of -0.5.", "One holding a project with fail_cost -30, since a loss typed below zero is outside the range the engine documents for fail_cost."]'::jsonb, 2, 'The negative capex is refused: Project "1" has a negative capex (-0.5); capex must be 0 or more. limitBelowEveryProject at 30.0000 funds nothing, inverted percentiles give a spread of 0.0000, and a fail_cost of -30 is read as 0.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 12, 'The published gridOvershoot case funds a set whose capex lands over its limit on the coarse grid. What does the repaired engine do with it?', '["Refuses the run with a PortfolioInputError, since a funded capex above the limit breaks the one constraint the knapsack is built to hold.", "Returns the set and flags it, reporting overLimit true and overLimitBy 2.0000.", "Drops the last project it added and returns the smaller set, so that the funded capex always comes back inside the limit it was given.", "Reruns the whole inventory on the exact 1 million USD grid, which removes the overshoot and returns a set that spends no more than the limit."]'::jsonb, 1, 'A set over the limit is not refused, only flagged, and the overshoot here is 2.0000 million USD; the only refusal in the engine is a negative capex.'::text, 'The published gridOvershoot case has projects costing 4000.0000, 2002.0000 and 1995.0000 against a limit of 6000.0000. What does the engine return?', '["A PortfolioInputError, since two projects whose capex together pass the limit cannot be entered in one inventory.", "A + C at capex 5995.0000 for 780.0000, solved exactly, with overLimit false and overLimitBy 0.0000.", "A + B at capex 6002.0000 for 800.0000, flagged with overLimit true and overLimitBy 2.0000 for the reader to correct.", "B + C at capex 3997.0000 for 580.0000, since the engine drops the largest project whenever a pair would breach the limit."]'::jsonb, 1, 'The exact solve never exceeds the limit: A + B would cost 6002.0000, so the best set that fits is A + C at 500.0000 plus 280.0000. overLimit and overLimitBy stay in every result and read false and 0.0000 on an exact solve.'::text),
      ('beginner', 'module', 'm01-capital-is-a-constraint'::text, 14, 'Sorting OKONO by risked EMV per million USD and funding down the list at 450.0000 gives OK-1 + OK-4 + OK-5 for 287.7500. Why does the engine reach 291.0000?', '["It ranks by plain risked EMV instead of the ratio, which puts the exploration well ahead of the workovers.", "It risks each project again in the simulation, which marks down the workovers'' certain success.", "It compares combinations of whole projects, while a list judges projects one at a time and stops when the next one does not fit.", "It uses a coarser grid than the hand list, and rounding lets the well''s capex fit beside OK-1 and OK-4."]'::jsonb, 2, 'OKONO''s limits are whole and under 5000, so the grid is exact at a resolution of 1.0000; the gain of 3.2500 comes from choosing the set, not from rounding or risk.'::text, 'Sorting OKONO by risked EMV per million USD and funding down the list at 450.0000 gives OK-1 + OK-4 + OK-5 for 287.7500. Why does the engine reach 291.0000?', '["It ranks by plain risked EMV and ignores the ratio, which puts the exploration well ahead of the workovers.", "It risks each project again in the simulation, which marks down the workovers'' certain success.", "It compares combinations of whole projects, while a list judges projects one at a time and stops when the next one does not fit.", "It uses a coarser grid than the hand list, and rounding lets the well''s capex fit beside OK-1 and OK-4."]'::jsonb, 2, 'OKONO is solved exactly, solveMethod "exact" with optimalityGap 0.0000; the gain of 3.2500 comes from choosing the set, with no rounding or risk involved.'::text),
      ('beginner', 'module', 'm02-risking-a-project'::text, 2, 'An exploration well is entered with an npv_p50 and a fail_cost, but the pos field is left out of the row entirely. How does the engine value it?', '["It refuses the row, since a project with no chance of success cannot be risked and the engine names the offending project in its error.", "At the middle of the range, since a missing chance of success is read as a coin toss until a value between 0 and 1 is entered.", "At its npv_p50 weighted by the average pos of the other projects, which is how the engine fills a chance nobody entered.", "As a certain success worth its npv_p50, since an absent pos defaults to 1."]'::jsonb, 3, 'The published unrisked case enters no pos and no fail_cost and returns 250.0000, its whole npv_p50 of 250, so a blank well is counted as if it cannot fail.'::text, 'An exploration well is entered with an npv_p50 and a fail_cost, but the pos field is left out of the row entirely. How does the engine value it?', '["It refuses the row, since a project with no chance of success cannot be risked and the engine names the offending project in its error.", "At the middle of the range, since a missing chance of success is read as a coin toss until a value between 0 and 1 is entered.", "At its npv_p50 weighted by the average pos of the other projects, which is how the engine fills a chance nobody entered.", "As a certain success worth its npv_p50, since an absent pos defaults to 1."]'::jsonb, 3, 'The published unrisked case enters no pos and no fail_cost and returns 250.0000, its whole npv_p50 of 250, so a well entered with no pos is counted as if it cannot fail. A pos typed as a blank is refused by name.'::text),
      ('beginner', 'module', 'm02-risking-a-project'::text, 4, 'The published missingNpvIsZero case enters no npv_p50, a fail_cost of 8 and a pos of 0.25, and the engine returns -6.0000. What produced that number?', '["The fail cost weighted by pos, since a row with no success case is charged its loss at its chance of success instead of its chance of failure.", "A default of 1 for the missing npv_p50, applied the way a missing pos defaults to 1.", "The failure branch alone: a missing npv_p50 is 0, so 0.25 x 0 - (1 - 0.25) x 8 leaves only the loss.", "The capex of 10 weighted by the chance of failure, standing in for the loss."]'::jsonb, 2, 'Every unit of -6.0000 is the failure branch: (1 - 0.25) x 8. The engine never links fail_cost to capex and never refuses a row with no NPV.'::text, 'The published missingNpvIsZero case enters no npv_p50, a fail_cost of 8 and a pos of 0.25, and the engine returns -6.0000. What produced that number?', '["The fail cost weighted by pos, since a row with no success case is charged its loss at its chance of success where its chance of failure belongs.", "A default of 1 for the missing npv_p50, applied the way a missing pos defaults to 1.", "The failure branch alone: a missing npv_p50 is 0, so 0.25 x 0 - (1 - 0.25) x 8 leaves only the loss.", "The capex of 10 weighted by the chance of failure, standing in for the loss."]'::jsonb, 2, 'Every unit of -6.0000 is the failure branch: (1 - 0.25) x 8. The engine never links fail_cost to capex and never refuses a row with no NPV.'::text),
      ('beginner', 'module', 'm02-risking-a-project'::text, 7, 'The risk summary for OKONO''s 600.0000 set reads emv 402.7500 at a correlation of 0.000000. What does emv read at a correlation of 1.000000?', '["Less than 402.7500, since projects that fail together drag the expected value down as well as widening the range of outcomes.", "More than 402.7500, since projects that succeed together compound their success cases in the same draws of the simulation.", "A value that depends on the seed, since emv is read from the simulated draws.", "402.7500 again, since emv is the sum of the four risked EMVs and correlation changes only the spread."]'::jsonb, 3, '89.7500 + 115.0000 + 160.0000 + 38.0000 = 402.7500; emv comes in closed form, and correlation moves how far outcomes spread around that mean, never the mean.'::text, 'The risk summary for OKONO''s 600.0000 set reads emv 402.7500 at a correlation of 0.000000. What does emv read at a correlation of 1.000000?', '["Less than 402.7500, since projects that fail together drag the expected value down as well as widening the range of outcomes.", "More than 402.7500, since projects that succeed together compound their success cases in the same draws of the simulation.", "A value that depends on the seed, since emv is read from the simulated draws.", "402.7500 again, since emv is the sum of the four risked EMVs and correlation changes only the spread."]'::jsonb, 3, '89.7500 + 115.0000 + 160.0000 + 38.0000 = 402.7500; emv comes in closed form, and correlation moves how far outcomes spread around that mean while the mean stays put.'::text),
      ('beginner', 'module', 'm02-risking-a-project'::text, 13, 'A risky project''s pos is mistyped as 1.4 and clamps to 1. Beyond its risked EMV, what else does the clamp change?', '["Nothing else, because the risk summary reads pos as typed and only the risked EMV line applies the clamp.", "The seeded risk summary draws it as a success in every iteration, so its funded set looks safer as well as more valuable.", "The seed, because the engine reseeds the simulation whenever a clamp fires, recording the correction.", "The grid, because a clamped row is charged an extra cell so the optimizer can mark it as corrected."]'::jsonb, 1, 'posAboveOneClamps returns 80.0000, a certain success, and at seed 20260829 over 10000 iterations such a project never contributes a failure to P(loss) or to the P90 low case.'::text, 'An appraisal well''s row is saved with no pos field at all, and the optimizer values it at the default of 1. Where else does that default reach?', '["Nothing else, because the risk summary draws its own success rate from the entered percentiles and only the risked EMV line uses the default.", "The seeded risk summary draws it as a success in every iteration, so its funded set looks safer as well as more valuable.", "The seed, because the engine reseeds the simulation whenever a default fires, recording the correction.", "The optimizer''s method, because a defaulted row sends the solve to the fallback grid so it can be marked."]'::jsonb, 1, 'nullPosIsDefault returns 80.0000, a certain success, and at seed 20260829 over 10000 iterations such a project never contributes a failure to P(loss) or to the P90 low case. A pos typed as 1.4 is refused before anything runs.'::text),
      ('beginner', 'module', 'm02-risking-a-project'::text, 15, 'The published posBelowZeroClamps case enters pos -0.2 on npv_p50 80 and fail_cost 30, and returns -30.0000. What value of pos did the engine use?', '["-0.2 as typed, which makes the success branch negative and weights the failure branch by more than one.", "The default of 1, since a pos out of range is handled like a non-numeric one and replaced by the default.", "0.2, since the engine takes the absolute value of a negative chance before it weights the two branches.", "0, a certain failure worth minus its fail cost."]'::jsonb, 3, 'pos is held between 0 and 1, so -0.2 becomes 0 and the result is -(1 - 0) x 30 = -30.0000, the same as the posZero case; no warning says a clamp fired.'::text, 'The published posZero case enters pos 0 on npv_p50 80 and fail_cost 30, and returns -30.0000. What does that value describe?', '["A pos typed below the range and read as 0, since the engine holds every chance of success between 0 and 1.", "The default of 1 applied to a pos it could not read, with the success branch then charged at the fail cost.", "The absolute value of the fail cost taken as a gain, since a chance of 0 reverses the sign of the failure branch.", "A certain failure worth -30.0000, minus its fail cost, since a pos of 0 is inside the range the engine accepts."]'::jsonb, 3, '-(1 - 0) x 30 = -30.0000. A pos below 0 is refused: posBelowZeroRefused gives Project "a" has a pos outside 0 to 1 (-0.2); pos must be a number from 0 to 1.'::text),
      ('beginner', 'module', 'm03-choosing-under-a-budget'::text, 1, 'At a limit of 750.0000 million USD the engine funds OK-1 + OK-2 + OK-3 + OK-4 + OK-5 for capex 690.0000. Why is the rest of the limit left unspent?', '["The optimizer holds back a reserve against the loss probability, sized from the simulated spread of the set it has just funded.", "OK-6''s risked EMV per million USD is the lowest left, and the optimizer stops at the first project whose ratio falls under its cut-off.", "The grid is coarse at that limit and rounds each capex up, so the five projects fill every cell although their capex sums to 690.0000.", "The only project left, OK-6, costs 310.0000, and the optimizer cannot fund part of a project."]'::jsonb, 3, '750.0000 - 690.0000 = 60.0000 is left, and OK-6 needs 310.0000; the limit is whole and under 5000, so the grid is exact and nothing was rounded.'::text, 'At a limit of 750.0000 million USD the engine funds OK-1 + OK-2 + OK-3 + OK-4 + OK-5 for capex 690.0000. Why is the rest of the limit left unspent?', '["The optimizer holds back a reserve against the loss probability, sized from the simulated spread of the set it has just funded.", "OK-6''s risked EMV per million USD is the lowest left, and the optimizer stops at the first project whose ratio falls under its cut-off.", "The grid is coarse at that limit and rounds each capex up, so the five projects fill every cell although their capex sums to 690.0000.", "The only project left, OK-6, costs 310.0000, and the optimizer cannot fund part of a project."]'::jsonb, 3, '750.0000 - 690.0000 = 60.0000 is left, and OK-6 needs 310.0000; the knapsack is solved exactly, so nothing was rounded.'::text),
      ('beginner', 'module', 'm03-choosing-under-a-budget'::text, 4, 'The greedy set at 450.0000 is OK-1 + OK-4 + OK-5 for 287.7500, and the optimizer funds OK-1 + OK-3 + OK-4 for 291.0000. How does the project with the lowest ratio get into the best set?', '["It uses the 30.0000 the list left idle: 41.2500 on 90.0000 beats 38.0000 on 60.0000 once the whole limit counts.", "The optimizer ranks by plain risked EMV, where OK-3''s 41.2500 beats OK-5''s 38.0000.", "The optimizer credits the well with part of its success case of 420.0000, which the ratio leaves out.", "The optimizer lets the limit stretch by one grid cell, giving OK-3 room the ranked list lacked."]'::jsonb, 0, 'Swapping the workovers for the well spends the last 30.0000 and gains 3.2500; the grid is exact at 450.0000, so no stretch or rounding is involved.'::text, 'The greedy set at 450.0000 is OK-1 + OK-4 + OK-5 for 287.7500, and the optimizer funds OK-1 + OK-3 + OK-4 for 291.0000. How does the project with the lowest ratio get into the best set?', '["It uses the 30.0000 the list left idle: 41.2500 on 90.0000 beats 38.0000 on 60.0000 once the whole limit counts.", "The optimizer ranks by plain risked EMV, where OK-3''s 41.2500 beats OK-5''s 38.0000.", "The optimizer credits the well with part of its success case of 420.0000, which the ratio leaves out.", "The optimizer lets the limit stretch by one grid cell, giving OK-3 room the ranked list lacked."]'::jsonb, 0, 'Swapping the workovers for the well spends the last 30.0000 and gains 3.2500; the solve is exact at 450.0000, so no stretch or rounding is involved.'::text),
      ('beginner', 'module', 'm03-choosing-under-a-budget'::text, 7, 'The published negativeEmvHugeBudget case has a limit of 10000.0000 and funds good + better for capex 120.0000 and risked EMV 75.0000. A third project, neg, would easily fit. Why is it left out?', '["The limit is above 5000, so the coarse grid charges neg more cells than its capex of 20.0000 and it can no longer fit beside the others.", "Its risked EMV is -44.0000, and funding it would lower the summed risked EMV by exactly that amount.", "It is refused as an input error, since a negative risked EMV breaks the knapsack.", "The optimizer only considers the projects the two largest risked EMVs need."]'::jsonb, 1, 'A risked EMV of 0 or less is never funded however much money is left, so 10000.0000 - 120.0000 stays unspent and the engine reports no error.'::text, 'The published negativeEmvHugeBudget case has a limit of 10000.0000 and funds good + better for capex 120.0000 and risked EMV 75.0000. A third project, neg, would easily fit. Why is it left out?', '["The limit is above 5000, so a coarse grid charges neg more cells than its capex of 20.0000 and it cannot fit beside the others.", "Its risked EMV is -44.0000, and funding it would lower the summed risked EMV by exactly that amount.", "It is refused as an input error, since a negative risked EMV breaks the knapsack.", "The optimizer only considers the projects the two largest risked EMVs need."]'::jsonb, 1, 'A risked EMV of 0 or less is never funded however much money is left, so 10000.0000 - 120.0000 stays unspent and the engine reports no error.'::text),
      ('beginner', 'module', 'm03-choosing-under-a-budget'::text, 8, 'In the published zeroEmvExcluded case a project with capex 30.0000 and risked EMV 0.0000 sits beside good at a limit of 500.0000. Why does the engine leave it out?', '["It adds nothing to the objective and still uses capex, so a risked EMV of 0 or less is never funded.", "Its capex of 30.0000 cannot fit beside good, since a limit of 500.0000 is checked on a grid of the limit / 2000 per cell.", "The engine rejects a zero risked EMV row as unfinished and returns an error naming it.", "It would be funded under a tight limit, since a zero project is dropped only when money is left over and idle capex costs nothing."]'::jsonb, 0, 'The engine funds good alone for capex 50.0000 and risked EMV 30.0000 with 450.0000 of the limit spare; 500.0000 is whole and under 5000, so the grid is exact.'::text, 'In the published zeroEmvExcluded case a project with capex 30.0000 and risked EMV 0.0000 sits beside good at a limit of 500.0000. Why does the engine leave it out?', '["It adds nothing to the objective and still uses capex, so a risked EMV of 0 or less is never funded.", "Its capex of 30.0000 cannot fit beside good, since a limit of 500.0000 is checked on a grid of the limit / 2000 per cell.", "The engine rejects a zero risked EMV row as unfinished and returns an error naming it.", "It would be funded under a tight limit, since a zero project is dropped only when money is left over and idle capex costs nothing."]'::jsonb, 0, 'The engine funds good alone for capex 50.0000 and risked EMV 30.0000 with 450.0000 of the limit spare, solved exactly.'::text),
      ('beginner', 'module', 'm03-choosing-under-a-budget'::text, 14, 'At 450.0000 the optimizer''s set beats the greedy set by 3.2500. If a revision to one project''s inputs closed that gap to an exact tie, what would decide which set came back?', '["The loss probability, since a tie hands the choice to the risk summary and it favours the workovers'' certain success over the well.", "The larger total success NPV, used by the optimizer as a second key, favouring the well.", "The order the projects were entered in, since the first set built is kept against an equal one found later.", "The capex spent, since at equal value the knapsack prefers the set that leaves less unspent."]'::jsonb, 2, 'The optimizer compares risked EMV alone and keeps a set unless another is strictly larger, so a tie between the set at 450.0000 and the set at capex 420.0000 is settled by entry order.'::text, 'At 450.0000 the optimizer''s set beats the greedy set by 3.2500. If a revision to one project''s inputs closed that gap to an exact tie, what would decide which set came back?', '["The loss probability, since a tie hands the choice to the risk summary and it favours the workovers'' certain success over the well.", "The larger total success NPV, used by the optimizer as a second key, favouring the well.", "The capex spent: the optimizer keeps the tied set with less capex, OK-1 + OK-4 + OK-5 at 420.0000, whatever the entry order.", "The order the projects were entered in, since the first set built is kept against an equal one found later."]'::jsonb, 2, 'Among sets tied on risked EMV the exact solve keeps the one with less capex, and entry order decides only between sets of equal capex and equal EMV. The two sets here cost 450.0000 and 420.0000.'::text),
      ('beginner', 'module', 'm04-the-efficient-frontier'::text, 3, 'The OKONO frontier shows a step of 3.2500 three times, at points 2, 5 and 11. What is that step?', '["OK-3 added on top of the set before at a diluted ratio, since its 41.2500 is spread across the capex of the projects already funded.", "Rounding residue the grid leaves between whole cells, repeated wherever a capex does not divide evenly into the cell size.", "Three different small projects that each happen to be worth 3.2500 of risked EMV once their fail costs are charged.", "The same swap each time: OK-5 out and OK-3 in, a net 3.2500 for a net 30.0000 of capex."]'::jsonb, 3, 'OK-3 adds 41.2500 for 90.0000 and OK-5 takes away 38.0000 for 60.0000. On an exact grid of 1.0000 per cell there is no rounding to leave a residue.'::text, 'The OKONO frontier shows a step of 3.2500 three times, at points 2, 5 and 11. What is that step?', '["OK-3 added on top of the set before at a diluted ratio, since its 41.2500 is spread across the capex of the projects already funded.", "Rounding residue the grid leaves between whole cells, repeated wherever a capex does not divide evenly into the cell size.", "Three different small projects that each happen to be worth 3.2500 of risked EMV once their fail costs are charged.", "The same swap each time: OK-5 out and OK-3 in, a net 3.2500 for a net 30.0000 of capex."]'::jsonb, 3, 'OK-3 adds 41.2500 for 90.0000 and OK-5 takes away 38.0000 for 60.0000. The solve is exact, so there is no rounding to leave a residue.'::text),
      ('beginner', 'module', 'm04-the-efficient-frontier'::text, 7, 'The optimizer runs OKONO at a limit of 750.0000 million USD. Where does the frontier''s last point sit, and why?', '["At 690.0000 and 444.0000, with 60.0000 unspent, because no remaining project fits and OK-6 alone costs 310.0000.", "At 750.0000 and 444.0000, because the last point is always printed at the limit whatever its set costs.", "At 1000.0000 and 588.0000, the value of all six projects, since a limit is rounded up to the next whole set.", "At 690.0000 with a grid undershoot, the coarse rounding that leaves a set out, which a finer cell would recover."]'::jsonb, 0, 'A point is printed at what its set costs. OKONO solves on an exact grid of 1.0000 per cell, so the 60.0000 is genuine: OK-6 is the only project left and needs 310.0000.'::text, 'The optimizer runs OKONO at a limit of 750.0000 million USD. Where does the frontier''s last point sit, and why?', '["At 690.0000 and 444.0000, with 60.0000 unspent, because no remaining project fits and OK-6 alone costs 310.0000.", "At 750.0000 and 444.0000, because the last point is always printed at the limit whatever its set costs.", "At 1000.0000 and 588.0000, the value of all six projects, since a limit is rounded up to the next whole set.", "At 690.0000 with a grid undershoot, the coarse rounding that leaves a set out, which a finer cell would recover."]'::jsonb, 0, 'A point is printed at what its set costs. OKONO is solved exactly, so the 60.0000 is genuine: OK-6 is the only project left and needs 310.0000.'::text),
      ('beginner', 'module', 'm04-the-efficient-frontier'::text, 8, 'The OKONO frontier ends at 450.0000 and 291.0000. What does it say about the chance that the funded set loses money?', '["That it is small, because a set on the efficient frontier is by definition the one with the least risk at its budget.", "That it is the lowest of any set at 450.0000, since the optimizer breaks ties between equal values toward the set with less spread.", "Nothing: it ranks on risked EMV alone, and the seeded Monte Carlo reports P(loss) 0.123600 for that set separately.", "That it matches the 600.0000 set''s, since both sit on one frontier and share every point up to 450.0000."]'::jsonb, 2, 'The last point is the best value, not the safest. At seed 20260829 and 10000 iterations the 450.0000 set shows P(loss) 0.123600 and the 600.0000 set 0.001800, and the frontier shows neither.'::text, 'The OKONO frontier ends at 450.0000 and 291.0000. What does it say about the chance that the funded set loses money?', '["That it is small, because a set on the efficient frontier is by definition the one with the least risk at its budget.", "That it is the lowest of any set at 450.0000, since the optimizer breaks ties between equal values toward the set with less spread.", "Nothing: it ranks on risked EMV alone, and the seeded Monte Carlo reports P(loss) 0.123600 for that set separately.", "That it matches the 600.0000 set''s, since both sit on one frontier and share every point up to 450.0000."]'::jsonb, 2, 'The last point is the best value, and it need not be the safest. At seed 20260829 and 10000 iterations the 450.0000 set shows P(loss) 0.123600 and the 600.0000 set 0.001800, and the frontier shows neither.'::text),
      ('beginner', 'module', 'm04-the-efficient-frontier'::text, 13, 'A programme funded at 450.0000 million USD is raised to 600.0000, and the planner keeps OK-1, OK-3 and OK-4 and adds whatever still fits. Where does building up stop?', '["At 329.0000 on 510.0000, after adding OK-5, since OK-2''s 180.0000 no longer fits; solving again reaches 402.7500.", "At 402.7500, since adding what fits to a solved set reproduces the solved set at the larger budget.", "At 402.7500 on 600.0000, after adding OK-2 and OK-5, the two projects the larger budget was always going to fund.", "At 313.0000 on 480.0000, the next frontier point, which is where a set built up from the smaller answer lands."]'::jsonb, 0, '291.0000 plus 38.0000 is 329.0000. The solved set at 600.0000 is OK-1, OK-2, OK-4 and OK-5, reached by giving up OK-3, so a funded set is a starting point for nothing.'::text, 'A programme funded at 450.0000 million USD is raised to 600.0000, and the planner keeps OK-1, OK-3 and OK-4 and adds whatever still fits. Where does building up stop?', '["At 329.0000 on 510.0000, after adding OK-5, since OK-2''s 180.0000 then does not fit; solving again reaches 402.7500.", "At 402.7500, since adding what fits to a solved set reproduces the solved set at the larger budget.", "At 402.7500 on 600.0000, after adding OK-2 and OK-5, the two projects the larger budget was always going to fund.", "At 313.0000 on 480.0000, the next frontier point, which is where a set built up from the smaller answer lands."]'::jsonb, 0, '291.0000 plus 38.0000 is 329.0000. The solved set at 600.0000 is OK-1, OK-2, OK-4 and OK-5, reached by giving up OK-3, so a funded set is a starting point for nothing.'::text),
      ('beginner', 'module', 'm04-the-efficient-frontier'::text, 14, 'The OKONO set funded at 600.0000 million USD sums to 473.0000 of success-case NPV, against 725.0000 for the set at 450.0000. Is the larger budget buying less value?', '["Yes, since success-case NPV is what the projects return when they work and the larger programme returns less of it.", "Yes, because the optimizer at 600.0000 fell back to a coarser grid and lost the exploration well to rounding.", "No, because success-case NPV is reported only for the smaller set and the 473.0000 is a partial total of the larger one.", "No: risked EMV rises from 291.0000 to 402.7500, and success-case NPV falls because OK-3''s 420.0000 success case leaves the set."]'::jsonb, 3, 'The optimizer maximises risked EMV, not success-case NPV. OK-3 is worth 420.0000 if it works and 41.2500 risked, so dropping it costs little value.'::text, 'The OKONO set funded at 600.0000 million USD sums to 473.0000 of success-case NPV, against 725.0000 for the set at 450.0000. Is the larger budget buying less value?', '["Yes, since success-case NPV is what the projects return when they work and the larger programme returns less of it.", "Yes, because the optimizer at 600.0000 fell back to a coarser grid and lost the exploration well to rounding.", "No, because success-case NPV is reported only for the smaller set and the 473.0000 is a partial total of the larger one.", "No: risked EMV rises from 291.0000 to 402.7500, and success-case NPV falls because OK-3''s 420.0000 success case leaves the set."]'::jsonb, 3, 'The optimizer maximises risked EMV; success-case NPV plays no part. OK-3 is worth 420.0000 if it works and 41.2500 risked, so dropping it costs little value.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 1, 'Every OKONO limit from 300.0000 to 1000.0000 million USD reports a resolution of 1.0000. Why is the 450.0000 answer free of rounding?', '["The money is entered in million USD, and any limit in million USD is solved on a grid of one million per cell.", "Every capex and the limit are whole numbers and the limit is at most 5000, so each project weighs exactly its capex in cells.", "overLimit reads false at every limit, and a false flag is the engine''s certificate that no rounding changed the set.", "The limit is under 2000, so the grid has more cells than million USD and rounds every capex finer than it is entered."]'::jsonb, 1, 'The exact grid needs whole numbers and a limit of at most 5000; OKONO''s capexes run from 60.0000 to 310.0000, all whole. The nonIntegerLimit case is in million USD too and still turns coarse at 0.225250.'::text, 'Every OKONO limit from 300.0000 to 1000.0000 million USD reports solveMethod "exact" and optimalityGap 0.0000. What does that say about the 450.0000 answer?', '["Only that no project was refused; the set itself was rounded to whole million USD cells before it was chosen.", "That OK-1 + OK-3 + OK-4 at 291.0000 is the true optimum on the capex as typed, with nothing left out.", "That overLimit was checked and cleared, which is all an exact solve adds beyond the funded set.", "That the limit fell under the fallback''s 2000 cells, so the grid had more cells than million USD."]'::jsonb, 1, 'An exact solve reads the capex as typed, reports resolution null and optimalityGap 0.0000, and returns the optimum; OKONO at 450.0000 funds OK-1 + OK-3 + OK-4.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 2, 'The published nonIntegerLimit case enters its money in million USD with a limit of 450.5000. What grid does it solve on?', '["The exact grid at 1.0000 per cell, since every capex is whole and the limit is far under 5000.", "A coarse one at 225000.000000 per cell, since any limit that is not whole is converted to raw dollars before the cells are laid.", "The exact grid with one extra cell for the 0.5000 of headroom, which is how a fractional limit is honoured.", "A coarse one at 0.225250 per cell, because the limit is not a whole number."]'::jsonb, 3, 'The cell is 450.5000 over 2000, which is 0.225250 million USD. Typing a little headroom moves the whole solve off the exact grid without any change to the projects.'::text, 'The published nonIntegerLimit case enters its money in million USD with a limit of 450.5000. How is it solved, and what is left unspent?', '["On the fallback grid at 450.5000 over 2000 per cell, since a limit that is not whole cannot be solved exactly.", "Exactly, after the engine rounds the limit down to 450.0000, so nothing is left unspent.", "It is refused, since a limit must be a whole number of million USD like every capex.", "Exactly on the figures as typed, funding A + B + D for 250.0000 and leaving 0.5000 unspent."]'::jsonb, 3, 'nonIntegerLimit reports solveMethod exact, optimalityGap 0.0000 and resolution null; A + B + D costs 450.0000, so 0.5000 of the limit is idle because no project costs that little.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 3, 'The published rawDollars case reports a resolution of 225000.000000. What is that number?', '["A capex cell in the money units entered, 450000000.0000 USD over 2000, because the limit is far over 5000.", "The precision of the answer''s value, meaning the risked EMV is reliable only to within 225000.000000 of the true optimum.", "A cell in million USD, since the engine always solves portfolio money in million USD whatever units were typed.", "The number of cells in the grid, which is why a raw-dollar inventory takes far longer to solve than one in million USD."]'::jsonb, 0, 'Resolution is capex per cell and not precision in value: 225000.000000 USD here and 0.225250 million USD in nonIntegerLimit. The grid holds 2000 cells whenever it turns coarse.'::text, 'The published rawDollars case types every capex and the limit in whole USD, with a limit of 450000000.0000. What does the engine report?', '["A + B + D for 250.0000, solveMethod \"exact\" and resolution null, the same set the million USD inventory funds.", "The same set on a fallback grid of 225000 USD per cell, since a limit that large is always divided into 2000 cells.", "A PortfolioInputError, since a capex of 100000000.0000 is beyond the largest figure the knapsack reads.", "An empty set, since every capex is a million times the NPVs and no project''s value can pay for its cost."]'::jsonb, 0, 'The engine reads the capex as typed at any scale; rawDollars funds A + B + D, capex 450000000.0000, with optimalityGap 0.0000. The unit is the typist''s convention, and consistent scaling changes nothing.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 4, 'rawDollars and nonIntegerLimit both solve on a coarse grid and both land on A, B and D at 250.0000 with a golden gap of 0.0000. What should a reader take from that?', '["That a coarse grid is safe for these projects, since two matching answers show the rounding cancels out on this inventory.", "That the grid does not matter once the golden gap is 0.0000, so the resolution can be ignored on a user''s own inventory.", "A coarse grid can give the exact answer and is still unproven, so the funded capex must be checked against the limit in money.", "That both inventories are really the same exact problem, since the engine converts raw dollars to million USD before solving."]'::jsonb, 2, 'Once capexes are rounded to cells the knapsack solves a nearby problem. A user running their own inventory has no golden, so a gap of 0.0000 is never available to them.'::text, 'rawDollars and nonIntegerLimit both land on A, B and D at 250.0000, equal to the golden exact optimum. What should a reader take from the match?', '["That the fallback grid happens to be safe for these projects, since its rounding cancels on this inventory.", "That a golden is needed to trust any run, since the engine cannot tell whether its own answer is optimal.", "That no golden is needed: \"exact\" with optimalityGap 0.0000 already says the set is optimal.", "That both inventories are converted to million USD before solving, which is why their answers agree."]'::jsonb, 2, 'Both cases report solveMethod exact, optimalityGap 0.0000 and resolution null. A user running their own inventory reads the same two fields and needs no golden; only a grid-feasible answer carries a bound to weigh.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 5, 'In the published gridOvershoot case, A costs 4000.0000 and B 2002.0000 against a limit of 6000.0000 million USD at 3.000000 per cell. How do A and B fit on the grid?', '["B''s 2002.0000 does not divide evenly and rounds down to 667 cells, so A''s 1333 and B''s 667 fit inside the 2000.", "The limit is whole, so the grid is exact and A and B are simply charged their capex in one million USD cells.", "The engine tolerates a breach smaller than one cell, and 2.0000 is under the 3.000000 a cell holds.", "C''s 1995.0000 rounds up to fill the spare cells, which pushes the knapsack toward B as the better value per cell."]'::jsonb, 0, '2002.0000 over 3.000000 rounds to 667 cells, and 1333 plus 667 fills the 2000 exactly. In money the pair costs 6002.0000, 2.0000 over the limit.'::text, 'In the published gridOvershoot case, A costs 4000.0000, B 2002.0000 and C 1995.0000 against a limit of 6000.0000 million USD. Why does the exact solve fund A and C?', '["A and B together would cost 6002.0000, over the limit, so the best set that fits is A and C at 780.0000.", "B''s 2002.0000 is refused as a capex that does not divide evenly into the limit.", "The engine tolerates a breach smaller than one million, so it could fund A and B and prefers the set with slack.", "C has the best risked EMV per million of the three, and the optimizer funds down that ranking until the limit is reached."]'::jsonb, 0, 'A plus C costs 5995.0000 and returns 500.0000 plus 280.0000, the golden exact optimum; overLimit reads false and 5.0000 is left unspent.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 6, 'gridOvershoot returns A and B at 800.0000 with overLimit true and overLimitBy 2.0000. What is the best value that truly fits the limit?', '["800.0000, since the flag records the breach and the set it flags is still the optimum the engine solved for.", "780.0000 on A and C, found by checking in money, since the engine does not re-solve when it detects the overshoot.", "800.0000 less a charge for the 2.0000 overshoot, since a flagged set is priced back inside the limit.", "B and C, the only pair that leaves the 4000.0000 project out and so cannot breach the limit."]'::jsonb, 1, 'C''s 1995.0000 keeps A inside 6000.0000, giving 500.0000 plus 280.0000, which is 780.0000. The golden gap of 20.0000 is the value the engine reached by breaking the limit.'::text, 'The published gridOvershootFallback case forces the stated fallback on the gridOvershoot projects by setting exactStateLimit to 2. What does the fallback fund?', '["A and B at 800.0000 with overLimit true, since rounding lets B squeeze into the cells.", "A and C at 780.0000 with overLimit false, because every weight is rounded up and A and B together need more than the 2000 cells.", "Nothing, since a state limit of 2 is too small for any set and the call is refused.", "B and C at 580.0000, the only pair whose rounded weights leave a spare cell."]'::jsonb, 1, 'At 3.000000 per cell A weighs 1334, B 668 and C 665 cells; A and B need 2002 cells, so the fallback funds A + C at 5995.0000, solveMethod grid-feasible, optimalityGap 20.0000.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 7, 'What did the EC5-0 repair change in the gridOvershoot case?', '["It re-solves any overshooting set in money, so the case now returns A and C at 780.0000 with the flag kept for the record.", "It moved limits over 5000 onto the exact grid, which removes the rounding that let B squeeze into the cells.", "It refuses a set over the limit with an input error, the way a negative capex is refused, and funds nothing.", "It added the overLimit and overLimitBy flag; the grid still rounds and the set is still A and B at 800.0000."]'::jsonb, 3, 'Before EC5-0 a total capex of 6002.0000 sat beside a limit of 6000.0000 with nothing to mark it. The flag reports the overshoot of 2.0000 and does not correct it.'::text, 'Why does the stated fallback round every capex up to whole cells?', '["To make the fallback faster, since a rounded-up weight lets the knapsack skip the projects near the limit.", "To match the exact solve''s answer, since rounding up and rounding down cancel over a whole inventory.", "To leave a reserve in every run, since the fallback keeps one cell of the limit unspent by design.", "So any set that fits the grid also fits the limit in money: on gridOvershootFallback it keeps A + B, which would cost 6002.0000, out of the answer."]'::jsonb, 3, 'Rounding up can only overstate a capex, so a set that fits 2000 cells never costs more than the limit; the fallback on gridOvershootFallback funds A + C with overLimit false. The price is that a set which fits in money can miss the grid.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 8, 'The golden gap on gridOvershoot is 20.0000, and on gridUndershoot it is -200.0000. Why are their signs opposite?', '["Positive gaps are the grid rounding value up and negative gaps the grid rounding value down, both at 3.000000 per cell.", "The sign follows overLimitBy, which is 2.0000 on one case and a negative shortfall on the other.", "One case solves on the exact grid and the other on a coarse one, and the exact grid always overstates the value.", "The gap is the engine''s EMV less the exact optimum: positive where the engine broke the limit, negative where it left value out."]'::jsonb, 3, '800.0000 less 780.0000 is 20.0000, and 660.0000 less 860.0000 is -200.0000. The positive gap is value the budget cannot pay for.'::text, 'gridOvershootFallback reports optimalityGap 20.0000, and its set, A + C, is the exact optimum. How can both be true?', '["They cannot: a positive optimalityGap means the funded set missed the optimum by exactly that much.", "The gap measures the capex left unspent, 5.0000 here, scaled into million USD of risked EMV.", "The gap is the breach the fallback allowed over the limit, which is why its set could reach the optimum.", "optimalityGap is an upper bound on the EMV left out, worked from the grid with weights rounded down, and here the true shortfall is 0.0000."]'::jsonb, 3, 'Rounded down, A and B fit the 2000 cells, so the bound is worked from a set worth 800.0000 against the funded 780.0000; the exact optimum is also 780.0000, so nothing was lost. On gridUndershootFallback the bound of 200.0000 is exactly what was left out.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 9, 'gridUndershoot funds X, Y and Z at 4500.0000 against a limit of 6000.0000 million USD, with overLimit false and overLimitBy 0.0000. What does the false flag establish?', '["That the grid did not change the answer, since the flag is raised whenever rounding moves the funded set in either direction.", "That the 1500.0000 unspent is genuine, because the engine checks every left-out project against the unrounded capexes.", "Only that the set is not over the limit; it cannot say a better set was squeezed out, and here W worth 200.0000 was.", "That the answer is the exact optimum, since EC5-0 repaired the undershoot along with the overshoot."]'::jsonb, 2, 'The flag watches the limit from one side only. The exact optimum funds all four at 860.0000, and finding D4 left this undershoot silent.'::text, 'gridUndershoot has W, X and Y at 1499.0000 each and Z at 1502.0000 against a limit of 6000.0000 million USD. What does the exact solve fund?', '["X, Y and Z at 660.0000, dropping W, the least valuable, because four projects cannot share one limit.", "W, X and Y at 630.0000, the three cheapest, leaving 1503.0000 as a reserve.", "All four at capex 5999.0000 for 860.0000, with 1.0000 of the limit left unspent.", "Nothing, since a set that leaves only 1.0000 of headroom is treated as over the limit."]'::jsonb, 2, 'The four cost 5999.0000 in money and fit; the exact solve returns W + X + Y + Z for 200.0000 plus 210.0000 plus 220.0000 plus 230.0000, the golden optimum, with optimalityGap 0.0000.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 10, 'In gridUndershoot all four projects, W, X, Y and Z, fit inside 6000.0000 million USD in money. Why does the knapsack fund only three?', '["At 3.000000 per cell 1499.0000 and 1502.0000 both round up, to 500 and 501 cells, so the four weigh one cell more than the 2000 the limit holds.", "Z''s 1502.0000 pushes the money total of the four over 6000.0000, so one project has to leave the set, and the knapsack drops W because it is the least valuable of them.", "The knapsack keeps one project''s capex unspent on a coarse grid, as a reserve against rounding up.", "W''s EMV of 200.0000 falls below the value the grid assigns to a single cell at this resolution, so its value is rounded to nothing and it cannot win a place in the set."]'::jsonb, 0, 'Three weights of 500 and one of 501 exceed 2000 cells, so the knapsack drops W, the least valuable. The gap of -200.0000 is exactly W''s risked EMV.'::text, 'gridUndershootFallback forces the stated fallback on the same four projects with exactStateLimit 3. Why does it fund only three?', '["At 3.000000 per cell 1499.0000 and 1502.0000 both round up, to 500 and 501 cells, so the four weigh one cell more than the 2000 the limit holds.", "Z''s 1502.0000 pushes the money total of the four over 6000.0000, so one project has to leave the set, and the knapsack drops W because it is the least valuable of them.", "The fallback keeps one project''s capex unspent as a reserve against rounding up.", "W''s EMV of 200.0000 falls below the value the grid assigns to a single cell at this resolution, so its value is rounded to nothing and it cannot win a place in the set."]'::jsonb, 0, 'Three weights of 500 and one of 501 make 2001 cells, so the fallback drops W, the least valuable, and funds X + Y + Z for 660.0000; its optimalityGap of 200.0000 is exactly W''s risked EMV.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 11, 'Two answers leave money unspent: OKONO at 750.0000 leaves 60.0000, and gridUndershoot leaves 1500.0000. Which unspent money is genuine?', '["Both, because the optimizer never leaves money unspent unless no left-out project fits in the space.", "OKONO''s, because its grid is exact at 1.0000 and OK-6, the only project left, costs 310.0000; gridUndershoot''s hides W, which fits in money.", "gridUndershoot''s, since a coarse grid is solved in cells, and a count of whole cells cannot leave out a project whose capex still fits inside the limit.", "Neither, since unspent money on any grid means the knapsack stopped before it filled the limit."]'::jsonb, 1, 'On OKONO no remaining project fits in 60.0000. On gridUndershoot the 1500.0000 left over would pay for W at 1499.0000.'::text, 'Two answers leave money unspent: OKONO at 750.0000 leaves 60.0000, and gridUndershootFallback leaves 1500.0000 of 6000.0000. Which one calls for a closer look?', '["Neither, since the optimizer leaves money unspent only when no left-out project fits in the space.", "The fallback''s: it reports solveMethod \"grid-feasible\" and optimalityGap 200.0000, and W at 1499.0000 would fit the money left over.", "OKONO''s, since an exact solve that leaves money idle has stopped before it filled the limit.", "Both equally, since unspent money on any solve means the knapsack stopped early."]'::jsonb, 1, 'OKONO is solved exactly and OK-6, the only project left, costs 310.0000, so its 60.0000 is genuine. The fallback''s 1500.0000 sits beside a stated bound, and the exact solve funds all four for 860.0000.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 12, 'freeProjectTightLimit has a free project with capex 0.0000 and EMV 10.0000 beside A at capex 100.0000 and EMV 60.0000, at a limit of 100.0000. Why does the engine fund A alone?', '["A project with capex 0.0000 is treated as unentered and skipped, the same way a missing npv_p50 is read as zero.", "The free project''s EMV of 10.0000 is too small to beat A''s, and the optimizer funds the single best project at a tight limit.", "The grid weighs every project at max(1, round(capex / cell)), so the free project takes one cell and A already fills all 100.", "overLimit would read true if both were funded, so the engine drops the cheaper project to keep the flag false."]'::jsonb, 2, 'The golden optimum funds both for 70.0000, but on the grid they need one cell more than the limit holds. This is finding D2, which EC5-0 left as it was.'::text, 'freeProjectTightLimit has a free project with capex 0.0000 and EMV 10.0000 beside A at capex 100.0000 and EMV 60.0000, at a limit of 100.0000. What does the engine fund?', '["A alone for 60.0000, since a project with capex 0.0000 is treated as a row nobody finished entering and is skipped.", "The free project alone for 10.0000, since it is the only one that costs nothing.", "Both for 70.0000 at capex 100.0000, since a free project weighs nothing and rides along with A.", "A alone, since funding both would set overLimit true and the engine keeps the flag false."]'::jsonb, 2, 'On the exact solve a free project with positive EMV is always funded: 60.0000 plus 10.0000 is the golden optimum, and the total capex stays 100.0000.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 13, 'freeProjectSlack raises the limit to 101.0000 and the engine funds the free project and A at capex 100.0000 for 70.0000. What did the extra million buy?', '["The one cell the grid charges the free project; the million itself is never spent.", "A share of A''s capex overrun, since the engine lets a tight budget fund A only once it has a million of contingency.", "The free project''s 10.0000 at a price of one million USD, which is its true cost once its capex is read correctly.", "Nothing; the free project was funded because the larger limit moved the solve onto a coarse grid where zero capex rounds away."]'::jsonb, 0, 'Funded capex is 100.0000 against a limit of 101.0000, so 1.0000 stays unspent. The gap to the golden optimum closes to 0.0000.'::text, 'freeProjectSlack raises the limit to 101.0000 beside the same free project and A. What does the extra million change?', '["Only the money left unspent, 1.0000; the engine funds the same free project and A for 70.0000 at either limit.", "A share of A''s capex overrun, since the engine lets a tight budget fund A only once it has a million of contingency.", "The free project''s price, one million USD, which is its true cost once its capex is read at the higher limit.", "The solve method, since a limit of 101.0000 sends the free project to the fallback grid where it rounds away."]'::jsonb, 0, 'Funded capex is 100.0000 against 101.0000, so 1.0000 stays unspent; freeProjectTightLimit at 100.0000 already funds both, because a free project weighs nothing.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 14, 'In the three published free-project cases, at limits of 0.0000, 100.0000 and 101.0000, overLimit reads false. Why does the flag stay quiet where the engine loses 10.0000?', '["The flag counts cells rather than money, and a free project''s one cell is inside the limit in every case.", "EC5-0 repaired the free-project case, so the 10.0000 can no longer be lost.", "A set worth less than its exact optimum raises overLimitBy instead, which reads 10.0000 in two of the three cases.", "The engine''s set is inside the limit in money every time, and the flag only watches for a set over it."]'::jsonb, 3, 'The engine funds nothing, then A alone, then both, always within the limit. Finding D2 is left as it was, so a positive-EMV project with capex 0.0000 left out has to be noticed by hand.'::text, 'In all three free-project cases, at limits of 0.0000, 100.0000 and 101.0000, overLimit reads false and the free project is funded. What does the false flag tell you?', '["That a cell was charged and fitted, since the flag counts cells and a free project''s cell sits inside every limit.", "That the free project was funded only where money remained after A, which a limit of 0.0000 cannot offer.", "That the free project''s value was checked against its cost, since the flag reads true when a set is worth less than it costs.", "Only that each funded set sits inside its limit in money; an exact solve cannot exceed the limit, so the flag reads false every time."]'::jsonb, 3, 'The engine funds the free project, then free + A twice, at capex 0.0000, 100.0000 and 100.0000, each inside its limit with optimalityGap 0.0000. overLimit and overLimitBy stay in the result shape and read false and 0.0000.'::text),
      ('beginner', 'module', 'm05-the-grid-under-the-answer'::text, 15, 'The engine gives a user running their own coarse-grid inventory no gap to the exact optimum. Where did the golden''s 860.0000 on gridUndershoot come from?', '["The engine''s own exact re-check in money, which it runs and prints beside the answer whenever the reported resolution is not 1.0000.", "The test suite solved the exact problem separately; the engine never tests its answer against the unrounded capexes.", "The overLimitBy field, read as the value a larger limit would have added to the funded set.", "The Suite''s resolution display, which shows the gap to the exact optimum whenever the grid turns coarse."]'::jsonb, 1, 'A user sees 660.0000 and a clean flag, and the 200.0000 left out is found only by checking the unrounded capexes in money.'::text, 'A user runs their own inventory and gets solveMethod "grid-feasible" with optimalityGap 200.0000. What does the gap tell them without any golden?', '["Nothing until the exact optimum is solved separately, since the engine does not compare its answer with anything.", "That the funded set may fall short of the best set that fits by at most 200.0000 of risked EMV.", "That the funded capex runs 200.0000 over the limit, the amount to cut before the set is authorised.", "That exactly 200.0000 was left out, since the gap is always the shortfall to the exact optimum on any inventory."]'::jsonb, 1, 'optimalityGap is the best value on the same grid with every weight rounded down, less the funded EMV, so it bounds what the fallback left out. On gridUndershootFallback it is 200.0000 and the shortfall is exactly that; on gridOvershootFallback it is 20.0000 and the shortfall is 0.0000.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 2, 'Step one of the method compares a hand-risked EMV with the explorer''s column, and a row disagrees. What does the method say a mismatch means?', '["The explorer''s value comes from the seeded Monte Carlo, so it differs from the closed form by simulation noise at 10000 iterations.", "An input was typed wrong or a clamp fired: a pos over 1 read as 1, a pos under 0 as 0, or a negative fail_cost as 0.", "The explorer discounts the fail cost over the project life, which a hand calculation in one line cannot reproduce.", "The grid rounded the project''s value to a whole cell, and the hand value is the unrounded figure."]'::jsonb, 1, 'Risked EMV is closed form, pos x npv_p50 - (1 - pos) x fail_cost. The published posAboveOneClamps case reads a pos of 1.4 as 1 and returns 80.0000.'::text, 'Step one of the method compares a hand-risked EMV with the explorer''s column, and a row disagrees. What does the method say a mismatch means?', '["The explorer''s value comes from the seeded Monte Carlo, so it differs from the closed form by simulation noise at 10000 iterations.", "An input was typed wrong, or a default fired: a pos left out read as 1, or a negative fail_cost read as 0.", "The explorer discounts the fail cost over the project life, which a hand calculation in one line cannot reproduce.", "The grid rounded the project''s value to a whole cell, and the hand value is the unrounded figure."]'::jsonb, 1, 'Risked EMV is closed form, pos x npv_p50 - (1 - pos) x fail_cost. nullPosIsDefault returns 80.0000 and negativeFailCostIsZero 40.0000; a pos over 1 is refused by project name before it reaches the column.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 4, 'OKONO''s grid is exact at 1.0000. On an inventory whose resolution is anything else, which checks does the method require even when overLimit reads false?', '["None beyond the flag, since EC5-0 added overLimit precisely so that a coarse answer could be quoted without checking.", "Re-run the optimizer at a finer resolution chosen on request, and quote whichever answer has the larger EMV.", "Sum the funded capex against the limit in money, look for a left-out project that would still fit, and look for an unfunded positive-EMV project with capex 0.0000.", "Compare the funded set with the frontier''s last point, since the two disagree whenever rounding has moved the answer."]'::jsonb, 2, 'overLimit catches only the overshoot, 2.0000 on gridOvershoot. The undershoot that left 200.0000 out and the free project charged a cell worth 10.0000 are both silent.'::text, 'OKONO is solved exactly at every limit. On an inventory whose result reads solveMethod "grid-feasible", which checks does the method require even when overLimit reads false?', '["None beyond the flag, since the fallback rounds every weight up and so its answer can be quoted without checking.", "Re-run the optimizer on an exact solve chosen in the Studio, and quote whichever answer has the larger EMV.", "Read optimalityGap as the most risked EMV the set may leave out, and look for a left-out project that would still fit in money.", "Compare the funded set with the frontier''s last point, since the two disagree whenever rounding has moved the answer."]'::jsonb, 2, 'overLimit reads false on every answer, fallback included. On gridUndershootFallback the fallback funds X + Y + Z for 660.0000 with its bound stated beside it, and W at 1499.0000 would still fit the money left.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 10, 'OFON-1''s line CSG-02 has spent 4300000 against a budget of 3900000 with no entered forecast. What does it forecast, and why?', '["3900000, since a line with no entered forecast carries its budget as its forecast until one is typed.", "The actual less the budget, the overrun alone, since a forecast reports only what remains to be spent on the line.", "Nothing until a forecast is entered, since the forecast rule refuses a line whose forecast is not positive.", "4300000, the larger of its budget and its actual plus commitment."]'::jsonb, 3, 'The AFE''s estimate at completion is 27600000, a variance at completion of -550000. A forecast copied from the budget would hide CSG-02''s overrun, which the Suite did before EC5-0 whenever a line was edited.'::text, 'OFON-1''s line CSG-02 has spent 4300000 against a budget of 3900000 with no entered forecast. What does it forecast, and why?', '["3900000, since a line with no entered forecast carries its budget as its forecast until one is typed.", "The actual less the budget, the overrun alone, since a forecast reports only what remains to be spent on the line.", "Nothing until a forecast is entered, since the forecast rule refuses a line whose forecast is not positive.", "4300000, the larger of its budget and its actual plus commitment."]'::jsonb, 3, 'The AFE''s estimate at completion is 27600000, a variance at completion of -550000. A forecast copied from the budget would hide CSG-02''s overrun.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 12, 'OFON-1''s S-curve ends with a Planned point of 24452483 against a budget of 27050000. What does the shortfall mean?', '["An underspend of the plan, since the budget was phased to finish below its total and the rest is held as contingency.", "Nothing at the well: the curve is built in monthly buckets and stops at the window end, short of the full budget.", "The work running behind schedule by that amount, since a Planned point below budget means progress fell short.", "A curve that keeps walking past the end date, which moves the final month''s plan into the following year."]'::jsonb, 1, 'The last Planned point is 24452483, and past the as-of date the forecast jumps from the last actual of 15090000 to 19374834. Neither the shortfall nor the jump is an event at the well.'::text, 'OFON-1''s last monthly S-curve point, "Nov 27", plans 24452483 against a budget of 27050000. What does the gap mean?', '["An underspend of the plan, since the budget was phased to finish below its total and the rest is held as contingency.", "Nothing at the well: the curve closes on a point dated the window end, \"30 Nov 27\", which plans the whole 27050000.", "The work running behind schedule by that amount, since a Planned point below budget means progress fell short.", "A curve that stops short of the window end, which leaves the last days of plan off the chart."]'::jsonb, 1, 'The closing point "30 Nov 27" carries Planned 27050000, the budget, and Forecast 27600000, the EAC; it adds the remaining 2597517 of plan after "Nov 27".'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 14, 'Every step of the method checks out on OKONO at 450.0000: rows risked by hand, resolution 1.0000, the set proven at 291.0000 and the greedy set beaten. What does that still not prove?', '["That the inputs were right: the arithmetic is proven, but no step can show that a pos or a fail_cost was a good estimate.", "That the set is the optimum, since a proof by hand covers only the three funded projects and says nothing about the three left out of the set.", "That the frontier''s last point matches the funded set, which only the Monte Carlo can confirm.", "That the grid was exact, since a resolution of 1.0000 can still round a capex typed with decimals."]'::jsonb, 0, 'The method funds projects whole, uses one average correlation and assumes a normal success spread. OK-3''s 41.2500 is only as good as its pos of 0.250000 and its fail_cost of 85.0000.'::text, 'Every step of the method checks out on OKONO at 450.0000: rows risked by hand, solveMethod "exact", the set proven at 291.0000 and the greedy set beaten. What does that still not prove?', '["That the inputs were right: the arithmetic is proven, but no step can show that a pos or a fail_cost was a good estimate.", "That the set is the optimum, since a proof by hand covers only the three funded projects and says nothing about the three left out of the set.", "That the frontier''s last point matches the funded set, which only the Monte Carlo can confirm.", "That the solve was exact, since solveMethod can read \"exact\" while a capex typed with decimals is rounded."]'::jsonb, 0, 'The method funds projects whole, uses one average correlation and assumes a normal success spread. OK-3''s 41.2500 is only as good as its pos of 0.250000 and its fail_cost of 85.0000.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 15, 'OK-3 is out of the OKONO set at 300.0000, in at 450.0000, out at 600.0000 and back at 750.0000. What does that path show?', '["OK-3 is marginal at 0.458333 per million USD, so the optimizer rotates it in and out of the funded set to spread the exploration risk across budgets.", "Each budget is solved afresh over the whole inventory, so a project''s place in one funded set promises nothing at another limit.", "The grid rounds OK-3''s 90.0000 differently at each limit, which moves it across the edge of the knapsack.", "The optimizer builds each larger set on the one before and removes OK-3 whenever a better project is added."]'::jsonb, 1, 'At 450.0000 OK-3 fills the 30.0000 greedy leaves, for 291.0000; at 600.0000 the set is OK-1, OK-2, OK-4 and OK-5 at 402.7500 without it. On OKONO''s exact grid of 1.0000 nothing is rounded.'::text, 'OK-3 is out of the OKONO set at 300.0000, in at 450.0000, out at 600.0000 and back at 750.0000. What does that path show?', '["OK-3 is marginal at 0.458333 per million USD, so the optimizer rotates it in and out of the funded set to spread the exploration risk across budgets.", "Each budget is solved afresh over the whole inventory, so a project''s place in one funded set promises nothing at another limit.", "The grid rounds OK-3''s 90.0000 differently at each limit, which moves it across the edge of the knapsack.", "The optimizer builds each larger set on the one before and removes OK-3 whenever a better project is added."]'::jsonb, 1, 'At 450.0000 OK-3 fills the 30.0000 greedy leaves, for 291.0000; at 600.0000 the set is OK-1, OK-2, OK-4 and OK-5 at 402.7500 without it. The solve is exact, so nothing is rounded.'::text),
      ('intermediate', 'final', null::text, 3, 'The dashboard shows OFON-1''s EAC as 27600000, while the last point of the S-curve''s Forecast series, Nov 27, reads 24949669. A partner concludes the chart runs on a different forecast rule. What is the better reading?', '["The curve forecasts each line at its budget less its actual, the export rule from before the repair, so the projection carries none of the overrun on CSG-02 or CMT-03 and ends lower.", "The curve projects spend from the invoices at the pace of the last four, so its Forecast is a burn-rate estimate that happens to land short of the rule''s EAC.", "The curve''s Forecast is the budget redrawn, and the distance between the two figures is the variance at completion of -550000 that the tiles report.", "Both carry the same EAC from the one itemForecast rule; the curve spreads it evenly from the start and its last monthly point stands on the first of November, before the end date."]'::jsonb, 3, 'Past the as-of date the Forecast is the EAC of 27600000 spread from 2027-02-01, and the walk stops at Nov 27, so the chart ends at 24949669 while the rule behind both figures is the same.'::text, 'The dashboard shows OFON-1''s EAC as 27600000. On the S-curve as of 2027-08-15 the Nov 27 point''s Forecast reads 24949669, and a partner concludes the chart runs on a different forecast rule. What is the better reading?', '["The curve forecasts each line at its budget less its actual, a separate export rule, so the projection carries none of the overrun on CSG-02 or CMT-03 and ends lower.", "The curve projects spend from the invoices at the pace of the last four, so its Forecast is a burn-rate estimate that happens to land short of the rule''s EAC.", "The curve''s Forecast is the budget redrawn, and the distance between the two figures is the variance at completion of -550000 that the tiles report.", "Both carry the same EAC from the one itemForecast rule; the curve spreads it evenly from the start, Nov 27 is only the last monthly point, and the closing point \"30 Nov 27\" carries 27600000."]'::jsonb, 3, 'Past the as-of date the Forecast is the EAC of 27600000 spread from 2027-02-01. Nov 27 stands on the first of November, and the closing point dated 2027-11-30 carries Forecast 27600000, the dashboard''s EAC.'::text),
      ('intermediate', 'final', null::text, 5, 'Between OFON-1''s reports dated 2027-06-30 and 2027-08-15 the lines were not touched. SPI falls from 1.141290 to 0.872063 and CPI holds at 1.009377. A manager takes the steady CPI as proof the crew kept working at budgeted efficiency through those weeks. What is wrong with that?', '["Nothing, since CPI and SPI share earned value as their numerator, and a CPI that holds while spend rises pins the growth in earned value to the growth in spend over the period.", "CPI is earned value over actuals read from the lines as entered, so it prints 1.009377 on both dates whether the rig worked or nobody updated the progress column.", "CPI is taken against planned value on the report date, so it should have fallen with SPI, and its steadiness shows that one report was exported before the repair.", "A steady CPI beside a falling SPI means spend fell in step with progress, which is the signature of a rig held on standby at a reduced day rate."]'::jsonb, 1, 'Earned value stood at 15231500 while planned value grew from 13345861 to 17466060; neither CPI nor SPI can say whether the work stopped or the progress was simply never updated.'::text, 'Between OFON-1''s reports dated 2027-06-30 and 2027-08-15 the lines were not touched. SPI falls from 1.141290 to 0.872063 and CPI holds at 1.009377. A manager takes the steady CPI as proof the crew kept working at budgeted efficiency through those weeks. What is wrong with that?', '["Nothing, since CPI and SPI share earned value as their numerator, and a CPI that holds while spend rises pins the growth in earned value to the growth in spend over the period.", "CPI is earned value over actuals read from the lines as entered, so it prints 1.009377 on both dates whether the rig worked or nobody updated the progress column.", "CPI is taken against planned value on the report date, so it should have fallen with SPI, and its steadiness shows that one report was exported from an older copy.", "A steady CPI beside a falling SPI means spend fell in step with progress, which is the signature of a rig held on standby at a reduced day rate."]'::jsonb, 1, 'Earned value stood at 15231500 while planned value grew from 13345861 to 17466060; neither CPI nor SPI can say whether the work stopped or the progress was simply never updated.'::text),
      ('intermediate', 'final', null::text, 8, 'DRL-01''s progress is retyped from 72.0000 to a figure past 100 percent, and nothing else on OFON-1 changes. What does the repaired engine do?', '["It refuses the figure with a message naming the cost item, because its own message says progress runs from 0 to 100 percent.", "It silently clamps the figure to 100 percent on the way in, so DRL-01 earns exactly its 14200000 budget and no reading can pass what the line was authorised to cost.", "It accepts the figure: DRL-01 earns more than its 14200000 budget, so earned value, CPI, percent complete and every non-null SPI rise, while the EAC stays at 27600000.", "It accepts the figure and lowers the EAC, because the forecast rule reads progress past 100 percent as work bought for less than its budget."]'::jsonb, 2, 'The published case "progress beyond 100 percent earns beyond the budget" returns EV 150.0000 and CPI 1.666667; only negative progress is refused, and the forecast rule never reads progress.'::text, 'DRL-01''s progress is retyped from 72.0000 to 120 percent, and nothing else on OFON-1 changes. What does the engine do?', '["It accepts the figure: DRL-01 earns 120 percent of its 14200000 budget, so earned value, CPI and percent complete rise while the EAC stays put.", "It silently clamps the figure to 100 percent on the way in, so DRL-01 earns exactly its 14200000 budget and no reading can pass what the line was authorised to cost.", "It refuses the report with an AfeInputError naming DRL-01: progress runs from 0 to 100 percent, so no line can earn past its budget.", "It accepts the figure and lowers the EAC, because the forecast rule reads progress past 100 percent as work bought for less than its budget."]'::jsonb, 2, 'The engine returns Cost item "DRL-01" has progress above 100 percent (120 percent). Progress runs from 0 to 100 percent. Progress of exactly 100 is accepted and earns the whole budget; the forecast rule never reads progress.'::text),
      ('intermediate', 'final', null::text, 10, 'One line carries an entered forecast of -50; another, Completion, carries progress of -0.5 percent. How does the repaired AFE engine treat the two entries?', '["Both are refused with an AfeInputError naming the cost item, because the repair added one guard against negative entries across every column of a line.", "Both are clamped to zero without a message, so the forecast becomes 0 and falls back to the rule, while the progress earns nothing on the line.", "The forecast is dropped without a word and the line falls back to the larger of its budget and actual + commitment; the progress stops the calculation with a message naming the cost item.", "The forecast is refused with a message, since a negative cost cannot be forecast, while the progress is clamped to zero so earned value can still be summed."]'::jsonb, 2, 'The published line with a forecast of -50 returns EAC 100.0000 and variance 0.0000 silently, while negative progress fails with "Progress runs from 0 to 100 percent."'::text, 'One line carries an entered forecast of -50; another, Completion, carries progress of -0.5 percent. How does the AFE engine treat the two entries?', '["Both are refused with an AfeInputError naming the cost item, because one guard against negative entries covers every column of a line.", "Both are clamped to zero without a message, so the forecast becomes 0 and falls back to the rule, while the progress earns nothing on the line.", "The forecast is replaced by the larger of budget and actual + commitment and the line is flagged forecastIgnored \"negative\"; the progress stops the calculation with a message naming the cost item.", "The forecast is refused with a message, since a negative cost cannot be forecast, while the progress is clamped to zero so earned value can still be summed."]'::jsonb, 2, 'The published line with a forecast of -50 returns EAC 100.0000 and variance 0.0000 with one line counted in linesForecastIgnored, while negative progress fails with "Progress runs from 0 to 100 percent."'::text),
      ('intermediate', 'final', null::text, 12, 'CMT-03''s actual is raised by an accrual until its actual + commitment passes its entered forecast of 1400000, and no invoice is entered. What does the AFE report?', '["CMT-03 forecasts its new actual + commitment, since the rule takes the larger of the entered figure and the money already spent and committed.", "CMT-03 still forecasts 1400000, so the EAC stays at 27600000, while CPI falls and percent spent rises; the S-curve does not move.", "The EAC and the curve''s Actual both rise, since an accrual is posted to the invoices so that the two records of spend stay in step.", "CMT-03 forecasts its budget of 1250000 again, because an entered forecast below the money already spent is read as not positive."]'::jsonb, 1, 'A positive entered forecast wins unconditionally and is never compared with actual + commitment, so the line can report 1400000 on money already past it; the curve reads only the invoices.'::text, 'CMT-03''s actual is raised by an accrual until its actual + commitment passes its entered forecast of 1400000, and no invoice is entered. What does the AFE report?', '["CMT-03 forecasts its new actual + commitment, since the rule takes the larger of the entered figure and the money already spent and committed.", "CMT-03 still forecasts 1400000, so the EAC stays at 27600000, while CPI falls and percent spent rises; the S-curve does not move.", "The EAC and the curve''s Actual both rise, since an accrual is posted to the invoices so that the two records of spend stay in step.", "CMT-03 forecasts its budget of 1250000 again, because an entered forecast below the money already spent is read as not positive."]'::jsonb, 1, 'A positive entered forecast is kept even when the money spent and committed passes it; the line is then flagged forecastBelowCommitted with the shortfall, and the curve reads only the invoices.'::text),
      ('intermediate', 'final', null::text, 17, 'Two reports both print time progress 1.000000: one on an AFE run after its end date, one on an AFE saved with no window. What in the engine''s metrics tells them apart?', '["The SPI, which is null on an AFE with no window because the engine cannot build a plan without dates to spread it over.", "The planned value, which is 0 on an AFE with no window and the whole budget on one whose end date has passed.", "Nothing: both divide earned value by the whole budget, so each SPI is percent complete over 100, and only the window fields show which AFE never had dates.", "A refusal, since the engine rejects any as-of date on an AFE with no window, printing \"asOf is not a valid date\"."]'::jsonb, 2, 'The published no-dates case returns time progress 1.000000 and SPI 0.250000, the published window read after its end returns 1.000000 and 0.940000; the repaired Suite labels SPI unavailable when there are no dates.'::text, 'Two reports both print time progress 1.000000: one on an AFE run after its end date, one on an AFE saved with no window. What in the engine''s metrics tells them apart?', '["The SPI, which is null on an AFE with no window because the engine cannot build a plan without dates to spread it over.", "The planned value, which is 0 on an AFE with no window and the whole budget on one whose end date has passed.", "Nothing: both divide earned value by the whole budget, so each SPI is percent complete over 100, and only the window fields show which AFE never had dates.", "A refusal, since the engine rejects any as-of date on an AFE with no window, printing \"asOf is not a valid date\"."]'::jsonb, 2, 'The published no-dates case returns time progress 1.000000 and SPI 0.250000, the published window read after its end returns 1.000000 and 0.940000; the Suite labels SPI unavailable when there are no dates.'::text),
      ('intermediate', 'final', null::text, 18, 'The published "suite test: empty AFE" returns SPI 1.000000, while OFON-1 as of 2027-01-15 returns SPI null. What separates the two?', '["The empty AFE has a budget of 0, and a guard returns SPI 1 before planned value is considered; OFON-1 has a budget and a planned value of 0, which gives null.", "The empty AFE has no window, so time progress falls back to 1 and planned value equals earned value, which makes the ratio exactly 1, the same fallback the no-dates case uses.", "OFON-1 is dated before its start and the empty AFE after its end, and the engine prints null before a window and 1 after one.", "Both are the same reading printed two ways: the empty AFE''s report came from the Suite and OFON-1''s came from the engine, which prints null for 1."]'::jsonb, 0, 'The zero-budget guard fires first, so an AFE with nothing in it reports SPI 1.000000 while one with 27050000 of budget and no planned value reports null.'::text, 'The published "suite test: empty AFE: no budget and no spend, so SPI and CPI are null" returns SPI null, and OFON-1 as of 2027-01-15 returns SPI null too. What separates the two nulls?', '["spiStatus: the empty AFE has no budget and reads \"no-budget\"; OFON-1 has a budget but no planned value yet and reads \"no-planned-value\".", "Nothing: both AFEs lack a window, so time progress falls back and the engine prints one null for every AFE without dates.", "OFON-1 is dated before its start and the empty AFE after its end, and the engine prints null on both sides of a window.", "The CPI: OFON-1''s is null before the start and the empty AFE''s is 1, and the SPI simply follows the CPI in each report."]'::jsonb, 0, 'The status says why the schedule index is missing: "no-budget" when there is nothing to plan against at all, "no-planned-value" when a budget exists but the window has not yet planned any of it.'::text),
      ('intermediate', 'final', null::text, 20, 'As of 2028-01-10 OFON-1''s planned value is 27050000 and its SPI 0.563087, though its EAC is 27600000. What can still change that SPI?', '["A later as-of date, since planned value keeps climbing past the end date toward the EAC, so the SPI falls further every month the AFE runs late.", "A revised EAC, because after the end the engine divides earned value by the forecast at completion rather than by the approved budget.", "A new invoice, because after the end of the window SPI is computed from the S-curve''s Actual line in place of the typed progress.", "Only progress entered on the lines, because planned value has stopped at the approved budget and a later date or a revised EAC cannot move it."]'::jsonb, 3, 'After the end SPI is 15231500 over 27050000, percent complete over 100; the -550000 overrun never enters the schedule measure.'::text, 'As of 2028-01-10 OFON-1''s planned value is 27050000 and its SPI 0.563087, though its EAC is 27600000. What can still change that SPI?', '["A later as-of date, since planned value keeps climbing past the end date toward the EAC, so the SPI falls further every month the AFE runs late.", "A revised EAC, because after the end the engine divides earned value by the forecast at completion in place of the approved budget.", "A new invoice, because after the end of the window SPI is computed from the S-curve''s Actual line in place of the typed progress.", "Only progress entered on the lines, because planned value has stopped at the approved budget and a later date or a revised EAC cannot move it."]'::jsonb, 3, 'After the end SPI is 15231500 over 27050000, percent complete over 100; the -550000 overrun never enters the schedule measure.'::text),
      ('intermediate', 'final', null::text, 21, 'LOG-04 places a further order large enough that its actual + commitment passes its 2100000 budget, and nothing is invoiced or paid. Which readings move?', '["Percent spent and CPI as well as the EAC, because a placed order is counted as spend once it takes the line past its budget.", "Nothing until the order is invoiced, since commitments enter the forecast only when an invoice ties them to a line.", "The EAC only, while the curve''s Forecast stays put, because past the as-of date the curve reads the invoices rather than the rule.", "The EAC and the variance at completion, since LOG-04 now forecasts its actual + commitment, and with them the projected Forecast; earned value, CPI, percent spent and SPI stay."]'::jsonb, 3, 'The published line with 70 spent and 60 committed on a budget of 100 forecasts 130.0000; commitments enter the rule and no other reading, and the curve projects whatever EAC the rule gives.'::text, 'LOG-04 places a further order large enough that its actual + commitment passes its 2100000 budget, and nothing is invoiced or paid. Which readings move?', '["Percent spent and CPI as well as the EAC, because a placed order is counted as spend once it takes the line past its budget.", "Nothing until the order is invoiced, since commitments enter the forecast only when an invoice ties them to a line.", "The EAC only, while the curve''s Forecast stays put, because past the as-of date the curve reads the invoices and skips the rule.", "The EAC and the variance at completion, since LOG-04 now forecasts its actual + commitment, and with them the projected Forecast; earned value, CPI, percent spent and SPI stay."]'::jsonb, 3, 'The published line with 70 spent and 60 committed on a budget of 100 forecasts 130.0000; commitments enter the rule and no other reading, and the curve projects whatever EAC the rule gives.'::text),
      ('intermediate', 'final', null::text, 24, 'The published window from 2020-01-01 to 2020-12-31, read as of 2020-06-30, has one line with a budget of 1200, an actual of 200, a commitment of 100 and an entered forecast of 1500. Its last point reads Planned 1101 and Forecast 1377. What is the line''s EAC, and why is it not on the curve?', '["1377, because past the as-of date the Forecast series is the EAC itself, and the last point is where the projection finishes.", "1200, the budget, because an entered forecast is taken only when the actual + commitment of 300 has already passed the budget.", "1500, the entered forecast; the projection spreads it from the start and the last point stands on the first of December, so 1377 falls short of it as 1101 falls short of 1200.", "300, the actual + commitment, because the entered 1500 is set aside once invoices have been billed against the line."]'::jsonb, 2, 'A positive entered forecast wins, and on 12 monthly points the Forecast and the Planned lines take the same share of the calendar, of 1500 and of 1200.'::text, 'The published window from 2020-01-01 to 2020-12-31, read as of 2020-06-30, has one line with a budget of 1200, an actual of 200, a commitment of 100 and an entered forecast of 1500. What is the line''s EAC, and where does it appear on the curve?', '["1200, the budget, because past the as-of date the Forecast series follows the plan and the closing point carries only the budget.", "300, the actual + commitment, because the entered 1500 is set aside once invoices have been billed against the line.", "1500, the entered forecast; the projection spreads it from the start and the closing point \"31 Dec 20\" carries Forecast 1500 beside Planned 1200.", "1377, the projection read on the first of December, since the curve stops at its last monthly step before the end date."]'::jsonb, 2, 'A positive entered forecast wins, so the EAC is 1500. The curve has 13 points and closes on "31 Dec 20", windowEnd true, with Planned 1200 and Forecast 1500; Actual there is null because the end is after the as-of date.'::text),
      ('intermediate', 'final', null::text, 26, 'A new AFE is reported as of its start day. Progress is typed on its budgeted lines but no actuals have been entered. What CPI and SPI does the engine print?', '["CPI null and SPI null, because the repair made every division by zero across the AFE metrics return null in place of a number a chart could plot.", "CPI 1 and SPI 1, because a single guard returns 1 for both ratios whenever nothing has been spent on the lines and nothing has yet been planned.", "CPI 1 and SPI null: both ratios are undefined, but only the SPI says so, because CPI 1 whenever actuals are 0 is an unrepaired property.", "A refusal for the CPI, which the engine cannot compute without spend on the lines, and an SPI of 0 because no planned value has yet accrued."]'::jsonb, 2, 'The weighted earned value case shows CPI 1.000000 with 110.0000 earned and nothing spent, and OFON-1 on 2027-02-01 shows time progress 0.000000 and SPI null.'::text, 'A new AFE is reported as of its start day. Progress is typed on its budgeted lines but no actuals have been entered. What CPI and SPI does the engine print?', '["CPI 1 and SPI null, because the engine prints a neutral CPI of 1 whenever nothing has been spent and keeps null for the schedule only.", "CPI 1 and SPI 1, because a single guard returns 1 for both ratios whenever nothing has been spent on the lines and nothing has yet been planned.", "CPI null and SPI null: CPI with cpiStatus \"no-spend\" because nothing has been spent, and SPI with \"no-planned-value\" because no whole day has elapsed.", "A refusal for the CPI, which the engine cannot compute without spend on the lines, and an SPI of 0 because no planned value has yet accrued."]'::jsonb, 2, 'The published weighted earned value case shows CPI null (no-spend) with 110.0000 earned and nothing spent, and OFON-1 on 2027-02-01 shows time progress 0.000000 and SPI null (no-planned-value).'::text),
      ('intermediate', 'final', null::text, 27, 'A published S-curve on a window from 2090-01-01 to 2091-01-01 has three lines: budget 1200 with actual 900 and commitment 600; budget 500 with forecast 650; budget 300 with forecast -10. Its last Forecast point is 2450. Which reading of the lines produces that figure?', '["The first line forecasts its budget of 1200 with its 600 committed added on top, the second its entered 650, and the third drops out because a negative entry removes the line.", "The rule before the repair, which took any non-zero entry: the first line at its actual + commitment, the second at 650 and the third at its entered -10.", "Every line forecasts its budget, 2000 in all, and the curve lifts the last point by the entered forecasts less the budgets they replace.", "The first line forecasts its actual + commitment of 1500, the second its entered 650, and the third its budget of 300, because -10 is not positive."]'::jsonb, 3, 'The 13 points reach the whole EAC because a point stands on the end date, where Planned is 2000; the third line''s -10 is ignored by the rule and by the curve.'::text, 'A published S-curve on a window from 2090-01-01 to 2091-01-01 has three lines: budget 1200 with actual 900 and commitment 600; budget 500 with forecast 650; budget 300 with forecast -10. Its last Forecast point is 2450. Which reading of the lines produces that figure?', '["The first line forecasts its budget of 1200 with its 600 committed added on top, the second its entered 650, and the third drops out because a negative entry removes the line.", "Any non-zero entry is taken as typed: the first line at its actual + commitment, the second at 650 and the third at its entered -10.", "Every line forecasts its budget, 2000 in all, and the curve lifts the last point by the entered forecasts less the budgets they replace.", "The first line forecasts its actual + commitment of 1500, the second its entered 650, and the third its budget of 300, because -10 is not positive."]'::jsonb, 3, 'The 13 points close on "1 Jan 91", the end date, where Planned is 2000 and Forecast the whole EAC; the third line''s -10 is ignored by the rule and by the curve.'::text),
      ('intermediate', 'final', null::text, 28, 'A group capital summary adds OFON-1''s operator share of 6762500 to the risked EMV of 402.7500 on OKONO''s 600.0000 set. What is wrong with the sum?', '["Only the units: dividing 6762500 by a million and rounding to four decimals first makes the sum sound, since both figures are dollars of capital the operator stands behind.", "The two models share nothing: 6762500 is a share of an AFE budget in whole USD, 402.7500 a risked value in million USD, and no rescaling makes them one quantity.", "Only the timing: the operator''s share should be taken on the EAC of 27600000 rather than the budget, so that both figures describe the end of the programme and can be summed.", "Nothing, since an operator''s share and a risked EMV are both the operator''s expected outlay, and they add directly."]'::jsonb, 1, 'Mixing the two fields is the mistake examined here: 25.0000 percent of 27050000 is an authorised cost, and OKONO''s figure is value from a different inventory in a different unit.'::text, 'A group capital summary adds OFON-1''s operator share of 6762500 to the risked EMV of 402.7500 on OKONO''s 600.0000 set. What is wrong with the sum?', '["Only the units: dividing 6762500 by a million and rounding to four decimals first makes the sum sound, since both figures are dollars of capital the operator stands behind.", "The two models share nothing: 6762500 is a share of an AFE budget in whole USD, 402.7500 a risked value in million USD, and no rescaling makes them one quantity.", "Only the timing: the operator''s share should be taken on the EAC of 27600000 in place of the budget, so that both figures describe the end of the programme and can be summed.", "Nothing, since an operator''s share and a risked EMV are both the operator''s expected outlay, and they add directly."]'::jsonb, 1, 'Mixing the two fields is the mistake examined here: 25.0000 percent of 27050000 is an authorised cost, and OKONO''s figure is value from a different inventory in a different unit.'::text),
      ('intermediate', 'final', null::text, 32, 'Before the repair, an AFE whose window spanned today was opened on two days in a row with nothing changed on its lines. What differed between the two openings, and what does the repaired engine do instead?', '["The EAC, because the forecast rule read today''s date to decide which invoices counted toward each cost line, and the repaired rule reads the window''s end date in its place instead.", "The CPI, because actuals were pro-rated to today''s date across the window, and the repaired engine now reads the actuals as they stood on the window''s opening start date instead.", "The SPI, because the engine read the clock for time progress; it now takes an explicit as-of date, so OFON-1 run for 2027-08-15 gives planned value 17466060 whenever it is run.", "Nothing, since the old engine already took a report date, and the repair only renamed the field and added the refusal of an invalid one."]'::jsonb, 2, 'The same clock also walked the S-curve on to the current month, 81 points for a 2020 AFE on 2026-09-14; now the date is an input and the curve stops at the window''s end.'::text, 'An AFE whose window spans today is opened on two days in a row with nothing changed on its lines, and the as-of box is left at its default each time. What differs between the two openings?', '["The EAC, because the forecast rule reads the as-of date to decide which invoices count toward each cost line.", "The CPI, because actuals are pro-rated to the as-of date across the window before they are divided into earned value.", "The SPI, because the dashboard passes today as the as-of date by default; OFON-1 run for 2027-08-15 gives planned value 17466060 on any day.", "Nothing, since the engine reads the window''s end date for every calculation and the as-of date only labels the report."]'::jsonb, 2, 'The engine never reads the clock: every call states its as-of date, and only time progress, planned value and SPI move with it. The dashboard supplies today unless a date is typed into its As of box.'::text),
      ('intermediate', 'final', null::text, 36, 'Drawn as of 2027-06-30 rather than 2027-08-15, how many points does OFON-1''s S-curve carry, and why?', '["Still 10: the walk runs from the start date to the end date in monthly steps, and the as-of date decides only where Actual stops and Forecast projects.", "Fewer, since the repaired walk stops at the as-of date and plots no point after the day the report was run for.", "One more, since a report dated inside the window adds a point on the as-of date so that the plan behind the SPI can be read.", "As many as the months to the present, since the walk runs on from the start date to the current calendar month."]'::jsonb, 0, 'The repair bound the walk to the window, where before it a 2020 AFE drew 81 points on 2026-09-14; the as-of date moves null Actuals, never the count.'::text, 'Drawn as of 2027-06-30, earlier than the usual 2027-08-15, how many points does OFON-1''s S-curve carry, and why?', '["Still 11: ten monthly steps from the start date and a closing point on the end date; the as-of date decides only where Actual stops and Forecast projects.", "Fewer, since the walk stops at the as-of date and plots no point after the day the report was run for.", "One more, since a report dated inside the window adds a point on the as-of date so that the plan behind the SPI can be read.", "As many as the months to the present, since the walk runs on from the start date to the current calendar month."]'::jsonb, 0, 'The walk is bound to the window and closes on "30 Nov 27" whatever the as-of date; the date moves null Actuals and the projected Forecast, and leaves the count alone.'::text),
      ('intermediate', 'final', null::text, 37, 'The published window from 2026-01-01 to 2027-12-31 returns SPI 1.139063 as of 2026-09-14 and SPI 0.940000 as of 2028-06-30. What is the second figure?', '["Earned value over the whole budget, the case''s percent complete divided by 100, because time progress stops at 1 after the end.", "A schedule ratio that has fallen because the plan kept growing after the end date while earned value stood still on the lines.", "The first reading corrected for the 256 of 729 days, applied once the window closed to turn a mid-window ratio into a final one.", "The case''s CPI, which the engine substitutes for SPI once the window has closed and planned value can no longer be computed."]'::jsonb, 0, 'At 2026-09-14 time progress is 0.351166, 256 of 729 days; after the end it is 1.000000, so the date can no longer move the 0.940000.'::text, 'The published window from 2026-01-01 to 2027-12-31 returns SPI 1.139063 as of 2026-09-14 and SPI 0.940000 as of 2028-06-30. What is the second figure?', '["Earned value over the whole budget, the case''s percent complete divided by 100, because time progress stops at 1 after the end.", "A schedule ratio that has fallen because the plan kept growing after the end date while earned value stood still on the lines.", "The first reading corrected for the 256 of 729 days, applied once the window closed to turn a mid-window ratio into a final one.", "The case''s CPI, which the engine substitutes for SPI once the window has closed and planned value cannot be computed any more."]'::jsonb, 0, 'At 2026-09-14 time progress is 0.351166, 256 of 729 days; after the end it is 1.000000, so the date cannot move the 0.940000.'::text),
      ('intermediate', 'final', null::text, 39, 'Which of these entries does the repaired AFE engine refuse outright with a message?', '["An entered forecast smaller than the money already spent and committed on the line, which the rule declines to take.", "An invoice whose date is null, which the curve refuses outright rather than leave it out of every bucket it draws.", "A progress figure below zero on a cost line, refused with a message that names the item.", "Progress above 100 percent, which the message says lies outside the range from 0 to 100 percent."]'::jsonb, 2, 'Negative progress fails with the item named, as the published message for CMP-02 at -20 percent shows; CMT-03 with 900000 entered is taken as typed, an invoice with a null date is left off the curve and counted beside it rather than refused, and progress past 100 percent is accepted, earning 150.0000 in its published case.'::text, 'Which of these entries does the AFE engine refuse outright with a message?', '["An entered forecast smaller than the money already spent and committed on the line, which the rule declines to take.", "An invoice whose date is null, which the curve refuses outright and so leaves out of every bucket it draws.", "A progress figure below zero on a cost line, refused with a message that names the item.", "An entered forecast below zero, which the message says lies outside what a line can cost."]'::jsonb, 2, 'Negative progress fails with the item named, as the published message for CMP-02 at -20 percent shows. CMT-03 with 900000 entered is kept and flagged forecastBelowCommitted, a null-dated invoice is left off the curve and counted, and a negative forecast is replaced and flagged forecastIgnored "negative".'::text),
      ('intermediate', 'final', null::text, 40, 'Past the as-of date the S-curve''s Forecast is the EAC spread from the window''s start. Could its first projected point sit below the last actual?', '["No, because the projection adds the spend still to come onto the last actual it follows, so the series can only rise or hold level past the as-of date.", "No, because the EAC is never below actual + commitment, so no share of it can fall under the invoices at any point.", "Only when an entered forecast is negative, since the S-curve takes a negative entry at its face value and pulls the projected line down under the actuals.", "Yes: the projection never starts from the actuals, so an AFE whose invoices ran ahead of a straight spread of its EAC would step down at the as-of date."]'::jsonb, 3, 'OFON-1 steps up from 15090000 to 19374834 because its invoices sit under the straight line; the size and sign of the step come from that distance, not from spending.'::text, 'Past the as-of date the S-curve''s Forecast is the EAC spread from the window''s start. Could its first projected point sit below the last actual?', '["No, because the projection adds the spend still to come onto the last actual it follows, so the series can only rise or hold level past the as-of date.", "No, because the EAC is never below actual + commitment, so no share of it can fall under the invoices at any point.", "Only when an entered forecast is negative, since the S-curve takes a negative entry at its face value and pulls the projected line down under the actuals.", "Yes: the projection never starts from the actuals, so an AFE whose invoices ran ahead of a straight spread of its EAC would step down at the as-of date."]'::jsonb, 3, 'OFON-1 steps up from 15090000 to 19374834 because its invoices sit under the straight line; the size and sign of the step come from that distance, and no spending happens at that point.'::text),
      ('intermediate', 'module', 'm01-an-afe-is-a-promise'::text, 4, 'OFON-1 reads 55.7856 percent spent. What sits in the numerator of that figure?', '["Actuals and commitments together, because money promised to a contractor is money the AFE can no longer spend on anything else.", "Only the 15090000 of actuals on the lines; the 5000000 committed stays outside it.", "The earned value of 15231500, since percent spent measures how much of the authorised budget the finished work has used up.", "The invoice total, because a spend percentage is a reading of money that has left the company and only the invoices carry a date."]'::jsonb, 1, 'Percent spent is 15090000 over the budget of 27050000. CPI and percent spent read the line actuals only; commitments enter the forecast rule and nothing else.'::text, 'OFON-1 reads 55.7856 percent spent. What sits in the numerator of that figure?', '["Actuals and commitments together, because money promised to a contractor is money the AFE cannot spend on anything else.", "Only the 15090000 of actuals on the lines; the 5000000 committed stays outside it.", "The earned value of 15231500, since percent spent measures how much of the authorised budget the finished work has used up.", "The invoice total, because a spend percentage is a reading of money that has left the company and only the invoices carry a date."]'::jsonb, 1, 'Percent spent is 15090000 over the budget of 27050000. CPI and percent spent read the line actuals only; commitments enter the forecast rule and nothing else.'::text),
      ('intermediate', 'module', 'm01-an-afe-is-a-promise'::text, 6, 'An invoice on an AFE is saved with a null date. What does the repaired engine do with it?', '["Refuses the AFE with an error that names the invoice, in the way negative progress on a cost line is refused.", "Counts it from 1970, which is earlier than every bucket, so it appears in the S-curve from the first point on.", "Places it at the as-of date, so it lifts only the points from that day onward and leaves the earlier ones alone.", "Leaves it off the S-curve and reports it in the count of undated invoices beside the curve."]'::jsonb, 3, 'The engine still does not refuse an undated invoice, but it no longer guesses a date for one: an invoice it cannot date reaches no bucket, and the count is reported beside the curve, 2 on the published undated case.'::text, 'An invoice on an AFE is saved with a null date. What does the engine do with it?', '["Refuses the AFE with an error that names the invoice, in the way negative progress on a cost line is refused.", "Counts it from 1970, which is earlier than every bucket, so it appears in the S-curve from the first point on.", "Places it at the as-of date, so it lifts only the points from that day onward and leaves the earlier ones alone.", "Leaves it off the S-curve and reports it in the count of undated invoices beside the curve."]'::jsonb, 3, 'The engine does not refuse an undated invoice and does not guess a date for one: an invoice it cannot date reaches no bucket, and the count is reported beside the curve, 2 on the published undated case.'::text),
      ('intermediate', 'module', 'm01-an-afe-is-a-promise'::text, 13, 'One cost line is saved with a progress of -0.5 percent and another with progress past 100 percent. What does the engine do?', '["Refuses the first with a message naming the cost item, and accepts the second, letting it earn more than its budget.", "Refuses both, since its own message says progress runs from 0 to 100 percent.", "Clamps both into the range, reading the first as 0 and the second as 100, and reports the clamped figures as though they were typed.", "Accepts both with a flag, leaving the flagged lines out of earned value while still carrying their budgets in the EAC and the total."]'::jsonb, 0, 'Negative progress stops the calculation with "Progress runs from 0 to 100 percent." in the message, yet progress past 100 is taken, and earned value is only as good as the progress typed in.'::text, 'One cost line is saved with a progress of -0.5 percent and another with progress past 100 percent. What does the engine do?', '["Refuses both, each with a message naming its cost item, since progress runs from 0 to 100 percent.", "Refuses the first with a message naming the cost item, and accepts the second, letting it earn more than its budget.", "Clamps both into the range, reading the first as 0 and the second as 100, and reports the clamped figures as though they were typed.", "Accepts both with a flag, leaving the flagged lines out of earned value while still carrying their budgets in the EAC and the total."]'::jsonb, 0, 'Negative progress fails with "Cost item "Completion" has negative progress (-0.5 percent)." and progress above 100 fails the same way, naming the line; progress of exactly 100 is accepted and earns the whole budget.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 2, 'CMT-03''s entered forecast is replaced by 900000, below the 940000 already spent and committed on the line. What does the line forecast?', '["940000, because the engine floors an entered forecast at the money already spent and committed before it accepts the figure.", "1250000, because a forecast below the spend to date is not credible and the rule falls back to the larger of its two formula figures.", "Nothing, because a forecast below actual plus commitment is refused with an input error that names the cost item carrying it.", "900000, because any positive entered forecast is taken as typed."]'::jsonb, 3, 'The rule never compares a positive entry with the spend (finding EC5-1); an entry of 1 on the same line forecasts 1.'::text, 'CMT-03''s entered forecast is replaced by 900000, below the 940000 already spent and committed on the line. What does the line forecast?', '["940000, because the engine floors an entered forecast at the money already spent and committed before it accepts the figure.", "1250000, because a forecast below the spend to date is not credible and the rule falls back to the larger of its two formula figures.", "Nothing, because a forecast below actual plus commitment is refused with an input error that names the cost item carrying it.", "900000, because any positive entered forecast is taken as typed."]'::jsonb, 3, 'A positive entry is kept as the forecast and compared with the spend: the line is flagged forecastBelowCommitted, forecastBelowCommittedBy 40000; an entry of 1 on the same line forecasts 1.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 6, 'With CMT-03''s other figures unchanged, an entered forecast of 1 makes it forecast 1, and an entered forecast of 0 makes it forecast 1250000. What separates them?', '["The engine reads 1 as a forecast stated in millions and scales it up before comparing, while it reads 0 as a field left blank.", "Only the sign test: 1 is positive and taken as typed, while 0 is not positive and falls back to the formula.", "A forecast of 1 is held for review and shown as entered, while a forecast of 0 is taken as a descope and the line keeps its budget.", "A floor at actual plus commitment applies only to a zero entry and leaves 1 alone."]'::jsonb, 1, 'Nothing checks a positive entry against the 940000 already spent and committed, so 1 stands; 0 falls to the larger of 1250000 and 940000.'::text, 'With CMT-03''s other figures unchanged, an entered forecast of 1 makes it forecast 1, and an entered forecast of 0 makes it forecast 1250000. What separates them?', '["The engine reads 1 as a forecast stated in millions and scales it up before comparing, while it reads 0 as a field left blank.", "Only the sign test: 1 is positive and taken as typed, while 0 is not positive and falls back to the formula.", "A forecast of 1 is held for review and shown as entered, while a forecast of 0 is taken as a descope and the line keeps its budget.", "A floor at actual plus commitment applies only to a zero entry and leaves 1 alone."]'::jsonb, 1, 'A positive entry is kept, so 1 stands, flagged forecastBelowCommitted with forecastBelowCommittedBy 939999; 0 is no entry at all and falls to the larger of 1250000 and 940000.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 8, '"suite test: entered forecast" has nothing spent or committed and forecasts 140.0000 on a budget of 100. What makes its overrun different from the 130.0000 in "suite test: committed past the budget"?', '["It is no overrun, since a variance is booked only once actuals are recorded.", "The engine leaves an entry with no spend out of the EAC until money is spent.", "Nothing, since both lines forecast the larger of budget and actual plus commitment.", "It rests on a typed judgment with nothing spent, while 130.0000 is money already spent and promised."]'::jsonb, 3, 'The first returns variance -40.0000 on an entry of 140 alone; the second has 70 spent and 60 committed, which pass the budget of 100 and give -30.0000.'::text, '"suite test: entered forecast (nothing spent: CPI null)" has nothing spent or committed and forecasts 140.0000 on a budget of 100. What makes its overrun different from the 130.0000 in "suite test: committed past the budget"?', '["It is no overrun, since a variance is booked only once actuals are recorded.", "The engine leaves an entry with no spend out of the EAC until money is spent.", "Nothing, since both lines forecast the larger of budget and actual plus commitment.", "It rests on a typed judgment with nothing spent, while 130.0000 is money already spent and promised."]'::jsonb, 3, 'The first returns variance -40.0000 on an entry of 140 alone; the second has 70 spent and 60 committed, which pass the budget of 100 and give -30.0000.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 9, 'The published line "negative entered forecast is ignored (the S-curve ignores it too)" has a budget of 100, 20 spent and an entered forecast of -50. Why does it forecast 100.0000?', '["The engine refuses the -50 with a message naming the line and restores the budget, as it does for a negative progress figure.", "The -50 is booked as a saving, and the variance is then clamped at 0.0000.", "-50 is not positive, so the rule compares the budget of 100 with the 20 spent and takes the larger.", "The engine reads the minus sign as a typing slip and uses 50, then floors the forecast of that line at its budget of 100."]'::jsonb, 2, 'Ignored is not refused: nothing on the screen says the -50 was never used, and the line returns EAC 100.0000 and variance 0.0000.'::text, 'The published line "negative entered forecast is ignored (the S-curve ignores it too)" has a budget of 100, 20 spent and an entered forecast of -50. Why does it forecast 100.0000?', '["The engine refuses the -50 with a message naming the line and restores the budget, as it does for a negative progress figure.", "The -50 is booked as a saving, and the variance is then clamped at 0.0000.", "-50 is not positive, so the rule compares the budget of 100 with the 20 spent and takes the larger.", "The engine reads the minus sign as a typing slip and uses 50, then floors the forecast of that line at its budget of 100."]'::jsonb, 2, 'Ignored and flagged: the line returns EAC 100.0000 and variance 0.0000, carries forecastIgnored "negative", and the AFE counts it in linesForecastIgnored.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 10, 'CMP-05 forecasts 5600000. Can a reviewer tell from that whether its forecast field is blank, 0 or negative?', '["No, since none of the three is positive and each falls back to the same 5600000 without a word.", "Yes, since a negative forecast is refused with a message and a blank is not.", "Yes, since a zero forecast drops the line from the EAC and a blank does not.", "Yes, since the rule used column prints entered for any figure typed into the forecast field, whatever the sign of that figure."]'::jsonb, 0, '"Not yet estimated", "cancel this work" and a typing slip produce one forecast: the larger of 5600000 and the 1200000 spent and committed.'::text, 'CMP-05 forecasts 5600000. Can a reviewer tell whether its forecast field is blank, 0 or negative?', '["Partly: all three forecast the same 5600000, but a negative entry carries forecastIgnored \"negative\", while blank and 0 carry no flag.", "Yes, since a negative forecast is refused with a message and a blank is not.", "Yes, since a zero forecast drops the line from the EAC and a blank does not.", "Yes, since the rule used column prints entered for any figure typed into the forecast field, whatever the sign of that figure."]'::jsonb, 0, 'None of the three is positive, so each falls back to the larger of 5600000 and the 1200000 spent and committed. Blank and 0 mean no forecast was entered; a negative figure is replaced and flagged.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 11, 'Had CSG-02''s budget of 3900000 been copied into its forecast field, as editing a line did before EC5-0, what would the line report?', '["4300000 and -400000, since entries are floored at the money spent.", "A refusal, since an entry below the actual of 4300000 is rejected.", "A forecast of 3900000 and a variance of 0, hiding the 400000 overrun already spent.", "4300000 and -400000, since a forecast equal to its budget is ignored."]'::jsonb, 2, 'A copied budget is a positive entered forecast and wins; the repaired Suite no longer copies it, but a figure copied by hand does the same damage.'::text, 'Had CSG-02''s budget of 3900000 been typed into its forecast field, what would the line report?', '["4300000 and -400000, since entries are floored at the money spent.", "A refusal, since an entry below the actual of 4300000 is rejected.", "A forecast of 3900000 and a variance of 0, hiding the 400000 overrun already spent.", "4300000 and -400000, since a forecast equal to its budget is ignored."]'::jsonb, 2, 'A typed budget is a positive entered forecast and wins. The engine flags the line forecastBelowCommitted by 400000, but the forecast and the EAC carry 3900000.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 12, 'Before EC5-0 the Cost Breakdown table showed the budget as the forecast and the PDF and Excel variance was budget less actual. What does the repaired Suite show on OFON-1?', '["27050000 as the table''s forecast, since it shows what was authorised.", "27600000 and -550000 on the tiles, the table, both exports and the Top 5, all from the one rule.", "The one rule on screen, while the PDF and Excel exports keep budget less actual so that earlier issued reports still reconcile.", "27600000 on the tiles and table, while the Top 5 keeps its own old rule."]'::jsonb, 1, 'After the Suite repair the tiles, Cost Breakdown table, PDF, Excel and Top 5 read one rule, so a disagreement between two reports points at the data or the export date.'::text, 'Which forecast figures does the Suite show for OFON-1 across the dashboard tiles, the Cost Breakdown table, the PDF and Excel exports and the Top 5?', '["27050000 as the table''s forecast, since it shows what was authorised.", "27600000 and -550000 on the tiles, the table, both exports and the Top 5, all from the one rule.", "The one rule on screen, while the PDF and Excel exports print budget less actual so that earlier issued reports still reconcile.", "27600000 on the tiles and table, while the Top 5 reads budget less actual."]'::jsonb, 1, 'The tiles, Cost Breakdown table, PDF, Excel and Top 5 read one rule, so a disagreement between two reports points at the data or the export date.'::text),
      ('intermediate', 'module', 'm02-one-forecast-rule'::text, 13, 'Every repaired screen now reads the one forecast rule. What has that fixed, and what has it left alone?', '["It fixed the forecast, which now extrapolates from progress and CPI.", "Nothing, since every old screen already showed 27600000.", "It made the rule stricter, refusing a forecast below the spend.", "It makes the screens agree, and every screen still shares the rule''s limits."]'::jsonb, 3, 'No screen forecasts a line under its budget without an entered forecast, and none reads progress, CPI or a non-positive entry, so OFON-1''s EAC is still 27600000.'::text, 'Every screen reads the one forecast rule. What does that settle, and what does it leave alone?', '["It makes each screen extrapolate the forecast from progress and CPI.", "Nothing, since each report still sets its own forecast rule.", "It made the rule stricter, refusing a forecast below the spend.", "It makes the screens agree, and every screen still shares the rule''s limits."]'::jsonb, 3, 'No screen forecasts a line under its budget without an entered forecast, and none reads progress, CPI or a non-positive entry as a forecast, so OFON-1''s EAC is 27600000 on every screen.'::text),
      ('intermediate', 'module', 'm03-earned-value'::text, 4, '"progress beyond 100 percent earns beyond the budget" returns earned value 150.0000 against actuals of 90.0000 and CPI 1.666667. What does that CPI record?', '["Progress typed past 100 percent, which the engine accepts and which earns beyond the budget without a dollar saved.", "A genuine saving, since 150.0000 over 90.0000 is exact arithmetic on the line''s own earned value and actuals.", "A clamp, since the engine caps progress at 100 percent and 1.666667 is the index it reports at that cap.", "An inverted index, actuals over earned value, which the engine switches to once progress passes 100 percent."]'::jsonb, 0, 'The refusal message says progress runs from 0 to 100 percent, yet only negative progress is refused; the same case reports SPI 1.500000 from the same typing.'::text, '"progress of exactly 100 percent is accepted and earns the whole budget" returns earned value 140.0000 against actuals of 100.0000 and CPI 1.400000. What does that CPI record?', '["Work earned at its budgeted value set against the money spent: a line typed at 100 percent earns its whole budget, however the work was really done.", "A genuine saving proved by the arithmetic, since 140.0000 over 100.0000 is exact and progress cannot be typed wrongly at 100 percent.", "A clamp, since the engine caps progress at 100 percent and 1.400000 is the index it reports at that cap.", "An inverted index, actuals over earned value, which the engine switches to once a line reaches 100 percent."]'::jsonb, 0, 'Progress of exactly 100 is accepted and earns the whole budget; above 100 is refused, naming the line. The same case reports SPI 1.000000 from the same typing.'::text),
      ('intermediate', 'module', 'm03-earned-value'::text, 7, '"suite test: weighted earned value" reports CPI 1.000000 with 110.0000 earned and nothing spent. How should that CPI be read?', '["As work bought at exactly its budget, one for one.", "As undefined: with actuals of 0 the engine returns 1 whatever has been earned.", "As infinity clamped to 1, the largest index the engine reports.", "As a null that the screens print as 1.000000 in place of a blank."]'::jsonb, 1, 'CPI 1 before any spend is a finding left unrepaired; the same case reports SPI 0.275000, a real ratio of earned value to planned value, beside a CPI that is only a default.'::text, '"suite test: weighted earned value (value earned, nothing spent: CPI null)" has 110.0000 earned and nothing spent. What CPI does the engine report?', '["1.000000, work bought at exactly its budget, one for one, which is the neutral reading when nothing has yet been spent.", "Null, with cpiStatus \"no-spend\": with actuals of 0 there is no cost efficiency to report.", "Infinity clamped to 1, since 110.0000 over nothing has no finite value and 1 is the largest index the engine reports.", "0, since no money has yet bought any of the work, so the earned value is set against a spend of nothing."]'::jsonb, 1, 'With actuals of 0 there is nothing to divide by, so the engine prints no CPI and names the reason; beside it the case still reports SPI 0.275000 with status ok, earned value over planned value.'::text),
      ('intermediate', 'module', 'm03-earned-value'::text, 8, '"suite test: empty AFE" has nothing budgeted, earned or spent and returns CPI 1.000000 and SPI 1.000000. Where does each 1 come from?', '["Both are measurements: an empty AFE has done all its scope, on budget and on time.", "CPI from the default for zero actuals, and SPI from a zero-budget guard that fires before the null rule.", "Both come from the zero-actuals default, which the engine applies to every index once nothing at all has been spent.", "SPI from time progress falling back to 1 on an AFE without dates, and CPI from 0 over 0 being read as exactly 1."]'::jsonb, 1, 'Where planned value is zero SPI is null, except that an AFE whose budget is 0 reports SPI 1 because its guard is checked first; neither 1 is a reading of performance.'::text, '"suite test: empty AFE: no budget and no spend, so SPI and CPI are null" has nothing budgeted, earned or spent. Why is each ratio null?', '["Both are measurements: an empty AFE has done all its scope, on budget and on time, and null is how the engine prints a perfect score.", "CPI for want of spend, cpiStatus \"no-spend\", and SPI for want of a budget, spiStatus \"no-budget\".", "Both come from one zero-actuals guard, which the engine applies to every index once nothing at all has been spent.", "SPI because time progress falls back to 1 on an AFE without dates, and CPI because 0 over 0 is read as exactly 1 and then hidden."]'::jsonb, 1, 'Each null carries its reason: cpiStatus "no-spend" when nothing has been spent, spiStatus "no-budget" when the AFE has no budget. A reported ratio carries "ok".'::text),
      ('intermediate', 'module', 'm03-earned-value'::text, 11, 'As of 2027-02-01, the start day, OFON-1 has already earned 15231500 by its figures. What SPI does the engine report?', '["1, since a zero denominator gives 1, as CPI does before any spend.", "0.563087, since time progress falls back to 1 when no day has elapsed.", "Null, since no whole day has elapsed, planned value is 0 and there is nothing to divide by.", "Infinity, earned value over a planned value of 0, far ahead of schedule."]'::jsonb, 2, 'SPI is null before the start and on the start day; before EC5-0 the engine reported Infinity before the start date when value had been earned, and a report that prints the null as 0 or 1 has made one up.'::text, 'As of 2027-02-01, the start day, OFON-1 has already earned 15231500 by its figures. What SPI does the engine report?', '["1, since a zero denominator gives a neutral ratio of 1 in place of a division.", "0.563087, since time progress falls back to 1 when no day has elapsed.", "Null, since no whole day has elapsed, planned value is 0 and there is nothing to divide by.", "Infinity, earned value over a planned value of 0, far ahead of schedule."]'::jsonb, 2, 'SPI is null with spiStatus "no-planned-value" before the start and on the start day, and a report that prints the null as 0 or 1 has made one up.'::text),
      ('intermediate', 'module', 'm03-earned-value'::text, 13, 'OFON-1''s lines, saved through the pre-EC5-0 wizard that took no window dates, are reported on 2027-06-30. Which SPI does that old report print?', '["Null on every day, since with no window the engine could not form a planned value and declined to divide.", "0.563087, percent complete over 100, because time progress fell back to 1 on every day of the AFE''s life.", "1.141290, since the engine took the first invoice date, 2027-02-20, as the start of the missing window.", "0.872063, since the engine read the clock and applied the fallback only to the days before any start date."]'::jsonb, 1, 'The published "no dates: time progress 1" case still records the fallback; with the whole budget planned every day, SPI said nothing about the calendar.'::text, 'OFON-1''s lines are saved with no window dates and reported on 2027-06-30. Which SPI does that report print?', '["Null on every day, since with no window the engine cannot form a planned value and declines to divide.", "0.563087, percent complete over 100, because time progress falls back to 1 on every day of the AFE''s life.", "1.141290, since the engine takes the first invoice date, 2027-02-20, as the start of the missing window.", "0.872063, since the engine reads the clock and applies the fallback only to the days before any start date."]'::jsonb, 1, 'The published "no dates: time progress 1" case records the fallback; with the whole budget planned every day, SPI says nothing about the calendar, and the Suite labels it unavailable.'::text),
      ('intermediate', 'module', 'm04-the-as-of-date'::text, 3, 'OFON-1''s window opens on 2027-02-01. What SPI does the repaired engine report as of 2027-02-01 itself?', '["1.000000, because on the start day the job is exactly on schedule.", "Infinity, because earned value of 15231500 is divided by a planned value of 0 and the division is carried out as written.", "Null, because no whole day has elapsed on the start day, so time progress and planned value are both 0.", "0.563087, because a report on the boundary of the window falls back to percent complete divided by 100 as a report with no window does."]'::jsonb, 2, 'The start day reads exactly as the day before the start: time progress 0.000000, planned value 0, SPI null. Planned value first appears on the day after the start.'::text, 'OFON-1''s window opens on 2027-02-01. Which schedule reading does a report dated that very day carry?', '["1.000000, because on the start day the job is exactly on schedule.", "Infinity, because earned value of 15231500 is divided by a planned value of 0 and the division is carried out as written.", "Null, because no whole day has elapsed on the start day, so time progress and planned value are both 0.", "0.563087, because a report on the boundary of the window falls back to percent complete divided by 100 as a report with no window does."]'::jsonb, 2, 'The start day reads exactly as the day before the start: time progress 0.000000, planned value 0, SPI null. Planned value first appears on the day after the start.'::text),
      ('intermediate', 'module', 'm04-the-as-of-date'::text, 9, 'As of 2028-01-10, after OFON-1''s window closed on 2027-11-30, SPI is 0.563087. What does that number measure?', '["Schedule pace against the window, which will keep falling on each later report as the AFE runs further past its end date and the plan keeps growing.", "Earned value over the whole budget, which is percent complete 56.3087 divided by 100, so it no longer measures pace against a plan.", "Earned value over the EAC of 27600000, since after the end the plan is replaced by the forecast of what the work will cost.", "The average of the SPIs reported across the window, which the engine carries forward once no further planned value accrues."]'::jsonb, 1, 'From the end day planned value is 27050000 on every date, so 15231500 over 27050000 reads 0.563087 until somebody changes progress on the lines.'::text, 'As of 2028-01-10, after OFON-1''s window closed on 2027-11-30, SPI is 0.563087. What does that number measure?', '["Schedule pace against the window, which will keep falling on each later report as the AFE runs further past its end date and the plan keeps growing.", "Earned value over the whole budget, which is percent complete 56.3087 divided by 100, so it has stopped measuring pace against a plan.", "Earned value over the EAC of 27600000, since after the end the plan is replaced by the forecast of what the work will cost.", "The average of the SPIs reported across the window, which the engine carries forward once no further planned value accrues."]'::jsonb, 1, 'From the end day planned value is 27050000 on every date, so 15231500 over 27050000 reads 0.563087 until somebody changes progress on the lines.'::text),
      ('intermediate', 'module', 'm04-the-as-of-date'::text, 11, 'The published case with no window dates returns time progress 1.000000 and SPI 0.250000. What does the engine do with an AFE saved without a window?', '["Refuses it with AfeInputError, because planned value cannot be formed without a start date and an end date.", "Reports SPI null, as it does before the start, because with no window no day has elapsed inside it.", "Reports it as though the window had already ended, dividing earned value by the whole budget, a fallback EC5-0 did not change.", "Measures it against today, treating the report date as the end of the window so that time progress is always 1 on the day it runs."]'::jsonb, 2, 'The fallback to time progress 1 remains in the engine as published, and the repaired Suite labels SPI unavailable for such an AFE; a low SPI there is not a late project.'::text, 'The published case with no window dates returns time progress 1.000000 and SPI 0.250000. What does the engine do with an AFE saved without a window?', '["Refuses it with AfeInputError, because planned value cannot be formed without a start date and an end date.", "Reports SPI null, as it does before the start, because with no window no day has elapsed inside it.", "Reports it as though the window had already ended, dividing earned value by the whole budget, and the Suite labels its SPI unavailable.", "Measures it against today, treating the report date as the end of the window so that time progress is always 1 on the day it runs."]'::jsonb, 2, 'Time progress falls back to 1 on an AFE without both dates, so a low SPI there is not a late project; the Suite labels SPI "Unavailable" for such an AFE.'::text),
      ('intermediate', 'module', 'm04-the-as-of-date'::text, 13, 'Before EC5-0 the AFE wizard asked for no dates. What SPI would a report on OFON-1 have shown on its first day of drilling?', '["Null, because a report on the first day of drilling falls on the start of the window, where no whole day has elapsed.", "Infinity, because the old engine divided earned value by a planned value of 0 whenever it was run before the plan had grown.", "1.141290, because the old engine read the clock and the first day of drilling came early in the window, where the plan was small.", "0.563087, the same as on its last day."]'::jsonb, 3, 'With no window, time progress fell back to 1, so SPI equalled percent complete 56.3087 divided by 100 on whatever day the report was opened.'::text, 'OFON-1''s lines are saved on an AFE with no window dates. What SPI does a report show on the first day of drilling?', '["Null, because a report on the first day of drilling falls on the start of the window, where no whole day has elapsed.", "Infinity, because the engine divides earned value by a planned value of 0 whenever it is run before the plan has grown.", "1.141290, because the engine reads the clock and the first day of drilling comes early in the window, where the plan is small.", "0.563087, the same as on its last day."]'::jsonb, 3, 'With no window, time progress falls back to 1, so SPI equals percent complete 56.3087 divided by 100 on whatever day the report is opened; the Suite labels it unavailable.'::text),
      ('intermediate', 'module', 'm04-the-as-of-date'::text, 15, 'A report dated 2027-01-15, before OFON-1''s window opens, shows earned value 15231500 from DRL-01 at 72.0000 percent and CSG-02 at 100.0000 percent. What does the engine make of that?', '["It sets earned value to 0 before the start, since work cannot be earned before a window opens, and reports CPI null beside it.", "It reports it without complaint, since it never asks whether progress is plausible for the date, so the reader must suspect the window or the progress column.", "It flags the AFE invalid, since earned value above planned value of 0 is the case the EC5-0 repair was written to catch.", "It reports SPI null and zeroes the progress it cannot schedule, leaving only CSG-02''s finished line in earned value."]'::jsonb, 1, 'Before the start SPI is null, but earned value 15231500, CPI 1.009377 and the EAC of 27600000 are all still reported, because they are read from the lines and not from the calendar.'::text, 'A report dated 2027-01-15, before OFON-1''s window opens, shows earned value 15231500 from DRL-01 at 72.0000 percent and CSG-02 at 100.0000 percent. What does the engine make of that?', '["It sets earned value to 0 before the start, since work cannot be earned before a window opens, and reports CPI null beside it.", "It reports it without complaint, since it never asks whether progress is plausible for the date, so the reader must suspect the window or the progress column.", "It flags the AFE invalid, since earned value above a planned value of 0 is a combination the engine refuses to report.", "It reports SPI null and zeroes the progress it cannot schedule, leaving only CSG-02''s finished line in earned value."]'::jsonb, 1, 'Before the start SPI is null, but earned value 15231500, CPI 1.009377 and the EAC of 27600000 are all still reported, because they are read from the lines and the calendar plays no part in them.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 6, 'At OFON-1''s Aug 27 point the Actual is 15090000 and the Planned is 16212086. A reader calls the gap "behind schedule". What is the gap?', '["Earned value below planned value on the day of the point, which is the curve''s plot of SPI in money rather than as a ratio at each of the monthly buckets it draws.", "Commitments not yet invoiced, which the Actual line holds back until billing and which the Planned line already includes.", "Spend below a straight budget line, a cost comparison with no progress in it; the schedule measure is SPI 0.872063, earned value over planned value.", "Schedule slippage in money, since planned value and actual cost measured on the same day together form the schedule variance that the curve plots at every point."]'::jsonb, 2, 'SPI divides earned value, 15231500 from the progress column, by planned value; the curve never plots earned value, so no gap on it is a schedule reading.'::text, 'At OFON-1''s Aug 27 point the Actual is 15090000 and the Planned is 16212086. A reader calls the gap "behind schedule". What is the gap?', '["Earned value below planned value on the day of the point, which is the curve''s plot of SPI in money in place of a ratio at each of the monthly buckets it draws.", "Commitments not yet invoiced, which the Actual line holds back until billing and which the Planned line already includes.", "Spend below a straight budget line, a cost comparison with no progress in it; the schedule measure is SPI 0.872063, earned value over planned value.", "Schedule slippage in money, since planned value and actual cost measured on the same day together form the schedule variance that the curve plots at every point."]'::jsonb, 2, 'SPI divides earned value, 15231500 from the progress column, by planned value; the curve never plots earned value, so no gap on it is a schedule reading.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 7, 'On a live AFE the cost lines'' actuals total more than the S-curve''s last Actual at or before the as-of date. What is each describing?', '["Percent spent and CPI describe the actuals typed on the lines, the Actual line describes the dated invoices, and nothing on the screen says which is which, so the difference is a question about accruals, billing or a missing date.", "The same money on two schedules, since the curve converts line actuals into invoices by date and the gap is spend not yet reached by a bucket.", "An error in the engine, since it forces the invoices to match the lines and a gap can only mean the curve was drawn before a repair.", "Commitments, since the lines carry actual plus commitment and the curve carries the actual alone, and the gap is what is on order."]'::jsonb, 0, 'The metrics sum the actual column and the S-curve sums invoices; on OFON-1 both read 15090000 because the teaching field was written to match, which teaches the wrong habit.'::text, 'On a live AFE the cost lines'' actuals total more than the S-curve''s last Actual at or before the as-of date. What is each describing?', '["Percent spent and CPI describe the actuals typed on the lines, the Actual line describes the dated invoices, and nothing on the screen says which is which, so the difference is a question about accruals, billing or a missing date.", "The same money on two schedules, since the curve converts line actuals into invoices by date and the gap is spend not yet reached by a bucket.", "An error in the engine, since it forces the invoices to match the lines and a gap can only mean the curve was drawn from stale data.", "Commitments, since the lines carry actual plus commitment and the curve carries the actual alone, and the gap is what is on order."]'::jsonb, 0, 'The metrics sum the actual column and the S-curve sums invoices; on OFON-1 both read 15090000 because the teaching field was written to match, which teaches the wrong habit.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 8, 'A published case bills two invoices over a past window: 100 with no date field and 200 whose date is null. The first and last points both read an Actual of 0. What happened to each invoice?', '["The null date was read as a day in 1970 and counted in every bucket of the curve, while the invoice with no date field never counted at all.", "The engine refused the missing field and dropped that invoice with a warning, while it booked the null date at the start of the window as an opening balance.", "Both counted on the as-of date, the only day an undated invoice can take.", "Neither could be dated, so neither reached the curve, and the engine reported 2 undated invoices beside it."]'::jsonb, 3, 'An invoice the engine cannot date reaches no bucket, however its date is missing; the count of undated invoices, 2 here, is reported beside the curve so the money is named rather than dropped in silence.'::text, 'A published case bills two invoices over a past window: 100 with no date field and 200 whose date is null. The first and last points both read an Actual of 0. What happened to each invoice?', '["The null date was read as a day in 1970 and counted in every bucket of the curve, while the invoice with no date field never counted at all.", "The engine refused the missing field and dropped that invoice with a warning, while it booked the null date at the start of the window as an opening balance.", "Both counted on the as-of date, the only day an undated invoice can take.", "Neither could be dated, so neither reached the curve, and the engine reported 2 undated invoices beside it."]'::jsonb, 3, 'An invoice the engine cannot date reaches no bucket, however its date is missing; the count of undated invoices, 2 here, is reported beside the curve so the money is named.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 11, 'Before EC5-0, editing a line in the Suite copied its budget into its forecast. What would that have done to CSG-02 and to OFON-1''s Forecast line?', '["The copy is a positive entered forecast, so the rule takes 3900000 whatever CSG-02 has spent, hiding its line variance of -400000 and settling the Forecast line toward the Planned line.", "Nothing to CSG-02, because the rule compares an entered forecast with actual plus commitment and keeps the larger 4300000.", "It would have raised CSG-02''s forecast to its actual, since a copied budget is recognised as a default and ignored by the rule.", "It would have removed CSG-02 from the EAC, since a forecast equal to the budget carries no variance and the line drops out."]'::jsonb, 0, 'An entered forecast that is positive wins under the one rule, so a copied 3900000 replaces the 4300000 already spent; the repaired app no longer copies.'::text, 'Suppose CSG-02''s budget were typed into its forecast field. What would that do to CSG-02 and to OFON-1''s Forecast line?', '["The copy is a positive entered forecast, so the rule takes 3900000 whatever CSG-02 has spent, hiding its line variance of -400000 and settling the Forecast line toward the Planned line.", "Nothing to CSG-02, because the rule compares an entered forecast with actual plus commitment and keeps the larger 4300000.", "It would have raised CSG-02''s forecast to its actual, since a copied budget is recognised as a default and ignored by the rule.", "It would have removed CSG-02 from the EAC, since a forecast equal to the budget carries no variance and the line drops out."]'::jsonb, 0, 'A positive entered forecast wins under the one rule, so a typed 3900000 replaces the 4300000 already spent in the EAC; the engine flags the line forecastBelowCommitted, but the forecast stands.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 12, 'OFON-1''s last Planned point, Nov 27, is 24452483 against a budget of 27050000. Does the engine''s planned value itself stop short of the budget?', '["Yes, because the curve spreads the budget over the months before the end month and leaves the final month for contingency that is never planned.", "Yes, because the engine deducts the 2597517 held for the month the as-of date falls in, and releases it once a later report is run.", "No, because the curve rescales its last point to the budget when the chart is drawn, and 24452483 is only the value in the underlying table.", "No. The curve has no point on the end day; the metrics show 27050000 there."]'::jsonb, 3, 'The walk steps from 2027-02-01 by whole months; the next step, the first of December, falls after 2027-11-30, so the chart stops 2597517 short, a property the EC5-0 repair left in place.'::text, 'OFON-1''s Nov 27 point plans 24452483 against a budget of 27050000. Does the S-curve''s plan stop short of the budget?', '["Yes, because the curve spreads the budget over the months before the end month and leaves the final month for contingency that is never planned.", "Yes, because the engine deducts the 2597517 held for the month the as-of date falls in, and releases it once a later report is run.", "No, because the curve rescales its last point to the budget when the chart is drawn, and 24452483 is only the value in the underlying table.", "No. Nov 27 is only the last monthly point; the closing point \"30 Nov 27\" carries Planned 27050000, as the metrics do on the end day."]'::jsonb, 3, 'The walk steps from 2027-02-01 by whole months; the next step falls after 2027-11-30, so the curve closes on a point dated the end, adding the last 2597517 of plan.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 13, 'A published window from 2090-01-01 to 2091-01-01 returns 13 points with a last Forecast of 2450, the whole EAC. Why does that curve reach its EAC when OFON-1''s last Forecast of 24949669 falls short of 27600000?', '["Its window lies in the future, so the whole curve is projection and a projected line always runs to the EAC, while OFON-1''s mixes actuals in.", "Its end date falls exactly on a monthly step, so a point stands on the end day; OFON-1''s end, 2027-11-30, is not on a step from 2027-02-01.", "It has no invoices, so no actuals hold the forecast back, while OFON-1''s four invoices pull its projected points below the EAC.", "It is thirteen months long, and the engine closes any window of more than a year on its end date, while OFON-1''s is shorter."]'::jsonb, 1, 'The published one-year window 2020-01-01 to 2020-12-31 stops short the same way as OFON-1, with 12 points and a last Planned of 1101, because its last step lands on the first of December.'::text, 'A published window from 2090-01-01 to 2091-01-01 returns 13 points ending "1 Jan 91", and OFON-1 returns 11 ending "30 Nov 27". Both last points carry the whole EAC. Why is there no separate monthly point on 2091-01-01?', '["Its window lies wholly in the future, so the whole curve is projection, and the engine drops any monthly point that would only repeat the EAC already printed beside it.", "Its end date falls exactly on a monthly step, so the closing point replaces that step and no date appears twice; OFON-1''s end is not on a step from 2027-02-01.", "It has no invoices, so no actual needs a point of its own, while OFON-1''s four invoices each hold a monthly point open.", "It is thirteen months long, and the engine merges the last two points of any window longer than a year so that a chart never carries more than thirteen labels."]'::jsonb, 1, 'Every curve closes on a point dated the window end with Planned the budget and Forecast the EAC. When a monthly step lands on the end, the closing point takes its place; OFON-1''s steps land on the first of each month, so Nov 27 is followed by "30 Nov 27".'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 14, 'The course draws OFON-1''s first point as "Feb 27" with the timezone pinned to UTC. Drawn in America/Los_Angeles, the same AFE labels its first point "Jan 27" and every Planned value shifts. Why (finding EC5-5)?', '["The Suite converts AFE money into the viewer''s local currency, which rescales the Planned line and relabels the buckets.", "The Planned line is recomputed from today''s date in the viewer''s timezone, so a Pacific viewer sees a later as-of date.", "The engine parses the window as UTC midnight but steps months and prints labels in local time, so west of UTC the start lands on the previous evening.", "Invoices are stored in local time, and in Los Angeles the first invoice moves into January and carries the label with it, along with every Planned value that follows."]'::jsonb, 2, 'The metrics are unaffected, and Lagos, Tokyo and UTC agree with the course''s table; a curve compared across offices can disagree on every Planned point.'::text, 'The course draws OFON-1''s first point as "Feb 27". A viewer in America/Los_Angeles opens the same AFE. What does the curve show there?', '["The same amounts relabelled, since the Suite converts the month labels into the viewer''s local calendar before drawing them.", "A later as-of date, since the Planned line is recomputed from today''s date in the viewer''s time zone.", "The same curve: the window, the as-of date, the monthly step, the day count and every label are read in UTC, so the first point is \"Feb 27\" there too.", "A first point labelled \"Jan 27\" and every Planned value shifted, since the window is parsed at midnight and west of UTC that midnight falls on the previous evening."]'::jsonb, 2, 'The S-curve is read in UTC, so every zone draws what a UTC machine draws; the published February-start case labels its first point "Feb 27" in every zone, and OFON-1''s Mar 27 plans 2507947 everywhere.'::text),
      ('intermediate', 'module', 'm05-the-s-curve'::text, 15, 'Before EC5-0 a 2020 AFE drew 81 points on 2026-09-14 and gained one a month. What did the repair change, and what did it leave?', '["It now closes the curve on the as-of date, so an AFE read after its end draws no points beyond the day of the report.", "It now adds a final point on the end day, so the last Planned value of every curve equals the budget of the AFE.", "It now limits the curve to twelve points, the length of the longest window the Suite''s wizard accepts for an AFE.", "The walk now stops at the end date; the plan stopping short of the budget was not repaired."]'::jsonb, 3, 'The repaired curve for the published window 2020-01-01 to 2020-12-31 has 12 points ending at Dec 20 with a last Planned of 1101, still short of its budget of 1200.'::text, 'The published window 2020-01-01 to 2020-12-31 with two invoices returns 13 points. Where does the curve end, and what does its last point carry?', '["On the as-of date, so a window read after its end draws no point beyond the day of the report.", "On the last monthly step, \"Dec 20\", which stands on the first of December, with Planned short of the budget of 1200 by the whole plan for December.", "On the twelfth monthly point, since the engine limits every curve to twelve points whatever the window length.", "On a closing point \"31 Dec 20\" dated the window end, with Planned 1200, the budget, and Actual 350 from the invoices to that day."]'::jsonb, 3, 'Twelve monthly points from 2020-01-01 are followed by a closing point dated the end, windowEnd true, with Planned 1200 and Forecast 1200; its Actual counts the invoices dated on or before the end, 350.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 1, 'A graded reading of OFON-1 is worked with every calculation right, but the explorer was left on its default as-of date of today instead of 2027-08-15. Which of its metric readings are wrong?', '["Every number that depends on the lines, since the explorer recomputes earned value and the EAC for the date it is set to.", "Earned value, CPI and SPI, since all three divide by a figure the engine reads on the day the report is run.", "None, since the dashboard passes today as the as-of date and a report run today is the current reading of the AFE.", "Only time progress, planned value and SPI."]'::jsonb, 3, 'EAC 27600000, variance -550000, earned value 15231500 and CPI 1.009377 are identical at every date, so the answer looks complete while its SPI answers a different question from 0.872063.'::text, 'A graded reading of OFON-1 is worked with every calculation right, but the explorer was left on its default as-of date of today when the task named 2027-08-15. Which of its metric readings are wrong?', '["Every number that depends on the lines, since the explorer recomputes earned value and the EAC for the date it is set to.", "Earned value, CPI and SPI, since all three divide by a figure the engine reads on the day the report is run.", "None, since the dashboard passes today as the as-of date and a report run today is the current reading of the AFE.", "Only time progress, planned value and SPI."]'::jsonb, 3, 'EAC 27600000, variance -550000, earned value 15231500 and CPI 1.009377 are identical at every date, so the answer looks complete while its SPI answers a different question from 0.872063.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 4, 'With CMT-03''s budget of 1250000 and the 940000 already spent and committed, an entered forecast of 900000 gives an item forecast of 900000, and an entered forecast of 0 gives 1250000. What does the pair show?', '["The rule floors an entered forecast at the spend plus commitment, and 900000 passed only because it is within tolerance of 940000.", "The rule treats 0 as a request to close the line at budget and 900000 as a request to cut scope, so both are honoured.", "Any positive entered forecast is taken as typed, even one below the money already spent and committed (finding EC5-1), while 0 is not positive and falls back to the larger of budget and spend plus commitment.", "The rule reads 900000 as a saving to be booked against the budget, which is why the variance on that line becomes positive at once."]'::jsonb, 2, 'The same line with an entered forecast of 1 forecasts 1, so a typing slip passes straight into the EAC, and a forecast of 0 meant as a descope saves nothing on the report.'::text, 'With CMT-03''s budget of 1250000 and the 940000 already spent and committed, an entered forecast of 900000 gives an item forecast of 900000, and an entered forecast of 0 gives 1250000. What does the pair show?', '["The rule floors an entered forecast at the spend plus commitment, and 900000 passed only because it is within tolerance of 940000.", "The rule treats 0 as a request to close the line at budget and 900000 as a request to cut scope, so both are honoured.", "Any positive entered forecast is taken as typed, even one below the money already spent and committed, where it is flagged, while 0 is not positive and falls back to the larger of budget and spend plus commitment.", "The rule reads 900000 as a saving to be booked against the budget, which is why the variance on that line becomes positive at once."]'::jsonb, 2, 'Positive entries are trusted and marked when they undercut the money already out the door; a zero is no entry, so a descope typed as 0 saves nothing on the report.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 8, 'The published weighted earned value case reports earned value 110.0000, actuals 0.0000 and CPI 1.000000. How should a reader take that CPI?', '["As on budget, since the work earned was delivered for nothing and an index of 1 is the cost neutral reading that the engine reports.", "As a refusal marker standing in for null.", "As the ratio of earned value to planned value, since with no spend the engine substitutes the schedule index for the cost index on that AFE.", "As undefined: the engine returns CPI 1 whenever actuals are 0."]'::jsonb, 3, 'The finding is recorded and not repaired, so CPI 1.000000 beside any earned value with no spend, 110.0000 here, is a division the engine declined to do and printed as a neutral number.'::text, 'OFON-1 is re-entered with every actual set to 0 and its progress unchanged, so earned value stays at 15231500. What does the report print for CPI?', '["1.000000, on budget, since work earned for nothing is read as the cost-neutral index the engine falls back to.", "Infinity, since 15231500 over a spend of 0 has no finite value and the engine prints the division as it stands.", "The SPI in its place, since with no spend the engine substitutes the schedule index for the cost index on that AFE.", "No ratio: CPI is null with cpiStatus \"no-spend\", and the CPI tile reads N/A with \"Nothing spent yet, so no cost efficiency\"."]'::jsonb, 3, 'Value earned with nothing spent has no cost efficiency to report, so the engine returns null and names the reason; earned value itself is unchanged by the actuals.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 10, 'A reader takes OFON-1''s last Forecast point, 24949669, as the money the job will spend, and calls the rest of the EAC of 27600000 a saving. What went wrong?', '["The curve stops at its Nov 27 point, standing on the first of November, before the end of the window, so the EAC is read from the metrics and only the shape from the curve.", "The reader used the Forecast line where the Actual line applies, since past the as-of date the Actual line carries the committed spend to the end.", "The reader ignored the as-of date, since the last Forecast point moves up to the EAC once a report is run after the window''s end, when every projected point has become an actual.", "Nothing, since the projected line nets the entered forecasts against their budgets and the gap is the saving it has identified."]'::jsonb, 0, 'The last Planned point, 24452483, is short of the budget of 27050000 in the same way, a property of the engine as published; neither gap is money the job will not spend.'::text, 'A reader takes OFON-1''s Nov 27 Forecast, 24949669, as the money the job will spend, and calls the rest of the EAC of 27600000 a saving. What went wrong?', '["Nov 27 is only the last monthly point, standing on the first of November; the curve closes on \"30 Nov 27\", where Forecast is the EAC of 27600000.", "The reader used the Forecast line where the Actual line applies, since past the as-of date the Actual line carries the committed spend to the end.", "The reader ignored the as-of date, since the Forecast rises to the EAC only once a report is run after the window''s end, when every projected point has become an actual.", "Nothing, since the projected line nets the entered forecasts against their budgets and the gap is the saving it has identified."]'::jsonb, 0, 'The closing point dated the window end carries Forecast 27600000 and Planned 27050000; a reader who stops at the last monthly point sees neither the EAC nor the budget.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 12, 'Two exports of OFON-1 from the repaired Suite agree on an EAC of 27600000 but show different SPIs. Where should the check start?', '["At each line''s forecast field, since after EC5-0 the exports still apply different forecast rules and a copied budget changes SPI.", "At the invoices, since the S-curve feeds SPI and a late invoice moves the ratio in one export and not in the other.", "At the as-of date each export was run for.", "At the progress column, since progress is the only input SPI reads and the EAC agreeing proves the dates were the same."]'::jsonb, 2, 'After EC5-0 every screen shares one forecast rule, so the EAC agrees; SPI moves with the date, 1.141290 on 2027-06-30 and 0.872063 on 2027-08-15 on identical lines.'::text, 'Two exports of OFON-1 from the Suite agree on an EAC of 27600000 but show different SPIs. Where should the check start?', '["At each line''s forecast field, since the exports apply different forecast rules and a copied budget changes SPI.", "At the invoices, since the S-curve feeds SPI and a late invoice moves the ratio in one export and not in the other.", "At the as-of date each export was run for.", "At the progress column, since progress is the only input SPI reads and the EAC agreeing proves the dates were the same."]'::jsonb, 2, 'Every screen shares one forecast rule, so the EAC agrees; SPI moves with the date, 1.141290 on 2027-06-30 and 0.872063 on 2027-08-15 on identical lines.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 15, 'A capstone answer gives OFON-1''s planned value at the end of its window as 24452483, read off the last Planned point of the S-curve. Where should it have been read?', '["From the Forecast line''s last point, 24949669, since the plan at completion is the EAC once the AFE has overrun its budget.", "From the S-curve, which is the plan of record.", "From the metrics as of 2027-11-30, which give 27050000.", "From the metrics as of 2027-08-15, since planned value is fixed on the as-of date and is not carried to the end of the window."]'::jsonb, 2, 'The walk stops at the first of November because the next step falls after 2027-11-30, so the chart ends 2597517 short; on the end day time progress is 1 and planned value the whole budget.'::text, 'A capstone answer gives OFON-1''s planned value at the end of its window as 24452483, read off the Nov 27 point of the S-curve. Where should it have been read?', '["From the Forecast line''s last point, 24949669, since the plan at completion is the EAC once the AFE has overrun its budget.", "From the Nov 27 point, which is the plan of record for the whole window.", "From the metrics as of 2027-11-30, or the curve''s closing point \"30 Nov 27\", which both give 27050000.", "From the metrics as of 2027-08-15, since planned value is fixed on the as-of date and is not carried to the end of the window."]'::jsonb, 2, 'Nov 27 stands on the first of November; the curve closes on the end day, where time progress is 1 and planned value the whole budget, 2597517 more than the Nov 27 point.'::text),
      ('advanced', 'final', null::text, 1, 'A committee pack from before EC5-0 quotes -150.5560 as the P90 of a single exploration well that succeeds three times in ten, earns 300 on success and costs 50 on failure. What was wrong with that figure?', '["It was too optimistic, because a well failing 0.700000 of the time has a true low case further down than -150.5560.", "It lies beneath -50.0000, the worst outcome the well can produce, so it describes a loss no draw of this project can ever reach.", "Nothing of substance, because a low case below the worst outcome only adds a margin a committee reads as conservative.", "It carried the wrong label, because under the exceedance convention the low case of that well is its P10."]'::jsonb, 1, 'A risked project is success or a single failure point, and the bell smoothed that gap away; the simulation now returns P90 -50.0000, the failure itself.'::text, 'A committee pack built on a normal approximation quotes -150.5560 as the P90 of a single exploration well that succeeds three times in ten, earns 300 on success and costs 50 on failure. What is wrong with that figure?', '["It was too optimistic, because a well failing 0.700000 of the time has a true low case further down than -150.5560.", "It lies beneath -50.0000, the worst outcome the well can produce, so it describes a loss no draw of this project can ever reach.", "Nothing of substance, because a low case below the worst outcome only adds a margin a committee reads as conservative.", "It carried the wrong label, because under the exceedance convention the low case of that well is its P10."]'::jsonb, 1, 'A risked project is success or a single failure point, and the bell smooths that gap away; the simulation returns P90 -50.0000, the failure itself.'::text),
      ('advanced', 'final', null::text, 2, 'Across identical wildcats the old approximation understated P(loss) with three wells (0.276275 against an exact 0.343000) and overstated it with six (0.200464 against 0.117649). Why can no fixed margin repair the old figures?', '["The error shrinks steadily as wells are added, so a margin fitted on one well overcorrects every larger portfolio it is applied to.", "Only the P90 error changes sign between three and six wells, so a margin would repair the probabilities and leave the low cases wrong.", "The approximation turns exact once six wells are funded, so only smaller portfolios need a margin.", "The error changes sign as wells are added, so nothing tells a reviewer which way to lean on a given portfolio."]'::jsonb, 3, 'With eight wells it understated again, 0.166046 against 0.255298, so the direction of the error follows the lumps and not a trend.'::text, 'Across identical wildcats a normal approximation understates P(loss) with three wells (0.276275 against an exact 0.343000) and overstates it with six (0.200464 against 0.117649). Why can no fixed margin correct the normal figures?', '["The error shrinks steadily as wells are added, so a margin fitted on one well overcorrects every larger portfolio it is applied to.", "Only the P90 error changes sign between three and six wells, so a margin would repair the probabilities and leave the low cases wrong.", "The approximation turns exact once six wells are funded, so only smaller portfolios need a margin.", "The error changes sign as wells are added, so nothing tells a reviewer which way to lean on a given portfolio."]'::jsonb, 3, 'With eight wells it understates again, 0.166046 against 0.255298, so the direction of the error follows the lumps of the outcomes.'::text),
      ('advanced', 'final', null::text, 4, 'An analyst reruns OKONO''s 450.0000 set, the same OK-1, OK-3 and OK-4, at seed 20260829 and 10000 iterations, but enters them as OK-4, OK-3, OK-1. P(loss) no longer reads 0.123600. What happened?', '["Project order decides which project hears the shared drivers F1 and F2, so the reordered set was simulated under a different correlation.", "Entering OK-4 first made its fail cost the threshold for every draw, so losses were counted from another zero.", "The normals were dealt to the projects in a different order, so the same set at the same seed moved by sampling noise alone.", "A seeded run is meant to ignore how the list is typed, so a result that moves with the input order is a defect the repair left in place."]'::jsonb, 2, 'Each iteration draws F1, F2, then e1 and e2 per project in array order, so reproducing 0.123600 needs the seed, the iterations and the project order.'::text, 'An analyst reruns OKONO''s 450.0000 set, the same OK-1, OK-3 and OK-4, at seed 20260829 and 10000 iterations, but enters them as OK-4, OK-3, OK-1. P(loss) moves off 0.123600. What happened?', '["Project order decides which project hears the shared drivers F1 and F2, so the reordered set was simulated under a different correlation.", "Entering OK-4 first made its fail cost the threshold for every draw, so losses were counted from another zero.", "The normals were dealt to the projects in a different order, so the same set at the same seed moved by sampling noise alone.", "A seeded run is meant to ignore how the list is typed, so a result that moves with the input order is a defect in the engine."]'::jsonb, 2, 'Each iteration draws F1, F2, then e1 and e2 per project in array order, so reproducing 0.123600 needs the seed, the iterations and the project order.'::text),
      ('advanced', 'final', null::text, 7, 'On mixtureWithSpread the normal approximation put P90 at -12.4175 and the simulation reads 1.7148. What would a reader of the old figure have concluded wrongly?', '["That the low case loses money, when nine outcomes in ten are at or above a small gain.", "That -12.4175 was the very worst the portfolio could do, when the simulation shows its worst outcome is a gain of 1.7148.", "That the portfolio was lumpy, when a success spread makes the outcomes continuous and the old approximation exact on such a case.", "That the high case was a gain, when the committee should have read P10 first because it is the low case under exceedance."]'::jsonb, 0, 'The exact P90 outcome is 1.5838, so the sign of the low case changed with the model; the approximation was exact only on the pos1-normal cases.'::text, 'On mixtureWithSpread a normal approximation puts P90 at -12.4175 and the simulation reads 1.7148. What would a reader of the normal figure conclude wrongly?', '["That the low case loses money, when nine outcomes in ten are at or above a small gain.", "That -12.4175 was the very worst the portfolio could do, when the simulation shows its worst outcome is a gain of 1.7148.", "That the portfolio was lumpy, when a success spread makes the outcomes continuous and the normal approximation exact on such a case.", "That the high case was a gain, when the committee should have read P10 first because it is the low case under exceedance."]'::jsonb, 0, 'The exact P90 outcome is 1.5838, so the sign of the low case changed with the method; the normal approximation is exact only on the pos1-normal cases.'::text),
      ('advanced', 'final', null::text, 8, 'At rho 0.000000 OKONO''s 600.0000 set prints emv 402.7500 and stdDev 143.8374. A reviewer derives its low case as emv - 1.2816 x stdDev. Why does that disagree with the reported P90 of 200.3575?', '["The multiplier belongs to P10, so the low case needs emv plus 1.2816 x stdDev, and the reviewer has quoted the high tail.", "The repaired engine derives P90 from the closed-form stdDev only when rho is above 0, and at rho 0 it switches to a separate formula.", "That shortcut is the normal approximation EC5-0 retired, 218.4079 here, while the reported P90 is counted from simulated draws of success and failure.", "It does not disagree in substance, because at rho 0 the closed form and the simulation are the same model and the gap is sampling noise."]'::jsonb, 2, 'At 300.0000 the same shortcut gives 108.3959 against a simulated 100.7698; a bell on a risked set misses the low case in either direction.'::text, 'At rho 0.000000 OKONO''s 600.0000 set prints emv 402.7500 and stdDev 143.8374. A reviewer derives its low case as emv - 1.2816 x stdDev. Why does that disagree with the reported P90 of 200.3575?', '["The multiplier belongs to P10, so the low case needs emv plus 1.2816 x stdDev, and the reviewer has quoted the high tail.", "The engine derives P90 from the closed-form stdDev only when rho is above 0, and at rho 0 it switches to a separate formula.", "That shortcut is a normal approximation, 218.4079 here, while the reported P90 is counted from simulated draws of success and failure.", "It does not disagree in substance, because at rho 0 the closed form and the simulation are the same model and the gap is sampling noise."]'::jsonb, 2, 'At 300.0000 the shortcut also sits above the simulation, 108.3959 against 100.7698; at 450.0000 it falls the other way, -57.1494 against a simulated -18.3574. A bell on a risked set misses the low case in either direction.'::text),
      ('advanced', 'final', null::text, 16, 'In the Suite an analyst wants OKONO''s 600.0000 set at full dependence and drags the correlation slider to its top. What does the screen show?', '["The rho 1.000000 figures, because EC5-0 extended the slider to the engine''s full range when it replaced the normal approximation.", "An engine refusal, because the engine clamps correlation at 0.9 and throws for any value above it.", "The rho 0.900000 figures, stdDev 232.0795 and P(loss) 0.049500, because the slider stops at 0.9, an app item left unrepaired.", "The rho 1.000000 figures under a flag, since the slider''s top is labelled 0.9 but passes the clamped maximum of 1 through to the engine."]'::jsonb, 2, 'The engine accepts 1 and reads stdDev 239.8888 and P(loss) 0.059000 there; read the slider''s top as the app''s limit, never the engine''s.'::text, 'In the Suite an analyst wants OKONO''s 600.0000 set at full dependence and drags the correlation slider to its top. What does the screen show?', '["The rho 1.000000 figures, because the slider runs over the engine''s full range of correlation from 0 to 1.", "An engine refusal, because the engine clamps correlation at 0.9 and throws for any value above it.", "The rho 0.900000 figures, stdDev 232.0795 and P(loss) 0.049500, because the Suite''s slider stops at 0.9.", "The rho 1.000000 figures under a flag, since the slider''s top is labelled 0.9 but passes the clamped maximum of 1 through to the engine."]'::jsonb, 2, 'The engine accepts 1 and reads stdDev 239.8888 and P(loss) 0.059000 there; the slider''s top is the app''s limit on what can be set from the screen.'::text),
      ('advanced', 'final', null::text, 20, 'On the published split at 70 and 45 percent of a cost of 1000.00, the two partner amounts and the operator''s add back to 1000.00. What does that reconciliation prove?', '["That the allocation can be billed, because amounts that sum to the cost are how the engine defines valid.", "That the engine rescaled the interests to the whole before allocating, so the amounts come back to the cost.", "Nothing about the split, since the operator''s -150.00 restores the sum; valid false and the partner total of 115.00 percent catch it.", "That only the operator''s figure needs editing to 0 percent, after which the partners'' 700.00 and 450.00 can be billed as they stand."]'::jsonb, 2, 'The note says the interests total 115.00 percent and the operator share is negative; the fix is in the partner list, never in the computed operator figure.'::text, 'On the published split at 70 and 45 percent of a cost of 1000.00, the two partner amounts and the operator''s add back to 1000.00. What does that reconciliation prove?', '["That the allocation can be billed, because amounts that sum to the cost are how the engine defines valid.", "That the engine rescaled the interests to the whole before allocating, so the amounts come back to the cost.", "Nothing about the split, since the operator''s -150.00 restores the sum; valid false and the partner total of 115.00 percent catch it.", "That only the operator''s figure needs editing to 0 percent, after which the partners'' 700.00 and 450.00 can be billed as they stand."]'::jsonb, 2, 'The note says the interests total 115.00 percent and the operator share is negative; the fix belongs in the partner list; the computed operator figure is left alone.'::text),
      ('advanced', 'final', null::text, 21, 'Partner interests of 30 and -20 percent on a cost of 1000.00 leave the operator 90.0000 percent. Why did this split pass as valid before EC5-0?', '["The engine zeroed the negative interest first, so the split it tested was 30 percent with the operator at 70.", "The only test was whether the operator share went below zero, and a partner total of 10 percent leaves the residual positive.", "valid was computed from the amounts, and a partner credit of -200.00 plus the operator''s 900.00 and the 300.00 still sum to the cost.", "A negative interest was read as a carry, which the split models as a credit owed from an earlier phase."]'::jsonb, 1, 'Since EC5-0 it returns valid false naming Partner B at -20.00 percent; the negative entry moved 20 points onto an operator that would otherwise carry 70.'::text, 'Partner interests of 30 and -20 percent on a cost of 1000.00 leave the operator 90.0000 percent, a share that is not negative. Why does the engine still mark the split valid false?', '["It zeroes the negative interest first, finds the operator at 70 percent, and flags the gap between that and the 90.0000 it was handed.", "It checks every partner interest as well as the operator residual, and its note names Partner \"B\" at -20.00 percent.", "It compares the partner amounts with the cost, and a credit of -200.00 leaves the amounts short of the 1000.00 total.", "It reads a negative interest as a carry, and a carry has to be entered in a field the split does not have."]'::jsonb, 1, 'A partner total of 10 percent leaves the residual positive, so a test on the operator share alone would pass this split; the note reads "Partner "B" has a negative working interest (-20.00 percent). Correct the interests before billing."'::text),
      ('advanced', 'final', null::text, 24, 'A project with npv_p50 80 and fail_cost 30 is typed with pos 1.4. What does the portfolio engine do?', '["Refuses it with a PortfolioInputError naming the project, the same treatment it gives a negative capex before building a set.", "Uses 1.4 as typed, so the risked EMV exceeds the success-case NPV and the project ranks above every certain project in the inventory.", "Reads pos as 1 and returns risked EMV 80.0000, with nothing on the result to say the input changed.", "Marks the project invalid and funds it anyway, the way the grid returns an overshooting set beside overLimit true."]'::jsonb, 2, 'posAboveOneClamps returns 80.0000 and posBelowZeroClamps returns -30.0000; clamps are caught only by reading the inventory.'::text, 'A project with npv_p50 80 and fail_cost 30 is typed with pos 1.4. What does the portfolio engine do?', '["Reads pos as 1 and returns risked EMV 80.0000, with nothing on the result to say the input changed.", "Uses 1.4 as typed, so the risked EMV exceeds the success-case NPV and the project ranks above every certain project in the inventory.", "Refuses it with a PortfolioInputError naming the project: \"has a pos outside 0 to 1 (1.4); pos must be a number from 0 to 1\".", "Marks the project invalid and funds it anyway, the way the partner split returns its allocation beside valid false."]'::jsonb, 2, 'The published posAboveOneRefused case carries the same message; a chance of success is a probability, so 1.4 has no reading the engine could take, and -0.2 is refused the same way.'::text),
      ('advanced', 'final', null::text, 25, 'To get past the message that Project B has a negative capex (-150), an analyst types 0 in its place. What has the analyst made?', '["A clean entry the optimizer funds at no cost under any limit, since a capex of 0 weighs nothing on a grid of 1 million USD per cell.", "A free project that the grid still charges one cell (D2), with whatever the negative number carried gone from the model.", "A second refusal, since a capex of 0 is below the smallest grid cell and throws another error.", "The same project with its receipt kept, because a refused capex is booked into the NPV first."]'::jsonb, 1, 'In freeProjectTightLimit a free project with EMV 10.0000 is dropped beside A at 100.0000, so the engine returns 60.0000 where the exact optimum is 70.0000.'::text, 'To get past the message that Project B has a negative capex (-150), an analyst types 0 in its place. What has the analyst made?', '["A project the optimizer can never fund, because a capex of 0 leaves its EMV per million USD undefined and the solve drops it.", "A free project, funded whenever its EMV is positive, with whatever the negative number carried, such as a receipt, gone from the model.", "A second refusal, since a capex of exactly 0 is read as a missing capex and throws another error.", "The same project with its receipt kept, because a refused capex is booked into the NPV first."]'::jsonb, 1, 'In freeProjectTightLimit a free project with EMV 10.0000 rides beside A at capex 100.0000 under a limit of 100.0000, and the engine funds free + A for 70.0000; the receipt belonged in the NPV.'::text),
      ('advanced', 'final', null::text, 26, 'A published AFE case with progress beyond 100 percent returns earned value 150.0000, actuals 90.0000 and CPI 1.666667. How should that CPI be read?', '["As strong cost performance, because the engine refuses progress outside 0 to 100 percent and the input must therefore be valid.", "As a clamped figure, because progress above 100 is read as 100 and the earned value of 150.0000 includes the line''s commitment.", "As SPI printed in the cost column, since progress past the whole moves only SPI.", "With suspicion, since only negative progress is refused and the line has earned more than its budget can hold."]'::jsonb, 3, 'The refusal message says progress runs from 0 to 100 percent, yet the upper bound is not enforced; the same case reads SPI 1.500000.'::text, 'An engineer wants CSG-02, at 100.0000 percent with actuals of 4300000 against a budget of 3900000, to show more earned value and types its progress as 110. What happens to OFON-1''s report?', '["Earned value rises by a tenth of CSG-02''s budget, lifting CPI above 1.009377 with nothing on the report to mark the entry.", "CSG-02 is read at 100 percent and the report carries on unchanged, since progress past the whole is capped quietly.", "The line is flagged beside the metrics, the way a negative working interest is flagged beside the allocation.", "No report comes back: the AFE engine throws for that line, and the metrics return only once it is corrected."]'::jsonb, 3, 'Progress runs from 0 to 100 percent and a value outside that range is refused by line; CSG-02 at 100.0000 percent already earns its whole budget.'::text),
      ('advanced', 'final', null::text, 28, 'gridOvershoot returns A + B at 800.0000 with overLimit true and overLimitBy 2.0000 against a limit of 6000.0000. What belongs in the committee''s comparison?', '["A + B at 800.0000, since 2.0000 over the limit is inside one grid cell of 3.000000 and the engine counts that as within the limit.", "A + B with 2.0000 of capex trimmed, since overLimitBy tells the committee exactly how much to cut to make the higher EMV feasible.", "A + C at 780.0000, found by hand, since the flag marks A + B infeasible and never re-solves.", "A alone at 500.0000, since a flagged set is discarded and the engine falls back to the largest single project that fits the limit."]'::jsonb, 2, 'The golden gap is 20.0000; ranking 800.0000 against 780.0000 prefers the set the budget cannot pay for.'::text, 'Under a limit of 6000.0000 the published gridOvershoot case offers A (capex 4000.0000, EMV 500.0000), B (2002.0000, 300.0000) and C (1995.0000, 280.0000). A + B would return 800.0000. What does the optimizer fund?', '["A + B at 800.0000, since 2.0000 over the limit is inside one grid cell and the engine counts that as within the limit.", "A + B with overLimit true and overLimitBy 2.0000, leaving the committee to trim 2.0000 of capex from the higher EMV.", "A + C at capex 5995.0000 for 780.0000, solved exactly with overLimit false, since A + B does not fit the limit.", "A alone at 500.0000, since a set that would break the limit is discarded and the largest single project that fits is kept."]'::jsonb, 2, 'The result reads solveMethod exact and optimalityGap 0.0000; ranking 800.0000 against 780.0000 would prefer a set the budget cannot pay for.'::text),
      ('advanced', 'final', null::text, 29, 'gridUndershoot funds X + Y + Z at 660.0000 with overLimit false. What does overLimit false tell the reader?', '["That the grid found the best set within the limit, since the flag reports any case rounding changed.", "That the resolution of 3.000000 was fine enough, since a grid that misses a better set also flags.", "That W was rightly dropped, since its EMV of 200.0000 is the lowest and a full grid drops the lowest.", "Only that the set fits the limit; the exact optimum funds all four at 860.0000, and the undershoot (D4) is never flagged."]'::jsonb, 3, 'Rounding makes the four weigh 500, 500, 500 and 501 cells against a grid of 2000, so a gap of -200.0000 passes with no flag.'::text, 'Called with exactStateLimit 3, the published gridUndershootFallback case funds X + Y + Z at 660.0000 with overLimit false and optimalityGap 200.0000. What do the two readings tell the reader?', '["That the set is the best within the limit, since overLimit false is raised only when the fallback matches the exact optimum.", "That 200.0000 of the limit was left unspent, since optimalityGap reports the capex the rounded-up grid could not use.", "That W was rightly dropped, since its EMV of 200.0000 is the lowest of the four and the gap names the project left out.", "overLimit false says only that the set fits; the gap bounds what a better set could add, and the exact solve funds all four at 860.0000."]'::jsonb, 3, 'Every weight is rounded up, to 500, 500, 500 and 501 cells against 2000, so the four cannot fit the grid together; rounded down they fit, and 860.0000 less 660.0000 is the gap.'::text),
      ('advanced', 'final', null::text, 30, 'Which of these is a finding EC5-0 left in place, taught as a property of the engines as published?', '["SPI reported as Infinity before the start date when value had already been earned.", "CPI reported as 1.000000 whenever actuals are 0.", "A normal approximation whose P90 sits beneath the worst outcome of a single wildcat.", "An S-curve that keeps walking past its end date to the current month."]'::jsonb, 1, 'OFON-1 with every actual at 0 still earns 15231500 and reports CPI 1.000000, while SPI is now null before and on the start day and the curve stops at 10 points.'::text, 'Which of these is a property the course teaches as it stands in the engines and the Suite?', '["SPI reported as Infinity before the start date when value has already been earned.", "Time progress 1 on an AFE with no dates, so SPI there measures nothing and the Suite labels it unavailable.", "A P90 read off a normal curve that sits beneath the worst outcome of a single wildcat.", "An S-curve that keeps walking past its end date to the current month."]'::jsonb, 1, 'The published no-dates case reads time progress 1.000000 and SPI 0.250000; SPI is null before and on the start day, the risk summary is simulated, and the S-curve closes on a point dated the window end.'::text),
      ('advanced', 'final', null::text, 31, 'Suppose OFON-1''s cost postings are wiped so every line shows zero spend while progress stays as typed, and CPI now prints 1.000000. As of 2027-08-15, which reading keeps both its value and its meaning?', '["SPI 0.872063, because earned value ignores actuals and planned value comes from the calendar.", "The EAC of 27600000, because the forecast rule reads budgets and entered forecasts and never looks at the actuals on a line.", "The variance at completion of -550000, because a zero actual moves only the S-curve''s Actual line and none of the metrics.", "CPI itself, because 1.000000 records that the work done matched the money spent to the unit, which is still true with nothing spent."]'::jsonb, 0, 'SPI is 15231500 over 17466060; CSG-02 forecast from its actual of 4300000, so zeroing the actuals does move the EAC.'::text, 'Suppose OFON-1''s cost postings are wiped so every line shows zero spend while progress stays as typed, and CPI now prints null with cpiStatus "no-spend". As of 2027-08-15, which reading keeps both its value and its meaning?', '["SPI 0.872063, because earned value ignores actuals and planned value comes from the calendar.", "The EAC of 27600000, because the forecast rule reads budgets and entered forecasts and never looks at the actuals on a line.", "The variance at completion of -550000, because a zero actual moves only the S-curve''s Actual line and none of the metrics.", "CPI itself, because a null CPI reads as exactly on budget whenever nothing has been spent on the lines."]'::jsonb, 0, 'SPI is 15231500 over 17466060; CSG-02 forecast from its actual of 4300000, so zeroing the actuals does move the EAC.'::text),
      ('advanced', 'final', null::text, 32, 'The published empty AFE reports CPI 1.000000 and SPI 1.000000. What should a report say about those two figures?', '["That the AFE is exactly on cost and exactly on schedule, since both ratios equal one and neither depends on the date.", "That SPI should read null, since the repair made SPI null wherever planned value is zero and the published 1.000000 is a stale golden.", "That CPI means something here and SPI does not, since 0.0000 over 0.0000 is defined as one.", "Both are placeholders: CPI is 1 when actuals are 0, and SPI is 1 on a zero budget by a guard that fires before the null rule."]'::jsonb, 3, 'An AFE with no lines, no progress and no spend reads as perfect on cost and schedule at once; SPI 1 on a zero budget is a finding left unrepaired.'::text, 'The published empty AFE, with no lines, no progress and no spend, is read for its CPI and SPI. What does the engine report?', '["CPI 1.000000 and SPI 1.000000, exactly on cost and on schedule, since both ratios equal one when nothing has happened.", "CPI null with cpiStatus \"no-spend\" and SPI 0.000000, since a budget of 0 plans nothing and so earns against nothing.", "An AfeInputError, since an AFE with no lines cannot be measured and is refused before any ratio is formed.", "CPI null with cpiStatus \"no-spend\" and SPI null with spiStatus \"no-budget\": neither ratio can be formed."]'::jsonb, 3, 'A reported ratio carries the status "ok"; here there is no spend to divide by and no budget to plan, and the Suite''s SPI tile reads "N/A" with "No budget to measure schedule against".'::text),
      ('advanced', 'final', null::text, 33, 'An S-curve reads Planned 0 and Actual 0 at its first point, and 2 undated invoices are reported beside it. What is the Actual line leaving out?', '["Only the invoice whose invoice_date is null, because one with no invoice_date field is placed on the start day of the window instead.", "Nothing at all, because the count is a display note and both amounts are still carried into every bucket from the window''s start day.", "Every invoice the engine could not date, since none of them reaches a bucket at all.", "The commitments, because the curve''s Actual line adds the orders placed at the start of the window and drops them again once they are invoiced."]'::jsonb, 2, 'In the published undated case the Actual reads 0 at Jan 20 and at Dec 20 while the engine reports 2 undated invoices; a dated invoice first shows at the point after its date.'::text, 'An S-curve reads Planned 0 and Actual 0 at its first point, and 2 undated invoices are reported beside it. What is the Actual line leaving out?', '["Only the invoice whose invoice_date is null, because one with no invoice_date field is placed on the start day of the window instead.", "Nothing at all, because the count is a display note and both amounts are still carried into every bucket from the window''s start day.", "Every invoice the engine could not date, since none of them reaches a bucket at all.", "The commitments, because the curve''s Actual line adds the orders placed at the start of the window and drops them again once they are invoiced."]'::jsonb, 2, 'In the published undated case the Actual reads 0 at Jan 20 and at the closing point 31 Dec 20 while the engine reports 2 undated invoices; a dated invoice first shows at the first point on or after its date.'::text),
      ('advanced', 'final', null::text, 34, 'As of 2027-11-30 OFON-1''s metrics report planned value 27050000, but the S-curve''s last Planned point is 24452483. Which should a report quote as the plan?', '["The curve, because the 2597517 it never plots is contingency the plan never meant to spend.", "The metrics: time progress is 1.000000 on the end day, while the curve''s last point sits on the first of November.", "The curve, because the metrics read the plan from the budget while the curve builds it from invoices, which are the better record.", "Neither, because SPI is null on the end day and planned value is undefined once the window has closed."]'::jsonb, 1, 'The plan stops 2597517 short because the monthly buckets end before the window does; use the curve for its shape and the metrics for the number.'::text, 'OFON-1 is read as of its end day, 2027-11-30. Its metrics give planned value 27050000, while the chart''s Nov 27 point shows 24452483. Which figure is the plan?', '["The Nov 27 point, because the 2597517 after it is contingency the plan never meant to spend.", "The planned value in the metrics, 27050000, the same figure the chart shows at its window-end point.", "The Nov 27 point, because the metrics read the plan from the budget while the curve builds it from invoices, the better record.", "Neither, because SPI is null on the end day and planned value is undefined once the window has closed."]'::jsonb, 1, 'Monthly points sit on the 1st, so Nov 27 falls a month early; the chart''s last point is dated the end day and carries the whole budget.'::text),
      ('advanced', 'final', null::text, 35, 'A project manager glances at OFON-1''s chart, sees the final projected point of 24949669 sitting under the 27050000 authorisation, and tells the partners the well will come in cheap. What is the correction?', '["After the as-of date the Forecast line continues from the actual spend of 15090000, so 24949669 is the honest projection of the remaining work.", "The curve plots only budgets after the as-of date, so CMT-03''s 1400000 is missing.", "EC5-0 put one EAC rule on every screen except the chart, so the curve still forecasts from the budget and the manager''s reading stands.", "The last bucket stops before the end date; the metrics forecast 27600000, a variance at completion of -550000."]'::jsonb, 3, 'After the as-of date Forecast is the EAC spread from the start, which is why it jumps from 15090000 to 19374834; take the EAC and variance from the metrics.'::text, 'A project manager stops at the last monthly point of OFON-1''s chart, "Nov 27", sees Forecast 24949669 under the 27050000 authorisation, and tells the partners the well will come in cheap. What is the correction?', '["After the as-of date the Forecast line continues from the actual spend of 15090000, so 24949669 is the honest projection of the remaining work.", "The curve plots only budgets after the as-of date, so CMT-03''s 1400000 is missing.", "The chart draws one EAC rule and the metrics another, so the curve forecasts from the budget and the manager''s reading stands.", "Read the chart to its end: on the window-end point the forecast is 27600000 beside a plan of 27050000, an overrun of 550000."]'::jsonb, 3, 'After the as-of date Forecast is the EAC spread from the start, jumping from 15090000 to 19374834, and it reaches the EAC on the point dated 30 Nov 27.'::text),
      ('advanced', 'final', null::text, 36, 'OKONO''s 450.0000 set reads P(loss) 0.123600 at seed 20260829 with a standard error of 0.003291, where the old approximation said 0.142035. A reviewer proposes 40000 iterations to settle which is right. What will the run settle?', '["Only the simulation''s own precision, 0.125975 with a standard error of 0.001659; the gap to 0.142035 is a different model, which no iteration count closes.", "Which model is right, because as iterations grow the simulated count converges on the normal approximation and the gap closes.", "Nothing at all, because the larger run reuses the default seed and so repeats the draws of the 10000 iteration run exactly.", "That the approximation was nearer the truth, since 0.125975 sits closer to 0.142035 than 0.123600 did and the trend runs toward it."]'::jsonb, 0, 'The published cases sit no further than 1.4289 standard errors from exact, while the old approximation missed the single wildcat''s 0.700000 by dozens.'::text, 'OKONO''s 450.0000 set reads P(loss) 0.123600 at seed 20260829 with a standard error of 0.003291, where a normal approximation gives 0.142035. A reviewer proposes 40000 iterations to settle which is right. What will the run settle?', '["Only the simulation''s own precision, 0.125975 with a standard error of 0.001659; the gap to 0.142035 is a different model, which no iteration count closes.", "Which model is right, because as iterations grow the simulated count converges on the normal approximation and the gap closes.", "Nothing at all, because the larger run reuses the default seed and so repeats the draws of the 10000 iteration run exactly.", "That the normal approximation is nearer the truth, since 0.125975 sits closer to 0.142035 than 0.123600 did and the trend runs toward it."]'::jsonb, 0, 'The published cases sit no further than 1.4289 standard errors from exact, while a normal approximation misses the single wildcat''s 0.700000 by dozens.'::text),
      ('advanced', 'final', null::text, 37, 'A team that wants the 450.0000 set to look safer tries seeds until it finds 0.119100 at seed 3, having also seen 0.128500 at seed 1, all at 10000 iterations, and reports only the seed 3 figure. What is wrong?', '["Nothing, because seed 3''s result is exactly reproducible and reproducibility is what EC5-0 added to the risk summary.", "Seed 3 is right for another reason: its standard error of 0.003239 is the smallest of the seeds.", "It picked the draw that flatters the set; the seeds differ by what sampling alone produces, and the set''s risk is unchanged.", "The team should average the seeds, since their mean is the true loss probability of the set."]'::jsonb, 2, 'Standard errors between 0.003239 and 0.003346 make that spread ordinary noise; an honest report names the seed and iterations beside the figure.'::text, 'A team that wants the 450.0000 set to look safer tries seeds until it finds 0.119100 at seed 3, having also seen 0.128500 at seed 1, all at 10000 iterations, and reports only the seed 3 figure. What is wrong?', '["Nothing, because seed 3''s result is exactly reproducible and reproducibility is what the seed adds to the risk summary.", "Seed 3 is right for another reason: its standard error of 0.003239 is the smallest of the seeds.", "It picked the draw that flatters the set; the seeds differ by what sampling alone produces, and the set''s risk is unchanged.", "The team should average the seeds, since their mean is the true loss probability of the set."]'::jsonb, 2, 'Standard errors between 0.003239 and 0.003346 make that spread ordinary noise; an honest report names the seed and iterations beside the figure.'::text),
      ('advanced', 'final', null::text, 38, 'At a limit of 750.0000 OKONO funds five projects for 690.0000 and leaves 60.0000 unspent. A manager asks why the engine did not fund part of OK-6 with it. What is the answer?', '["OK-6''s risked EMV per million USD of 0.464516 falls below the cut-off the optimizer applies to leftover money at the end of a solve.", "Projects are funded whole; OK-6 costs 310.0000, and a farm-down or phased start does not exist for the engine.", "A fraction of OK-6 would not fill one whole cell of the grid at 750.0000.", "The risk summary rejects a set whose P(loss) rises, and a share of OK-6 would lift the set''s 0.012800 above what the engine allows."]'::jsonb, 1, 'The resolution is 1.0000 at that limit; at 1000.0000 the whole of OK-6 fits and the set reaches 588.0000.'::text, 'At a limit of 750.0000 OKONO funds five projects for 690.0000 and leaves 60.0000 unspent. A manager asks why the engine did not fund part of OK-6 with it. What is the answer?', '["OK-6''s risked EMV per million USD of 0.464516 falls below the cut-off the optimizer applies to leftover money at the end of a solve.", "Projects are funded whole; OK-6 costs 310.0000, and a farm-down or phased start does not exist for the engine.", "A fraction of OK-6 would fall below the smallest capex step the optimizer can fund at 750.0000.", "The risk summary rejects a set whose P(loss) rises, and a share of OK-6 would lift the set''s 0.012800 above what the engine allows."]'::jsonb, 1, 'The solve is exact at that limit, solveMethod exact with optimalityGap 0.0000; at 1000.0000 the whole of OK-6 fits and the set reaches 588.0000.'::text),
      ('advanced', 'final', null::text, 40, 'Each of these capstone lines quotes a correct number. Which one loses marks?', '["OFON-1: SPI 0.872063.", "OKONO at 450.0000: P(loss) 0.123600 at seed 20260829, 10000 iterations, correlation 0.", "OFON-1: CPI 1.009377 beside actuals of 15090000.", "OKONO at 450.0000: OK-1 + OK-3 + OK-4, capex 450.0000, EMV 291.0000, resolution 1.0000, overLimit false."]'::jsonb, 0, 'SPI moves with the date, 1.141290 at 2027-06-30 and 0.872063 at 2027-08-15 on the same lines, so an SPI without its as-of date is incomplete.'::text, 'Each of these capstone lines quotes a correct number. Which one loses marks?', '["OFON-1: SPI 0.872063.", "OKONO at 450.0000: P(loss) 0.123600 at seed 20260829, 10000 iterations, correlation 0.", "OFON-1: CPI 1.009377 beside actuals of 15090000.", "OKONO at 450.0000: OK-1 + OK-3 + OK-4, capex 450.0000, EMV 291.0000, solveMethod exact, optimalityGap 0.0000."]'::jsonb, 0, 'SPI moves with the date, 1.141290 at 2027-06-30 and 0.872063 at 2027-08-15 on the same lines, so an SPI without its as-of date is incomplete.'::text),
      ('advanced', 'final', null::text, 42, 'An inventory submitted to the Capital Portfolio Studio contains a project whose capex is -150. What P90 does the risk summary report?', '["The P90 of the set with that project clamped to capex 0, as odd inputs are clamped.", "None, because the PortfolioInputError throws first and the engine returns no set, no frontier and no risk summary.", "A P90 carrying a flag, since the repaired engine returns the answer and marks the negative capex the way it marks an overshoot.", "The P90 of the set without that project, since a refused project is simply dropped."]'::jsonb, 1, 'The message names the project, "capex must be 0 or more", and a simulated low case exists only for a set the engine agreed to build.'::text, 'An inventory submitted to the Capital Portfolio Studio contains a project whose capex is -150. What P90 does the risk summary report?', '["The P90 of the set with that project clamped to capex 0, as odd inputs are clamped.", "None, because the PortfolioInputError throws first and the engine returns no set, no frontier and no risk summary.", "A P90 carrying a flag, since the engine returns the answer and marks the negative capex the way it marks an invalid partner split.", "The P90 of the set without that project, since a refused project is simply dropped."]'::jsonb, 1, 'The message names the project, "capex must be 0 or more", and a simulated low case exists only for a set the engine agreed to build.'::text),
      ('advanced', 'module', 'm01-portfolio-risk-by-simulation'::text, 1, 'One wildcat with pos 0.3, a success-case NPV of 300 and a fail cost of 50. Before EC5-0 the engine put its P90 at -150.5560. What is wrong with that figure?', '["Nothing is wrong with it: a low case set beneath the worst outcome is a conservative margin, and the simulation has simply removed that margin.", "It is the high case with its sign reversed, because the old engine ranked outcomes under the opposite percentile convention to the one used now.", "It sits beneath -50.0000, the worst outcome the well can produce, so it describes a loss this project can never book.", "It is right for the success case alone, since the old engine drew the failure lump in a separate pass and never added it back into the sum."]'::jsonb, 2, 'The old P90 was emv minus 1.2816 x stdDev on a bell the well does not have: it fails with chance 0.700000 and then loses exactly 50.0000, which is the engine''s P90 now, -50.0000.'::text, 'One wildcat with pos 0.3, a success-case NPV of 300 and a fail cost of 50. A normal approximation puts its P90 at -150.5560. What is wrong with that figure?', '["Nothing is wrong with it: a low case set beneath the worst outcome is a conservative margin, and the simulation has simply removed that margin.", "It is the high case with its sign reversed, because the normal curve ranks outcomes under the opposite percentile convention to the one the engine uses.", "It sits beneath -50.0000, the worst outcome the well can produce, so it describes a loss this project can never book.", "It is right for the success case alone, since the normal curve is fitted to the success spread and leaves the failure lump out of the sum."]'::jsonb, 2, 'The normal P90 is emv minus 1.2816 x stdDev on a bell the well does not have: it fails with chance 0.700000 and then loses exactly 50.0000, which is the engine''s P90, -50.0000.'::text),
      ('advanced', 'module', 'm01-portfolio-risk-by-simulation'::text, 5, 'mixtureWithSpread pairs a risked project with a sure one. Before EC5-0 the engine put its P90 at -12.4175; the simulation reads 1.7148. What would a reader of the old figure have got wrong?', '["Nothing of substance, since both figures sit close to zero and the gap between them is inside one standard error of the simulated count.", "The sign of the high case, because under the exceedance convention the old P90 was the figure a committee would quote as the upside.", "That the low case loses money, when nine simulated outcomes in ten are gains.", "The worst case, because a P90 of -12.4175 is the floor of the portfolio and the simulation shows the floor is really a small gain."]'::jsonb, 2, 'Under the exceedance convention P90 is the 10th percentile of simulated portfolio NPV, and at 1.7148 it is a gain; the bell fitted to emv and stdDev put it at a loss of 12.4175.'::text, 'mixtureWithSpread pairs a risked project with a sure one. A normal approximation puts its P90 at -12.4175; the simulation reads 1.7148. What would a reader of the normal figure get wrong?', '["Nothing of substance, since both figures sit close to zero and the gap between them is inside one standard error of the simulated count.", "The sign of the high case, because under the exceedance convention the normal P90 is the figure a committee would quote as the upside.", "That the low case loses money, when nine simulated outcomes in ten are gains.", "The worst case, because a P90 of -12.4175 is the floor of the portfolio and the simulation shows the floor is really a small gain."]'::jsonb, 2, 'Under the exceedance convention P90 is the 10th percentile of simulated portfolio NPV, and at 1.7148 it is a gain; the bell fitted to emv and stdDev put it at a loss of 12.4175.'::text),
      ('advanced', 'module', 'm01-portfolio-risk-by-simulation'::text, 11, 'The engine counts P(loss) 0.696100 for the single wildcat against an exact 0.700000, with a standard error of 0.004583. Is the engine wrong?', '["Yes, because a reproducible seeded run ought to land on the exact P(loss).", "Yes, because the strict test drops iterations that net exactly zero, which biases the count below the exact loss chance.", "No, it sits 0.8510 standard errors from the exact figure, where a count from 10000 iterations should land.", "No, because the engine rounds P(loss) to the nearest standard error before printing it."]'::jsonb, 2, 'probLoss is a proportion with standard error sqrt(p(1 - p) / n); the largest z on the published cases is 1.4289, and the old 0.365832 sat dozens of standard errors away.'::text, 'The engine counts P(loss) 0.696100 for the single wildcat against an exact 0.700000, with a standard error of 0.004583. Is the engine wrong?', '["Yes, because a reproducible seeded run ought to land on the exact P(loss).", "Yes, because the strict test drops iterations that net exactly zero, which biases the count below the exact loss chance.", "No, it sits 0.8510 standard errors from the exact figure, where a count from 10000 iterations should land.", "No, because the engine rounds P(loss) to the nearest standard error before printing it."]'::jsonb, 2, 'probLoss is a proportion with standard error sqrt(p(1 - p) / n); the largest z on the published cases is 1.4289, and a normal approximation''s 0.365832 sits dozens of standard errors away.'::text),
      ('advanced', 'module', 'm02-correlation'::text, 5, 'comonotoneIdentical3 has three wildcats at rho 1.000000, each pos 0.3, 300 on success and a fail cost of 50. Its exact P(loss) is 0.700000, the same as one wildcat. Why?', '["At rho 1 the three wells hear only F1 and fail together whenever one fails, so the portfolio loses exactly when a single well would.", "At rho 1 the three losses of 50.0000 are averaged rather than summed, so the portfolio is scored as one well carrying the average loss.", "At rho 1 the optimizer treats identical projects as duplicates and funds one well, so the risk summary is simulated for that one alone.", "At rho 1 the normal approximation becomes exact, and 0.700000 is the bell''s reading for three perfectly correlated wells."]'::jsonb, 0, 'Independent, the three fail together with chance 0.343000 and the copula case sits between at 0.469561; the low case is -150.0000 on all three rows, and only its frequency changes.'::text, 'comonotoneIdentical3 has three wildcats at rho 1.000000, each pos 0.3, 300 on success and a fail cost of 50. Its exact P(loss) is 0.700000, the same as one wildcat. Why?', '["At rho 1 the three wells hear only F1 and fail together whenever one fails, so the portfolio loses exactly when a single well would.", "At rho 1 the three losses of 50.0000 are averaged where they should be summed, so the portfolio is scored as one well carrying the average loss.", "At rho 1 the optimizer treats identical projects as duplicates and funds one well, so the risk summary is simulated for that one alone.", "At rho 1 the normal approximation becomes exact, and 0.700000 is the bell''s reading for three perfectly correlated wells."]'::jsonb, 0, 'Independent, the three fail together with chance 0.343000 and the copula case sits between at 0.469561; the low case is -150.0000 on all three rows, and only its frequency changes.'::text),
      ('advanced', 'module', 'm02-correlation'::text, 7, 'An analyst builds the spread formula for the 600.0000 set from success spreads, using OK-4''s 78.0305 in place of its mixture sd of 121.9467. What happens to stdDev?', '["It is overstated, because success spreads are read from npv_p10 and npv_p90, which bracket a wider range than the mixture variance does.", "It is unchanged at rho 1, where the formula reduces to the plain sum of the sds and it no longer matters which of its two sds each project contributes.", "It changes only for OK-5, the one project in the set with pos 1.000000, since its two spread columns are the only ones that differ.", "It is understated at every rho, because success spreads leave out the gap between a success centred on 210.0000 and a failure costing 40.0000."]'::jsonb, 3, 'The mixture sd is the square root of the success and failure variance taken together; only OK-5, with no fail cost, has the two columns agree, at 12.8750.'::text, 'An analyst builds the spread formula for the 600.0000 set from success spreads, using OK-4''s 78.0305 in place of its mixture sd of 121.9467. What happens to stdDev?', '["It is overstated, because success spreads are read from npv_p10 and npv_p90, which bracket a wider range than the mixture variance does.", "It is unchanged at rho 1, where the formula reduces to the plain sum of the sds and it stops mattering which of its two sds each project contributes.", "It changes only for OK-5, the one project in the set with pos 1.000000, since its two spread columns are the only ones that differ.", "It is understated at every rho, because success spreads leave out the gap between a success centred on 210.0000 and a failure costing 40.0000."]'::jsonb, 3, 'The mixture sd is the square root of the success and failure variance taken together; only OK-5, with no fail cost, has the two columns agree, at 12.8750.'::text),
      ('advanced', 'module', 'm02-correlation'::text, 9, 'At rho 0.600000 the risk summary prints stdDev 206.8905 beside P90 137.2208 for the 600.0000 set. A reader checks P90 as emv minus 1.2816 x stdDev and it does not match. Why?', '["P90 carries the sampling noise of seed 20260829, and the mismatch is about one standard error that a longer run at 40000 iterations would close.", "The multiplier 1.2816 holds only at rho 0, and at rho 0.600000 the engine derives P90 from a z adjusted for the correlation it was given.", "stdDev is the moment formula with rho on the project outcomes, while P90 comes from the simulation with rho on the latent drivers: two models that need not agree.", "P90 is the high case under the exceedance convention, so the check should add 1.2816 x stdDev to emv rather than subtract it from it."]'::jsonb, 2, 'The simulated P(loss), P90 and P10 are counted and sorted from outcomes; emv minus 1.2816 x stdDev was the normal approximation''s P90 and is history since EC5-0.'::text, 'At rho 0.600000 the risk summary prints stdDev 206.8905 beside P90 137.2208 for the 600.0000 set. A reader checks P90 as emv minus 1.2816 x stdDev and it does not match. Why?', '["P90 carries the sampling noise of seed 20260829, and the mismatch is about one standard error that a longer run at 40000 iterations would close.", "The multiplier 1.2816 holds only at rho 0, and at rho 0.600000 the engine derives P90 from a z adjusted for the correlation it was given.", "stdDev is the moment formula with rho on the project outcomes, while P90 comes from the simulation with rho on the latent drivers: two models that need not agree.", "P90 is the high case under the exceedance convention, so the check should add 1.2816 x stdDev to emv and drop the subtraction."]'::jsonb, 2, 'The simulated P(loss), P90 and P10 are counted and sorted from outcomes; emv minus 1.2816 x stdDev is a normal approximation''s P90, a different method.'::text),
      ('advanced', 'module', 'm02-correlation'::text, 14, 'Why does emv read 402.7500 at every rho on the correlation table?', '["z1 = sqrt(rho) F1 + sqrt(1 - rho) e1 is still a standard normal, so each project succeeds with chance pos at any rho and only which projects succeed together changes.", "The weights sqrt(rho) and sqrt(1 - rho) add up to one at every rho, so the shared draw and the project''s own draw always average back to its npv_p50.", "The engine re-centres the simulated values on the closed-form emv at the end of every run, so the mean is held by the construction of the output.", "Correlation reaches only the failures, and emv is computed from the success-case NPVs alone, which the shared driver never touches at all."]'::jsonb, 0, 'The squared weights add to one, not the weights, and the average of a sum is the sum of the averages whatever the dependence. The emv printed is the closed form, with no simulated mean beside it.'::text, 'Why does emv read 402.7500 at every rho on the correlation table?', '["z1 = sqrt(rho) F1 + sqrt(1 - rho) e1 is still a standard normal, so each project succeeds with chance pos at any rho and only which projects succeed together changes.", "The weights sqrt(rho) and sqrt(1 - rho) add up to one at every rho, so the shared draw and the project''s own draw always average back to its npv_p50.", "The engine re-centres the simulated values on the closed-form emv at the end of every run, so the mean is held by the construction of the output.", "Correlation reaches only the failures, and emv is computed from the success-case NPVs alone, which the shared driver never touches at all."]'::jsonb, 0, 'The squared weights add to one while the weights do not, and the average of a sum is the sum of the averages whatever the dependence. The emv printed is the closed form, with no simulated mean beside it.'::text),
      ('advanced', 'module', 'm03-joint-venture-shares'::text, 3, 'Where does OFON-1''s operator share of 25.0000 percent come from?', '["It is typed in as the operator''s interest in the agreement, and the engine checks it against the partners'' total before splitting.", "It is the largest partner''s interest less the others, 40.0000 less 22.5000 and 12.5000 plus the operator''s own carried cost.", "It is computed as 100 less the partnerTotal of 75.0000, never typed in, so the four percents add to 100 by construction.", "It is a default the engine assigns to every operator, and partners are scaled to fill the remaining 75.0000 percent of cost."]'::jsonb, 2, 'Against the budget of 27050000 the residual is 6762500 and against the actuals to date of 15090000 it is 3772500. The operator absorbs every gap and every excess in the partner list.'::text, 'Where does OFON-1''s operator share of 25.0000 percent come from?', '["It is typed in as the operator''s interest in the agreement, and the engine checks it against the partners'' total before splitting.", "It is the largest partner''s interest less the others, 40.0000 less 22.5000 and 12.5000 plus the operator''s own carried cost.", "It is computed as 100 less the partnerTotal of 75.0000 and is not typed in, so the four percents add to 100 by construction.", "It is a default the engine assigns to every operator, and partners are scaled to fill the remaining 75.0000 percent of cost."]'::jsonb, 2, 'Against the budget of 27050000 the residual is 6762500 and against the actuals to date of 15090000 it is 3772500. The operator absorbs every gap and every excess in the partner list.'::text),
      ('advanced', 'module', 'm03-joint-venture-shares'::text, 9, 'On that case at 30 and -20 percent, what has the negative entry done to the operator?', '["Moved its magnitude onto the operator, who carries 90.0000 percent where it would carry 70 without the entry, while the partner bills itself a credit of 200.00.", "Nothing, since the operator share depends only on whether the partner total reaches 100, and a total of 10 percent leaves the operator at the same residual it would carry anyway.", "Reduced the operator''s load by 20 percent, since a partner''s negative interest is a contribution the operator deducts from its own share of cost.", "Split the credit between the operator and the positive partner, in proportion to their interests of 90.0000 and 30 percent of the cost."]'::jsonb, 0, 'Before EC5-0 this split passed as valid, because the only test was whether the operator share went below zero; a check that the total is at most 100 also passes it.'::text, 'On that case at 30 and -20 percent, what has the negative entry done to the operator?', '["Moved its magnitude onto the operator, who carries 90.0000 percent where it would carry 70 without the entry, while the partner bills itself a credit of 200.00.", "Nothing, since the operator share depends only on whether the partner total reaches 100, and a total of 10 percent leaves the operator at the same residual it would carry anyway.", "Reduced the operator''s load by 20 percent, since a partner''s negative interest is a contribution the operator deducts from its own share of cost.", "Split the credit between the operator and the positive partner, in proportion to their interests of 90.0000 and 30 percent of the cost."]'::jsonb, 0, 'A test on the operator share alone passes this split, since the residual is not below zero, and so does a check that the total is at most 100; the engine checks each interest and reports valid false with the partner named.'::text),
      ('advanced', 'module', 'm03-joint-venture-shares'::text, 12, 'What does OFON-1 bill Ofon Energy, at 40.0000 percent, for the work to date?', '["10820000 USD, its share of the budget of 27050000 that the partners approved when the AFE was authorised.", "6036000 USD, 40.0000 percent of the actuals to date of 15090000.", "Its 40.0000 percent of the actuals plus the commitments of 5000000, since orders placed are costs the operator is already bound to.", "Its 40.0000 percent of the EAC of 27600000, since a partner is billed on the forecast that every screen shares after EC5-0."]'::jsonb, 1, 'Partners are billed on actuals, not the budget or the EAC. The four bills, 6036000 + 3395250 + 1886250 + 3772500, sum to 15090000.'::text, 'What does OFON-1 bill Ofon Energy, at 40.0000 percent, for the work to date?', '["10820000 USD, its share of the budget of 27050000 that the partners approved when the AFE was authorised.", "6036000 USD, 40.0000 percent of the actuals to date of 15090000.", "Its 40.0000 percent of the actuals plus the commitments of 5000000, since orders placed are costs the operator is already bound to.", "Its 40.0000 percent of the EAC of 27600000, since a partner is billed on the forecast that every screen of the AFE shares."]'::jsonb, 1, 'Partners are billed on actuals; the budget is an authorisation and the EAC a forecast. The four bills, 6036000 + 3395250 + 1886250 + 3772500, sum to 15090000.'::text),
      ('advanced', 'module', 'm03-joint-venture-shares'::text, 14, 'OFON-1 records actuals of 15090000 on its cost lines and an invoice total of 15090000. What should a partner bill say about that?', '["Which total it split, because the two agree by construction on OFON-1 and need not agree on a real AFE.", "Nothing, because the engine reconciles invoices with cost lines and refuses a split that disagrees.", "That it split the larger of the two, since the rule every screen shares after EC5-0 takes the larger of any two recorded actuals.", "That it split the invoices, since the cost lines hold commitments and not money spent."]'::jsonb, 0, 'The metrics read actuals from the cost lines and the S-curve reads them from invoices. The split applies one set of interests to whatever total it is handed and converts nothing.'::text, 'OFON-1 records actuals of 15090000 on its cost lines and an invoice total of 15090000. What should a partner bill say about that?', '["Which total it split, because the two agree by construction on OFON-1 and need not agree on a real AFE.", "Nothing, because the engine reconciles invoices with cost lines and refuses a split that disagrees.", "That it split the larger of the two, since the one forecast rule every screen shares takes the larger of any two recorded actuals.", "That it split the invoices, since the cost lines hold commitments and not money spent."]'::jsonb, 0, 'The metrics read actuals from the cost lines and the S-curve reads them from invoices. The split applies one set of interests to whatever total it is handed and converts nothing.'::text),
      ('advanced', 'module', 'm03-joint-venture-shares'::text, 15, 'Before EC5-0, what did the AFE summary PDF bill for an AFE whose saved partners were Ofon Energy, Enang Petroleum and Mfem Resources?', '["The three saved partners on the budget of 27050000, because the PDF read the approved total rather than the actuals.", "The three saved partners with the operator left out, so the operator''s 25.0000 percent was missing from the printed split.", "Two invented partners, Partner A at 30 percent and Partner B at 10 percent, whatever partners had been saved.", "The three saved partners with no note, so an invalid split printed without its warning."]'::jsonb, 2, 'The repaired PDF bills the AFE''s saved partners and prints the engine note whenever the split is invalid; a screen that hides valid and the note bills an error quietly.'::text, 'What does the AFE summary PDF bill for an AFE whose saved partners are Ofon Energy, Enang Petroleum and Mfem Resources, and what does it print when their split is invalid?', '["Only the partners whose interests are valid, since the PDF drops any partner the engine note names and bills the operator for the rest.", "The three saved partners with the operator left out, so the operator''s 25.0000 percent is missing from the printed split.", "The three saved partners with the operator carrying the rest, and the engine note printed beside an invalid split.", "The three saved partners with no note, so an invalid split prints without its warning."]'::jsonb, 2, 'With no partners saved the operator carries 100 percent; a screen that hides valid and the note bills an error quietly.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 2, 'When negativeCapexRefused fires on project "B" with a capex of -150, what does the optimizer return?', '["No set, no frontier and no risk summary: the PortfolioInputError and its message are the whole result.", "The best set among the other projects, with B left out of the inventory and the message attached to the result as a warning.", "The best set with B clamped to a capex of 0, the treatment a pos of 1.4 or a negative fail_cost receives without any warning.", "The best set with overLimit true, since funding B would add 150 to the limit and the flag marks a limit that stopped meaning a limit."]'::jsonb, 0, 'A refusal stops the engine and a flag returns an answer; a negative capex is refused, while a pos of 1.4 is clamped and quietly returns 80.0000.'::text, 'When negativeCapexRefused fires on project "B" with a capex of -150, what does the optimizer return?', '["No set, no frontier and no risk summary: the PortfolioInputError and its message are the whole result.", "The best set among the other projects, with B left out of the inventory and the message attached to the result as a warning.", "The best set with B read as a capex of 0, the treatment a negative fail_cost receives without any warning.", "The best set with overLimit true, since funding B would add 150 to the limit and the flag marks a limit that stopped meaning a limit."]'::jsonb, 0, 'A refusal stops the engine and a flag returns an answer; a negative capex is refused, a pos of 1.4 is refused too, and only a negative fail_cost is read as 0 with no warning.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 3, 'A user gets past the negative capex refusal by typing 0 in place of -150. Why is that not a safe repair?', '["A capex of 0 gives the project a risked EMV of 0, since the risked EMV is scaled by capex, and a project with EMV of 0 or less is never funded.", "The engine refuses a capex of exactly 0 as well, because the message is read as capex must be more than 0, so the edit trades one refusal for another.", "The optimizer ranks projects by EMV per million USD before it fills the limit, so a capex of 0 raises a division by zero inside the ranking.", "A free project is still charged one grid cell (finding D2), and whatever the negative number carried, such as a receipt, belonged in the NPV and has vanished."]'::jsonb, 3, 'In freeProjectTightLimit a free project with EMV 10.0000 beside A at capex 100.0000 under a limit of 100.0000 is dropped: the engine funds A alone for 60.0000 where the exact optimum is 70.0000.'::text, 'A user gets past the negative capex refusal by typing 0 in place of -150. Why is that not a safe repair?', '["A capex of 0 gives the project a risked EMV of 0, since the risked EMV is scaled by capex, and a project with EMV of 0 or less is never funded.", "The engine refuses a capex of exactly 0 as well, because the message is read as capex must be more than 0, so the edit trades one refusal for another.", "The optimizer ranks projects by EMV per million USD before it fills the limit, so a capex of 0 raises a division by zero inside the ranking.", "A free project is funded at no cost whenever its EMV is positive, and whatever the negative number carried, such as a receipt, belonged in the NPV and has vanished."]'::jsonb, 3, 'In freeProjectTightLimit a free project with EMV 10.0000 beside A at capex 100.0000 under a limit of 100.0000 is funded: the engine funds free + A for 70.0000, solveMethod exact.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 4, 'Three copies of a project with npv_p50 80 and fail_cost 30 leave pos out, type it as "n/a", and type it as an empty string. What risked EMVs come back?', '["80.0000 for the first and a PortfolioInputError for the other two, because a typed pos that is not a number is refused like a negative capex.", "80.0000, 80.0000 and -30.0000: an absent or non-numeric pos defaults to 1, while an empty string is the number 0 and reads as certain failure.", "80.0000 three times, because every pos the engine cannot read as a number falls back to the documented default of 1.", "-30.0000 three times, because a pos that is missing or unreadable is treated as a chance of success of 0 until one is typed in."]'::jsonb, 1, 'None of the three is refused or flagged; the blank pos read as -30.0000 is finding EC5-6, left unrepaired and taught as a property of the engine.'::text, 'Three copies of a project with npv_p50 80 and fail_cost 30 leave pos out, type it as "n/a", and type it as an empty string. What risked EMVs come back?', '["80.0000 three times, because every pos the engine cannot read as a number falls back to the documented default of 1.", "80.0000 for the pos left out, and a PortfolioInputError for the other two, each ending \"pos must be a number from 0 to 1\".", "80.0000, 80.0000 and -30.0000: a non-numeric pos defaults to 1, while an empty string is the number 0 and reads as certain failure.", "-30.0000 three times, because a pos that is missing or unreadable is treated as a chance of success of 0 until one is typed in."]'::jsonb, 1, 'A missing or null pos is the documented default of 1; a pos that is present must be a number from 0 to 1, and a blank or non-numeric one is refused by project name ("has a blank pos", "has a pos that is not a number ("n/a")").'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 5, 'Project T is entered with capex "abc" beside project U at capex 40, under a limit of 100. What does the optimizer return?', '["A PortfolioInputError naming T, because the capex check refuses any value that is not a number of 0 or more before the grid is built.", "T + U at a total capex of 40.0000, because \"abc\" counts as capex 0, weighs one grid cell and is neither refused nor flagged.", "U alone at 40.0000, because a capex the engine cannot read as a number drops that project from the inventory before the grid is built.", "T + U with overLimit true, because a capex that is not a number is flagged the same way the grid overshoot is flagged."]'::jsonb, 1, 'The probe funds T + U at capex 40.0000 and EMV 80.0000; a non-numeric capex is finding EC5-7, a property of the engine as published, and only reading the inventory catches it.'::text, 'Project T is entered with capex "abc" beside project U at capex 40, under a limit of 100. What does the optimizer return?', '["T + U at a total capex of 40.0000, because \"abc\" counts as capex 0 and is neither refused nor flagged.", "A PortfolioInputError naming T, \"has a capex that is not a finite number (\"abc\"); capex must be 0 or more\", and nothing funded.", "U alone at 40.0000, because a capex the engine cannot read as a number drops that project from the inventory before the solve.", "T + U with a flag on T, the way a negative working interest returns valid false beside the allocation."]'::jsonb, 1, 'Every project is checked in list order, capex before pos, before anything is computed; the whole call is refused, so U is not funded either.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 7, 'The negative progress message says progress runs from 0 to 100 percent. A published case enters progress beyond 100 percent. What does the engine do with it?', '["It accepts it and earns beyond the budget: earned value 150.0000 against actuals of 90.0000, a CPI of 1.666667 and an SPI of 1.500000.", "It refuses it with the same AfeInputError, because the message states both bounds and the check enforces the range it prints.", "It clamps the line to 100 percent, so earned value stops at the budget and the CPI cannot pass the budget over the actuals.", "It returns the metrics with a flag on the line, the way the grid overshoot returns its set beside overLimit true."]'::jsonb, 0, 'Only the lower bound is enforced; a CPI of 1.666667 reads as a line far ahead on cost when it has earned more than its budget can hold, a finding left unrepaired.'::text, 'The negative progress message says progress runs from 0 to 100 percent. A published case enters progress of 150 percent. What does the engine do with it?', '["It refuses it with an AfeInputError naming the line: \"has progress above 100 percent (150 percent). Progress runs from 0 to 100 percent.\"", "It accepts it and earns beyond the budget, since the message states a range the check enforces only at the lower bound.", "It clamps the line to 100 percent, so earned value stops at the budget and the CPI cannot pass the budget over the actuals.", "It returns the metrics with a flag on the line, the way the partner split returns its allocation beside valid false."]'::jsonb, 0, 'Both bounds are enforced. Exactly 100 is accepted and earns the whole budget: the published case reads earned value 140.0000 against actuals of 100.0000, a CPI of 1.400000.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 9, 'gridOvershoot now returns A + B at capex 6002.0000 and EMV 800.0000, with overLimit true and overLimitBy 2.0000. What did the EC5-0 repair change about that answer?', '["The set: the engine now re-solves on the exact capex and reports A + C at 780.0000, keeping overLimitBy 2.0000 to record the overshoot it avoided.", "The limit: the engine now widens it to 6002.0000 so that the set is feasible, and overLimitBy records how far the limit had to move.", "The capex: the engine funds B at 2.0000 less than its cost so the set fits, and overLimit true warns that B is funded short.", "Only the marking: the same set comes back and now says it breaks the limit, and the engine never re-solves to A + C at 780.0000."]'::jsonb, 3, 'The overshoot is flagged and still happens; ranking 800.0000 against a feasible 780.0000 prefers the set the budget cannot pay for, a golden gap of 20.0000.'::text, 'The published gridOvershoot case offers A (capex 4000.0000), B (2002.0000) and C (1995.0000) under a limit of 6000.0000. What do overLimit and overLimitBy read on the result, and why?', '["true and 2.0000, because A + B fills the limit to within one cell and the flag records the overshoot the engine accepted.", "true and 5.0000, because the flag reports any difference between the funded capex and the limit in either direction.", "Neither is reported on an exact solve.", "false and 0.0000: the exact solve funds A + C at 5995.0000, and a funded set never exceeds the limit."]'::jsonb, 3, 'overLimit and overLimitBy stay in every optimizer result and read false and 0.0000 on every exact solve; the fallback rounds weights up, so it cannot overshoot either.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 10, 'In gridOvershoot the limit of 6000.0000 runs on a resolution of 3.000000. Why does A + B, at a real capex of 6002.0000, fit the grid?', '["Rounding capex over 3.000000 weighs A at 1333 cells and B at 667, which fill the 2000 cells exactly.", "The limit and every capex are whole numbers, so the grid runs at 1 million USD per cell and the 2.0000 excess stays inside one cell.", "The engine admits any set within one cell of the limit, and an excess of 2.0000 is smaller than the resolution of 3.000000.", "B and C round to the same number of cells, so the grid cannot tell them apart and keeps whichever of the two was entered first."]'::jsonb, 0, 'Above a limit of 5000 each cell is the limit / 2000; rounding drops a fraction of a cell from A and from B, which is why the flag reports overLimitBy 2.0000.'::text, 'Called with exactStateLimit 2, the published gridOvershootFallback case runs A (capex 4000.0000), B (2002.0000) and C (1995.0000) against 6000.0000 on a grid of 2000 cells at resolution 3.000000. Why does it fund A + C and leave A + B out?', '["Every weight is rounded up, A to 1334 cells, B to 668 and C to 665, so A + B needs 2002 cells and A + C needs 1999.", "The limit and every capex are whole numbers, so the fallback runs at 1 million USD per cell and A + B is 2.0000 over it.", "The fallback admits any set within one cell of the limit, and A + C is kept because it leaves 5.0000 unspent.", "B and C round to the same number of cells, so the grid cannot tell them apart and keeps whichever of the two was entered last."]'::jsonb, 0, 'Rounding up means any set that fits the grid fits the limit in money. The result reads solveMethod grid-feasible, overLimit false and optimalityGap 20.0000, the bound from the same grid with every weight rounded down.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 11, 'gridUndershoot funds X + Y + Z at capex 4500.0000 and EMV 660.0000 under a limit of 6000.0000, and reports overLimit false. What does that false establish?', '["That the set is the best within the limit, since the repaired engine re-solves on the exact capex and compares the two answers before it sets the flag.", "That rounding changed nothing, since overLimit is raised whenever the grid and the exact capex disagree in either direction.", "Only that the funded capex is within the limit: the exact optimum funds all four at 860.0000, a gap of -200.0000 that no flag reports (finding D4).", "That 1500.0000 was left unspent by choice, because W at 1499.0000 carries the lowest EMV of the four and was not worth its capex."]'::jsonb, 2, 'Rounding makes the four together weigh more cells than the 2000 the grid holds, so one is left out; the undershoot is unflagged and taught as a property.'::text, 'The published gridUndershoot case offers W, X and Y at capex 1499.0000 and Z at 1502.0000, with EMVs 200.0000, 210.0000, 220.0000 and 230.0000, under a limit of 6000.0000. What does the optimizer fund?', '["X + Y + Z at 4500.0000 for 660.0000, since rounding makes the four together weigh more cells than the grid holds.", "Y + Z at 3001.0000 for 450.0000, since the optimizer funds the highest EMV per million USD first and stops at half the limit.", "All four at capex 5999.0000 for 860.0000, solved exactly with optimalityGap 0.0000 and 1.0000 left unspent.", "W + X + Y + Z with overLimit true, since 5999.0000 is within one cell of the limit and the flag marks a set that fills it."]'::jsonb, 2, 'The solve is exact on the capex as typed. Only a stated small exactStateLimit forces the fallback grid, where the published gridUndershootFallback funds X + Y + Z at 660.0000 with optimalityGap 200.0000.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 12, 'A joint venture split on a cost of 1000.00 enters partner interests of 30 and -20. Is that a refusal or a flag, and what comes back?', '["A refusal: an AfeInputError naming partner \"B\" and no allocation at all, the same treatment the AFE engine gives a cost line entered with negative progress or a bad as-of date.", "A flag: valid false with the engine note naming partner \"B\" and its -20.00 percent, and the allocation still shown with the operator at 90.0000 percent.", "A flag, with the -20 interest clamped to 0, so partner \"B\" is billed nothing and the operator is shown carrying 70.0000 percent.", "Neither: the split nets the two interests to 10 percent, so the operator carries 90.0000 percent and valid stays true."]'::jsonb, 1, 'Partner amounts read 300.00 and -200.00 and the operator 900.00; the repaired AFE summary prints the note beside the allocation instead of billing on it.'::text, 'A joint venture split on a cost of 1000.00 enters partner interests of 30 and -20. Is that a refusal or a flag, and what comes back?', '["A refusal: an AfeInputError naming partner \"B\" and no allocation at all, the same treatment the AFE engine gives a cost line entered with negative progress or a bad as-of date.", "A flag: valid false with the engine note naming partner \"B\" and its -20.00 percent, and the allocation still shown with the operator at 90.0000 percent.", "A flag, with the -20 interest clamped to 0, so partner \"B\" is billed nothing and the operator is shown carrying 70.0000 percent.", "Neither: the split nets the two interests to 10 percent, so the operator carries 90.0000 percent and valid stays true."]'::jsonb, 1, 'Partner amounts read 300.00 and -200.00 and the operator 900.00; the AFE summary prints the note beside the allocation.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 13, 'EC5-0 made SPI null where planned value is zero, yet the published empty AFE, with no lines and no spend, reports SPI 1.000000. Why?', '["The empty AFE has no dates, so time progress falls back to 1 and planned value becomes the whole budget, which is no longer zero.", "SPI copies CPI whenever actuals are 0, and CPI on the empty AFE reads 1.000000 because nothing at all has been spent on it.", "The null rule applies only up to the start day, and an AFE with no lines is treated as already past the end of its window.", "An AFE whose budget is 0 reports SPI 1 by a guard that fires before the null rule, a finding left unrepaired."]'::jsonb, 3, 'The same empty AFE also reports CPI 1.000000, so an AFE with no lines, no progress and no spend reads as perfect on cost and on schedule at once.'::text, 'The published empty AFE has no lines, no budget and no spend. Why does it report SPI null?', '["The empty AFE has no dates, so time progress falls back to 1 and its whole budget of zero is planned, which prints SPI 0.000000.", "SPI copies CPI, which is null because nothing has been spent.", "The null rule applies only up to the start day, and an AFE with no lines is treated as one that has not yet started.", "An AFE with no budget has no plan to measure schedule against, so SPI is null with spiStatus \"no-budget\"."]'::jsonb, 3, 'CPI is null too, with cpiStatus "no-spend"; the Suite''s SPI tile reads "N/A" with "No budget to measure schedule against".'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 14, 'OFON-1''s S-curve starts at "Feb 27" in UTC, Lagos and Tokyo, but a viewer in America/Los_Angeles sees the first point labelled "Jan 27" and every Planned value shifted. What is going on?', '["The engine parses the window as UTC midnight but steps months and prints labels in local time, finding EC5-5, left unrepaired.", "The as-of date west of UTC is still the previous day, so that viewer''s curve is drawn for a different as-of date than the metrics.", "The saved window is converted to the viewer''s time zone when it is stored, so that viewer has edited the AFE window into January.", "The repaired curve opens a month before the window to show commitments, and only viewers west of UTC are shown that month."]'::jsonb, 0, 'OFON-1''s window opens 2027-02-01, and in UTC its first point is Feb 27 with Planned 0; west of UTC the same AFE carries other labels and other plan values with no warning.'::text, 'OFON-1''s S-curve is drawn by viewers in UTC, Lagos, Tokyo and America/Los_Angeles. What does each see as the first point?', '["Feb 27 with Planned 0 in every zone, because the window, the as-of date, the monthly step and the labels are all read in UTC.", "Jan 27 west of UTC, because the window is parsed as UTC midnight while the months are stepped and labelled in local time.", "Feb 27 in UTC and a point dated the viewer''s local start day elsewhere, because each zone draws its own calendar.", "A curve opening a month before the window in zones west of UTC, to show commitments placed before the start."]'::jsonb, 0, 'The published case with a February start labels Feb in every zone; the same AFE draws the same curve wherever it is read.'::text),
      ('advanced', 'module', 'm04-refusals-and-flags'::text, 15, 'In the Suite the correlation slider stops at 0.9, where OKONO''s 600.0000 set reads stdDev 232.0795 and P(loss) 0.049500. How should that top value be read?', '["As the engine''s clamp: any correlation above 0.9 is cut back to 0.9, which is what the published clampAbove case exists to show.", "As the largest correlation the simulation can hold, because a correlation of 1 makes sqrt(1 - rho) zero and the draws collapse.", "As the app''s limit, never the engine''s: the engine accepts 1 and reads stdDev 239.8888 and P(loss) 0.059000, which the screen cannot set.", "As a harmless cap, because the emv of 402.7500 does not move with correlation, so the last step of the slider would change nothing that is reported."]'::jsonb, 2, 'The published clampAbove case reads correlation used 1.000000; the slider stopping at 0.9 is an app item left as published, so the most correlated case has to be run on the engine and named.'::text, 'In the Suite the correlation slider stops at 0.9, where OKONO''s 600.0000 set reads stdDev 232.0795 and P(loss) 0.049500. How should that top value be read?', '["As the engine''s clamp: any correlation above 0.9 is cut back to 0.9, which is what the published clampAbove case exists to show.", "As the largest correlation the simulation can hold, because a correlation of 1 makes sqrt(1 - rho) zero and the draws collapse.", "As the app''s limit alone: the engine accepts 1 and reads stdDev 239.8888 and P(loss) 0.059000, which the screen cannot set.", "As a harmless cap, because the emv of 402.7500 does not move with correlation, so the last step of the slider would change nothing that is reported."]'::jsonb, 2, 'The published clampAbove case reads correlation used 1.000000; the slider stopping at 0.9 is a property of the app as it stands, so the most correlated case has to be run on the engine and named.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 1, 'OFON-1 with every actual set to 0 and progress unchanged reports earned value 15231500 and CPI 1.000000. What does that CPI say about cost performance?', '["That the work done cost exactly what it earned, since earned value is compared with the 5000000 committed when no actual has posted.", "Nothing: earned value over zero actuals has no value, and the engine returns 1 whenever actuals are 0, the number an AFE exactly on budget shows.", "That the AFE is on budget to the unit, because with nothing spent no line can yet have overrun its share of the 27050000 budget.", "That CPI is capped at 1 until the first invoice posts, so the 1.009377 the lines earned is held back until the costs catch up with the progress."]'::jsonb, 1, 'OFON-1 as entered reads 1.009377 on actuals of 15090000; with actuals at 0 the 15231500 earned is either costs not yet posted or progress typed ahead of the work, and CPI hides both.'::text, 'OFON-1 with every actual set to 0 and progress unchanged reports earned value 15231500. What does the engine report for CPI, and what does that say about cost performance?', '["CPI 1.000000: the work done cost exactly what it earned, since earned value is compared with the 5000000 committed when no actual has posted.", "CPI null with cpiStatus \"no-spend\": earned value over zero actuals has no value, and the Suite''s CPI tile reads \"N/A\", nothing spent yet.", "CPI 1.000000: the AFE is on budget to the unit, because with nothing spent no line can yet have overrun its share of the budget.", "CPI 1.009377, held from the last report until the first invoice posts."]'::jsonb, 1, 'OFON-1 as entered reads 1.009377 on actuals of 15090000; with actuals at 0 the 15231500 earned is either costs not yet posted or progress typed ahead of the work, a question the null ratio leaves to the reader.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 3, 'The published "past window, all invoices unpaid: none dated" case holds an invoice of 100 with no invoice_date field and one of 200 whose invoice_date is null. Its first and last Actual both read 0, and the engine reports 2 undated invoices. Why?', '["Neither invoice carries a date the engine can read, so neither reaches a bucket, and the count beside the curve names both.", "The null date counts from 1970, which is earlier than every bucket, so the 200 sits in all 12 points while the invoice with no date field never counts.", "The curve falls back to the cost lines when no invoice carries a usable date, and the case''s single line of budget 1200 has no actual typed on it.", "Both invoices are placed at the window start, and the 100 is netted against the 200 as a credit because neither can be put in date order."]'::jsonb, 0, 'At Jan 20 Planned is 0 and Actual 0, and at Dec 20 Actual is still 0 beside Planned 1101: the curve carries no money it cannot date, and the count of 2 says how many invoices it left out.'::text, 'The published "past window, all invoices unpaid: none dated" case holds an invoice of 100 with no invoice_date field and one of 200 whose invoice_date is null. Its first and last Actual both read 0, and the engine reports 2 undated invoices. Why?', '["Neither invoice carries a date the engine can read, so neither reaches a bucket, and the count beside the curve names both.", "The null date counts from 1970, earlier than every bucket, so the 200 sits in every point.", "The curve falls back to the cost lines, and the case''s single line has no actual typed on it.", "Both invoices are placed at the window start and netted against each other."]'::jsonb, 0, 'At Jan 20 Planned is 0 and Actual 0, and at the closing point 31 Dec 20 Actual is still 0 beside Planned 1200: the curve carries no money it cannot date, and the count of 2 says how many invoices it left out.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 6, 'OFON-1''s window runs 2027-02-01 to 2027-11-30 on a budget of 27050000, and the S-curve''s last Planned point is 24452483. Why does the plan end 2597517 short?', '["The plan spreads the budget less the 5000000 already committed, since commitments are drawn on the Actual line and cannot be planned twice.", "The plan holds back a contingency that is released only when the AFE closes, and the metrics carry that contingency inside the EAC instead.", "EC5-0 cut the curve at the as-of date of 2027-08-15 and extended the plan past it from the monthly rate, which loses the last weeks.", "Each point sits on the 1st of its month, so the last one is the 1st of November and the rest of the window to 2027-11-30 is never plotted."]'::jsonb, 3, 'The metrics do reach the budget: as of 2027-11-30 time progress is 1.000000 and planned value 27050000, so the chart and the metrics disagree about the same plan.'::text, 'OFON-1''s window runs 2027-02-01 to 2027-11-30 on a budget of 27050000. The S-curve''s last monthly point, "Nov 27", plans 24452483. Where does the rest of the plan appear?', '["Nowhere: the plan spreads the budget less the 5000000 already committed, since commitments are drawn on the Actual line.", "In the metrics only, since the chart holds back a contingency that is released when the AFE closes.", "Beyond the window, since the plan runs on past 2027-11-30 at the monthly rate until it reaches the budget in December.", "On the closing point, \"30 Nov 27\", which carries Planned 27050000, the budget, adding the remaining 2597517."]'::jsonb, 3, 'Each monthly point sits on the 1st of its month, and the closing point is dated the window end; as of 2027-11-30 the metrics also read time progress 1.000000 and planned value 27050000.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 7, 'A reader of OFON-1''s S-curve alone sees the last Forecast point at 24949669, below the budget of 27050000. What does the AFE actually forecast?', '["An overrun: an EAC of 27600000 and a variance at completion of -550000, cut short on the chart by the same last bucket that stops the plan.", "A saving, since the Forecast line is the only projection that reads the invoices, while the metrics forecast every unposted line at its full budget.", "Exactly the budget, because a line with no entered forecast forecasts its budget and the chart has simply not reached the last day yet.", "Both at once, an underrun on the chart and an overrun in the metrics, since the curve forecasts only to the as-of date and the metrics to completion."]'::jsonb, 0, 'After the as-of date the Forecast line is the EAC spread from the start and stops at the last bucket; take the EAC and the variance from the metrics and use the curve for its shape.'::text, 'A reader of OFON-1''s S-curve stops at the last monthly point, "Nov 27", and sees Forecast 24949669, below the budget of 27050000. What does the AFE actually forecast?', '["An overrun: the closing point, \"30 Nov 27\", carries Forecast 27600000, the EAC, a variance at completion of -550000.", "A saving, since the Forecast line is the only projection that reads the invoices.", "Exactly the budget, because every line with no entered forecast forecasts its budget.", "Both at once, an underrun on the chart and an overrun in the metrics, since the curve forecasts only to the as-of date and the metrics to completion."]'::jsonb, 0, 'The Nov 27 point sits on the 1st of November, a month before the window closes; the metrics agree with the closing point, an EAC of 27600000 against a budget of 27050000.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 8, 'The published "future window ending on a bucket" case has 13 points, and its last point reads Planned 2000 and Forecast 2450, the whole EAC. What decides whether a curve''s last point reaches the budget?', '["The size of the budget, since each monthly bucket of plan is rounded to whole units of the AFE currency, and a budget as small as 2000 loses nothing to that rounding.", "Whether any invoices exist, since a curve with no invoices has no Actual line to cut off and so draws its plan to the end of the window.", "Where the end date falls against the month starts: a window ending on the 1st gets a point there, and OFON-1, ending on 2027-11-30, loses almost a month.", "The as-of date, since a default as-of date after the window lets the plan run to completion while a dated report stops the plan."]'::jsonb, 2, 'The one-year 2020 case has 12 points and ends at Planned 1101 on Dec 20 against a budget of 1200, and OFON-1''s last Planned point is 24452483 against 27050000.'::text, 'The published "future window ending on a bucket" case has 13 points, and its last point reads Planned 2000 and Forecast 2450, the whole EAC. What decides whether a curve''s last point reaches the budget?', '["The size of the budget, since a small budget loses nothing to rounding.", "Whether any invoices exist to cut the Actual line off early.", "Nothing decides it: every curve closes on a point dated the window end, with Planned the budget and Forecast the EAC.", "The as-of date, since a dated report stops the plan at that date."]'::jsonb, 2, 'OFON-1 closes on "30 Nov 27" at Planned 27050000 and Forecast 27600000, and the one-year 2020 case on "31 Dec 20" at Planned 1200; when a month step lands on the end date, the closing point replaces it.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 11, 'OKONO''s 450.0000 set reads a Low case P90 of -15.1262 at 1000 iterations, -18.3574 at 10000 and -18.8524 at 40000, and -21.8586 to -15.3254 across seeds 1 to 3. What belongs to the set?', '["That the Low case P90 is below zero, which every run agrees on; its fourth decimal moves with the sample, and the engine prints no standard error for it.", "The value -18.3574 to four decimals, because a percentile is read straight off the sorted draws rather than averaged from them, and so carries no sampling error of its own.", "The value -57.1494, because the closed-form formula emv - 1.2816 x stdDev uses no draws at all and so removes the sampling noise that moves every simulated run.", "The average of the six runs, because averaging over seeds and iteration counts removes the sampling noise carried by each run."]'::jsonb, 0, 'The Low case P90 is the 10th percentile of simulated portfolio NPV and wobbles by several million USD between runs; -57.1494 is the normal approximation, a different model.'::text, 'OKONO''s 450.0000 set reads a Low case P90 of -15.1262 at 1000 iterations, -18.3574 at 10000 and -18.8524 at 40000, and -21.8586 to -15.3254 across seeds 1 to 3. What belongs to the set?', '["That the Low case P90 is below zero, as every run agrees; it moves by several million USD with the sample, and the engine prints no standard error for it.", "The value -18.3574 to four decimals, because a percentile is read straight off the sorted draws with no averaging, and so carries no sampling error of its own.", "The value -57.1494, because the closed-form formula emv - 1.2816 x stdDev uses no draws at all and so removes the sampling noise that moves every simulated run.", "The average of the six runs, because averaging over seeds and iteration counts removes the sampling noise carried by each run."]'::jsonb, 0, 'The Low case P90 is the 10th percentile of simulated portfolio NPV and wobbles by several million USD between runs; -57.1494 is the normal approximation, a different model.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 1, 'Before EC5-0 the risk summary gave the single wildcat (pos 0.300000, npv_p50 300.0000, fail_cost 50.0000) a Low case P90 of -150.5560. What was wrong with it?', '["It was too optimistic, since the exact low case of a lone wildcat lies further below zero than -150.5560 once the fail cost is risked.", "It was right but imprecise, since a normal approximation settles on the exact low case once enough projects are added to the portfolio.", "It lay below the worst possible outcome of -50.0000, a low case no portfolio could reach; the simulation''s P90 is -50.0000, an outcome that can happen.", "It was right for the model and wrong for the inventory, since the wildcat''s fail_cost of 50.0000 had been entered as a loss in every year."]'::jsonb, 2, 'The same approximation put P(loss) at 0.365832 against an exact 0.700000; the engine now draws success and failure and reads 0.696100 at seed 20260829 and 10000 iterations.'::text, 'A normal approximation gives the single wildcat (pos 0.300000, npv_p50 300.0000, fail_cost 50.0000) a Low case P90 of -150.5560. What is wrong with it?', '["It is too optimistic, since the exact low case of a lone wildcat lies further below zero than -150.5560 once the fail cost is risked.", "It is right but imprecise, since a normal approximation settles on the exact low case once enough projects are added to the portfolio.", "It lies below the worst possible outcome of -50.0000, a low case no portfolio can reach; the simulation''s P90 is -50.0000, an outcome that can happen.", "It is right for the method and wrong for the inventory, since the wildcat''s fail_cost of 50.0000 was entered as a loss in every year."]'::jsonb, 2, 'The same approximation puts P(loss) at 0.365832 against an exact 0.700000; the engine draws success and failure and reads 0.696100 at seed 20260829 and 10000 iterations.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 4, 'The capstone order starts with the inputs. Why write one risked EMV by hand, such as OK-3''s, before running anything?', '["The engine reports only the summed EMV of the funded set, so a project''s own risked EMV exists nowhere unless it is worked out by hand.", "A clamp or a default changes an input silently, so 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500 confirms the engine read what was typed.", "OK-3''s success-case NPV of 420.0000 is its value, and the hand calculation shows how much of that value the grid keeps after rounding.", "The hand figure is the one the capstone grades, since the engine rounds each project''s risked EMV to a whole million USD."]'::jsonb, 1, 'A pos of 1.4 or "n/a" returns 80.0000 on the published case with no warning; OK-3''s risked EMV of 41.2500 is only 0.098214 of its success-case NPV.'::text, 'The capstone order starts with the inputs. Why write one risked EMV by hand, such as OK-3''s, before running anything?', '["The engine reports only the summed EMV of the funded set, so a project''s own risked EMV exists nowhere unless it is worked out by hand.", "A default or a quiet reading changes an input silently, so 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500 confirms the engine read what was typed.", "OK-3''s success-case NPV of 420.0000 is its value, and the hand calculation shows how much of that value the optimizer keeps.", "The hand figure is the one the capstone grades, since the engine rounds each project''s risked EMV to a whole million USD."]'::jsonb, 1, 'An omitted pos defaults to 1 and a negative fail_cost reads as 0, with no warning; OK-3''s risked EMV of 41.2500 is only 0.098214 of its success-case NPV.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 5, 'OKONO at 450.0000 funds OK-1 + OK-3 + OK-4 at resolution 1.0000 with overLimit false. On a run whose resolution is coarser than 1 million USD per cell, what must the answer add?', '["Nothing further, because overLimit false on a coarse grid certifies both that the set is feasible and that no better set was missed.", "The exact optimum, which the repaired engine reports beside the grid answer whenever the resolution is coarser than 1 million USD.", "Whether overLimit fired, and that an undershoot (D4) or a free project charged a cell (D2) would not be flagged.", "A rerun on a different seed, since a coarse grid is sampled rather than solved and the funded set moves from one seed to the next."]'::jsonb, 2, 'gridUndershoot shows why: overLimit false and EMV 660.0000, where the exact optimum is 860.0000.'::text, 'OKONO at 450.0000 funds OK-1 + OK-3 + OK-4, solveMethod exact with optimalityGap 0.0000. On a run whose solveMethod reads grid-feasible, what must the answer add?', '["Nothing further, because overLimit false on the fallback certifies both that the set fits and that no better set was missed.", "The exact optimum, which the engine reports beside the fallback answer whenever the grid is used.", "The optimalityGap beside the EMV, the most a better set within the limit could add, since the fallback can fall short.", "A rerun on a different seed, since a fallback grid is sampled and the funded set moves from one seed to the next."]'::jsonb, 2, 'The published gridUndershootFallback reads X + Y + Z at 660.0000 with optimalityGap 200.0000, where the exact optimum is 860.0000.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 9, 'A capstone answer quotes OFON-1''s CPI of 1.009377, correctly, with nothing beside it. Why does it lose marks?', '["A CPI needs its as-of date beside it, because CPI moves with the date in the same way SPI moved from 1.141290 to 0.872063.", "A CPI needs its seed beside it, because every ratio in an expert capstone is simulated and moves from one run to the next.", "A CPI needs the actuals total beside it, 15090000 here, because 1.000000 is also what the engine reports when actuals are 0.", "A CPI above 1 has to be reported as 1, because the engine caps each performance ratio at the budget before it writes the report."]'::jsonb, 2, 'A correct number with its condition missing loses marks: a P90 without a seed, an SPI without an as-of date, a set without overLimit, and a CPI without the actuals total.'::text, 'A capstone answer quotes OFON-1''s CPI of 1.009377, correctly, with nothing beside it. Why does it lose marks?', '["A CPI needs its as-of date beside it, because CPI moves with the date in the same way SPI moved from 1.141290 to 0.872063.", "A CPI needs its seed beside it, because every ratio in an expert capstone is simulated and moves from one run to the next.", "A CPI needs the actuals total beside it, 15090000 here, the amount earned value was divided by; with nothing spent CPI is null.", "A CPI above 1 has to be reported as 1, because the engine caps each performance ratio at the budget before it writes the report."]'::jsonb, 2, 'A correct number with its condition missing loses marks: a P90 without a seed, an SPI without an as-of date, a set without its solveMethod, and a CPI without the actuals total.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 10, 'An answer reports OFON-1''s EAC as 24949669, read off the last Forecast point of the S-curve. What has it done?', '["Turned an overrun into an apparent saving: the EAC is 27600000 with a variance of -550000, and the curve''s last bucket cuts the Forecast line short.", "Reported the EAC correctly as of 2027-08-15, since the curve''s Forecast line is the only projection that takes the as-of date into account.", "Reported the forecast before commitments, which the metrics add on top of the curve''s last value to arrive at the EAC.", "Reported the plan instead of the forecast, since the two lines trade places after the as-of date and that point belongs to Planned."]'::jsonb, 0, 'The last Planned point is 24452483 and the last Forecast point 24949669, both below the budget of 27050000; take the EAC from the metrics and use the curve for its shape.'::text, 'An answer reports OFON-1''s EAC as 24949669, read off the Forecast of the S-curve''s last monthly point, "Nov 27". What has it done?', '["Turned an overrun into an apparent saving: the closing point and the metrics give the EAC as 27600000, a variance of -550000.", "Reported the EAC correctly as of 2027-08-15, since the curve''s Forecast line is the only projection that takes the as-of date into account.", "Reported the forecast before commitments, which the metrics add on top of the curve''s last value to arrive at the EAC.", "Reported the plan in place of the forecast, since the two lines trade places after the as-of date and that point belongs to Planned."]'::jsonb, 0, 'Nov 27 plans 24452483 and forecasts 24949669, both below the budget of 27050000; the closing point, "30 Nov 27", carries Planned 27050000 and Forecast 27600000.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 11, 'OKONO at 600.0000 is rerun on a different seed. Which of its results can change?', '["P(loss) and the stdDev of 143.8374, which is the spread of the simulated draws and moves with them.", "P(loss) and the funded set as well, because the optimizer breaks ties between sets of equal EMV by a draw on the seed.", "None of them, because a seed fixes only the order of the draws, and every order of the same draws yields the same count of losses.", "P(loss), the Low case P90 and the P10, which are simulated; the set, emv 402.7500 and stdDev 143.8374 are not."]'::jsonb, 3, 'emv and stdDev are closed form and the optimizer keeps the first best set it builds; at 450.0000, P(loss) runs from 0.119100 to 0.128500 across seeds 1 to 3.'::text, 'OKONO at 600.0000 is rerun on a different seed. Which of its results can change?', '["P(loss) and the stdDev of 143.8374, which is the spread of the simulated draws and moves with them.", "P(loss) and the funded set as well, because the optimizer breaks ties between sets of equal EMV by a draw on the seed.", "None of them, because a seed fixes only the order of the draws, and every order of the same draws yields the same count of losses.", "P(loss), the Low case P90 and the P10, which are simulated; the set, emv 402.7500 and stdDev 143.8374 are not."]'::jsonb, 3, 'emv and stdDev are closed form, and the optimizer is exact and deterministic; at 450.0000, P(loss) runs from 0.119100 to 0.128500 across seeds 1 to 3.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 13, 'Which sentence reports the P(loss) of OKONO''s 450.0000 set the way this tier asks?', '["P(loss) is 0.123600 at seed 20260829 and 10000 iterations, with a standard error of 0.003291, under a correlation of 0.", "P(loss) is 0.123600 on the default settings, with the standard error of 0.010050 that any probability counted from the draws carries.", "P(loss) is 0.142035, what this set''s emv and stdDev give once the noise of any one seed is taken out.", "P(loss) is 0.123600 to six decimals, a figure the seed makes exact, so that no standard error needs to be printed beside it."]'::jsonb, 0, '0.010050 is the standard error at 1000 iterations, not at 10000; 0.142035 is what the normal approximation would have said, a different model.'::text, 'Which sentence reports the P(loss) of OKONO''s 450.0000 set the way this tier asks?', '["P(loss) is 0.123600 at seed 20260829 and 10000 iterations, with a standard error of 0.003291, under a correlation of 0.", "P(loss) is 0.123600 on the default settings, with the standard error of 0.010050 that any probability counted from the draws carries.", "P(loss) is 0.142035, what this set''s emv and stdDev give once the noise of any one seed is taken out.", "P(loss) is 0.123600 to six decimals, a figure the seed makes exact, so that no standard error needs to be printed beside it."]'::jsonb, 0, '0.010050 is the standard error at 1000 iterations, and 0.003291 the one at 10000; 0.142035 is the normal approximation''s figure, a different model.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 15, 'Checking OFON-1''s inputs before the AFE is read, an answer finds every progress at 0 or more. What must it still point out?', '["Nothing more, because the engine refuses progress outside 0 to 100 percent, exactly as its message says, so a report that returns metrics has passed both bounds of the check.", "Any line at 0 percent, because the engine treats a line not yet begun as refused progress and drops its budget from planned value.", "Any progress above 100 percent, which the engine accepts and which earns value beyond the budget, as the published case''s CPI of 1.666667 shows.", "Any line at 100 percent, such as CSG-02, because a complete line is clamped and its actual of 4300000 is taken out of CPI."]'::jsonb, 2, 'Negative progress throws AfeInputError, but only the lower bound is enforced; CSG-02 sits at 100.0000 percent with actuals of 4300000 against a budget of 3900000 and could be pushed past 100 with no refusal.'::text, 'Checking OFON-1''s inputs before the AFE is read, an answer confirms every progress runs from 0 to 100 percent. Why does that check matter before the report is run?', '["A line above 100 percent is accepted and earns value beyond its budget, so it has to be read beside the CPI before the CPI is believed.", "Any line at 0 percent is treated as refused progress, and its budget is dropped from planned value.", "Because a single line outside it stops the whole report: the engine returns no metrics until that line is corrected.", "Any line at 100 percent, such as CSG-02, is clamped and its actual of 4300000 is taken out of CPI."]'::jsonb, 2, 'The published case at 150 percent reads Cost item "0" has progress above 100 percent (150 percent); CSG-02 sits at 100.0000 percent, the most a line can earn, with actuals of 4300000 against a budget of 3900000.'::text)
    ) as t(tier, scope, module_key, ord, old_prompt, old_options, old_answer, old_expl, new_prompt, new_options, new_answer, new_expl)
  loop
    select case
             when q.prompt = r.old_prompt and q.options = r.old_options and q.answer_index = r.old_answer and q.explanation is not distinct from r.old_expl then 'old'
             when q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer and q.explanation is not distinct from r.new_expl then 'new'
             else 'other' end
      into v_state
      from public.academy_quiz_questions q
     where q.app_slug = 'portfolio' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec45 recut refused: portfolio/%/%/%/ord % matched % active rows, expected 1', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
    end if;
    if v_state = 'other' then
      raise exception 'ec45 recut refused: portfolio/%/%/%/ord % carries neither its served text nor the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
    if v_state = 'old' then
      update public.academy_quiz_questions q
         set prompt = r.new_prompt, options = r.new_options, answer_index = r.new_answer, explanation = r.new_expl
       where q.app_slug = 'portfolio' and q.active and q.tier = r.tier and q.scope = r.scope
         and q.module_key is not distinct from r.module_key and q.ord = r.ord
         and q.answer_index = r.old_answer;
      get diagnostics v_count = row_count;
      if v_count <> 1 then
        raise exception 'ec45 recut refused: portfolio/%/%/%/ord % update touched % rows', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
      end if;
      v_updated := v_updated + 1;
    else
      v_done := v_done + 1;
    end if;
    perform 1 from public.academy_quiz_questions q
     where q.app_slug = 'portfolio' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord
       and q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer
       and q.explanation is not distinct from r.new_expl;
    if not found then
      raise exception 'ec45 recut refused: portfolio/%/%/%/ord % does not read back as the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
  end loop;
  if v_updated + v_done <> 178 then
    raise exception 'ec45 recut refused: portfolio accounted for % rows, expected 178', v_updated + v_done;
  end if;
  perform set_config('ec45.rows_portfolio', (v_updated + v_done)::text, false);
  raise notice 'ec45 recut: portfolio questions, % updated, % already recut, of 178', v_updated, v_done;
end $$;

-- ----------------------------------------------------------------------------
-- 3. joa: 2 question rows (beginner 1, intermediate 0, advanced 1).
-- ----------------------------------------------------------------------------
do $$
declare
  r         record;
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_done    integer := 0;
begin
  for r in
    select * from (values
      ('beginner', 'final', null::text, 4, 'What does the engine export under the name ACCEPTED_KEYS?', '["A list of aliases, such as wi, that it maps onto participatingPct.", "One shape of accepted keys for each of its 9 functions.", "The keys of the Ekene fixture file, for the panels to load at start.", "A table of error codes, one code for each of the 78 refusals the course lists."]'::jsonb, 1, 'ACCEPTED_KEYS is exported with one shape for each of the 9 functions, and every call refuses an input key its function does not read, at every level. The engine maps no alias onto a key it reads, the fixture is a separate file, and a refusal is an object with error and field, carrying a message in words and no code.'::text, 'What does the engine export under the name ACCEPTED_KEYS?', '["A list of aliases, such as wi, that it maps onto participatingPct.", "One shape of accepted keys for each of its 9 functions.", "The keys of the Ekene fixture file, for the panels to load at start.", "A table of error codes, one code for each of the 83 refusals the course lists."]'::jsonb, 1, 'ACCEPTED_KEYS is exported with one shape for each of the 9 functions, and every call refuses an input key its function does not read, at every level. The engine maps no alias onto a key it reads, the fixture is a separate file, and a refusal is an object with error and field, carrying a message in words and no code.'::text),
      ('advanced', 'module', 'm06-conventions-and-the-partner-report'::text, 9, 'How does every refusal message of the engine begin, and what does an unknown key''s message add?', '["It starts with the field it refuses; an unknown key''s message adds the key''s path and the full list of accepted keys", "It starts with the function''s name; an unknown key''s message adds the nearest accepted key as a spelling suggestion to try next", "It starts with a numbered refusal code from the engine''s table; an unknown key''s message names the key and nothing further", "It starts with the value it was given; an unknown key''s message adds the rule the key would have set"]'::jsonb, 0, 'The refusals table says a message starts with the name of the field it refuses and states the exact condition, and that an unknown key is refused wherever it sits with its path and the full list of accepted keys, for example uplift.rate is not an accepted key; the accepted keys of uplift are type, ratePctPerYear, multiplePct.'::text, 'How does every refusal message of the engine begin, and what does an unknown key''s message add?', '["It starts with the field it refuses; an unknown key''s message adds the key''s path and the full list of accepted keys", "It starts with the function''s name; an unknown key''s message adds the nearest accepted key as a spelling suggestion to try next", "It starts with a numbered refusal code from the engine''s table; an unknown key''s message names the key and nothing further", "It starts with the value it was given; an unknown key''s message adds the rule the key would have set"]'::jsonb, 0, 'The refusals table says a message starts with the name of the field it refuses and states the exact condition, and that an unknown key is refused wherever it sits with its path and the full list of accepted keys, for example uplift.rate is not an accepted key; the accepted keys of uplift are type, ratePctPerYear, multiplePct, dayBasis.'::text)
    ) as t(tier, scope, module_key, ord, old_prompt, old_options, old_answer, old_expl, new_prompt, new_options, new_answer, new_expl)
  loop
    select case
             when q.prompt = r.old_prompt and q.options = r.old_options and q.answer_index = r.old_answer and q.explanation is not distinct from r.old_expl then 'old'
             when q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer and q.explanation is not distinct from r.new_expl then 'new'
             else 'other' end
      into v_state
      from public.academy_quiz_questions q
     where q.app_slug = 'joa' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec45 recut refused: joa/%/%/%/ord % matched % active rows, expected 1', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
    end if;
    if v_state = 'other' then
      raise exception 'ec45 recut refused: joa/%/%/%/ord % carries neither its served text nor the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
    if v_state = 'old' then
      update public.academy_quiz_questions q
         set prompt = r.new_prompt, options = r.new_options, answer_index = r.new_answer, explanation = r.new_expl
       where q.app_slug = 'joa' and q.active and q.tier = r.tier and q.scope = r.scope
         and q.module_key is not distinct from r.module_key and q.ord = r.ord
         and q.answer_index = r.old_answer;
      get diagnostics v_count = row_count;
      if v_count <> 1 then
        raise exception 'ec45 recut refused: joa/%/%/%/ord % update touched % rows', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
      end if;
      v_updated := v_updated + 1;
    else
      v_done := v_done + 1;
    end if;
    perform 1 from public.academy_quiz_questions q
     where q.app_slug = 'joa' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord
       and q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer
       and q.explanation is not distinct from r.new_expl;
    if not found then
      raise exception 'ec45 recut refused: joa/%/%/%/ord % does not read back as the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
  end loop;
  if v_updated + v_done <> 2 then
    raise exception 'ec45 recut refused: joa accounted for % rows, expected 2', v_updated + v_done;
  end if;
  perform set_config('ec45.rows_joa', (v_updated + v_done)::text, false);
  raise notice 'ec45 recut: joa questions, % updated, % already recut, of 2', v_updated, v_done;
end $$;

-- ----------------------------------------------------------------------------
-- 4. decision advanced capstone: the dataset line only. Title, cert tier and fields
--    must be exactly the served ones and the prompt its pre-W3 (md5 9c474d00ca4f4b701116d084e1d22d06)
--    or post-W3 (md5 9099fda79bc00d69eaef2d67fad28009) form; none of them is written.
-- ----------------------------------------------------------------------------
do $$
declare
  v_state text;
  v_count integer;
begin
  select case
           when not (c.title = 'Judge the numbers' and c.cert_tier = 'expert' and md5(c.prompt) in ('9c474d00ca4f4b701116d084e1d22d06', '9099fda79bc00d69eaef2d67fad28009') and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "ab_three_reading_evii_musd", "tol": 0.001, "unit": "million USD", "label": "Gross EVII of the three-reading survey", "expected": 25.44400000000003}, {"key": "ab_three_reading_mixed_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the best action after a Mixed reading of the three-reading survey", "expected": 52.455084217092946}, {"key": "ab_mc_linked_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect tree with the Large payoff linked to the Monte Carlo summary", "expected": 72.10204}, {"key": "ab_mc_linked_decision_advantage_musd", "tol": 0.001, "unit": "million USD", "label": "Decision advantage row of the decision brief for that linked tree", "expected": 23.490040000000008}, {"key": "ab_analyzer_evpi_two_action_musd", "tol": 0.001, "unit": "million USD", "label": "EVPI the VOI Analyzer reports for this lottery, unrounded (Drill or Do Not Drill)", "expected": 54.960000000000036}, {"key": "ab_max_strong_chance_consistent_pct", "tol": 0.001, "unit": "percent", "label": "Largest Strong indicator chance that passes the consistency check with the typed posteriors", "expected": 39.058823529411754}]'::jsonb) with ordinality as e(f, n))) then 'other'
           when c.dataset = 'the ABALAMA tree, lottery and surveys, read through Decision Studio and the repaired VOI Analyzer' then 'old'
           when c.dataset = 'the ABALAMA tree, lottery and surveys, read through Decision Studio and the VOI Analyzer' then 'new'
           else 'other' end
    into v_state
    from public.academy_capstones c where c.app_slug = 'decision' and c.tier = 'advanced' and c.active;
  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'ec45 recut refused: decision/advanced has % active capstones, expected 1', v_count;
  end if;
  if v_state = 'other' then
    raise exception 'ec45 recut refused: the decision/advanced capstone carries neither its served title, cert tier, prompt (pre- or post-W3), fields and dataset nor the recut dataset';
  end if;
  if v_state = 'old' then
    update public.academy_capstones set dataset = 'the ABALAMA tree, lottery and surveys, read through Decision Studio and the VOI Analyzer'
     where app_slug = 'decision' and tier = 'advanced' and active and dataset = 'the ABALAMA tree, lottery and surveys, read through Decision Studio and the repaired VOI Analyzer';
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec45 recut refused: the decision/advanced capstone update touched % rows', v_count;
    end if;
  end if;
  perform 1 from public.academy_capstones c where c.app_slug = 'decision' and c.tier = 'advanced' and c.active and c.dataset = 'the ABALAMA tree, lottery and surveys, read through Decision Studio and the VOI Analyzer' and c.title = 'Judge the numbers' and c.cert_tier = 'expert' and md5(c.prompt) in ('9c474d00ca4f4b701116d084e1d22d06', '9099fda79bc00d69eaef2d67fad28009') and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "ab_three_reading_evii_musd", "tol": 0.001, "unit": "million USD", "label": "Gross EVII of the three-reading survey", "expected": 25.44400000000003}, {"key": "ab_three_reading_mixed_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the best action after a Mixed reading of the three-reading survey", "expected": 52.455084217092946}, {"key": "ab_mc_linked_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect tree with the Large payoff linked to the Monte Carlo summary", "expected": 72.10204}, {"key": "ab_mc_linked_decision_advantage_musd", "tol": 0.001, "unit": "million USD", "label": "Decision advantage row of the decision brief for that linked tree", "expected": 23.490040000000008}, {"key": "ab_analyzer_evpi_two_action_musd", "tol": 0.001, "unit": "million USD", "label": "EVPI the VOI Analyzer reports for this lottery, unrounded (Drill or Do Not Drill)", "expected": 54.960000000000036}, {"key": "ab_max_strong_chance_consistent_pct", "tol": 0.001, "unit": "percent", "label": "Largest Strong indicator chance that passes the consistency check with the typed posteriors", "expected": 39.058823529411754}]'::jsonb) with ordinality as e(f, n));
  if not found then
    raise exception 'ec45 recut refused: the decision/advanced capstone does not read back as the recut dataset with its prompt and fields unchanged';
  end if;
  raise notice 'ec45 recut: decision/advanced capstone dataset %', case when v_state = 'old' then 'recut' else 'already recut' end;
end $$;

-- ----------------------------------------------------------------------------
-- 5. portfolio advanced capstone: the dataset line only. Title, cert tier and fields
--    must be exactly the served ones and the prompt its pre-W3 (md5 2ea18ad13ac9723309bce7467bc3291f)
--    or post-W3 (md5 4fd416a471af05473c90bb7f526cf591) form; none of them is written.
-- ----------------------------------------------------------------------------
do $$
declare
  v_state text;
  v_count integer;
begin
  select case
           when not (c.title = 'Risk, shares and trust' and c.cert_tier = 'expert' and md5(c.prompt) in ('2ea18ad13ac9723309bce7467bc3291f', '4fd416a471af05473c90bb7f526cf591') and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "id_p90_npv_second_limit_independent_musd", "tol": 0.001, "unit": "million USD", "label": "NPV P90 (low case) of the portfolio funded at 640, correlation 0, default seed and iterations", "expected": 186.43748372945947}, {"key": "id_stddev_second_limit_correlated_musd", "tol": 0.001, "unit": "million USD", "label": "Standard deviation of NPV of the portfolio funded at 640, average correlation 0.45", "expected": 218.65902676147542}, {"key": "id_prob_loss_second_limit_correlated", "tol": 5e-05, "unit": "probability", "label": "Probability the portfolio funded at 640 loses money, average correlation 0.45, default seed and iterations", "expected": 0.028}, {"key": "id_p90_npv_second_limit_correlated_musd", "tol": 0.001, "unit": "million USD", "label": "NPV P90 (low case) of the portfolio funded at 640, average correlation 0.45, default seed and iterations", "expected": 128.14762834967667}, {"key": "id_second_partner_billed_usd", "tol": 0.5, "unit": "USD", "label": "Share of the actuals to date billed to Okwori Energy", "expected": 2505615.3000000003}, {"key": "id_operator_billed_usd", "tol": 0.5, "unit": "USD", "label": "Share of the actuals to date carried by the operator", "expected": 4714867.5}]'::jsonb) with ordinality as e(f, n))) then 'other'
           when c.dataset = 'the IDOHO inventory and the IDOHO-2 AFE, read through the repaired risk summary and the partner split' then 'old'
           when c.dataset = 'the IDOHO inventory and the IDOHO-2 AFE, read through the risk summary and the partner split' then 'new'
           else 'other' end
    into v_state
    from public.academy_capstones c where c.app_slug = 'portfolio' and c.tier = 'advanced' and c.active;
  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'ec45 recut refused: portfolio/advanced has % active capstones, expected 1', v_count;
  end if;
  if v_state = 'other' then
    raise exception 'ec45 recut refused: the portfolio/advanced capstone carries neither its served title, cert tier, prompt (pre- or post-W3), fields and dataset nor the recut dataset';
  end if;
  if v_state = 'old' then
    update public.academy_capstones set dataset = 'the IDOHO inventory and the IDOHO-2 AFE, read through the risk summary and the partner split'
     where app_slug = 'portfolio' and tier = 'advanced' and active and dataset = 'the IDOHO inventory and the IDOHO-2 AFE, read through the repaired risk summary and the partner split';
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec45 recut refused: the portfolio/advanced capstone update touched % rows', v_count;
    end if;
  end if;
  perform 1 from public.academy_capstones c where c.app_slug = 'portfolio' and c.tier = 'advanced' and c.active and c.dataset = 'the IDOHO inventory and the IDOHO-2 AFE, read through the risk summary and the partner split' and c.title = 'Risk, shares and trust' and c.cert_tier = 'expert' and md5(c.prompt) in ('2ea18ad13ac9723309bce7467bc3291f', '4fd416a471af05473c90bb7f526cf591') and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "id_p90_npv_second_limit_independent_musd", "tol": 0.001, "unit": "million USD", "label": "NPV P90 (low case) of the portfolio funded at 640, correlation 0, default seed and iterations", "expected": 186.43748372945947}, {"key": "id_stddev_second_limit_correlated_musd", "tol": 0.001, "unit": "million USD", "label": "Standard deviation of NPV of the portfolio funded at 640, average correlation 0.45", "expected": 218.65902676147542}, {"key": "id_prob_loss_second_limit_correlated", "tol": 5e-05, "unit": "probability", "label": "Probability the portfolio funded at 640 loses money, average correlation 0.45, default seed and iterations", "expected": 0.028}, {"key": "id_p90_npv_second_limit_correlated_musd", "tol": 0.001, "unit": "million USD", "label": "NPV P90 (low case) of the portfolio funded at 640, average correlation 0.45, default seed and iterations", "expected": 128.14762834967667}, {"key": "id_second_partner_billed_usd", "tol": 0.5, "unit": "USD", "label": "Share of the actuals to date billed to Okwori Energy", "expected": 2505615.3000000003}, {"key": "id_operator_billed_usd", "tol": 0.5, "unit": "USD", "label": "Share of the actuals to date carried by the operator", "expected": 4714867.5}]'::jsonb) with ordinality as e(f, n));
  if not found then
    raise exception 'ec45 recut refused: the portfolio/advanced capstone does not read back as the recut dataset with its prompt and fields unchanged';
  end if;
  raise notice 'ec45 recut: portfolio/advanced capstone dataset %', case when v_state = 'old' then 'recut' else 'already recut' end;
