-- ----------------------------------------------------------------------------
-- 6. Closing assertions: the row counts this file accounted for (321 question
--    rows), 396 active questions (132 a tier) and 3 capstones of 6 fields per
--    course, and the attempts and certifications untouched.
-- ----------------------------------------------------------------------------
do $$
declare
  v_count integer;
  v_c     text;
  v_t     text;
begin
  if coalesce(current_setting('ec45.rows_decision', true), '') <> '141' then
    raise exception 'ec45 recut refused: the decision block accounted for % rows, expected 141', current_setting('ec45.rows_decision', true);
  end if;
  if coalesce(current_setting('ec45.rows_portfolio', true), '') <> '178' then
    raise exception 'ec45 recut refused: the portfolio block accounted for % rows, expected 178', current_setting('ec45.rows_portfolio', true);
  end if;
  if coalesce(current_setting('ec45.rows_joa', true), '') <> '2' then
    raise exception 'ec45 recut refused: the joa block accounted for % rows, expected 2', current_setting('ec45.rows_joa', true);
  end if;
  foreach v_c in array array['decision', 'portfolio', 'joa'] loop
    foreach v_t in array array['beginner', 'intermediate', 'advanced'] loop
      select count(*) into v_count from public.academy_quiz_questions where app_slug = v_c and active and tier = v_t;
      if v_count <> 132 then
        raise exception 'ec45 recut refused: %/% holds % active questions, expected 132', v_c, v_t, v_count;
      end if;
    end loop;
    select count(*) into v_count from public.academy_quiz_questions where app_slug = v_c and active;
    if v_count <> 396 then
      raise exception 'ec45 recut refused: % holds % active questions, expected 396', v_c, v_count;
    end if;
    select count(*) into v_count from public.academy_capstones where app_slug = v_c and active;
    if v_count <> 3 then
      raise exception 'ec45 recut refused: % has % active capstones, expected 3', v_c, v_count;
    end if;
    select count(*) into v_count from public.academy_capstones k, lateral jsonb_array_elements(k.fields) f where k.app_slug = v_c and k.active;
    if v_count <> 18 then
      raise exception 'ec45 recut refused: % capstones carry % graded fields, expected 18', v_c, v_count;
    end if;
  end loop;
  if current_setting('ec45.snapshot', true) is distinct from md5(coalesce((select string_agg(md5(a::text), ',' order by a.id) from public.academy_capstone_attempts a where a.app_slug in ('decision', 'portfolio', 'joa')), '') || '#' || coalesce((select string_agg(md5(c::text), ',' order by md5(c::text)) from public.academy_certifications c where c.app_slug in ('decision', 'portfolio', 'joa')), '')) then
    raise exception 'ec45 recut refused: a stored capstone attempt or certification of decision, portfolio or joa changed';
  end if;
  raise notice 'ec45 recut: done; 321 question rows and 2 capstone datasets in their recut form; attempts and certifications untouched';
end $$;
